-- Prelaunch canonical baseline, generated by pinned Supabase CLI 2.111.0.
-- No historical product/file compatibility, application data or credentials.
do $$
declare v_role text;
begin
  foreach v_role in array array['domain_owner','account_executor','admin_executor','job_executor','recovery_executor','billing_ingress'] loop
    if not exists (select 1 from pg_roles where rolname=v_role) then
      execute format('create role %I noinherit nologin nosuperuser nocreatedb nocreaterole noreplication nobypassrls', v_role);
    end if;
    execute format('grant %I to postgres', v_role);
  end loop;
end;
$$;

SET statement_timeout = 0;
