CREATE OR REPLACE FUNCTION "private"."account_activate"("p_ctx" "private"."account_context") RETURNS TABLE("platform_account_id" "uuid", "account_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_platform public.platforms;
  v_account public.platform_accounts;
  v_session record;
begin
  select * into v_session from private.check_user_session((p_ctx).user_id, (p_ctx).session_id);
  if not coalesce(v_session.active, false) then raise exception using errcode = '42501', message = 'unauthorized'; end if;
  if private.identity_is_blocked((p_ctx).user_id) then raise exception using errcode = '42501', message = 'global_delete_pending'; end if;

  select * into v_platform from public.platforms where id = (p_ctx).platform_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_platform.status <> 'active' then raise exception using errcode = '42501', message = 'platform_disabled'; end if;
  if not v_platform.allow_activation then raise exception using errcode = 'P0001', message = 'activation_disabled'; end if;

  insert into public.platform_accounts (platform_id, user_id, status)
  values ((p_ctx).platform_id, (p_ctx).user_id, 'active')
  on conflict (platform_id, user_id) do nothing;
  select * into v_account from public.platform_accounts
  where platform_id = (p_ctx).platform_id and user_id = (p_ctx).user_id for update;
  if v_account.status <> 'active' then raise exception using errcode = 'P0001', message = 'account_not_activatable'; end if;

  insert into public.platform_profiles (platform_account_id) values (v_account.id) on conflict do nothing;
  insert into public.platform_preferences (platform_account_id) values (v_account.id) on conflict do nothing;
  perform private.audit_append((p_ctx).request_id, 'user', (p_ctx).user_id, (p_ctx).platform_id,
    v_account.id, 'account.activated', 'platform_account', v_account.id, null, null, '{}'::jsonb);
  return query select v_account.id, v_account.status;
end;
$$;


ALTER FUNCTION "private"."account_activate"("p_ctx" "private"."account_context") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."account_admin_support_privacy_cleanup"("p_platform_account_id" "uuid", "p_now" timestamp with time zone DEFAULT "clock_timestamp"()) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if p_platform_account_id is null or p_now is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  delete from public.platform_account_admin_tags t
  where t.platform_account_id = p_platform_account_id;
  update public.platform_account_admin_notes n
  set body = '[redacted]', redacted_at = coalesce(n.redacted_at, p_now)
  where n.platform_account_id = p_platform_account_id and n.redacted_at is null;
  update public.platform_account_governance_events g
  set reason = '[redacted]'
  where g.platform_account_id = p_platform_account_id and g.reason <> '[redacted]';
end;
$$;


ALTER FUNCTION "private"."account_admin_support_privacy_cleanup"("p_platform_account_id" "uuid", "p_now" timestamp with time zone) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."account_close"("p_ctx" "private"."account_context", "p_recent_proof_id" "uuid") RETURNS TABLE("platform_account_id" "uuid", "account_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_account public.platform_accounts;
  v_session record;
begin
  select * into v_session from private.check_user_session((p_ctx).user_id, (p_ctx).session_id);
  if not coalesce(v_session.active, false) then raise exception using errcode = '42501', message = 'unauthorized'; end if;
  select * into v_account from public.platform_accounts
  where platform_id = (p_ctx).platform_id and user_id = (p_ctx).user_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_account.status = 'closed' then return query select v_account.id, v_account.status; return; end if;
  if p_recent_proof_id is null or not exists (
    select 1 from private.user_recent_auth_proofs proof
    where proof.id = p_recent_proof_id and proof.user_id = (p_ctx).user_id
      and proof.session_id = (p_ctx).session_id and proof.expires_at > now()
      and proof.verified_at <= now() and proof.expires_at <= proof.verified_at + interval '5 minutes'
  ) then raise exception using errcode = '42501', message = 'recent_mfa_required'; end if;
  update public.platform_accounts set status = 'closed', closed_at = coalesce(closed_at, now()) where id = v_account.id;
  perform private.audit_append((p_ctx).request_id, 'user', (p_ctx).user_id, (p_ctx).platform_id,
    v_account.id, 'account.closed', 'platform_account', v_account.id, null, null, '{}'::jsonb);
  return query select v_account.id, 'closed'::text;
end;
$$;


ALTER FUNCTION "private"."account_close"("p_ctx" "private"."account_context", "p_recent_proof_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."account_principal"("p_ctx" "private"."account_context") RETURNS TABLE("ok" boolean, "reason" "text", "user_id" "uuid", "platform_id" "uuid", "platform_status" "text", "platform_account_id" "uuid", "account_status" "text", "authorization" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_session record;
  v_platform record;
  v_account record;
begin
  if (p_ctx).user_id is null or (p_ctx).session_id is null
     or (p_ctx).platform_id is null or (p_ctx).platform_key_id is null then
    return query select false, 'invalid_input', null::uuid, null::uuid, null::text,
      null::uuid, null::text, 'unauthorized';
    return;
  end if;

  select * into v_session
  from private.check_user_session((p_ctx).user_id, (p_ctx).session_id);
  if not coalesce(v_session.active, false) then
    return query select false, v_session.reason, (p_ctx).user_id, (p_ctx).platform_id,
      null::text, null::uuid, null::text, 'unauthorized';
    return;
  end if;

  select p.id, p.status into v_platform
  from public.platforms p
  where p.id = (p_ctx).platform_id
    and exists (
      select 1 from private.platform_api_keys k
      where k.id = (p_ctx).platform_key_id
        and k.platform_id = p.id
        and k.status = 'active'
        and (k.expires_at is null or k.expires_at > now())
    );
  if not found then
    return query select false, 'platform_key_invalid', (p_ctx).user_id, (p_ctx).platform_id,
      null::text, null::uuid, null::text, 'unauthorized';
    return;
  end if;

  select a.id, a.status into v_account
  from public.platform_accounts a
  where a.platform_id = (p_ctx).platform_id
    and a.user_id = (p_ctx).user_id;

  if not found then
    return query select true, 'ok', (p_ctx).user_id, (p_ctx).platform_id, v_platform.status,
      null::uuid, 'not_activated', case when v_platform.status = 'active' then 'not_activated' else 'platform_disabled' end;
    return;
  end if;

  return query select true, 'ok', (p_ctx).user_id, (p_ctx).platform_id, v_platform.status,
    v_account.id, v_account.status,
    case
      when v_platform.status <> 'active' then 'platform_disabled'
      when v_account.status = 'active' then 'allowed'
      when v_account.status = 'suspended' then 'suspended'
      else 'closed'
    end;
end;
$$;


ALTER FUNCTION "private"."account_principal"("p_ctx" "private"."account_context") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."account_principal_presented"("p_user_id" "uuid", "p_session_id" "uuid", "p_platform_key_id" "uuid", "p_key_hmac" "text", "p_hmac_key_version" integer) RETURNS TABLE("key_id" "uuid", "platform_id" "uuid", "platform_status" "text", "ok" boolean, "reason" "text", "user_id" "uuid", "platform_account_id" "uuid", "account_status" "text", "authorization" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_key record;
  v_session record;
  v_account record;
begin
  if p_user_id is null or p_session_id is null
     or p_platform_key_id is null or p_key_hmac is null
     or p_hmac_key_version is null then
    return;
  end if;

  select verified.key_id, verified.platform_id, verified.platform_status
    into v_key
  from private.platform_key_verify_presented(
    p_platform_key_id, p_key_hmac, p_hmac_key_version
  ) verified;
  if not found then
    return;
  end if;

  select * into v_session
  from private.check_user_session(p_user_id, p_session_id);
  if not coalesce(v_session.active, false) then
    return query select v_key.key_id, v_key.platform_id, v_key.platform_status,
      false, v_session.reason, p_user_id, null::uuid, null::text, 'unauthorized'::text;
    return;
  end if;

  select a.id, a.status into v_account
  from public.platform_accounts a
  where a.platform_id = v_key.platform_id
    and a.user_id = p_user_id;

  if not found then
    return query select v_key.key_id, v_key.platform_id, v_key.platform_status,
      true, 'ok', p_user_id, null::uuid, null::text,
      case when v_key.platform_status = 'active' then 'not_activated' else 'platform_disabled' end;
    return;
  end if;

  return query select v_key.key_id, v_key.platform_id, v_key.platform_status,
    true, 'ok', p_user_id, v_account.id, v_account.status,
    case
      when v_key.platform_status <> 'active' then 'platform_disabled'
      when v_account.status = 'active' then 'allowed'
      when v_account.status = 'suspended' then 'suspended'
      else 'closed'
    end;
end;
$$;


ALTER FUNCTION "private"."account_principal_presented"("p_user_id" "uuid", "p_session_id" "uuid", "p_platform_key_id" "uuid", "p_key_hmac" "text", "p_hmac_key_version" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."account_retention_candidates"("p_cutoff" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_account_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("platform_account_id" "uuid", "closed_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_cutoff timestamptz;
begin
  if p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select policy.cutoff_at into v_cutoff
  from private.account_retention_cutoff(p_cutoff) policy;
  return query
    select a.id, a.closed_at
    from public.platform_accounts a
    where a.status = 'closed' and a.user_id is not null
      and a.closed_at is not null
      and a.closed_at <= v_cutoff
      and (p_cursor_account_id is null or a.id > p_cursor_account_id)
    order by a.id
    limit p_limit;
end;
$$;


ALTER FUNCTION "private"."account_retention_candidates"("p_cutoff" timestamp with time zone, "p_cursor_account_id" "uuid", "p_limit" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."account_retention_cleanup"("p_ctx" "private"."job_context", "p_platform_account_id" "uuid", "p_cutoff" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_lease_seconds" integer DEFAULT 60) RETURNS TABLE("platform_account_id" "uuid", "action" "text", "status" "text", "anonymized_at" timestamp with time zone, "fencing_token" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_account public.platform_accounts;
  v_claim record;
  v_now timestamptz := clock_timestamp();
  v_cutoff timestamptz;
  v_retention_days integer;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null or p_platform_account_id is null
     or p_lease_seconds not between 1 and 3600 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select policy.cutoff_at, policy.retention_days into v_cutoff, v_retention_days
  from private.account_retention_cutoff(p_cutoff) policy;
  select * into v_claim from private.job_lease_claim(
    'account_retention', p_platform_account_id, (p_ctx).lease_owner, p_lease_seconds
  );
  if not coalesce(v_claim.claimed, false) then
    return query select p_platform_account_id, 'busy'::text, null::text,
      null::timestamptz, v_claim.fencing_token;
    return;
  end if;
  select * into v_account from public.platform_accounts a
  where a.id = p_platform_account_id for update;
  if not found then
    perform private.job_lease_release('account_retention', p_platform_account_id,
      (p_ctx).lease_owner, v_claim.fencing_token);
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if v_account.status <> 'closed' or v_account.user_id is null
     or v_account.closed_at is null or v_account.closed_at > v_cutoff then
    perform private.job_lease_release('account_retention', p_platform_account_id,
      (p_ctx).lease_owner, v_claim.fencing_token);
    return query select v_account.id, 'skipped'::text, v_account.status,
      v_account.anonymized_at, v_claim.fencing_token;
    return;
  end if;

  perform private.config_account_privacy_cleanup(v_account.id, v_now, 'account_retention_cleanup');
  perform private.feedback_account_privacy_cleanup(v_account.id, v_now, 'account_retention_cleanup');
  perform private.account_admin_support_privacy_cleanup(v_account.id, v_now);
  update public.platform_profiles p
  set display_name = null, avatar_url = null, bio = null, locale = null,
    timezone = null, metadata = '{}'::jsonb
  where p.platform_account_id = v_account.id;
  update public.platform_preferences p set preferences = '{}'::jsonb
  where p.platform_account_id = v_account.id;
  update public.platform_config_files f
  set status = case when f.status = 'deleted' then 'deleted' else 'deleting' end,
    cancel_requested_at = coalesce(f.cancel_requested_at, v_now),
    delete_requested_at = coalesce(f.delete_requested_at, v_now), next_attempt_at = v_now
  where f.platform_account_id = v_account.id and f.status <> 'deleted';
  update public.audit_logs l
  set actor_user_id = null, ip = null, user_agent = null, metadata = '{}'::jsonb
  where l.platform_account_id = v_account.id;
  update public.platform_accounts a
  set user_id = null, anonymized_at = coalesce(a.anonymized_at, v_now),
    status = 'closed', closed_at = coalesce(a.closed_at, v_now)
  where a.id = v_account.id returning * into v_account;
  perform private.audit_append(
    (p_ctx).request_id, 'job', null, v_account.platform_id, v_account.id,
    'account.retention_cleaned', 'platform_account', v_account.id, null, null,
    jsonb_build_object('closed_at', v_account.closed_at,
      'personal_data_retention_days', v_retention_days)
  );
  perform private.job_lease_release('account_retention', p_platform_account_id,
    (p_ctx).lease_owner, v_claim.fencing_token);
  return query select v_account.id, 'cleaned'::text, v_account.status,
    v_account.anonymized_at, v_claim.fencing_token;
end;
$$;


ALTER FUNCTION "private"."account_retention_cleanup"("p_ctx" "private"."job_context", "p_platform_account_id" "uuid", "p_cutoff" timestamp with time zone, "p_lease_seconds" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."account_retention_cutoff"("p_requested_cutoff" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("cutoff_at" timestamp with time zone, "retention_days" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
declare
  v_days integer;
  v_policy_cutoff timestamptz;
begin
  select policy.personal_data_retention_days
    into v_days
  from private.account_retention_policy policy
  where policy.singleton_id;
  if v_days is null then
    raise exception using errcode = 'P0001', message = 'retention_policy_not_configured';
  end if;
  v_policy_cutoff := clock_timestamp() - make_interval(days => v_days);
  return query
    select least(coalesce(p_requested_cutoff, v_policy_cutoff), v_policy_cutoff), v_days;
end;
$$;


ALTER FUNCTION "private"."account_retention_cutoff"("p_requested_cutoff" timestamp with time zone) OWNER TO "domain_owner";












CREATE OR REPLACE FUNCTION "private"."admin_account_list_v3"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_cursor_account_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20, "p_query" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_plan_id" "uuid" DEFAULT NULL::"uuid", "p_subscription_status" "text" DEFAULT NULL::"text", "p_tag" "text" DEFAULT NULL::"text", "p_joined_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_joined_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("platform_account_id" "uuid", "user_id" "uuid", "account_status" "text", "display_name" "text", "avatar_url" "text", "plan_id" "uuid", "plan_code" "text", "plan_name" "text", "plan_kind" "text", "subscription_status" "text", "current_period_end" timestamp with time zone, "tags" "text"[], "activated_at" timestamp with time zone, "suspended_at" timestamp with time zone, "closed_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_query text := nullif(btrim(p_query), '');
  v_tag text := nullif(lower(btrim(p_tag)), '');
  v_cursor_created_at timestamptz;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_limit is null or p_limit not between 1 and 100
     or v_query is not null and length(v_query) > 128
     or p_status is not null and p_status not in ('active', 'suspended', 'closed')
     or p_subscription_status is not null and p_subscription_status not in ('active', 'suspended', 'none')
     or v_tag is not null and (length(v_tag) > 32 or v_tag ~ '[[:cntrl:]]')
     or p_joined_from is not null and p_joined_to is not null and p_joined_from > p_joined_to then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from public.platforms p where p.id = p_platform_id) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if p_cursor_account_id is not null then
    select a.created_at into v_cursor_created_at
    from public.platform_accounts a
    where a.platform_id = p_platform_id and a.id = p_cursor_account_id;
    if v_cursor_created_at is null then
      raise exception using errcode = 'P0002', message = 'resource_not_found';
    end if;
  end if;

  return query
  select a.id, a.user_id, a.status, pr.display_name, pr.avatar_url,
    pl.id, pl.code, pl.name, pl.kind, coalesce(s.status, 'none'::text),
    s.current_period_end,
    coalesce((
      select array_agg(t.tag order by t.tag)
      from public.platform_account_admin_tags t
      where t.platform_id = a.platform_id and t.platform_account_id = a.id
    ), '{}'::text[]),
    a.activated_at, a.suspended_at, a.closed_at, a.created_at, a.updated_at
  from public.platform_accounts a
  join public.platforms platform on platform.id = a.platform_id
  left join public.platform_profiles pr on pr.platform_account_id = a.id
  left join public.subscriptions s
    on s.platform_id = a.platform_id and s.platform_account_id = a.id
  left join public.plans pl
    on pl.platform_id = a.platform_id
   and pl.id = case
     when s.status = 'suspended' then null::uuid
     when s.plan_id is not null then s.plan_id
     else platform.default_plan_id
   end
   and (s.plan_id is not null or (pl.status = 'active' and pl.kind = 'free'))
  where a.platform_id = p_platform_id
    and (v_query is null
      or a.id::text ilike '%' || v_query || '%'
      or coalesce(a.user_id::text, '') ilike '%' || v_query || '%'
      or a.status ilike '%' || v_query || '%'
      or coalesce(pr.display_name, '') ilike '%' || v_query || '%'
      or coalesce(pl.name, '') ilike '%' || v_query || '%'
      or coalesce(pl.code, '') ilike '%' || v_query || '%')
    and (p_status is null or a.status = p_status)
    and (p_plan_id is null or pl.id = p_plan_id)
    and (p_subscription_status is null
      or p_subscription_status = 'none' and s.id is null
      or p_subscription_status in ('active', 'suspended') and s.status = p_subscription_status)
    and (v_tag is null or exists (
      select 1 from public.platform_account_admin_tags t
      where t.platform_id = a.platform_id and t.platform_account_id = a.id and t.tag = v_tag
    ))
    and (p_joined_from is null or a.created_at >= p_joined_from)
    and (p_joined_to is null or a.created_at <= p_joined_to)
    and (p_cursor_account_id is null or (a.created_at, a.id) < (v_cursor_created_at, p_cursor_account_id))
  order by a.created_at desc, a.id desc
  limit p_limit;
end;
$$;


ALTER FUNCTION "private"."admin_account_list_v3"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_cursor_account_id" "uuid", "p_limit" integer, "p_query" "text", "p_status" "text", "p_plan_id" "uuid", "p_subscription_status" "text", "p_tag" "text", "p_joined_from" timestamp with time zone, "p_joined_to" timestamp with time zone) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_account_note_add"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_body" "text") RETURNS TABLE("note_id" "uuid", "platform_account_id" "uuid", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_note public.platform_account_admin_notes;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_platform_account_id is null or p_body is null
     or length(btrim(p_body)) not between 1 and 2000 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from public.platform_accounts a
    where a.platform_id = p_platform_id and a.id = p_platform_account_id) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  insert into public.platform_account_admin_notes(platform_id, platform_account_id, body, created_by)
  values (p_platform_id, p_platform_account_id, btrim(p_body), (p_ctx).admin_user_id)
  returning * into v_note;
  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, p_platform_id, p_platform_account_id,
    'account.note_added', 'platform_account', p_platform_account_id, null, null,
    jsonb_build_object('note_id', v_note.id)
  );
  return query select v_note.id, v_note.platform_account_id, v_note.created_at;
end;
$$;


ALTER FUNCTION "private"."admin_account_note_add"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_body" "text") OWNER TO "domain_owner";







CREATE OR REPLACE FUNCTION "private"."admin_account_tags_replace"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_tags" "text"[]) RETURNS TABLE("platform_account_id" "uuid", "tags" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_tags text[];
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_platform_account_id is null or p_tags is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from public.platform_accounts a
    where a.platform_id = p_platform_id and a.id = p_platform_account_id) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  select coalesce(array_agg(tag order by tag), '{}'::text[]) into v_tags
  from (select distinct lower(btrim(raw_tag)) as tag from unnest(p_tags) raw_tag) normalized;
  if cardinality(v_tags) > 20 or exists (
    select 1 from unnest(v_tags) tag where length(tag) not between 1 and 32 or tag ~ '[[:cntrl:]]'
  ) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  delete from public.platform_account_admin_tags t
  where t.platform_id = p_platform_id and t.platform_account_id = p_platform_account_id;
  insert into public.platform_account_admin_tags(platform_id, platform_account_id, tag, created_by)
  select p_platform_id, p_platform_account_id, tag, (p_ctx).admin_user_id from unnest(v_tags) tag;
  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, p_platform_id, p_platform_account_id,
    'account.tags_replaced', 'platform_account', p_platform_account_id, null, null,
    jsonb_build_object('tag_count', cardinality(v_tags))
  );
  return query select p_platform_account_id, v_tags;
end;
$$;


ALTER FUNCTION "private"."admin_account_tags_replace"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_tags" "text"[]) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_account_transition"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_action" "text", "p_reason" "text") RETURNS TABLE("platform_account_id" "uuid", "status" "text", "governance_event_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_account public.platform_accounts;
  v_event public.platform_account_governance_events;
  v_reason text := btrim(p_reason);
  v_before_status text;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_platform_account_id is null
     or p_action not in ('suspend', 'restore', 'close')
     or p_reason is null or length(v_reason) not between 1 and 2000
     or (p_ctx).request_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  select * into v_account
  from public.platform_accounts a
  where a.platform_id = p_platform_id and a.id = p_platform_account_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;

  v_before_status := v_account.status;
  if p_action = 'suspend' then
    if v_before_status <> 'active' then
      raise exception using errcode = 'P0001', message = 'invalid_account_transition';
    end if;
    update public.platform_accounts a
    set status = 'suspended', suspended_at = clock_timestamp()
    where a.id = v_account.id
    returning * into v_account;
  elsif p_action = 'restore' then
    if v_before_status <> 'suspended' then
      raise exception using errcode = 'P0001', message = 'invalid_account_transition';
    end if;
    update public.platform_accounts a
    set status = 'active', suspended_at = null
    where a.id = v_account.id
    returning * into v_account;
  else
    if v_before_status not in ('active', 'suspended') then
      raise exception using errcode = 'P0001', message = 'invalid_account_transition';
    end if;
    update public.platform_accounts a
    set status = 'closed', closed_at = coalesce(closed_at, clock_timestamp())
    where a.id = v_account.id
    returning * into v_account;
  end if;

  insert into public.platform_account_governance_events(
    platform_id, platform_account_id, action, reason, actor_admin_user_id,
    before_status, after_status, operation_id
  ) values (
    p_platform_id, p_platform_account_id, p_action, v_reason, (p_ctx).admin_user_id,
    v_before_status, v_account.status, (p_ctx).request_id
  ) returning * into v_event;

  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, p_platform_id,
    p_platform_account_id, 'account.' || p_action, 'platform_account',
    p_platform_account_id, null, null,
    jsonb_build_object(
      'governance_event_id', v_event.id,
      'action', p_action,
      'before_status', v_before_status,
      'after_status', v_account.status
    )
  );
  return query select v_account.id, v_account.status, v_event.id;
end;
$$;


ALTER FUNCTION "private"."admin_account_transition"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_action" "text", "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_account_workbench_read"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid") RETURNS TABLE("platform_account_id" "uuid", "user_id" "uuid", "account_status" "text", "activated_at" timestamp with time zone, "suspended_at" timestamp with time zone, "closed_at" timestamp with time zone, "anonymized_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "display_name" "text", "avatar_url" "text", "bio" "text", "locale" "text", "timezone" "text", "plan_id" "uuid", "plan_code" "text", "plan_name" "text", "plan_kind" "text", "subscription_status" "text", "subscription_started_at" timestamp with time zone, "current_period_end" timestamp with time zone, "next_transition_at" timestamp with time zone, "billing_order_count" bigint, "billing_attention_count" bigint, "billing_latest" "jsonb", "config_active_count" bigint, "config_published_count" bigint, "config_pending_review_count" bigint, "config_latest_updated_at" timestamp with time zone, "feedback_count" bigint, "feedback_open_count" bigint, "feedback_latest_submitted_at" timestamp with time zone, "tags" "text"[], "notes" "jsonb", "governance_events" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_platform_account_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (
    select 1 from public.platform_accounts a
    where a.platform_id = p_platform_id and a.id = p_platform_account_id
  ) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;

  return query
  select a.id, a.user_id, a.status, a.activated_at, a.suspended_at, a.closed_at,
    a.anonymized_at, a.created_at, a.updated_at,
    pr.display_name, pr.avatar_url, pr.bio, pr.locale, pr.timezone,
    pl.id, pl.code, pl.name, pl.kind, coalesce(s.status, 'none'::text),
    s.started_at, s.current_period_end, s.next_transition_at,
    (select count(*) from public.billing_orders bo
      where bo.platform_id = a.platform_id and bo.platform_account_id = a.id),
    (select count(*) from public.billing_orders bo
      left join public.billing_settlements bs on bs.billing_order_id = bo.id
      where bo.platform_id = a.platform_id and bo.platform_account_id = a.id
        and bo.resolution_status = 'open'
        and (bo.verification_status <> 'verified'
          or bo.entitlement_status in ('not_started', 'blocked')
          or bo.linkage_status <> 'linked'
          or bs.state in ('retryable', 'blocked', 'review_required'))),
    coalesce((select jsonb_build_object(
        'order_id', bo.id,
        'provider_status', bo.provider_status,
        'verification_status', bo.verification_status,
        'entitlement_status', bo.entitlement_status,
        'linkage_status', bo.linkage_status,
        'resolution_status', bo.resolution_status,
        'settlement_state', bs.state,
        'updated_at', bo.updated_at
      )
      from public.billing_orders bo
      left join public.billing_settlements bs on bs.billing_order_id = bo.id
      where bo.platform_id = a.platform_id and bo.platform_account_id = a.id
      order by bo.updated_at desc, bo.id desc limit 1), '{}'::jsonb),
    (select count(*) from public.platform_configs c
      where c.platform_id = a.platform_id and c.platform_account_id = a.id and c.status = 'active'),
    (select count(*) from public.platform_configs c
      join public.platform_config_gallery_entries ge
        on ge.platform_id = c.platform_id and ge.config_id = c.id and ge.status = 'approved'
      where c.platform_id = a.platform_id and c.platform_account_id = a.id),
    (select count(*) from public.platform_config_gallery_submissions gs
      where gs.platform_id = a.platform_id and gs.submitted_by_account_id = a.id and gs.status = 'pending'),
    (select max(c.updated_at) from public.platform_configs c
      where c.platform_id = a.platform_id and c.platform_account_id = a.id and c.status <> 'deleted'),
    (select count(*) from public.platform_feedback f
      where f.platform_id = a.platform_id and f.platform_account_id = a.id and f.status not in ('draft', 'deleted')),
    (select count(*) from public.platform_feedback f
      where f.platform_id = a.platform_id and f.platform_account_id = a.id and f.status in ('new', 'reviewing')),
    (select max(f.submitted_at) from public.platform_feedback f
      where f.platform_id = a.platform_id and f.platform_account_id = a.id and f.status not in ('draft', 'deleted')),
    coalesce((select array_agg(t.tag order by t.tag)
      from public.platform_account_admin_tags t
      where t.platform_id = a.platform_id and t.platform_account_id = a.id), '{}'::text[]),
    coalesce((select jsonb_agg(jsonb_build_object(
        'id', n.id, 'body', n.body, 'created_by', n.created_by,
        'created_at', n.created_at, 'redacted_at', n.redacted_at
      ) order by n.created_at desc, n.id desc)
      from (select * from public.platform_account_admin_notes nx
        where nx.platform_id = a.platform_id and nx.platform_account_id = a.id
        order by nx.created_at desc, nx.id desc limit 20) n), '[]'::jsonb),
    coalesce((select jsonb_agg(jsonb_build_object(
        'id', g.id, 'action', g.action, 'reason', g.reason,
        'actor_admin_user_id', g.actor_admin_user_id, 'created_at', g.created_at
      ) order by g.created_at desc, g.id desc)
      from (select * from public.platform_account_governance_events gx
        where gx.platform_id = a.platform_id and gx.platform_account_id = a.id
        order by gx.created_at desc, gx.id desc limit 50) g), '[]'::jsonb)
  from public.platform_accounts a
  join public.platforms platform on platform.id = a.platform_id
  left join public.platform_profiles pr on pr.platform_account_id = a.id
  left join public.subscriptions s
    on s.platform_id = a.platform_id and s.platform_account_id = a.id
  left join public.plans pl
    on pl.platform_id = a.platform_id
   and pl.id = case
     when s.status = 'suspended' then null::uuid
     when s.plan_id is not null then s.plan_id
     else platform.default_plan_id
   end
   and (s.plan_id is not null or (pl.status = 'active' and pl.kind = 'free'))
  where a.platform_id = p_platform_id and a.id = p_platform_account_id;
end;
$$;


ALTER FUNCTION "private"."admin_account_workbench_read"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid") OWNER TO "domain_owner";







CREATE OR REPLACE FUNCTION "private"."admin_audit_list_v2"("p_ctx" "private"."admin_context", "p_cursor_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20, "p_query" "text" DEFAULT NULL::"text", "p_platform_id" "uuid" DEFAULT NULL::"uuid", "p_actor_query" "text" DEFAULT NULL::"text", "p_action" "text" DEFAULT NULL::"text", "p_target_type" "text" DEFAULT NULL::"text", "p_outcome" "text" DEFAULT NULL::"text") RETURNS TABLE("audit_id" "uuid", "request_id" "uuid", "platform_id" "uuid", "platform_name" "text", "platform_code" "text", "platform_account_id" "uuid", "actor_type" "text", "actor_id" "uuid", "actor_display_name" "text", "actor_email" "text", "event_type" "text", "target_type" "text", "target_id" "uuid", "outcome" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_cursor_created_at timestamptz;
  v_query text := nullif(btrim(p_query), '');
  v_actor_query text := nullif(btrim(p_actor_query), '');
  v_action text := nullif(btrim(p_action), '');
  v_target_type text := nullif(btrim(p_target_type), '');
  v_outcome text := nullif(btrim(p_outcome), '');
begin
  if (p_ctx).admin_user_id is null or (p_ctx).session_id is null
     or p_limit is null or p_limit not between 1 and 100
     or (p_query is not null and length(btrim(p_query)) > 128)
     or (p_actor_query is not null and length(btrim(p_actor_query)) > 128)
     or (p_action is not null and length(btrim(p_action)) > 128)
     or (p_target_type is not null and length(btrim(p_target_type)) > 128)
     or (p_outcome is not null and length(btrim(p_outcome)) > 64)
     or not exists (
       select 1 from private.system_admin sa
       where sa.user_id = (p_ctx).admin_user_id
     )
     or not exists (
       select 1
       from private.check_user_session(
         (p_ctx).admin_user_id,
         (p_ctx).session_id
       )
       where active
     ) then
    raise exception using
      errcode = case
        when p_limit is null or p_limit not between 1 and 100
          or (p_query is not null and length(btrim(p_query)) > 128)
          or (p_actor_query is not null and length(btrim(p_actor_query)) > 128)
          or (p_action is not null and length(btrim(p_action)) > 128)
          or (p_target_type is not null and length(btrim(p_target_type)) > 128)
          or (p_outcome is not null and length(btrim(p_outcome)) > 64)
          then '22023'
        else '42501'
      end,
      message = case
        when p_limit is null or p_limit not between 1 and 100
          or (p_query is not null and length(btrim(p_query)) > 128)
          or (p_actor_query is not null and length(btrim(p_actor_query)) > 128)
          or (p_action is not null and length(btrim(p_action)) > 128)
          or (p_target_type is not null and length(btrim(p_target_type)) > 128)
          or (p_outcome is not null and length(btrim(p_outcome)) > 64)
          then 'invalid_input'
        else 'admin_required'
      end;
  end if;

  if p_cursor_id is not null then
    select a.created_at into v_cursor_created_at
    from public.audit_logs a
    where a.id = p_cursor_id;
    if v_cursor_created_at is null then
      raise exception using errcode = 'P0002', message = 'resource_not_found';
    end if;
  end if;

  return query
    with enriched as (
      select
        a.id as audit_id,
        a.request_id,
        a.platform_id,
        p.name as platform_name,
        p.code as platform_code,
        a.platform_account_id,
        a.actor_type,
        a.actor_user_id as actor_id,
        case
          when a.actor_type = 'user' and actor_account.user_id = a.actor_user_id
            then nullif(actor_profile.display_name, '')
          else null
        end as actor_display_name,
        private.audit_actor_email(a.actor_user_id) as actor_email,
        a.event_type,
        a.target_type,
        a.target_id,
        nullif(a.metadata ->> 'outcome', '') as outcome,
        a.created_at
      from public.audit_logs a
      left join public.platforms p
        on p.id = a.platform_id
      left join public.platform_accounts actor_account
        on a.actor_type = 'user'
       and actor_account.id = a.platform_account_id
       and actor_account.platform_id = a.platform_id
       and actor_account.user_id = a.actor_user_id
      left join public.platform_profiles actor_profile
        on actor_profile.platform_account_id = actor_account.id
      where (p_cursor_id is null
        or (a.created_at, a.id) < (v_cursor_created_at, p_cursor_id))
        and (p_platform_id is null or a.platform_id = p_platform_id)
        and (v_action is null or a.event_type = v_action)
        and (v_target_type is null or a.target_type = v_target_type)
        and (
          v_outcome is null
          or (lower(v_outcome) = 'unrecorded'
            and nullif(a.metadata ->> 'outcome', '') is null)
          or (lower(v_outcome) <> 'unrecorded'
            and lower(nullif(a.metadata ->> 'outcome', '')) = lower(v_outcome))
        )
    )
    select
      e.audit_id,
      e.request_id,
      e.platform_id,
      e.platform_name,
      e.platform_code,
      e.platform_account_id,
      e.actor_type,
      e.actor_id,
      e.actor_display_name,
      e.actor_email,
      e.event_type,
      e.target_type,
      e.target_id,
      e.outcome,
      e.created_at
    from enriched e
    where (
      v_actor_query is null
      or e.actor_type ilike '%' || v_actor_query || '%'
      or e.actor_id::text ilike '%' || v_actor_query || '%'
      or e.actor_display_name ilike '%' || v_actor_query || '%'
      or e.actor_email ilike '%' || v_actor_query || '%'
    ) and (
      v_query is null
      or e.audit_id::text ilike '%' || v_query || '%'
      or e.request_id::text ilike '%' || v_query || '%'
      or e.platform_id::text ilike '%' || v_query || '%'
      or e.platform_name ilike '%' || v_query || '%'
      or e.platform_code ilike '%' || v_query || '%'
      or e.platform_account_id::text ilike '%' || v_query || '%'
      or e.actor_type ilike '%' || v_query || '%'
      or e.actor_id::text ilike '%' || v_query || '%'
      or e.actor_display_name ilike '%' || v_query || '%'
      or e.actor_email ilike '%' || v_query || '%'
      or e.event_type ilike '%' || v_query || '%'
      or e.target_type ilike '%' || v_query || '%'
      or e.target_id::text ilike '%' || v_query || '%'
      or e.outcome ilike '%' || v_query || '%'
    )
    order by e.created_at desc, e.audit_id desc
    limit p_limit;
end;
$$;


ALTER FUNCTION "private"."admin_audit_list_v2"("p_ctx" "private"."admin_context", "p_cursor_id" "uuid", "p_limit" integer, "p_query" "text", "p_platform_id" "uuid", "p_actor_query" "text", "p_action" "text", "p_target_type" "text", "p_outcome" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_batch_confirm"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_batch_id" "uuid", "p_receipt_hmac" "text") RETURNS TABLE("batch_id" "uuid", "status" "text", "delivered_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
  select * from private.admin_batch_confirm_candidates(
    p_ctx, p_platform_id, p_batch_id, array[p_receipt_hmac]
  );
$$;


ALTER FUNCTION "private"."admin_batch_confirm"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_batch_id" "uuid", "p_receipt_hmac" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_batch_confirm_candidates"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_batch_id" "uuid", "p_receipt_hmacs" "text"[]) RETURNS TABLE("batch_id" "uuid", "status" "text", "delivered_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_batch public.redemption_code_batches;
begin
  if p_receipt_hmacs is null
     or coalesce(array_length(p_receipt_hmacs, 1), 0) not between 1 and 2
     or exists (
       select 1 from unnest(p_receipt_hmacs) as candidate(value)
       where candidate.value is null or length(candidate.value) <> 64
     ) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (
       select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id)
       where active
     ) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;
  select * into v_batch from public.redemption_code_batches b
  where b.platform_id = p_platform_id and b.id = p_batch_id for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if v_batch.status = 'disabled' then
    raise exception using errcode = 'P0001', message = 'batch_disabled';
  end if;
  if v_batch.status = 'active' then
    return query select v_batch.id, v_batch.status, v_batch.delivered_at;
    return;
  end if;
  if v_batch.delivery_session_id <> (p_ctx).session_id
     or not (v_batch.delivery_receipt_hmac = any(p_receipt_hmacs))
     or v_batch.delivery_deadline <= clock_timestamp() then
    raise exception using errcode = '42501', message = 'delivery_confirmation_invalid';
  end if;
  update public.redemption_code_batches b
  set status = 'active', delivered_at = clock_timestamp(),
      delivery_confirmed_by = (p_ctx).admin_user_id
  where b.id = v_batch.id
  returning b.id, b.status, b.delivered_at into batch_id, status, delivered_at;
  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, p_platform_id, null,
    'redemption.batch_confirmed', 'redemption_code_batch', batch_id, null, null, '{}'::jsonb
  );
  return next;
end;
$$;


ALTER FUNCTION "private"."admin_batch_confirm_candidates"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_batch_id" "uuid", "p_receipt_hmacs" "text"[]) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_batch_disable"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_batch_id" "uuid") RETURNS TABLE("batch_id" "uuid", "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_batch public.redemption_code_batches;
begin
  if not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;
  select * into v_batch from public.redemption_code_batches b
  where b.platform_id = p_platform_id and b.id = p_batch_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  update public.redemption_code_batches b set status = 'disabled' where b.id = v_batch.id
  returning b.id, b.status into batch_id, status;
  perform private.audit_append((p_ctx).request_id, 'admin', (p_ctx).admin_user_id, p_platform_id, null,
    'redemption.batch_disabled', 'redemption_code_batch', batch_id, null, null, '{}'::jsonb);
  return next;
end;
$$;


ALTER FUNCTION "private"."admin_batch_disable"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_batch_id" "uuid") OWNER TO "domain_owner";







CREATE OR REPLACE FUNCTION "private"."admin_billing_observability"("p_ctx" "private"."admin_context") RETURNS TABLE("observed_at" timestamp with time zone, "pending_count" bigint, "processing_count" bigint, "retryable_count" bigint, "completed_count" bigint, "manual_review_count" bigint, "oldest_pending_age_seconds" numeric, "oldest_processing_age_seconds" numeric, "expired_lease_count" bigint, "retry_attempts_total" bigint, "retry_budget_exhausted_count" bigint, "duplicate_payment_count" bigint, "refund_mismatch_count" bigint, "discovery_last_success_at" timestamp with time zone, "processing_last_success_at" timestamp with time zone, "discovery_lag_seconds" numeric, "processing_lag_seconds" numeric, "scheduler_last_accepted_at" timestamp with time zone, "scheduler_last_completed_at" timestamp with time zone, "scheduler_failure_count" bigint, "active_alert_count" bigint, "pending_alert_delivery_count" bigint, "alert_thresholds" "jsonb", "alert_threshold_source" "text", "alerts" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.billing_admin_assert(p_ctx);
  return query
    select m.*,
      (select count(*)::bigint from private.billing_operational_alerts where status = 'active'),
      (select count(*)::bigint from private.billing_operational_alerts where delivery_status in ('pending', 'failed')),
      private.billing_alert_threshold_defaults(),
      'local_default'::text,
      coalesce((select jsonb_agg(jsonb_build_object(
        'alert_id', a.id, 'alert_key', a.alert_key, 'severity', a.severity,
        'status', a.status, 'occurrence_count', a.occurrence_count,
        'first_seen_at', a.first_seen_at, 'last_seen_at', a.last_seen_at,
        'recovered_at', a.recovered_at, 'delivery_status', a.delivery_status,
        'delivery_attempts', a.delivery_attempts, 'last_delivery_error', a.last_delivery_error,
        'details', a.details
      ) order by case a.severity when 'critical' then 1 when 'high' then 2 else 3 end, a.last_seen_at desc)
      from private.billing_operational_alerts a where a.status = 'active'), '[]'::jsonb)
    from private.billing_observability_snapshot() m;
end;
$$;


ALTER FUNCTION "private"."admin_billing_observability"("p_ctx" "private"."admin_context") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_billing_order_list_v2"("p_ctx" "private"."admin_context", "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50, "p_status" "text" DEFAULT NULL::"text", "p_platform_id" "uuid" DEFAULT NULL::"uuid", "p_platform_account_id" "uuid" DEFAULT NULL::"uuid", "p_provider_account_id" "uuid" DEFAULT NULL::"uuid", "p_query" "text" DEFAULT NULL::"text") RETURNS TABLE("order_id" "uuid", "provider" "text", "provider_order_no" "text", "platform_id" "uuid", "platform_account_id" "uuid", "checkout_intent_id" "uuid", "provider_status" "text", "verification_status" "text", "entitlement_status" "text", "linkage_status" "text", "resolution_status" "text", "settlement_state" "text", "settlement_kind" "text", "decision_code" "text", "admin_version" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.billing_admin_assert(p_ctx);
  if p_limit is null or p_limit not between 1 and 100
     or (p_cursor is null and p_cursor_id is not null)
     or (p_cursor is not null and p_cursor_id is null)
     or (p_status is not null and p_status not in (
       'pending', 'retryable', 'manual_review', 'finalized', 'granted',
       'rejected', 'unlinked'
     ))
     or (p_query is not null and length(p_query) > 128) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  return query
    select o.id, pa.provider, o.provider_order_no, o.platform_id,
      o.platform_account_id, o.checkout_intent_id, o.provider_status,
      o.verification_status, o.entitlement_status, o.linkage_status,
      o.resolution_status, s.state, s.settlement_kind, s.decision_code,
      o.admin_version, o.created_at, o.updated_at
    from public.billing_orders o
    join public.billing_provider_accounts pa on pa.id = o.provider_account_id
    left join public.billing_settlements s on s.billing_order_id = o.id
    where (
        p_cursor is null
        or (o.created_at, o.id) < (p_cursor, p_cursor_id)
      )
      and (p_platform_id is null or o.platform_id = p_platform_id)
      and (
        p_platform_account_id is null
        or o.platform_account_id = p_platform_account_id
      )
      and (
        p_provider_account_id is null
        or o.provider_account_id = p_provider_account_id
      )
      and (
        p_query is null
        or o.provider_order_no ilike '%' || p_query || '%'
      )
      and (
        p_status is null
        or p_status = coalesce(s.state, o.entitlement_status)
        or (p_status = 'manual_review' and exists (
          select 1
          from public.billing_processing_jobs j
          where j.billing_order_id = o.id and j.state = 'manual_review'
        ))
        or (p_status = 'unlinked' and o.linkage_status = 'unlinked')
      )
    order by o.created_at desc, o.id desc
    limit p_limit;
end;
$$;


ALTER FUNCTION "private"."admin_billing_order_list_v2"("p_ctx" "private"."admin_context", "p_cursor" timestamp with time zone, "p_cursor_id" "uuid", "p_limit" integer, "p_status" "text", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_provider_account_id" "uuid", "p_query" "text") OWNER TO "domain_owner";







CREATE OR REPLACE FUNCTION "private"."admin_billing_order_read_v2"("p_ctx" "private"."admin_context", "p_order_id" "uuid") RETURNS TABLE("order_id" "uuid", "provider" "text", "provider_order_no" "text", "provider_user_id" "text", "external_plan_id" "text", "external_sku_ids" "text"[], "product_type" "text", "purchase_months" integer, "total_amount" numeric, "show_amount" numeric, "currency" "text", "provider_facts" "jsonb", "platform_id" "uuid", "platform_account_id" "uuid", "checkout_intent_id" "uuid", "custom_order_id" "text", "provider_status" "text", "verification_status" "text", "verification_reason" "text", "entitlement_status" "text", "linkage_status" "text", "resolution_status" "text", "resolution_reason" "text", "settlement_id" "uuid", "settlement_state" "text", "settlement_kind" "text", "decision_code" "text", "grant_id" "uuid", "admin_version" bigint, "open_job_count" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "timeline" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_order public.billing_orders;
  v_timeline jsonb;
begin
  perform private.billing_admin_assert(p_ctx);

  select o.* into v_order
  from public.billing_orders o
  where o.id = p_order_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;

  select coalesce(jsonb_agg(t.item order by t.event_at, t.source, t.entity_id), '[]'::jsonb)
    into v_timeline
  from (
    select
      v_order.created_at as event_at,
      'billing_order'::text as source,
      v_order.id::text as entity_id,
      jsonb_build_object(
        'source', 'billing_order',
        'event_type', 'order.created',
        'event_at', v_order.created_at,
        'provider_event_at', v_order.provider_created_at,
        'received_at', null::timestamptz,
        'entity_id', v_order.id,
        'status', v_order.provider_status,
        'state', v_order.entitlement_status,
        'code', null::text,
        'request_id', null::uuid,
        'job_id', null::uuid,
        'actor_type', null::text,
        'actor_id', null::uuid,
        'details', jsonb_build_object(
          'verification_status', v_order.verification_status,
          'linkage_status', v_order.linkage_status,
          'resolution_status', v_order.resolution_status,
          'provider_paid_at', v_order.provider_paid_at
        )
      ) as item

    union all

    select c.created_at, 'checkout', c.id::text,
      jsonb_build_object(
        'source', 'checkout',
        'event_type', 'checkout.created',
        'event_at', c.created_at,
        'provider_event_at', null::timestamptz,
        'received_at', null::timestamptz,
        'entity_id', c.id,
        'status', c.status,
        'state', null::text,
        'code', null::text,
        'request_id', null::uuid,
        'job_id', null::uuid,
        'actor_type', null::text,
        'actor_id', null::uuid,
        'details', jsonb_build_object(
          'offer_code', c.offer_code_snapshot,
          'price_amount', c.price_amount,
          'currency', c.currency,
          'paid_at', c.paid_at,
          'granted_at', c.granted_at
        )
      )
    from public.billing_checkout_intents c
    where c.id = v_order.checkout_intent_id

    union all

    select e.received_at, 'provider_webhook', e.id::text,
      jsonb_build_object(
        'source', 'provider_webhook',
        'event_type', 'webhook.received',
        'event_at', e.received_at,
        'provider_event_at', null::timestamptz,
        'received_at', e.received_at,
        'entity_id', e.id,
        'status', e.processing_status,
        'state', e.signature_status,
        'code', e.error_code,
        'request_id', null::uuid,
        'job_id', null::uuid,
        'actor_type', null::text,
        'actor_id', null::uuid,
        'details', jsonb_build_object(
          'provider_event_key', e.provider_event_key,
          'provider_order_no', e.provider_order_no,
          'signature_status', e.signature_status,
          'processed_at', e.processed_at
        )
      )
    from public.billing_webhook_events e
    where e.provider_account_id = v_order.provider_account_id
      and e.provider_order_no = v_order.provider_order_no

    union all

    select coalesce(j.updated_at, j.created_at), 'processing_job', j.id::text,
      jsonb_build_object(
        'source', 'processing_job',
        'event_type', 'job.' || j.job_kind,
        'event_at', coalesce(j.updated_at, j.created_at),
        'provider_event_at', null::timestamptz,
        'received_at', j.created_at,
        'entity_id', j.id,
        'status', j.state,
        'state', j.job_kind,
        'code', coalesce(j.error_code, j.last_error_code),
        'request_id', null::uuid,
        'job_id', j.id,
        'actor_type', 'job',
        'actor_id', null::uuid,
        'details', jsonb_build_object(
          'attempts', j.attempts,
          'retry_attempts', j.retry_attempts,
          'requeue_count', j.requeue_count,
          'fence', j.fence,
          'webhook_event_id', j.webhook_event_id,
          'dead_lettered_at', j.dead_lettered_at
        )
      )
    from public.billing_processing_jobs j
    where j.billing_order_id = v_order.id

    union all

    select o.observed_at, 'provider_observation', o.id::text,
      jsonb_build_object(
        'source', 'provider_observation',
        'event_type', 'provider.observed',
        'event_at', o.observed_at,
        'provider_event_at', null::timestamptz,
        'received_at', null::timestamptz,
        'entity_id', o.id,
        'status', o.provider_status,
        'state', o.source,
        'code', null::text,
        'request_id', null::uuid,
        'job_id', o.processing_job_id,
        'actor_type', 'job',
        'actor_id', null::uuid,
        'details', jsonb_build_object(
          'provider_contract_version', o.provider_contract_version
        )
      )
    from public.billing_order_observations o
    where o.billing_order_id = v_order.id

    union all

    select s.updated_at, 'settlement', s.id::text,
      jsonb_build_object(
        'source', 'settlement',
        'event_type', 'settlement.updated',
        'event_at', s.updated_at,
        'provider_event_at', null::timestamptz,
        'received_at', s.created_at,
        'entity_id', s.id,
        'status', s.state,
        'state', s.settlement_kind,
        'code', s.decision_code,
        'request_id', s.operation_id,
        'job_id', null::uuid,
        'actor_type', case when s.settlement_kind = 'manual' then 'admin' else 'system' end,
        'actor_id', null::uuid,
        'details', jsonb_build_object(
          'billing_order_id', s.billing_order_id,
          'checkout_intent_id', s.checkout_intent_id,
          'grant_id', s.grant_id,
          'decision_reason', s.decision_reason
        )
      )
    from public.billing_settlements s
    where s.billing_order_id = v_order.id

    union all

    select g.created_at, 'entitlement', g.id::text,
      jsonb_build_object(
        'source', 'entitlement',
        'event_type', 'grant.created',
        'event_at', g.created_at,
        'provider_event_at', null::timestamptz,
        'received_at', null::timestamptz,
        'entity_id', g.id,
        'status', g.source,
        'state', case when g.ends_at is null or g.ends_at > current_timestamp then 'active' else 'expired' end,
        'code', null::text,
        'request_id', g.operation_id,
        'job_id', null::uuid,
        'actor_type', case when g.source = 'admin' then 'admin' else 'system' end,
        'actor_id', g.created_by,
        'details', jsonb_build_object(
          'plan_id', g.plan_id,
          'billing_order_id', g.billing_order_id,
          'starts_at', g.starts_at,
          'ends_at', g.ends_at,
          'reason', g.reason
        )
      )
    from public.subscription_grants g
    where g.billing_order_id = v_order.id

    union all

    select e.created_at, 'entitlement', e.id::text,
      jsonb_build_object(
        'source', 'entitlement',
        'event_type', 'subscription.' || e.event_type,
        'event_at', e.created_at,
        'provider_event_at', null::timestamptz,
        'received_at', null::timestamptz,
        'entity_id', e.id,
        'status', e.event_type,
        'state', null::text,
        'code', null::text,
        'request_id', e.operation_id,
        'job_id', null::uuid,
        'actor_type', case when e.actor_user_id is null then 'system' else 'admin' end,
        'actor_id', e.actor_user_id,
        'details', jsonb_build_object(
          'sequence', e.sequence,
          'subscription_id', e.subscription_id,
          'grant_id', e.grant_id,
          'reason', e.reason
        )
      )
    from public.subscription_events e
    where e.platform_id = v_order.platform_id
      and e.platform_account_id = v_order.platform_account_id
      and e.grant_id in (
        select g.id from public.subscription_grants g
        where g.billing_order_id = v_order.id
      )

    union all

    select c.created_at, 'entitlement_correction', c.id::text,
      jsonb_build_object(
        'source', 'entitlement_correction',
        'event_type', 'grant.corrected',
        'event_at', c.created_at,
        'provider_event_at', null::timestamptz,
        'received_at', null::timestamptz,
        'entity_id', c.id,
        'status', 'applied',
        'state', null::text,
        'code', null::text,
        'request_id', c.operation_id,
        'job_id', null::uuid,
        'actor_type', 'admin',
        'actor_id', c.created_by,
        'details', jsonb_build_object(
          'original_grant_id', c.original_grant_id,
          'replacement_grant_id', c.replacement_grant_id,
          'expected_event_sequence', c.expected_event_sequence,
          'reason', c.reason
        )
      )
    from public.subscription_grant_corrections c
    where c.platform_id = v_order.platform_id
      and c.platform_account_id = v_order.platform_account_id
      and (
        c.original_grant_id in (
          select g.id from public.subscription_grants g
          where g.billing_order_id = v_order.id
        )
        or c.replacement_grant_id in (
          select g.id from public.subscription_grants g
          where g.billing_order_id = v_order.id
        )
      )

    union all

    select a.created_at, 'admin_audit', a.id::text,
      jsonb_build_object(
        'source', 'admin_audit',
        'event_type', a.event_type,
        'event_at', a.created_at,
        'provider_event_at', null::timestamptz,
        'received_at', null::timestamptz,
        'entity_id', a.id,
        'status', null::text,
        'state', a.actor_type,
        'code', null::text,
        'request_id', a.request_id,
        'job_id', null::uuid,
        'actor_type', a.actor_type,
        'actor_id', a.actor_user_id,
        'details', jsonb_strip_nulls(jsonb_build_object(
          'target_type', a.target_type,
          'target_id', a.target_id,
          'reason', nullif(a.metadata ->> 'reason', ''),
          'decision', nullif(a.metadata ->> 'decision', ''),
          'scope', nullif(a.metadata ->> 'scope', '')
        ))
      )
    from public.audit_logs a
    where a.target_type = 'billing_order'
      and a.target_id = v_order.id
  ) t;

  return query
    select o.id, pa.provider, o.provider_order_no, o.provider_user_id,
      o.external_plan_id, o.external_sku_ids, o.product_type,
      o.purchase_months, o.total_amount, o.show_amount, o.currency,
      o.provider_facts, o.platform_id, o.platform_account_id,
      o.checkout_intent_id, o.custom_order_id, o.provider_status,
      o.verification_status, o.verification_reason, o.entitlement_status,
      o.linkage_status, o.resolution_status, o.resolution_reason,
      s.id, s.state, s.settlement_kind, s.decision_code, s.grant_id,
      o.admin_version,
      (select count(*) from public.billing_processing_jobs j
       where j.billing_order_id = o.id
         and j.state in ('pending', 'processing', 'retryable', 'manual_review')),
      o.created_at, o.updated_at, v_timeline
    from public.billing_orders o
    join public.billing_provider_accounts pa on pa.id = o.provider_account_id
    left join public.billing_settlements s on s.billing_order_id = o.id
    where o.id = p_order_id;
end;
$$;


ALTER FUNCTION "private"."admin_billing_order_read_v2"("p_ctx" "private"."admin_context", "p_order_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_billing_order_read_v3"("p_ctx" "private"."admin_context", "p_order_id" "uuid") RETURNS TABLE("order_id" "uuid", "provider" "text", "provider_order_no" "text", "provider_user_id" "text", "external_plan_id" "text", "external_sku_ids" "text"[], "product_type" "text", "purchase_months" integer, "total_amount" numeric, "show_amount" numeric, "currency" "text", "provider_facts" "jsonb", "platform_id" "uuid", "platform_account_id" "uuid", "checkout_intent_id" "uuid", "custom_order_id" "text", "provider_status" "text", "verification_status" "text", "verification_reason" "text", "entitlement_status" "text", "linkage_status" "text", "resolution_status" "text", "resolution_reason" "text", "settlement_id" "uuid", "settlement_state" "text", "settlement_kind" "text", "decision_code" "text", "grant_id" "uuid", "admin_version" bigint, "open_job_count" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "timeline" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_detail record;
  v_timeline jsonb;
begin
  perform private.billing_admin_assert(p_ctx);
  select * into v_detail
  from private.admin_billing_order_read_v2(p_ctx, p_order_id);
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;

  select coalesce(jsonb_agg(
    case
      when item ->> 'source' = 'provider_webhook' then
        item || jsonb_build_object(
          'job_id', job.id,
          'details', coalesce(item -> 'details', '{}'::jsonb) ||
            jsonb_strip_nulls(jsonb_build_object(
              'payload_hash_prefix', case when webhook_event.payload_hash is null then null
                else left(encode(webhook_event.payload_hash, 'hex'), 16) end,
              'processing_job_id', job.id,
              'job_state', job.state,
              'job_health', case
                when job.state = 'processing' and job.lease_until <= current_timestamp then 'lost'
                when job.state = 'processing' then 'active'
                else 'idle'
              end
            ))
        )
      when item ->> 'source' = 'processing_job' then
        item || jsonb_build_object(
          'details', coalesce(item -> 'details', '{}'::jsonb) ||
            jsonb_strip_nulls(jsonb_build_object(
              'max_attempts', job.max_attempts,
              'next_attempt_at', job.next_attempt_at,
              'lease_until', job.lease_until,
              'lease_owner_fingerprint', case when job.lease_owner is null then null
                else left(encode(extensions.digest(convert_to(job.lease_owner, 'utf8'), 'sha256'), 'hex'), 12) end,
              'error_class', job.error_class,
              'last_error_class', job.last_error_class,
              'last_error_code', job.last_error_code,
              'last_requeue_at', job.last_requeue_at,
              'health', case
                when job.state = 'processing' and job.lease_until <= current_timestamp then 'lost'
                when job.state = 'processing' then 'active'
                else 'idle'
              end
            ))
        )
      else item
    end
    order by ordinal), '[]'::jsonb)
    into v_timeline
  from jsonb_array_elements(coalesce(v_detail.timeline, '[]'::jsonb))
    with ordinality as timeline_items(item, ordinal)
  left join public.billing_webhook_events webhook_event
    on item ->> 'source' = 'provider_webhook'
   and webhook_event.id = (item ->> 'entity_id')::uuid
  left join lateral (
    select j.*
    from public.billing_processing_jobs j
    where (item ->> 'source' = 'processing_job'
       and j.id = (item ->> 'job_id')::uuid)
       or (item ->> 'source' = 'provider_webhook'
       and j.webhook_event_id = (item ->> 'entity_id')::uuid)
    order by j.updated_at desc, j.id desc
    limit 1
  ) job on true;

  return query select
    v_detail.order_id, v_detail.provider, v_detail.provider_order_no,
    v_detail.provider_user_id, v_detail.external_plan_id,
    v_detail.external_sku_ids, v_detail.product_type,
    v_detail.purchase_months, v_detail.total_amount, v_detail.show_amount,
    v_detail.currency, v_detail.provider_facts, v_detail.platform_id,
    v_detail.platform_account_id, v_detail.checkout_intent_id,
    v_detail.custom_order_id, v_detail.provider_status,
    v_detail.verification_status, v_detail.verification_reason,
    v_detail.entitlement_status, v_detail.linkage_status,
    v_detail.resolution_status, v_detail.resolution_reason,
    v_detail.settlement_id, v_detail.settlement_state,
    v_detail.settlement_kind, v_detail.decision_code, v_detail.grant_id,
    v_detail.admin_version, v_detail.open_job_count, v_detail.created_at,
    v_detail.updated_at, v_timeline;
end;
$$;


ALTER FUNCTION "private"."admin_billing_order_read_v3"("p_ctx" "private"."admin_context", "p_order_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_billing_order_requery"("p_ctx" "private"."admin_context", "p_order_id" "uuid", "p_operation_id" "uuid", "p_expected_version" bigint, "p_reason" "text") RETURNS TABLE("order_id" "uuid", "job_id" "uuid", "state" "text", "admin_version" bigint, "replayed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_order public.billing_orders;
  v_job public.billing_processing_jobs;
  v_existing private.admin_idempotency%rowtype;
  v_scope text;
  v_hash bytea;
  v_new boolean := false;
  v_response jsonb;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_order_id is null or p_operation_id is null or p_expected_version is null
     or p_expected_version < 1 or p_reason is null or length(p_reason) not between 1 and 1024 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  select * into v_order from public.billing_orders where id = p_order_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  v_scope := case
    when v_order.platform_id is null then 'global'
    else 'platform:' || v_order.platform_id::text
  end;
  v_hash := extensions.digest(
    convert_to(
      p_order_id::text || ':' || p_expected_version::text || ':' || p_reason,
      'utf8'
    ),
    'sha256'
  );
  insert into private.admin_idempotency(
    admin_user_id, platform_id, scope, operation, idempotency_key, request_hash
  ) values (
    (p_ctx).admin_user_id,
    case when v_scope = 'global' then null else v_order.platform_id end,
    v_scope,
    'billing_order_requery',
    p_operation_id::text,
    v_hash
  ) on conflict (admin_user_id, scope, operation, idempotency_key)
    do nothing returning true into v_new;
  if not coalesce(v_new, false) then
    select * into v_existing from private.admin_idempotency i
    where i.admin_user_id = (p_ctx).admin_user_id and i.scope = v_scope
      and i.operation = 'billing_order_requery' and i.idempotency_key = p_operation_id::text
    for update;
    if v_existing.request_hash <> v_hash then
      raise exception using errcode = '23505', message = 'idempotency_conflict';
    end if;
    if v_existing.state = 'completed' then
      return query select
        (v_existing.response_body->>'order_id')::uuid,
        (v_existing.response_body->>'job_id')::uuid,
        v_existing.response_body->>'state',
        (v_existing.response_body->>'admin_version')::bigint,
        coalesce((v_existing.response_body->>'replayed')::boolean, false);
      return;
    end if;
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;

  if v_order.admin_version <> p_expected_version then
    raise exception using errcode = '40001', message = 'precondition_failed';
  end if;
  select * into v_job from public.billing_processing_jobs j
  where j.operation_id = p_operation_id
  for update;
  if found then
    if v_job.billing_order_id is distinct from p_order_id then
      raise exception using errcode = '23505', message = 'idempotency_conflict';
    end if;
    v_response := jsonb_build_object(
      'order_id', v_order.id,
      'job_id', v_job.id,
      'state', v_job.state,
      'admin_version', v_order.admin_version,
      'replayed', true
    );
    update private.admin_idempotency i
    set state = 'completed', response_status = 202, response_body = v_response
    where i.admin_user_id = (p_ctx).admin_user_id and i.scope = v_scope
      and i.operation = 'billing_order_requery' and i.idempotency_key = p_operation_id::text;
    return query select v_job.billing_order_id, v_job.id, v_job.state,
      v_order.admin_version, true;
    return;
  end if;

  select * into v_job from public.billing_processing_jobs j
  where j.billing_order_id = p_order_id and j.state in ('pending', 'processing', 'retryable')
  order by j.created_at desc limit 1
  for update;
  if found then
    v_response := jsonb_build_object(
      'order_id', v_order.id,
      'job_id', v_job.id,
      'state', v_job.state,
      'admin_version', v_order.admin_version,
      'replayed', true
    );
    update private.admin_idempotency i
    set state = 'completed', response_status = 202, response_body = v_response
    where i.admin_user_id = (p_ctx).admin_user_id and i.scope = v_scope
      and i.operation = 'billing_order_requery' and i.idempotency_key = p_operation_id::text;
    return query select v_job.billing_order_id, v_job.id, v_job.state,
      v_order.admin_version, true;
    return;
  end if;

  insert into public.billing_processing_jobs(job_kind, billing_order_id, operation_id, state)
  values ('reconciliation', p_order_id, p_operation_id, 'pending')
  returning * into v_job;
  v_response := jsonb_build_object(
    'order_id', v_order.id,
    'job_id', v_job.id,
    'state', v_job.state,
    'admin_version', v_order.admin_version,
    'replayed', false
  );
  update private.admin_idempotency i
  set state = 'completed', response_status = 202, response_body = v_response
  where i.admin_user_id = (p_ctx).admin_user_id and i.scope = v_scope
    and i.operation = 'billing_order_requery' and i.idempotency_key = p_operation_id::text;
  perform private.audit_append(p_operation_id, 'admin', (p_ctx).admin_user_id,
    v_order.platform_id, v_order.platform_account_id, 'billing.order.requery_requested',
    'billing_order', v_order.id, null, null, jsonb_build_object('reason', p_reason));
  return query select v_order.id, v_job.id, v_job.state, v_order.admin_version, false;
end;
$$;


ALTER FUNCTION "private"."admin_billing_order_requery"("p_ctx" "private"."admin_context", "p_order_id" "uuid", "p_operation_id" "uuid", "p_expected_version" bigint, "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_billing_order_resolve"("p_ctx" "private"."admin_context", "p_order_id" "uuid", "p_operation_id" "uuid", "p_expected_version" bigint, "p_decision" "text", "p_reason" "text") RETURNS TABLE("order_id" "uuid", "resolution_status" "text", "settlement_state" "text", "admin_version" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_order public.billing_orders;
  v_settlement public.billing_settlements;
  v_existing private.admin_idempotency%rowtype;
  v_scope text;
  v_hash bytea;
  v_new boolean := false;
  v_response jsonb;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_order_id is null or p_operation_id is null or p_expected_version is null
     or p_expected_version < 1 or p_decision not in ('refund_confirmed', 'closed_anomaly', 'manual_correction')
     or p_reason is null or length(p_reason) not between 1 and 1024 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  select * into v_order from public.billing_orders where id = p_order_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  v_scope := case
    when v_order.platform_id is null then 'global'
    else 'platform:' || v_order.platform_id::text
  end;
  v_hash := extensions.digest(
    convert_to(
      p_order_id::text || ':' || p_decision || ':' || p_expected_version::text || ':' || p_reason,
      'utf8'
    ),
    'sha256'
  );
  insert into private.admin_idempotency(
    admin_user_id, platform_id, scope, operation, idempotency_key, request_hash
  ) values (
    (p_ctx).admin_user_id,
    case when v_scope = 'global' then null else v_order.platform_id end,
    v_scope,
    'billing_order_resolve',
    p_operation_id::text,
    v_hash
  ) on conflict (admin_user_id, scope, operation, idempotency_key)
    do nothing returning true into v_new;
  if not coalesce(v_new, false) then
    select * into v_existing from private.admin_idempotency i
    where i.admin_user_id = (p_ctx).admin_user_id and i.scope = v_scope
      and i.operation = 'billing_order_resolve' and i.idempotency_key = p_operation_id::text
    for update;
    if v_existing.request_hash <> v_hash then
      raise exception using errcode = '23505', message = 'idempotency_conflict';
    end if;
    if v_existing.state = 'completed' then
      return query select
        (v_existing.response_body->>'order_id')::uuid,
        v_existing.response_body->>'resolution_status',
        v_existing.response_body->>'settlement_state',
        (v_existing.response_body->>'admin_version')::bigint;
      return;
    end if;
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;

  if v_order.admin_version <> p_expected_version then
    raise exception using errcode = '40001', message = 'precondition_failed';
  end if;
  select * into v_settlement from public.billing_settlements where billing_order_id = p_order_id for update;
  if not found then raise exception using errcode = 'P0001', message = 'settlement_required'; end if;
  if v_order.linkage_status = 'unlinked'
     and (v_settlement.platform_id is not null or v_settlement.platform_account_id is not null
       or v_settlement.checkout_intent_id is not null or v_settlement.grant_id is not null) then
    raise exception using errcode = 'P0001', message = 'settlement_scope_conflict';
  end if;
  update public.billing_settlements set state = 'finalized', decision_reason = p_reason
  where id = v_settlement.id;
  update public.billing_orders set resolution_status = 'resolved', resolved_by = (p_ctx).admin_user_id,
    resolved_at = clock_timestamp(), resolution_reason = p_reason
  where id = p_order_id
  returning * into v_order;
  update public.billing_processing_jobs
  set state = 'completed', lease_owner = null, lease_until = null,
    error_class = null, error_code = null
  where billing_order_id = p_order_id and state = 'manual_review';
  v_response := jsonb_build_object(
    'order_id', v_order.id,
    'resolution_status', v_order.resolution_status,
    'settlement_state', 'finalized',
    'admin_version', v_order.admin_version
  );
  update private.admin_idempotency i
  set state = 'completed', response_status = 200, response_body = v_response
  where i.admin_user_id = (p_ctx).admin_user_id and i.scope = v_scope
    and i.operation = 'billing_order_resolve' and i.idempotency_key = p_operation_id::text;
  perform private.audit_append(p_operation_id, 'admin', (p_ctx).admin_user_id,
    v_order.platform_id, v_order.platform_account_id, 'billing.order.resolved',
    'billing_order', v_order.id, null, null,
    jsonb_build_object('decision', p_decision, 'reason', p_reason));
  return query select v_order.id, v_order.resolution_status, 'finalized'::text, v_order.admin_version;
end;
$$;


ALTER FUNCTION "private"."admin_billing_order_resolve"("p_ctx" "private"."admin_context", "p_order_id" "uuid", "p_operation_id" "uuid", "p_expected_version" bigint, "p_decision" "text", "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_commerce_entitlement_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_cursor_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_account_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20, "p_query" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_plan_id" "uuid" DEFAULT NULL::"uuid", "p_source" "text" DEFAULT NULL::"text", "p_ending_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ending_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("platform_account_id" "uuid", "user_id" "uuid", "display_name" "text", "avatar_url" "text", "account_status" "text", "subscription_status" "text", "plan_id" "uuid", "plan_code" "text", "plan_name" "text", "grant_id" "uuid", "entitlement_source" "text", "billing_order_id" "uuid", "redemption_batch_id" "uuid", "commercial_offer_id" "uuid", "offer_code" "text", "commercial_price_id" "uuid", "started_at" timestamp with time zone, "current_period_end" timestamp with time zone, "next_transition_at" timestamp with time zone, "account_created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_query text := nullif(btrim(p_query), '');
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_limit is null or p_limit not between 1 and 100
     or ((p_cursor_created_at is null) <> (p_cursor_account_id is null))
     or (v_query is not null and length(v_query) > 128)
     or (p_status is not null and p_status not in ('active', 'suspended'))
     or (p_source is not null and p_source not in ('billing_order', 'redemption_code', 'admin'))
     or (p_ending_from is not null and p_ending_to is not null and p_ending_from > p_ending_to) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from public.platforms p where p.id = p_platform_id) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if p_cursor_account_id is not null and not exists (
    select 1
    from public.platform_accounts a
    where a.platform_id = p_platform_id
      and a.id = p_cursor_account_id
      and a.created_at = p_cursor_created_at
  ) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;

  return query
  select a.id, a.user_id, pr.display_name, pr.avatar_url, a.status, s.status,
    plan.id, plan.code, plan.name, winning.id, winning.source,
    winning.billing_order_id, redemption.batch_id, attribution.offer_id,
    attribution.offer_code, attribution.price_id, s.started_at,
    s.current_period_end, s.next_transition_at, a.created_at, s.updated_at
  from public.subscriptions s
  join public.platform_accounts a
    on a.platform_id = s.platform_id and a.id = s.platform_account_id
  left join public.platform_profiles pr on pr.platform_account_id = a.id
  left join lateral (
    select g.id, g.plan_id, g.source, g.billing_order_id, g.redemption_code_id,
      g.starts_at, g.ends_at, g.created_at
    from public.subscription_grants g
    where g.platform_id = s.platform_id
      and g.platform_account_id = s.platform_account_id
      and g.starts_at <= now()
      and (g.ends_at is null or g.ends_at > now())
      and not exists (
        select 1 from public.subscription_events revoked
        where revoked.platform_id = g.platform_id
          and revoked.platform_account_id = g.platform_account_id
          and revoked.grant_id = g.id
          and revoked.event_type = 'revoked'
      )
    order by g.starts_at desc, g.created_at desc, g.id desc
    limit 1
  ) winning on true
  left join public.plans plan
    on plan.platform_id = s.platform_id
   and plan.id = coalesce(winning.plan_id, s.plan_id)
  left join public.redemption_codes redemption
    on redemption.platform_id = s.platform_id
   and redemption.id = winning.redemption_code_id
  left join lateral (
    select chosen.offer_id, chosen.offer_code, chosen.price_id
    from (
      select o.id as offer_id, o.code as offer_code,
        c.commercial_price_id as price_id, 1 as priority
      from public.billing_checkout_intents c
      join public.platform_commercial_offers o
        on o.platform_id = c.platform_id and o.id = c.commercial_offer_id
      where winning.source = 'billing_order'
        and c.platform_id = s.platform_id
        and c.platform_account_id = s.platform_account_id
        and c.id = (
          select bo.checkout_intent_id from public.billing_orders bo
          where bo.id = winning.billing_order_id
        )
      union all
      select o.id, o.code, null::uuid, 1
      from public.redemption_code_batches b
      join public.platform_commercial_offers o
        on o.platform_id = b.platform_id and o.id = b.commercial_offer_id
      where winning.source = 'redemption_code'
        and b.platform_id = s.platform_id
        and b.id = redemption.batch_id
    ) chosen
    order by chosen.priority
    limit 1
  ) attribution on true
  where s.platform_id = p_platform_id
    and s.plan_id is not null
    and (v_query is null
      or a.id::text ilike '%' || v_query || '%'
      or coalesce(a.user_id::text, '') ilike '%' || v_query || '%'
      or coalesce(pr.display_name, '') ilike '%' || v_query || '%'
      or coalesce(plan.code, '') ilike '%' || v_query || '%'
      or coalesce(plan.name, '') ilike '%' || v_query || '%')
    and (p_status is null or s.status = p_status)
    and (p_plan_id is null or plan.id = p_plan_id)
    and (p_source is null or winning.source = p_source)
    and (p_ending_from is null or winning.ends_at >= p_ending_from)
    and (p_ending_to is null or winning.ends_at <= p_ending_to)
    and (p_cursor_account_id is null
      or (a.created_at, a.id) < (p_cursor_created_at, p_cursor_account_id))
  order by a.created_at desc, a.id desc
  limit p_limit;
end;
$$;


ALTER FUNCTION "private"."admin_commerce_entitlement_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_cursor_created_at" timestamp with time zone, "p_cursor_account_id" "uuid", "p_limit" integer, "p_query" "text", "p_status" "text", "p_plan_id" "uuid", "p_source" "text", "p_ending_from" timestamp with time zone, "p_ending_to" timestamp with time zone) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_commerce_policy_patch"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_expected_version" bigint, "p_purchases_paused" boolean, "p_subscription_copy_override" "text", "p_reason" "text") RETURNS TABLE("platform_id" "uuid", "purchases_paused" boolean, "subscription_copy_override" "text", "row_version" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.billing_admin_assert(p_ctx);
  if p_expected_version is null or p_expected_version<1 or p_purchases_paused is null
    or (p_subscription_copy_override is not null and length(p_subscription_copy_override)>1024)
    or p_reason is null or length(p_reason) not between 1 and 1024 then
    raise exception using errcode='22023', message='invalid_input';
  end if;
  perform 1 from public.platforms p where p.id=p_platform_id for update;
  if not found then raise exception using errcode='P0002', message='resource_not_found'; end if;
  update public.platform_commerce_policy c
  set purchases_paused=p_purchases_paused,
      subscription_copy_override=p_subscription_copy_override,
      row_version=c.row_version+1
  where c.platform_id=p_platform_id and c.row_version=p_expected_version;
  if not found then raise exception using errcode='40001', message='precondition_failed'; end if;
  perform private.audit_append((p_ctx).request_id,'admin',(p_ctx).admin_user_id,p_platform_id,null,
    'commerce.policy_updated','platform_commerce_policy',p_platform_id,null,null,
    jsonb_build_object('purchases_paused',p_purchases_paused,'reason',p_reason));
  return query select * from private.admin_commerce_policy_read(p_ctx,p_platform_id);
end;
$$;


ALTER FUNCTION "private"."admin_commerce_policy_patch"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_expected_version" bigint, "p_purchases_paused" boolean, "p_subscription_copy_override" "text", "p_reason" "text") OWNER TO "domain_owner";


