CREATE OR REPLACE FUNCTION "private"."admin_commerce_summary"("p_ctx" "private"."admin_context", "p_platform_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("platform_id" "uuid", "period_start" timestamp with time zone, "period_end" timestamp with time zone, "currency" "text", "active_paid_entitlement_accounts" bigint, "billing_grant_count" bigint, "admin_grant_count" bigint, "redemption_grant_count" bigint, "verified_gross_amount" numeric, "compensated_refund_amount" numeric, "net_verified_amount" numeric, "amount_unknown_count" bigint, "refund_amount_unknown_count" bigint, "expiring_paid_entitlement_accounts" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_from timestamptz := coalesce(p_from, v_now - interval '30 days');
  v_to timestamptz := coalesce(p_to, v_now);
begin
  perform private.billing_admin_assert(p_ctx);
  if v_from >= v_to or v_to - v_from > interval '366 days' then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if p_platform_id is not null and not exists (
    select 1 from public.platforms p where p.id = p_platform_id
  ) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;

  return query
  with active_paid as (
    select *
    from private.commerce_active_paid_entitlements(p_platform_id, v_now)
  ),
  grant_metrics as (
    select
      count(*) filter (where g.source = 'billing_order')::bigint as billing_grant_count,
      count(*) filter (where g.source = 'admin')::bigint as admin_grant_count,
      count(*) filter (where g.source = 'redemption_code')::bigint as redemption_grant_count
    from public.subscription_grants g
    where (p_platform_id is null or g.platform_id = p_platform_id)
      and g.created_at >= v_from and g.created_at < v_to
  ),
  eligible_success_orders as (
    select o.id, o.platform_id, o.total_amount, o.currency,
      s.updated_at as finalized_at
    from public.billing_orders o
    join public.billing_settlements s on s.billing_order_id = o.id
    where s.state = 'finalized'
      and s.decision_code = 'granted'
      and o.verification_status = 'verified'
      and o.entitlement_status = 'granted'
      and o.linkage_status = 'linked'
      and o.checkout_intent_id is not null
      and o.platform_id is not null
      and o.platform_account_id is not null
      and (p_platform_id is null or o.platform_id = p_platform_id)
  ),
  gross_metrics as (
    select
      coalesce(sum(e.total_amount) filter (
        where e.total_amount is not null and e.currency = 'CNY'
      ), 0::numeric) as verified_gross_amount,
      count(*) filter (
        where e.total_amount is null or e.currency is null or e.currency <> 'CNY'
      )::bigint as amount_unknown_count
    from eligible_success_orders e
    where e.finalized_at >= v_from and e.finalized_at < v_to
  ),
  refund_metrics as (
    select
      coalesce(sum(r.refund_amount) filter (
        where r.refund_amount is not null and r.currency = 'CNY'
      ), 0::numeric) as compensated_refund_amount,
      count(*) filter (
        where r.refund_amount is null or r.currency is null or r.currency <> 'CNY'
      )::bigint as refund_amount_unknown_count
    from private.billing_refund_observations r
    join eligible_success_orders e on e.id = r.billing_order_id
    where r.status = 'compensated'
      and r.compensated_at >= v_from and r.compensated_at < v_to
  )
  select
    p_platform_id,
    v_from,
    v_to,
    'CNY'::text,
    (select count(*)::bigint from active_paid),
    grants.billing_grant_count,
    grants.admin_grant_count,
    grants.redemption_grant_count,
    gross.verified_gross_amount,
    refunds.compensated_refund_amount,
    gross.verified_gross_amount - refunds.compensated_refund_amount,
    gross.amount_unknown_count,
    refunds.refund_amount_unknown_count,
    (select count(*)::bigint from active_paid ap
      where ap.ends_at is not null
        and ap.ends_at > v_now
        and ap.ends_at <= v_now + interval '30 days')
  from grant_metrics grants
  cross join gross_metrics gross
  cross join refund_metrics refunds;
end;
$$;


ALTER FUNCTION "private"."admin_commerce_summary"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "domain_owner";

SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."billing_provider_products" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "provider_account_id" "uuid" NOT NULL,
    "external_plan_id" "text" NOT NULL,
    "product_type" "text" NOT NULL,
    "external_sku_ids" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "sku_count" integer DEFAULT 0 NOT NULL,
    "purchase_months" integer,
    "expected_show_amount" numeric(12,2) NOT NULL,
    "expected_total_amount" numeric(12,2) NOT NULL,
    "currency" "text" DEFAULT 'CNY'::"text" NOT NULL,
    "price_version" integer NOT NULL,
    "mapping_version" integer NOT NULL,
    "validation_status" "text" DEFAULT 'unverified'::"text" NOT NULL,
    "published" boolean DEFAULT false NOT NULL,
    "enabled" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "platform_id" "uuid" NOT NULL,
    "commercial_price_id" "uuid" NOT NULL,
    CONSTRAINT "billing_provider_products_check" CHECK ((("sku_count" >= 0) AND ("sku_count" = "cardinality"("external_sku_ids")))),
    CONSTRAINT "billing_provider_products_check1" CHECK (((NOT "published") OR ("validation_status" = 'verified'::"text"))),
    CONSTRAINT "billing_provider_products_currency_check" CHECK (("currency" = 'CNY'::"text")),
    CONSTRAINT "billing_provider_products_expected_show_amount_check" CHECK (("expected_show_amount" >= (0)::numeric)),
    CONSTRAINT "billing_provider_products_expected_total_amount_check" CHECK (("expected_total_amount" >= (0)::numeric)),
    CONSTRAINT "billing_provider_products_external_plan_id_check" CHECK ((("length"("external_plan_id") >= 1) AND ("length"("external_plan_id") <= 128))),
    CONSTRAINT "billing_provider_products_mapping_version_check" CHECK (("mapping_version" > 0)),
    CONSTRAINT "billing_provider_products_price_version_check" CHECK (("price_version" > 0)),
    CONSTRAINT "billing_provider_products_product_type_check" CHECK ((("length"("product_type") >= 1) AND ("length"("product_type") <= 128))),
    CONSTRAINT "billing_provider_products_purchase_months_check" CHECK ((("purchase_months" IS NULL) OR ("purchase_months" > 0))),
    CONSTRAINT "billing_provider_products_validation_status_check" CHECK (("validation_status" = ANY (ARRAY['unverified'::"text", 'verified'::"text", 'rejected'::"text"])))
);

ALTER TABLE ONLY "public"."billing_provider_products" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."billing_provider_products" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."admin_commercial_mapping_command"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_mapping_id" "uuid", "p_action" "text", "p_operation_id" "uuid", "p_reason" "text") RETURNS "public"."billing_provider_products"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public', 'extensions'
    AS $$
declare
  v_mapping public.billing_provider_products;
  v_price public.platform_commercial_prices;
  v_provider_id uuid;
  v_price_id uuid;
  v_claim record;
  v_hash bytea;
  v_response jsonb;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_action not in ('switch','disable') or p_operation_id is null
    or p_reason is null or length(p_reason) not between 1 and 1024 then
    raise exception using errcode='22023', message='invalid_input';
  end if;
  v_hash:=extensions.digest(convert_to(jsonb_build_object('mapping_id',p_mapping_id,'action',p_action,'reason',p_reason)::text,'utf8'),'sha256');
  select * into v_claim from private.admin_operation_claim(p_ctx,p_platform_id,'commerce_mapping_command',p_operation_id,v_hash);
  if v_claim.outcome='replayed' then
    select * into v_mapping from jsonb_populate_record(null::public.billing_provider_products,v_claim.response_body);
    return v_mapping;
  end if;
  select m.provider_account_id,m.commercial_price_id into v_provider_id,v_price_id
  from public.billing_provider_products m where m.id=p_mapping_id and m.platform_id=p_platform_id;
  if not found then raise exception using errcode='P0002', message='resource_not_found'; end if;
  perform 1 from public.billing_provider_accounts pa where pa.id=v_provider_id for update;
  select * into v_price from public.platform_commercial_prices p
  where p.platform_id=p_platform_id and p.id=v_price_id for update;
  select * into v_mapping from public.billing_provider_products m
  where m.id=p_mapping_id and m.platform_id=p_platform_id for update;
  if p_action='switch' then
    if v_mapping.published and v_mapping.enabled then
      raise exception using errcode='P0001', message='provider_mapping_already_current';
    end if;
    if v_mapping.validation_status<>'verified' or v_price.id is null
      or v_mapping.expected_show_amount<>v_price.amount or v_mapping.currency<>v_price.currency
      or v_mapping.price_version<>v_price.version then
      raise exception using errcode='P0001', message='provider_mapping_unavailable';
    end if;
    update public.billing_provider_products m set enabled=false
    where m.provider_account_id=v_provider_id and m.commercial_price_id=v_price_id
      and m.id<>p_mapping_id and m.published and m.enabled;
    update public.billing_provider_products set published=true,enabled=true
    where id=p_mapping_id returning * into v_mapping;
  else
    update public.billing_provider_products set enabled=false
    where id=p_mapping_id returning * into v_mapping;
  end if;
  v_response:=to_jsonb(v_mapping);
  perform private.admin_operation_finalize(p_ctx,p_platform_id,'commerce_mapping_command',p_operation_id,v_response);
  perform private.audit_append(p_operation_id,'admin',(p_ctx).admin_user_id,p_platform_id,null,
    'commerce.mapping_'||p_action,'billing_provider_product',p_mapping_id,null,null,
    jsonb_build_object('reason',p_reason,'price_id',v_price_id));
  return v_mapping;
end;
$$;


ALTER FUNCTION "private"."admin_commercial_mapping_command"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_mapping_id" "uuid", "p_action" "text", "p_operation_id" "uuid", "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_commercial_mapping_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_price_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("mapping_id" "uuid", "provider_account_id" "uuid", "provider_name" "text", "commercial_price_id" "uuid", "offer_id" "uuid", "price_version" integer, "price_amount" numeric, "external_plan_id" "text", "product_type" "text", "external_sku_ids" "text"[], "mapping_version" integer, "validation_status" "text", "published" boolean, "enabled" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.billing_admin_assert(p_ctx);
  return query
  select m.id,m.provider_account_id,pa.name,m.commercial_price_id,price.offer_id,
    price.version,price.amount,m.external_plan_id,m.product_type,m.external_sku_ids,
    m.mapping_version,m.validation_status,m.published,m.enabled
  from public.billing_provider_products m
  join public.billing_provider_accounts pa on pa.id=m.provider_account_id
  join public.platform_commercial_prices price on price.platform_id=m.platform_id and price.id=m.commercial_price_id
  where m.platform_id=p_platform_id and (p_price_id is null or m.commercial_price_id=p_price_id)
  order by price.offer_id,price.version desc,m.mapping_version desc;
end;
$$;


ALTER FUNCTION "private"."admin_commercial_mapping_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_price_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_commercial_mapping_upsert"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_mapping_id" "uuid", "p_provider_account_id" "uuid", "p_price_id" "uuid", "p_external_plan_id" "text", "p_product_type" "text", "p_external_sku_ids" "text"[], "p_purchase_months" integer, "p_validation_status" "text") RETURNS "public"."billing_provider_products"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_price public.platform_commercial_prices;
  v_mapping public.billing_provider_products;
  v_version integer;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_validation_status not in ('unverified','verified','rejected') then
    raise exception using errcode='22023', message='invalid_input';
  end if;
  perform 1 from public.billing_provider_accounts pa where pa.id=p_provider_account_id for update;
  if not found then raise exception using errcode='P0002', message='resource_not_found'; end if;
  select * into v_price from public.platform_commercial_prices p
  where p.platform_id=p_platform_id and p.id=p_price_id for update;
  if not found then raise exception using errcode='P0002', message='resource_not_found'; end if;
  if p_mapping_id is null then
    select coalesce(max(m.mapping_version),0)+1 into v_version
    from public.billing_provider_products m
    where m.provider_account_id=p_provider_account_id and m.commercial_price_id=p_price_id;
    insert into public.billing_provider_products(
      provider_account_id,platform_id,commercial_price_id,external_plan_id,product_type,
      external_sku_ids,sku_count,purchase_months,expected_show_amount,expected_total_amount,
      currency,price_version,mapping_version,validation_status,published,enabled
    ) values (
      p_provider_account_id,p_platform_id,p_price_id,p_external_plan_id,p_product_type,
      coalesce(p_external_sku_ids,'{}'::text[]),cardinality(coalesce(p_external_sku_ids,'{}'::text[])),
      p_purchase_months,v_price.amount,v_price.amount,v_price.currency,v_price.version,
      v_version,p_validation_status,false,false
    ) returning * into v_mapping;
  else
    update public.billing_provider_products m set external_plan_id=p_external_plan_id,
      product_type=p_product_type,external_sku_ids=coalesce(p_external_sku_ids,'{}'::text[]),
      sku_count=cardinality(coalesce(p_external_sku_ids,'{}'::text[])),purchase_months=p_purchase_months,
      validation_status=p_validation_status
    where m.id=p_mapping_id and m.platform_id=p_platform_id
      and m.provider_account_id=p_provider_account_id and m.commercial_price_id=p_price_id
      and not m.published returning * into v_mapping;
    if not found then raise exception using errcode='P0002', message='resource_not_found'; end if;
  end if;
  return v_mapping;
end;
$$;


ALTER FUNCTION "private"."admin_commercial_mapping_upsert"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_mapping_id" "uuid", "p_provider_account_id" "uuid", "p_price_id" "uuid", "p_external_plan_id" "text", "p_product_type" "text", "p_external_sku_ids" "text"[], "p_purchase_months" integer, "p_validation_status" "text") OWNER TO "domain_owner";


CREATE TABLE IF NOT EXISTS "public"."platform_commercial_offers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "platform_id" "uuid" NOT NULL,
    "plan_id" "uuid" NOT NULL,
    "code" "text" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "term_kind" "text" DEFAULT 'finite'::"text" NOT NULL,
    "duration_value" integer NOT NULL,
    "duration_unit" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "sort_order" integer DEFAULT 100 NOT NULL,
    "recommended" boolean DEFAULT false NOT NULL,
    "row_version" bigint DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "platform_commercial_offers_code_check" CHECK (((("length"("code") >= 1) AND ("length"("code") <= 64)) AND ("code" ~ '^[a-z0-9][a-z0-9_-]*$'::"text"))),
    CONSTRAINT "platform_commercial_offers_description_check" CHECK ((("description" IS NULL) OR ("length"("description") <= 1024))),
    CONSTRAINT "platform_commercial_offers_duration_unit_check" CHECK (("duration_unit" = ANY (ARRAY['day'::"text", 'month'::"text", 'year'::"text"]))),
    CONSTRAINT "platform_commercial_offers_duration_value_check" CHECK (("duration_value" > 0)),
    CONSTRAINT "platform_commercial_offers_name_check" CHECK ((("length"("name") >= 1) AND ("length"("name") <= 128))),
    CONSTRAINT "platform_commercial_offers_row_version_check" CHECK (("row_version" > 0)),
    CONSTRAINT "platform_commercial_offers_sort_order_check" CHECK (("sort_order" > 0)),
    CONSTRAINT "platform_commercial_offers_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'archived'::"text"]))),
    CONSTRAINT "platform_commercial_offers_term_kind_check" CHECK (("term_kind" = 'finite'::"text"))
);

ALTER TABLE ONLY "public"."platform_commercial_offers" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."platform_commercial_offers" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."admin_commercial_offer_command"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_offer_id" "uuid", "p_action" "text", "p_operation_id" "uuid", "p_reason" "text") RETURNS "public"."platform_commercial_offers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public', 'extensions'
    AS $$
declare
  v_offer public.platform_commercial_offers;
  v_claim record;
  v_hash bytea;
  v_response jsonb;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_action not in ('activate','archive') or p_operation_id is null
    or p_reason is null or length(p_reason) not between 1 and 1024 then
    raise exception using errcode='22023', message='invalid_input';
  end if;
  v_hash:=extensions.digest(convert_to(jsonb_build_object('offer_id',p_offer_id,'action',p_action,'reason',p_reason)::text,'utf8'),'sha256');
  select * into v_claim from private.admin_operation_claim(p_ctx,p_platform_id,'commerce_offer_command',p_operation_id,v_hash);
  if v_claim.outcome='replayed' then
    select * into v_offer from jsonb_populate_record(null::public.platform_commercial_offers,v_claim.response_body);
    return v_offer;
  end if;
  select * into v_offer from public.platform_commercial_offers o
  where o.platform_id=p_platform_id and o.id=p_offer_id for update;
  if not found then raise exception using errcode='P0002', message='resource_not_found'; end if;
  if p_action='activate' then
    if v_offer.status='archived' then raise exception using errcode='P0001', message='commercial_offer_archived'; end if;
    if v_offer.status='active' then raise exception using errcode='P0001', message='commercial_offer_already_active'; end if;
    if not exists(select 1 from public.platform_commercial_prices p
      where p.platform_id=p_platform_id and p.offer_id=p_offer_id and p.status='active') then
      raise exception using errcode='P0001', message='price_unavailable';
    end if;
    update public.platform_commercial_offers set status='active' where id=p_offer_id returning * into v_offer;
  else
    if v_offer.status='archived' then raise exception using errcode='P0001', message='commercial_offer_archived'; end if;
    update public.platform_commercial_offers set status='archived' where id=p_offer_id returning * into v_offer;
  end if;
  v_response:=to_jsonb(v_offer);
  perform private.admin_operation_finalize(p_ctx,p_platform_id,'commerce_offer_command',p_operation_id,v_response);
  perform private.audit_append(p_operation_id,'admin',(p_ctx).admin_user_id,p_platform_id,null,
    'commerce.offer_'||p_action,'commercial_offer',p_offer_id,null,null,
    jsonb_build_object('reason',p_reason,'status',v_offer.status));
  return v_offer;
end;
$$;


ALTER FUNCTION "private"."admin_commercial_offer_command"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_offer_id" "uuid", "p_action" "text", "p_operation_id" "uuid", "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_commercial_offer_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid") RETURNS TABLE("offer_id" "uuid", "plan_id" "uuid", "plan_code" "text", "plan_name" "text", "offer_code" "text", "offer_name" "text", "description" "text", "duration_value" integer, "duration_unit" "text", "status" "text", "recommended" boolean, "row_version" bigint, "price_id" "uuid", "price_version" integer, "price_amount" numeric, "currency" "text", "price_status" "text", "provider_mapping_id" "uuid", "mapping_status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.billing_admin_assert(p_ctx);
  if not exists(select 1 from public.platforms p where p.id=p_platform_id) then
    raise exception using errcode='P0002', message='resource_not_found';
  end if;
  return query
  select o.id,o.plan_id,plan.code,plan.name,o.code,o.name,o.description,o.duration_value,
    o.duration_unit,o.status,o.recommended,o.row_version,price.id,price.version,price.amount,
    price.currency,price.status,mapping.id,
    case when mapping.id is null then 'missing'
      when mapping.published and mapping.enabled and mapping.validation_status='verified' then 'ready'
      when mapping.validation_status='rejected' then 'rejected' else 'draft' end
  from public.platform_commercial_offers o
  join public.plans plan on plan.platform_id=o.platform_id and plan.id=o.plan_id
  left join lateral(select p.* from public.platform_commercial_prices p
    where p.platform_id=o.platform_id and p.offer_id=o.id
    order by p.version desc limit 1) price on true
  left join lateral(select m.* from public.billing_provider_products m
    where m.platform_id=o.platform_id and m.commercial_price_id=price.id
    order by (m.published and m.enabled) desc,m.mapping_version desc limit 1) mapping on true
  where o.platform_id=p_platform_id order by o.sort_order,o.id;
end;
$$;


ALTER FUNCTION "private"."admin_commercial_offer_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_commercial_offer_upsert"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_offer_id" "uuid", "p_plan_id" "uuid", "p_code" "text", "p_name" "text", "p_description" "text", "p_duration_value" integer, "p_duration_unit" "text", "p_recommended" boolean) RETURNS "public"."platform_commercial_offers"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_offer public.platform_commercial_offers;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_plan_id is null or p_code is null or p_name is null
    or p_duration_value is null or p_duration_value<=0 or p_duration_unit not in ('day','month','year') then
    raise exception using errcode='22023', message='invalid_input';
  end if;
  if not exists(select 1 from public.plans p where p.platform_id=p_platform_id and p.id=p_plan_id and p.kind='paid' and p.status='active') then
    raise exception using errcode='P0001', message='plan_unavailable';
  end if;
  if p_offer_id is null then
    insert into public.platform_commercial_offers(platform_id,plan_id,code,name,description,
      duration_value,duration_unit,status,recommended)
    values(p_platform_id,p_plan_id,p_code,p_name,p_description,p_duration_value,p_duration_unit,
      'draft',coalesce(p_recommended,false)) returning * into v_offer;
  else
    update public.platform_commercial_offers o set plan_id=p_plan_id,code=p_code,name=p_name,
      description=p_description,duration_value=p_duration_value,duration_unit=p_duration_unit,
      recommended=coalesce(p_recommended,false)
    where o.platform_id=p_platform_id and o.id=p_offer_id and o.status<>'archived'
    returning * into v_offer;
    if not found then raise exception using errcode='P0002', message='resource_not_found'; end if;
  end if;
  perform private.audit_append((p_ctx).request_id,'admin',(p_ctx).admin_user_id,p_platform_id,null,
    'commerce.offer_saved','commercial_offer',v_offer.id,null,null,
    jsonb_build_object('status',v_offer.status,'plan_id',v_offer.plan_id));
  return v_offer;
end;
$$;


