CREATE TABLE IF NOT EXISTS "public"."platform_commercial_prices" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "platform_id" "uuid" NOT NULL,
    "offer_id" "uuid" NOT NULL,
    "version" integer NOT NULL,
    "amount" numeric(12,2) NOT NULL,
    "currency" "text" DEFAULT 'CNY'::"text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "effective_from" timestamp with time zone,
    "row_version" bigint DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "platform_commercial_prices_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "platform_commercial_prices_check" CHECK ((("status" <> 'active'::"text") OR ("effective_from" IS NOT NULL))),
    CONSTRAINT "platform_commercial_prices_currency_check" CHECK (("currency" = 'CNY'::"text")),
    CONSTRAINT "platform_commercial_prices_row_version_check" CHECK (("row_version" > 0)),
    CONSTRAINT "platform_commercial_prices_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'active'::"text", 'retired'::"text"]))),
    CONSTRAINT "platform_commercial_prices_version_check" CHECK (("version" > 0))
);

ALTER TABLE ONLY "public"."platform_commercial_prices" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."platform_commercial_prices" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."admin_commercial_price_command"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_price_id" "uuid", "p_action" "text", "p_operation_id" "uuid", "p_reason" "text") RETURNS "public"."platform_commercial_prices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public', 'extensions'
    AS $$
declare
  v_price public.platform_commercial_prices;
  v_offer_id uuid;
  v_claim record;
  v_hash bytea;
  v_response jsonb;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_action not in ('publish','retire') or p_operation_id is null
    or p_reason is null or length(p_reason) not between 1 and 1024 then
    raise exception using errcode='22023', message='invalid_input';
  end if;
  v_hash:=extensions.digest(convert_to(jsonb_build_object('price_id',p_price_id,'action',p_action,'reason',p_reason)::text,'utf8'),'sha256');
  select * into v_claim from private.admin_operation_claim(p_ctx,p_platform_id,'commerce_price_command',p_operation_id,v_hash);
  if v_claim.outcome='replayed' then
    select * into v_price from jsonb_populate_record(null::public.platform_commercial_prices,v_claim.response_body);
    return v_price;
  end if;
  select p.offer_id into v_offer_id from public.platform_commercial_prices p
  where p.platform_id=p_platform_id and p.id=p_price_id;
  if not found then raise exception using errcode='P0002', message='resource_not_found'; end if;
  perform 1 from public.platform_commercial_offers o
  where o.platform_id=p_platform_id and o.id=v_offer_id for update;
  select * into v_price from public.platform_commercial_prices p
  where p.platform_id=p_platform_id and p.id=p_price_id for update;
  if v_price.status='retired' then raise exception using errcode='P0001', message='commercial_price_retired'; end if;
  if p_action='publish' then
    if v_price.status<>'draft' then raise exception using errcode='P0001', message='commercial_price_transition_invalid'; end if;
    update public.platform_commercial_prices p set status='retired'
    where p.offer_id=v_offer_id and p.status='active' and p.id<>p_price_id;
    update public.platform_commercial_prices set status='active',effective_from=clock_timestamp()
    where id=p_price_id returning * into v_price;
  else
    update public.platform_commercial_prices set status='retired'
    where id=p_price_id and status in ('draft','active') returning * into v_price;
    if not found then raise exception using errcode='P0001', message='commercial_price_transition_invalid'; end if;
  end if;
  v_response:=to_jsonb(v_price);
  perform private.admin_operation_finalize(p_ctx,p_platform_id,'commerce_price_command',p_operation_id,v_response);
  perform private.audit_append(p_operation_id,'admin',(p_ctx).admin_user_id,p_platform_id,null,
    'commerce.price_'||p_action,'commercial_price',p_price_id,null,null,
    jsonb_build_object('reason',p_reason,'offer_id',v_offer_id,'version',v_price.version));
  return v_price;
end;
$$;


ALTER FUNCTION "private"."admin_commercial_price_command"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_price_id" "uuid", "p_action" "text", "p_operation_id" "uuid", "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_commercial_price_create"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_offer_id" "uuid", "p_amount" numeric, "p_currency" "text" DEFAULT 'CNY'::"text") RETURNS "public"."platform_commercial_prices"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_offer public.platform_commercial_offers; v_price public.platform_commercial_prices; v_version integer;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_amount is null or p_amount<=0 or p_currency<>'CNY' then
    raise exception using errcode='22023', message='invalid_input';
  end if;
  select * into v_offer from public.platform_commercial_offers o
  where o.platform_id=p_platform_id and o.id=p_offer_id and o.status<>'archived' for update;
  if not found then raise exception using errcode='P0002', message='resource_not_found'; end if;
  select coalesce(max(p.version),0)+1 into v_version
  from public.platform_commercial_prices p where p.offer_id=p_offer_id;
  insert into public.platform_commercial_prices(platform_id,offer_id,version,amount,currency,status)
  values(p_platform_id,p_offer_id,v_version,p_amount,p_currency,'draft') returning * into v_price;
  perform private.audit_append((p_ctx).request_id,'admin',(p_ctx).admin_user_id,p_platform_id,null,
    'commerce.price_created','commercial_price',v_price.id,null,null,
    jsonb_build_object('offer_id',p_offer_id,'version',v_version,'amount',p_amount,'currency',p_currency));
  return v_price;
end;
$$;


ALTER FUNCTION "private"."admin_commercial_price_create"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_offer_id" "uuid", "p_amount" numeric, "p_currency" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_config_gallery_govern"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_config_id" "uuid", "p_action" "text", "p_reason" "text") RETURNS TABLE("config_id" "uuid", "gallery_status" "text", "published_version_id" "uuid", "governance_reason" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_entry public.platform_config_gallery_entries;
  v_status text;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_config_id is null
     or p_action not in ('remove', 'restore', 'block')
     or p_reason is null or length(btrim(p_reason)) not between 1 and 2000 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_entry
  from public.platform_config_gallery_entries e
  where e.platform_id = p_platform_id and e.config_id = p_config_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if p_action = 'restore' then
    if not exists (
      select 1
      from public.platform_configs c
      join public.platform_accounts a
        on a.platform_id = c.platform_id and a.id = c.platform_account_id
      join public.platform_config_versions v
        on v.platform_id = c.platform_id and v.config_id = c.id
          and v.id = v_entry.published_version_id
      join public.platform_config_files f on f.id = v.file_id
      where c.platform_id = p_platform_id and c.id = p_config_id
        and c.status = 'active' and a.status = 'active'
        and f.resource_kind = 'config_version' and f.status = 'active'
        and f.write_outcome = 'confirmed'
    ) then
      raise exception using errcode = 'P0001', message = 'config_not_publishable';
    end if;
    v_status := 'approved';
  elsif p_action = 'block' then
    v_status := 'blocked';
  else
    v_status := 'removed';
  end if;
  update public.platform_config_gallery_entries e
  set status = v_status,
      governance_reason = case when v_status = 'approved' then null else btrim(p_reason) end
  where e.platform_id = p_platform_id and e.config_id = p_config_id
  returning * into v_entry;
  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, p_platform_id, null,
    'config.gallery_' || p_action, 'platform_config_gallery_entry', p_config_id,
    null, null, jsonb_build_object('reason', btrim(p_reason), 'status', v_status)
  );
  return query select v_entry.config_id, v_entry.status,
    v_entry.published_version_id, v_entry.governance_reason, v_entry.updated_at;
end;
$$;


ALTER FUNCTION "private"."admin_config_gallery_govern"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_config_id" "uuid", "p_action" "text", "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_config_gallery_review"("p_ctx" "private"."admin_context", "p_submission_id" "uuid", "p_action" "text", "p_reason" "text") RETURNS TABLE("submission_id" "uuid", "config_id" "uuid", "version_id" "uuid", "status" "text", "entry_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_submission public.platform_config_gallery_submissions;
  v_config public.platform_configs;
  v_entry public.platform_config_gallery_entries;
  v_now timestamptz := clock_timestamp();
begin
  if (p_ctx).request_id is null or p_submission_id is null
     or p_action not in ('approve', 'reject')
     or p_reason is null or length(btrim(p_reason)) not between 1 and 2000 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if (p_ctx).admin_user_id is null or (p_ctx).session_id is null
     or not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;
  select * into v_submission from public.platform_config_gallery_submissions s
    where s.id = p_submission_id and s.status = 'pending' for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  select * into v_config from public.platform_configs c
    where c.id = v_submission.config_id and c.platform_id = v_submission.platform_id for update;
  if v_config.status <> 'active'
     or not exists (select 1 from public.platform_accounts a
       where a.platform_id = v_config.platform_id and a.id = v_config.platform_account_id and a.status = 'active') then
    raise exception using errcode = 'P0001', message = 'config_not_publishable';
  end if;
  if p_action = 'approve' then
    if not exists (select 1 from public.platform_config_versions v
      join public.platform_config_files f on f.id = v.file_id
      where v.id = v_submission.version_id and v.config_id = v_submission.config_id
        and f.resource_kind = 'config_version' and f.status = 'active' and f.write_outcome = 'confirmed') then
      raise exception using errcode = 'P0001', message = 'version_not_ready';
    end if;
    update public.platform_config_gallery_submissions s
    set status = 'approved', reviewed_by = (p_ctx).admin_user_id,
      review_reason = btrim(p_reason), reviewed_at = v_now
    where s.id = v_submission.id returning * into v_submission;
    insert into public.platform_config_gallery_entries(
      config_id, platform_id, published_version_id, approved_submission_id,
      status, approved_by, approved_at, governance_reason
    ) values (v_submission.config_id, v_submission.platform_id, v_submission.version_id,
      v_submission.id, 'approved', (p_ctx).admin_user_id, v_now, null)
    on conflict on constraint platform_config_gallery_entries_pkey do update set
      published_version_id = excluded.published_version_id,
      approved_submission_id = excluded.approved_submission_id,
      status = 'approved', approved_by = excluded.approved_by,
      approved_at = excluded.approved_at, governance_reason = null
    returning * into v_entry;
  else
    update public.platform_config_gallery_submissions s
    set status = 'rejected', reviewed_by = (p_ctx).admin_user_id,
      review_reason = btrim(p_reason), reviewed_at = v_now
    where s.id = v_submission.id returning * into v_submission;
    select * into v_entry from public.platform_config_gallery_entries e
      where e.config_id = v_submission.config_id;
  end if;
  perform private.audit_append((p_ctx).request_id, 'admin', (p_ctx).admin_user_id,
    v_submission.platform_id, v_submission.submitted_by_account_id,
    'config.gallery_' || case when p_action = 'approve' then 'approved' else 'rejected' end,
    'platform_config_gallery_submission', v_submission.id, null, null,
    jsonb_build_object('config_id', v_submission.config_id,
      'version_id', v_submission.version_id, 'reason', btrim(p_reason)));
  return query select v_submission.id, v_submission.config_id, v_submission.version_id,
    v_submission.status, v_entry.status;
end;
$$;


ALTER FUNCTION "private"."admin_config_gallery_review"("p_ctx" "private"."admin_context", "p_submission_id" "uuid", "p_action" "text", "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_config_gallery_review_v2"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_submission_id" "uuid", "p_action" "text", "p_reason" "text") RETURNS TABLE("submission_id" "uuid", "config_id" "uuid", "version_id" "uuid", "status" "text", "entry_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_submission_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (
    select 1 from public.platform_config_gallery_submissions s
    where s.platform_id = p_platform_id and s.id = p_submission_id
  ) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  return query
    select * from private.admin_config_gallery_review(
      p_ctx, p_submission_id, p_action, p_reason
    );
end;
$$;


