CREATE OR REPLACE FUNCTION "private"."admin_config_resource_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_cursor_config_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20, "p_query" "text" DEFAULT NULL::"text", "p_gallery_status" "text" DEFAULT NULL::"text") RETURNS TABLE("config_id" "uuid", "platform_id" "uuid", "platform_account_id" "uuid", "author_display_name" "text", "title" "text", "description" "text", "config_status" "text", "current_version_id" "uuid", "current_version_number" integer, "current_schema_key" "text", "current_schema_version" "text", "current_file_status" "text", "current_write_outcome" "text", "gallery_status" "text", "published_version_id" "uuid", "pending_submission_id" "uuid", "pending_version_id" "uuid", "pending_submitted_at" timestamp with time zone, "like_count" bigint, "download_count" bigint, "apply_delivery_count" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_cursor_created_at timestamptz;
  v_query text := nullif(btrim(p_query), '');
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_limit is null or p_limit not between 1 and 100
     or v_query is not null and length(v_query) > 128
     or p_gallery_status is not null
        and p_gallery_status not in ('approved', 'removed', 'blocked', 'none', 'pending') then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from public.platforms p where p.id = p_platform_id) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if p_cursor_config_id is not null then
    select c.created_at into v_cursor_created_at
    from public.platform_configs c
    where c.platform_id = p_platform_id and c.id = p_cursor_config_id;
    if v_cursor_created_at is null then
      raise exception using errcode = 'P0002', message = 'resource_not_found';
    end if;
  end if;
  return query
    select c.id, c.platform_id, c.platform_account_id,
      coalesce(pr.display_name, 'Unknown author'::text),
      c.title, c.description, c.status,
      c.current_version_id, cv.version_number, cv.schema_key, cv.schema_version,
      cf.status, cf.write_outcome,
      coalesce(e.status, 'none'::text), e.published_version_id,
      pending.submission_id, pending.version_id, pending.submitted_at,
      (select count(*) from public.platform_config_likes l
        where l.platform_id = c.platform_id and l.config_id = c.id),
      (select count(*) from public.platform_config_usage_events u
        where u.platform_id = c.platform_id and u.config_id = c.id
          and u.event_type = 'download_completed'),
      (select count(*) from public.platform_config_usage_events u
        where u.platform_id = c.platform_id and u.config_id = c.id
          and u.event_type = 'apply_delivery_completed'),
      c.created_at, c.updated_at
    from public.platform_configs c
    left join public.platform_profiles pr
      on pr.platform_account_id = c.platform_account_id
    left join public.platform_config_versions cv
      on cv.platform_id = c.platform_id and cv.config_id = c.id
        and cv.id = c.current_version_id
    left join public.platform_config_files cf on cf.id = cv.file_id
    left join public.platform_config_gallery_entries e
      on e.platform_id = c.platform_id and e.config_id = c.id
    left join lateral (
      select s.id as submission_id, s.version_id, s.submitted_at
      from public.platform_config_gallery_submissions s
      where s.platform_id = c.platform_id and s.config_id = c.id
        and s.status = 'pending'
      order by s.submitted_at desc, s.id desc
      limit 1
    ) pending on true
    where c.platform_id = p_platform_id
      and (v_query is null
        or c.title ilike '%' || v_query || '%'
        or coalesce(c.description, '') ilike '%' || v_query || '%'
        or coalesce(pr.display_name, '') ilike '%' || v_query || '%')
      and (p_gallery_status is null
        or p_gallery_status = 'none' and e.config_id is null
        or p_gallery_status = 'pending' and pending.submission_id is not null
        or p_gallery_status in ('approved', 'removed', 'blocked')
          and e.status = p_gallery_status)
      and (p_cursor_config_id is null
        or (c.created_at, c.id) < (v_cursor_created_at, p_cursor_config_id))
    order by c.created_at desc, c.id desc
    limit p_limit;
end;
$$;


ALTER FUNCTION "private"."admin_config_resource_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_cursor_config_id" "uuid", "p_limit" integer, "p_query" "text", "p_gallery_status" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_config_resource_read"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_config_id" "uuid") RETURNS TABLE("config_id" "uuid", "platform_id" "uuid", "platform_account_id" "uuid", "author_display_name" "text", "title" "text", "description" "text", "config_status" "text", "row_version" bigint, "current_version_id" "uuid", "current_version_number" integer, "current_schema_key" "text", "current_schema_version" "text", "current_file_id" "uuid", "current_file_status" "text", "current_write_outcome" "text", "gallery_status" "text", "published_version_id" "uuid", "version_count" bigint, "like_count" bigint, "download_count" bigint, "apply_delivery_count" bigint, "latest_submission_status" "text", "latest_review_reason" "text", "latest_reviewed_at" timestamp with time zone, "delete_requested_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_config_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  return query
    select c.id, c.platform_id, c.platform_account_id,
      coalesce(pr.display_name, 'Unknown author'::text),
      c.title, c.description, c.status, c.row_version,
      c.current_version_id, cv.version_number, cv.schema_key, cv.schema_version,
      cv.file_id, cf.status, cf.write_outcome,
      coalesce(e.status, 'none'::text), e.published_version_id,
      (select count(*) from public.platform_config_versions v
        where v.platform_id = c.platform_id and v.config_id = c.id),
      (select count(*) from public.platform_config_likes l
        where l.platform_id = c.platform_id and l.config_id = c.id),
      (select count(*) from public.platform_config_usage_events u
        where u.platform_id = c.platform_id and u.config_id = c.id
          and u.event_type = 'download_completed'),
      (select count(*) from public.platform_config_usage_events u
        where u.platform_id = c.platform_id and u.config_id = c.id
          and u.event_type = 'apply_delivery_completed'),
      latest.status, latest.review_reason, latest.reviewed_at,
      c.delete_requested_at, c.created_at, c.updated_at
    from public.platform_configs c
    left join public.platform_profiles pr
      on pr.platform_account_id = c.platform_account_id
    left join public.platform_config_versions cv
      on cv.platform_id = c.platform_id and cv.config_id = c.id
        and cv.id = c.current_version_id
    left join public.platform_config_files cf on cf.id = cv.file_id
    left join public.platform_config_gallery_entries e
      on e.platform_id = c.platform_id and e.config_id = c.id
    left join lateral (
      select s.status, s.review_reason, s.reviewed_at
      from public.platform_config_gallery_submissions s
      where s.platform_id = c.platform_id and s.config_id = c.id
      order by s.submitted_at desc, s.id desc
      limit 1
    ) latest on true
    where c.platform_id = p_platform_id and c.id = p_config_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
end;
$$;


ALTER FUNCTION "private"."admin_config_resource_read"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_config_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_config_review_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_cursor_submission_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("submission_id" "uuid", "config_id" "uuid", "version_id" "uuid", "title" "text", "author_display_name" "text", "schema_key" "text", "schema_version" "text", "changelog" "text", "version_number" integer, "submitted_at" timestamp with time zone, "current_gallery_status" "text", "current_published_version_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_cursor_submitted_at timestamptz;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from public.platforms p where p.id = p_platform_id) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if p_cursor_submission_id is not null then
    select s.submitted_at into v_cursor_submitted_at
    from public.platform_config_gallery_submissions s
    where s.platform_id = p_platform_id and s.id = p_cursor_submission_id
      and s.status = 'pending';
    if v_cursor_submitted_at is null then
      raise exception using errcode = 'P0002', message = 'resource_not_found';
    end if;
  end if;
  return query
    select s.id, s.config_id, s.version_id, c.title,
      coalesce(pr.display_name, 'Unknown author'::text),
      v.schema_key, v.schema_version, v.changelog, v.version_number,
      s.submitted_at, coalesce(e.status, 'none'::text), e.published_version_id
    from public.platform_config_gallery_submissions s
    join public.platform_configs c
      on c.platform_id = s.platform_id and c.id = s.config_id
    join public.platform_config_versions v
      on v.platform_id = s.platform_id and v.config_id = s.config_id
        and v.id = s.version_id
    left join public.platform_profiles pr
      on pr.platform_account_id = c.platform_account_id
    left join public.platform_config_gallery_entries e
      on e.platform_id = s.platform_id and e.config_id = s.config_id
    where s.platform_id = p_platform_id and s.status = 'pending'
      and (p_cursor_submission_id is null
        or (s.submitted_at, s.id) < (v_cursor_submitted_at, p_cursor_submission_id))
    order by s.submitted_at desc, s.id desc
    limit p_limit;
end;
$$;


ALTER FUNCTION "private"."admin_config_review_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_cursor_submission_id" "uuid", "p_limit" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_config_usage_summary"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_config_id" "uuid") RETURNS TABLE("config_id" "uuid", "like_count" bigint, "download_count" bigint, "apply_delivery_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_config_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (
    select 1 from public.platform_configs c
    where c.platform_id = p_platform_id and c.id = p_config_id
  ) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  return query select p_config_id,
    (select count(*) from public.platform_config_likes l
      where l.platform_id = p_platform_id and l.config_id = p_config_id),
    (select count(*) from public.platform_config_usage_events u
      where u.platform_id = p_platform_id and u.config_id = p_config_id
        and u.event_type = 'download_completed'),
    (select count(*) from public.platform_config_usage_events u
      where u.platform_id = p_platform_id and u.config_id = p_config_id
        and u.event_type = 'apply_delivery_completed');
end;
$$;


ALTER FUNCTION "private"."admin_config_usage_summary"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_config_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_deletion_job_list"("p_ctx" "private"."admin_context", "p_limit" integer DEFAULT 20) RETURNS TABLE("job_id" "uuid", "request_id" "uuid", "user_id" "uuid", "state" "text", "checkpoint" "text", "fence" bigint, "retry_count" integer, "next_attempt_at" timestamp with time zone, "last_error_code" "text", "created_at" timestamp with time zone, "completed_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (
       select 1
       from private.system_admin sa
       where sa.user_id = (p_ctx).admin_user_id
     )
     or not exists (
       select 1
       from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id)
       where active
     ) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;
  return query
    select j.id, j.request_id, j.user_id, j.state, j.checkpoint, j.fence,
      j.retry_count, j.next_attempt_at, j.last_error_code, j.created_at, j.completed_at
    from private.deletion_jobs j
    order by j.created_at desc, j.id desc
    limit p_limit;
end;
$$;


