CREATE OR REPLACE FUNCTION "private"."admin_deletion_job_read"("p_ctx" "private"."admin_context", "p_job_id" "uuid") RETURNS TABLE("job_id" "uuid", "request_id" "uuid", "user_id" "uuid", "state" "text", "checkpoint" "text", "fence" bigint, "retry_count" integer, "next_attempt_at" timestamp with time zone, "last_error_code" "text", "created_at" timestamp with time zone, "completed_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if p_job_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (
       select 1
       from private.system_admin sa
       where sa.user_id = (p_ctx).admin_user_id
     )
     or not exists (
       select 1
       from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id)
       where active
     ) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;
  return query
    select j.id, j.request_id, j.user_id, j.state, j.checkpoint, j.fence,
