ALTER FUNCTION "private"."admin_deletion_job_read"("p_ctx" "private"."admin_context", "p_job_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_deletion_job_retry"("p_ctx" "private"."admin_context", "p_job_id" "uuid", "p_recent_proof_id" "uuid", "p_idempotency_key" "text") RETURNS TABLE("job_id" "uuid", "state" "text", "checkpoint" "text", "retry_count" integer, "next_attempt_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_job private.deletion_jobs;
  v_proof private.admin_step_up;
  v_hash bytea;
  v_existing private.admin_idempotency%rowtype;
  v_new boolean := false;
  v_now timestamptz := clock_timestamp();
  v_response jsonb;
begin
  if p_job_id is null or p_recent_proof_id is null
     or p_idempotency_key is null or length(p_idempotency_key) not between 1 and 128 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;
  select * into v_proof from private.admin_step_up p where p.id = p_recent_proof_id
    and p.user_id = (p_ctx).admin_user_id and p.session_id = (p_ctx).session_id
    and p.expires_at > v_now for update;
  if not found then raise exception using errcode = '42501', message = 'recent_mfa_required'; end if;
  v_hash := extensions.digest(convert_to(p_job_id::text || ':retry', 'utf8'), 'sha256');
  insert into private.admin_idempotency(admin_user_id, scope, operation, idempotency_key, request_hash)
  values ((p_ctx).admin_user_id, 'global', 'deletion_job_retry', p_idempotency_key, v_hash)
  on conflict (admin_user_id, scope, operation, idempotency_key)
    do nothing returning true into v_new;
  if not coalesce(v_new, false) then
    select * into v_existing from private.admin_idempotency i
    where i.admin_user_id = (p_ctx).admin_user_id and i.scope = 'global'
      and i.operation = 'deletion_job_retry' and i.idempotency_key = p_idempotency_key for update;
    if v_existing.request_hash <> v_hash then raise exception using errcode = '23505', message = 'idempotency_conflict'; end if;
    if v_existing.state = 'completed' then
      return query select (v_existing.response_body->>'job_id')::uuid,
        v_existing.response_body->>'state', v_existing.response_body->>'checkpoint',
        (v_existing.response_body->>'retry_count')::integer,
        (v_existing.response_body->>'next_attempt_at')::timestamptz;
      return;
    end if;
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;
  select * into v_job from private.deletion_jobs j where j.id = p_job_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_job.state not in ('blocked', 'retry') then raise exception using errcode = 'P0001', message = 'deletion_job_not_retryable'; end if;
  update private.deletion_jobs j
  set state = 'retry', retry_count = j.retry_count + 1,
      next_attempt_at = v_now, last_error_code = null, fence = j.fence + 1
  where j.id = v_job.id
  returning * into v_job;
  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, null, null,
    'identity.delete_retry_requested', 'deletion_job', v_job.id, null, null,
    jsonb_build_object('checkpoint', v_job.checkpoint, 'retry_count', v_job.retry_count)
  );
  v_response := jsonb_build_object(
    'job_id', v_job.id, 'state', v_job.state, 'checkpoint', v_job.checkpoint,
    'retry_count', v_job.retry_count, 'next_attempt_at', v_job.next_attempt_at
  );
  update private.admin_idempotency i
  set state = 'completed', response_status = 202, response_body = v_response
  where i.admin_user_id = (p_ctx).admin_user_id and i.scope = 'global'
    and i.operation = 'deletion_job_retry' and i.idempotency_key = p_idempotency_key;
  return query select v_job.id, v_job.state, v_job.checkpoint, v_job.retry_count, v_job.next_attempt_at;
end;
$$;


ALTER FUNCTION "private"."admin_deletion_job_retry"("p_ctx" "private"."admin_context", "p_job_id" "uuid", "p_recent_proof_id" "uuid", "p_idempotency_key" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_deletion_job_start"("p_ctx" "private"."admin_context", "p_request_id" "uuid", "p_recent_proof_id" "uuid", "p_idempotency_key" "text") RETURNS TABLE("job_id" "uuid", "request_id" "uuid", "state" "text", "checkpoint" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_request private.deletion_requests;
  v_job private.deletion_jobs;
  v_existing private.admin_idempotency%rowtype;
  v_hash bytea;
  v_new boolean := false;
  v_now timestamptz := clock_timestamp();
  v_response jsonb;
begin
  if (p_ctx).admin_user_id is null or (p_ctx).session_id is null
     or (p_ctx).request_id is null or p_request_id is null
     or p_recent_proof_id is null
     or p_idempotency_key is null or length(p_idempotency_key) not between 1 and 128
     or not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active)
     or not exists (
       select 1 from private.admin_step_up proof
       where proof.id = p_recent_proof_id and proof.user_id = (p_ctx).admin_user_id
         and proof.session_id = (p_ctx).session_id and proof.expires_at > v_now
         and proof.verified_at <= v_now
     ) then
    raise exception using errcode = case when p_idempotency_key is null or length(p_idempotency_key) not between 1 and 128 then '22023' else '42501' end,
      message = case when p_idempotency_key is null or length(p_idempotency_key) not between 1 and 128 then 'invalid_input' else 'recent_mfa_required' end;
  end if;

  v_hash := extensions.digest(convert_to(p_request_id::text || ':global-delete', 'utf8'), 'sha256');
  insert into private.admin_idempotency(
    admin_user_id, scope, operation, idempotency_key, request_hash
  ) values (
    (p_ctx).admin_user_id, 'global', 'deletion_job_start', p_idempotency_key, v_hash
  ) on conflict (admin_user_id, scope, operation, idempotency_key)
    do nothing returning true into v_new;
  if not coalesce(v_new, false) then
    select * into v_existing from private.admin_idempotency i
    where i.admin_user_id = (p_ctx).admin_user_id and i.scope = 'global'
      and i.operation = 'deletion_job_start' and i.idempotency_key = p_idempotency_key
    for update;
    if v_existing.request_hash <> v_hash then
      raise exception using errcode = '23505', message = 'idempotency_conflict';
    end if;
    if v_existing.state = 'completed' then
      return query select (v_existing.response_body->>'job_id')::uuid,
        (v_existing.response_body->>'request_id')::uuid,
        v_existing.response_body->>'state', v_existing.response_body->>'checkpoint';
      return;
    end if;
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;

  select * into v_request from private.deletion_requests r
  where r.id = p_request_id for update;
  if not found or v_request.user_id is null then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if v_request.state = 'pending_admin' then
    update private.deletion_requests r
    set state = 'approved', approved_at = v_now, approved_by = (p_ctx).admin_user_id
    where r.id = p_request_id
    returning * into v_request;
  elsif v_request.state <> 'approved' then
    raise exception using errcode = 'P0001', message = 'deletion_request_not_approvable';
  end if;

  insert into private.identity_lifecycle(user_id, state)
  values (v_request.user_id, 'deleting')
  on conflict (user_id) do update set state = 'deleting', updated_at = v_now;
  insert into private.deletion_jobs(request_id, user_id, state, checkpoint, next_attempt_at)
  values (v_request.id, v_request.user_id, 'pending', 'created', v_now)
  on conflict on constraint deletion_jobs_request_id_key
    do update set user_id = excluded.user_id
  returning * into v_job;
  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, null, null,
    'identity.delete_approved', 'deletion_job', v_job.id, null, null,
    jsonb_build_object('request_id', v_request.id, 'checkpoint', v_job.checkpoint)
  );
  v_response := jsonb_build_object(
    'job_id', v_job.id, 'request_id', v_job.request_id,
    'state', v_job.state, 'checkpoint', v_job.checkpoint
  );
  update private.admin_idempotency i
  set state = 'completed', response_status = 202, response_body = v_response
  where i.admin_user_id = (p_ctx).admin_user_id and i.scope = 'global'
    and i.operation = 'deletion_job_start' and i.idempotency_key = p_idempotency_key;
  return query select v_job.id, v_job.request_id, v_job.state, v_job.checkpoint;
end;
$$;


ALTER FUNCTION "private"."admin_deletion_job_start"("p_ctx" "private"."admin_context", "p_request_id" "uuid", "p_recent_proof_id" "uuid", "p_idempotency_key" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_entitlement_command"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_action" "text", "p_operation_id" "uuid", "p_plan_id" "uuid" DEFAULT NULL::"uuid", "p_duration_value" integer DEFAULT NULL::integer, "p_duration_unit" "text" DEFAULT NULL::"text", "p_grant_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS TABLE("outcome" "text", "grant_id" "uuid", "account_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_account public.platform_accounts;
  v_grant public.subscription_grants;
  v_sequence bigint;
  v_existing public.subscription_events;
  v_new_grant record;
begin
  if p_operation_id is null or p_reason is null or length(p_reason) not between 1 and 1024
     or p_action not in ('grant', 'revoke', 'pause', 'resume') then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;
  select * into v_account from public.platform_accounts a
  where a.platform_id = p_platform_id and a.id = p_platform_account_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  select * into v_existing from public.subscription_events e
  where e.platform_id = p_platform_id and e.platform_account_id = p_platform_account_id
    and e.operation_id = p_operation_id and e.event_type = case when p_action = 'grant' then 'granted' when p_action = 'revoke' then 'revoked' else p_action || 'd' end;
  if found then return query select 'replayed'::text, v_existing.grant_id, v_account.status; return; end if;

  if p_action = 'grant' then
    select * into v_new_grant from private.entitlement_apply(
      p_platform_id, p_platform_account_id, p_plan_id, 'admin', p_operation_id,
      p_duration_value, p_duration_unit, (p_ctx).admin_user_id, p_reason, null);
    return query select 'applied'::text, v_new_grant.grant_id, v_account.status;
    return;
  end if;
  if p_action = 'revoke' then
    select * into v_grant from public.subscription_grants g
    where g.platform_id = p_platform_id and g.platform_account_id = p_platform_account_id and g.id = p_grant_id;
    if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
    select coalesce(max(e.sequence), 0) + 1 into v_sequence from public.subscription_events e
    where e.platform_id = p_platform_id and e.platform_account_id = p_platform_account_id;
    insert into public.subscription_events(platform_id, platform_account_id, sequence, event_type, grant_id, operation_id, actor_user_id, reason)
      values(p_platform_id, p_platform_account_id, v_sequence, 'revoked', p_grant_id, p_operation_id, (p_ctx).admin_user_id, p_reason);
    perform private.entitlement_recompute(p_platform_id, p_platform_account_id);
    perform private.audit_append(p_operation_id, 'admin', (p_ctx).admin_user_id, p_platform_id, p_platform_account_id,
      'entitlement.revoked', 'subscription_grant', p_grant_id, null, null, '{}'::jsonb);
    return query select 'applied'::text, p_grant_id, v_account.status;
    return;
  end if;
  select coalesce(max(e.sequence), 0) + 1 into v_sequence from public.subscription_events e
  where e.platform_id = p_platform_id and e.platform_account_id = p_platform_account_id;
  insert into public.subscription_events(platform_id, platform_account_id, sequence, event_type, operation_id, actor_user_id, reason)
    values(p_platform_id, p_platform_account_id, v_sequence, p_action || 'd', p_operation_id, (p_ctx).admin_user_id, p_reason);
  perform private.entitlement_recompute(p_platform_id, p_platform_account_id);
  perform private.audit_append(p_operation_id, 'admin', (p_ctx).admin_user_id, p_platform_id, p_platform_account_id,
    'entitlement.' || p_action, 'platform_account', p_platform_account_id, null, null, '{}'::jsonb);
  return query select 'applied'::text, null::uuid, v_account.status;
end;
$$;


ALTER FUNCTION "private"."admin_entitlement_command"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_action" "text", "p_operation_id" "uuid", "p_plan_id" "uuid", "p_duration_value" integer, "p_duration_unit" "text", "p_grant_id" "uuid", "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_entitlement_correction_apply"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_original_grant_id" "uuid", "p_expected_event_sequence" bigint, "p_replacement_plan_id" "uuid", "p_replacement_duration_value" integer, "p_replacement_duration_unit" "text", "p_operation_id" "uuid", "p_reason" "text") RETURNS TABLE("outcome" "text", "original_grant_id" "uuid", "replacement_grant_id" "uuid", "event_sequence" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_subscription public.subscriptions;
  v_existing public.subscription_grant_corrections;
  v_revoke_operation_id uuid;
  v_grant_operation_id uuid;
  v_replacement record;
  v_current_sequence bigint;
begin
  if p_platform_id is null or p_platform_account_id is null or p_original_grant_id is null
     or p_expected_event_sequence is null or p_expected_event_sequence < 0
     or p_replacement_plan_id is null or p_replacement_duration_value is null
     or p_replacement_duration_value <= 0
     or p_replacement_duration_unit not in ('month', 'year')
     or p_operation_id is null or p_reason is null or length(p_reason) not between 1 and 1024 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;
  if not (
    (p_replacement_duration_value = 1 and p_replacement_duration_unit = 'month')
    or (p_replacement_duration_value = 1 and p_replacement_duration_unit = 'year')
    or (p_replacement_duration_value = 99 and p_replacement_duration_unit = 'year')
  ) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  perform 1 from public.platforms p
  where p.id = p_platform_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  perform 1 from public.platform_accounts a
  where a.platform_id = p_platform_id and a.id = p_platform_account_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  select s.* into v_subscription from public.subscriptions s
  where s.platform_id = p_platform_id and s.platform_account_id = p_platform_account_id
  for update;
  v_current_sequence := coalesce(v_subscription.last_event_sequence, 0);

  -- The operation id is the durable idempotency key. Check it after the
  -- account/subscription locks but before the stale snapshot precondition so
  -- retries return the committed result after the event sequence advances.
  select c.* into v_existing from public.subscription_grant_corrections c
  where c.platform_id = p_platform_id and c.operation_id = p_operation_id;
  if found then
    if v_existing.platform_account_id <> p_platform_account_id
       or v_existing.original_grant_id <> p_original_grant_id then
      raise exception using errcode = '23505', message = 'idempotency_conflict';
    end if;
    return query select 'replayed'::text, v_existing.original_grant_id,
      v_existing.replacement_grant_id, v_current_sequence;
    return;
  end if;

  if v_current_sequence <> p_expected_event_sequence then
    raise exception using errcode = '40001', message = 'precondition_failed';
  end if;

  if exists (select 1 from public.subscription_grant_corrections c
             where c.platform_id = p_platform_id and c.original_grant_id = p_original_grant_id) then
    raise exception using errcode = '23505', message = 'correction_exists';
  end if;
  perform 1 from public.subscription_grants g
  where g.platform_id = p_platform_id and g.platform_account_id = p_platform_account_id
    and g.id = p_original_grant_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if exists (select 1 from public.subscription_events e
             where e.platform_id = p_platform_id and e.platform_account_id = p_platform_account_id
               and e.grant_id = p_original_grant_id and e.event_type = 'revoked') then
    raise exception using errcode = 'P0001', message = 'grant_already_revoked';
  end if;
  if not exists (select 1 from public.plans p
                 where p.platform_id = p_platform_id and p.id = p_replacement_plan_id
                   and p.kind = 'paid' and p.status = 'active') then
    raise exception using errcode = 'P0001', message = 'plan_unavailable';
  end if;

  v_revoke_operation_id := (
    substr(md5(p_operation_id::text || ':correction:revoke'), 1, 8) || '-' ||
    substr(md5(p_operation_id::text || ':correction:revoke'), 9, 4) || '-' ||
    substr(md5(p_operation_id::text || ':correction:revoke'), 13, 4) || '-' ||
    substr(md5(p_operation_id::text || ':correction:revoke'), 17, 4) || '-' ||
    substr(md5(p_operation_id::text || ':correction:revoke'), 21, 12)
  )::uuid;
  v_grant_operation_id := (
    substr(md5(p_operation_id::text || ':correction:grant'), 1, 8) || '-' ||
    substr(md5(p_operation_id::text || ':correction:grant'), 9, 4) || '-' ||
    substr(md5(p_operation_id::text || ':correction:grant'), 13, 4) || '-' ||
    substr(md5(p_operation_id::text || ':correction:grant'), 17, 4) || '-' ||
    substr(md5(p_operation_id::text || ':correction:grant'), 21, 12)
  )::uuid;

  perform private.admin_entitlement_command(
    p_ctx, p_platform_id, p_platform_account_id, 'revoke',
    v_revoke_operation_id, null, null, null, p_original_grant_id,
    'correction: ' || p_reason
  );
  select * into v_replacement from private.entitlement_apply(
    p_platform_id, p_platform_account_id, p_replacement_plan_id, 'admin',
    v_grant_operation_id, p_replacement_duration_value, p_replacement_duration_unit,
    (p_ctx).admin_user_id, 'correction: ' || p_reason, null
  );
  insert into public.subscription_grant_corrections (
    platform_id, platform_account_id, operation_id, original_grant_id,
    replacement_grant_id, expected_event_sequence, reason, created_by
  ) values (
    p_platform_id, p_platform_account_id, p_operation_id, p_original_grant_id,
    v_replacement.grant_id, p_expected_event_sequence, p_reason, (p_ctx).admin_user_id
  );
  select coalesce(s.last_event_sequence, 0) into v_current_sequence
  from public.subscriptions s
  where s.platform_id = p_platform_id and s.platform_account_id = p_platform_account_id;
  return query select 'applied'::text, p_original_grant_id, v_replacement.grant_id, v_current_sequence;
end;
$$;


ALTER FUNCTION "private"."admin_entitlement_correction_apply"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_original_grant_id" "uuid", "p_expected_event_sequence" bigint, "p_replacement_plan_id" "uuid", "p_replacement_duration_value" integer, "p_replacement_duration_unit" "text", "p_operation_id" "uuid", "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_entitlement_correction_preview"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_grant_id" "uuid") RETURNS TABLE("original_grant_id" "uuid", "plan_id" "uuid", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "already_revoked" boolean, "current_event_sequence" bigint, "later_grant_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;
  return query
    select g.id, g.plan_id, g.starts_at, g.ends_at,
      exists (
        select 1 from public.subscription_events revoked
        where revoked.platform_id = g.platform_id
          and revoked.platform_account_id = g.platform_account_id
          and revoked.grant_id = g.id and revoked.event_type = 'revoked'
      ),
      coalesce((select s.last_event_sequence from public.subscriptions s
        where s.platform_id = g.platform_id and s.platform_account_id = g.platform_account_id), 0),
      (select count(*) from public.subscription_grants later
        where later.platform_id = g.platform_id
          and later.platform_account_id = g.platform_account_id
          and later.starts_at >= g.starts_at and later.id <> g.id)
    from public.subscription_grants g
    where g.platform_id = p_platform_id
      and g.platform_account_id = p_platform_account_id
      and g.id = p_grant_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
end;
$$;


ALTER FUNCTION "private"."admin_entitlement_correction_preview"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_grant_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_feedback_attachment_download_authorize"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_id" "uuid", "p_attachment_id" "uuid") RETURNS TABLE("attachment_id" "uuid", "storage_bucket" "text", "storage_path" "text", "original_name" "text", "mime_type" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.billing_admin_assert(p_ctx);
  return query
  select a.id, a.storage_bucket, a.storage_path, a.original_name, a.mime_type
  from public.platform_feedback f
  join public.platform_feedback_attachments a
    on a.platform_id = f.platform_id and a.feedback_id = f.id
  where f.platform_id = p_platform_id and f.id = p_feedback_id
    and f.status in ('new','reviewing','planned','resolved','closed')
    and a.id = p_attachment_id and a.status = 'active'
    and a.write_outcome = 'confirmed' and a.storage_path is not null;
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
end;
$$;


ALTER FUNCTION "private"."admin_feedback_attachment_download_authorize"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_id" "uuid", "p_attachment_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_feedback_batch_delete"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_ids" "uuid"[], "p_reason" "text", "p_operation_id" "uuid") RETURNS TABLE("feedback_id" "uuid", "status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_feedback_id uuid;
  v_status text;
  v_count integer;
  v_ids uuid[];
  v_reason text := btrim(p_reason);
  v_scope text;
  v_hash bytea;
  v_existing private.admin_idempotency%rowtype;
  v_new boolean := false;
  v_items jsonb := '[]'::jsonb;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_feedback_ids is null
     or cardinality(p_feedback_ids) not between 1 and 100
     or p_reason is null or length(v_reason) not between 1 and 128
     or p_operation_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  select array_agg(x order by x), count(*)::integer
    into v_ids, v_count
  from (select distinct unnest(p_feedback_ids) as x) ids;
  if v_count <> cardinality(p_feedback_ids) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  v_scope := 'platform:' || p_platform_id::text;
  v_hash := extensions.digest(convert_to(
    p_platform_id::text || ':' || array_to_string(v_ids, ',') || ':' || v_reason,
    'utf8'
  ), 'sha256');

  insert into private.admin_idempotency(
    admin_user_id, platform_id, scope, operation, idempotency_key, request_hash
  ) values (
    (p_ctx).admin_user_id, p_platform_id, v_scope, 'feedback_batch_delete',
    p_operation_id::text, v_hash
  ) on conflict (admin_user_id, scope, operation, idempotency_key)
    do nothing returning true into v_new;

  if not coalesce(v_new, false) then
    select * into v_existing
    from private.admin_idempotency i
    where i.admin_user_id = (p_ctx).admin_user_id
      and i.scope = v_scope
      and i.operation = 'feedback_batch_delete'
      and i.idempotency_key = p_operation_id::text
    for update;
    if v_existing.request_hash <> v_hash then
      raise exception using errcode = '23505', message = 'idempotency_conflict';
    end if;
    if v_existing.state = 'completed' then
      return query
      select (item->>'feedback_id')::uuid, item->>'status'
      from jsonb_array_elements(v_existing.response_body->'items') item;
      return;
    end if;
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;

  if exists (
    select 1
    from unnest(v_ids) requested(id)
    left join public.platform_feedback f
      on f.platform_id = p_platform_id and f.id = requested.id
    where f.id is null or f.status in ('draft', 'deleted')
  ) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if exists (
    select 1
    from unnest(v_ids) requested(id)
    join public.platform_feedback f
      on f.platform_id = p_platform_id and f.id = requested.id
    where f.status = 'deleting'
  ) then
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;

  foreach v_feedback_id in array v_ids loop
    perform private.feedback_privacy_delete(
      v_feedback_id, left('admin:' || v_reason, 128), clock_timestamp()
    );
    select f.status into v_status
    from public.platform_feedback f
    where f.platform_id = p_platform_id and f.id = v_feedback_id;
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'feedback_id', v_feedback_id,
      'status', v_status
    ));
  end loop;

  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, p_platform_id, null,
    'feedback.batch_delete_requested', 'platform', p_platform_id, null, null,
    jsonb_build_object('operation_id', p_operation_id, 'feedback_count', v_count)
  );

  update private.admin_idempotency i
  set state = 'completed', response_status = 202,
      response_body = jsonb_build_object('operation_id', p_operation_id, 'items', v_items)
  where i.admin_user_id = (p_ctx).admin_user_id
    and i.scope = v_scope
    and i.operation = 'feedback_batch_delete'
    and i.idempotency_key = p_operation_id::text;

  return query
  select (item->>'feedback_id')::uuid, item->>'status'
  from jsonb_array_elements(v_items) item;
end;
$$;


ALTER FUNCTION "private"."admin_feedback_batch_delete"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_ids" "uuid"[], "p_reason" "text", "p_operation_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_feedback_export_rows"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_query" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_label" "text" DEFAULT NULL::"text", "p_user" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_has_attachments" boolean DEFAULT NULL::boolean, "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 5001) RETURNS TABLE("feedback_id" "uuid", "submitted_at" timestamp with time zone, "author_display_name" "text", "user_id" "uuid", "platform_account_id" "uuid", "contact_allowed" boolean, "contact_email" "text", "category" "text", "status" "text", "flagged" boolean, "labels" "text"[], "attachment_count" integer, "title" "text", "body" "text", "resolved_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_query text := nullif(btrim(p_query), '');
  v_label text := nullif(lower(btrim(p_label)), '');
  v_user text := nullif(btrim(p_user), '');
  v_email text := nullif(lower(btrim(p_email)), '');
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_limit not between 1 and 5001
     or p_feedback_ids is not null and cardinality(p_feedback_ids) > 100
     or p_status is not null and p_status not in ('new','reviewing','planned','resolved','closed','deleting')
     or p_category is not null and p_category not in ('bug','idea','experience','other')
     or p_from is not null and p_to is not null and p_from > p_to then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  return query
  select f.id, f.submitted_at,
    coalesce(f.author_display_name_snapshot, 'Unknown user'::text), f.user_id,
    f.platform_account_id, f.contact_allowed, f.contact_email_snapshot,
    f.category, f.status, f.flagged,
    coalesce((select array_agg(l.label order by l.label)
      from public.platform_feedback_labels l where l.feedback_id = f.id), '{}'::text[]),
    (select count(*)::integer from public.platform_feedback_attachments a
      where a.feedback_id = f.id and a.status not in ('deleted','expired','failed')),
    f.title, f.body, f.resolved_at
  from public.platform_feedback f
  where f.platform_id = p_platform_id and f.status not in ('draft','deleted')
    and (p_feedback_ids is null or f.id = any(p_feedback_ids))
    and (p_status is null or f.status = p_status)
    and (p_category is null or f.category = p_category)
    and (v_label is null or exists (select 1 from public.platform_feedback_labels l
      where l.feedback_id = f.id and lower(l.label) = v_label))
    and (v_user is null
      or f.user_id::text ilike '%' || v_user || '%'
      or f.platform_account_id::text ilike '%' || v_user || '%'
      or coalesce(f.author_display_name_snapshot, '') ilike '%' || v_user || '%')
    and (v_email is null or lower(coalesce(f.contact_email_snapshot, '')) ilike '%' || v_email || '%')
    and (p_has_attachments is null or p_has_attachments = exists (
      select 1 from public.platform_feedback_attachments a
      where a.feedback_id = f.id and a.status not in ('deleted','expired','failed')))
    and (p_from is null or coalesce(f.submitted_at, f.created_at) >= p_from)
    and (p_to is null or coalesce(f.submitted_at, f.created_at) <= p_to)
    and (v_query is null
      or coalesce(f.title, '') ilike '%' || v_query || '%'
      or coalesce(f.body, '') ilike '%' || v_query || '%'
      or coalesce(f.author_display_name_snapshot, '') ilike '%' || v_query || '%'
      or coalesce(f.contact_email_snapshot, '') ilike '%' || v_query || '%')
  order by coalesce(f.submitted_at, f.created_at) desc, f.id desc
  limit p_limit;
end;
$$;


ALTER FUNCTION "private"."admin_feedback_export_rows"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_ids" "uuid"[], "p_query" "text", "p_status" "text", "p_category" "text", "p_label" "text", "p_user" "text", "p_email" "text", "p_has_attachments" boolean, "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_limit" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_feedback_flag_update"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_id" "uuid", "p_expected_row_version" bigint, "p_flagged" boolean, "p_reason" "text") RETURNS TABLE("feedback_id" "uuid", "flagged" boolean, "row_version" bigint, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_feedback public.platform_feedback;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_feedback_id is null or p_expected_row_version is null
     or p_expected_row_version < 1 or p_flagged is null
     or p_reason is null or length(btrim(p_reason)) not between 1 and 2000 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_feedback from public.platform_feedback f
  where f.platform_id = p_platform_id and f.id = p_feedback_id for update;
  if not found or v_feedback.status in ('draft','deleting','deleted') then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if v_feedback.row_version <> p_expected_row_version then
    raise exception using errcode = '40001', message = 'precondition_failed';
  end if;
  update public.platform_feedback f set flagged = p_flagged, row_version = f.row_version + 1
  where f.id = p_feedback_id returning * into v_feedback;
  insert into public.platform_feedback_events(platform_id, feedback_id, event_type, actor_user_id, metadata)
  values (p_platform_id, p_feedback_id, 'flag_changed', (p_ctx).admin_user_id,
    jsonb_build_object('flagged', p_flagged, 'reason', btrim(p_reason)));
  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, p_platform_id, v_feedback.platform_account_id,
    'feedback.flag_changed', 'platform_feedback', p_feedback_id, null, null,
    jsonb_build_object('flagged', p_flagged)
  );
  return query select v_feedback.id, v_feedback.flagged, v_feedback.row_version, v_feedback.updated_at;
end;
$$;


ALTER FUNCTION "private"."admin_feedback_flag_update"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_id" "uuid", "p_expected_row_version" bigint, "p_flagged" boolean, "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_feedback_labels_replace"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_id" "uuid", "p_expected_row_version" bigint, "p_labels" "text"[]) RETURNS TABLE("feedback_id" "uuid", "labels" "text"[], "row_version" bigint, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_feedback public.platform_feedback;
  v_labels text[];
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_feedback_id is null or p_expected_row_version is null
     or p_expected_row_version < 1 or p_labels is null or cardinality(p_labels) > 10 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select coalesce(array_agg(label order by label), '{}'::text[]) into v_labels
  from (
    select distinct lower(btrim(value)) as label from unnest(p_labels) as t(value)
  ) normalized
  where label <> '';
  if exists (select 1 from unnest(v_labels) x where length(x) > 32 or x ~ '[[:cntrl:]]') then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_feedback from public.platform_feedback f
  where f.platform_id = p_platform_id and f.id = p_feedback_id for update;
  if not found or v_feedback.status in ('draft','deleting','deleted') then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if v_feedback.row_version <> p_expected_row_version then
    raise exception using errcode = '40001', message = 'precondition_failed';
  end if;
  delete from public.platform_feedback_labels l where l.feedback_id = p_feedback_id;
  insert into public.platform_feedback_labels(platform_id, feedback_id, label)
  select p_platform_id, p_feedback_id, label from unnest(v_labels) label;
  update public.platform_feedback f set row_version = f.row_version + 1
  where f.id = p_feedback_id returning * into v_feedback;
  insert into public.platform_feedback_events(platform_id, feedback_id, event_type, actor_user_id, metadata)
  values (p_platform_id, p_feedback_id, 'labels_changed', (p_ctx).admin_user_id,
    jsonb_build_object('labels', to_jsonb(v_labels)));
  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, p_platform_id, v_feedback.platform_account_id,
    'feedback.labels_changed', 'platform_feedback', p_feedback_id, null, null,
    jsonb_build_object('label_count', cardinality(v_labels))
  );
  return query select p_feedback_id, v_labels, v_feedback.row_version, v_feedback.updated_at;
end;
$$;


ALTER FUNCTION "private"."admin_feedback_labels_replace"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_id" "uuid", "p_expected_row_version" bigint, "p_labels" "text"[]) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_feedback_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_cursor_feedback_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20, "p_query" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_category" "text" DEFAULT NULL::"text", "p_label" "text" DEFAULT NULL::"text", "p_user" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_has_attachments" boolean DEFAULT NULL::boolean, "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("feedback_id" "uuid", "platform_account_id" "uuid", "user_id" "uuid", "author_display_name" "text", "contact_allowed" boolean, "category" "text", "title" "text", "body_summary" "text", "status" "text", "flagged" boolean, "labels" "text"[], "attachment_count" integer, "row_version" bigint, "submitted_at" timestamp with time zone, "resolved_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_cursor_at timestamptz;
  v_query text := nullif(btrim(p_query), '');
  v_label text := nullif(lower(btrim(p_label)), '');
  v_user text := nullif(btrim(p_user), '');
  v_email text := nullif(lower(btrim(p_email)), '');
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_limit is null or p_limit not between 1 and 100
     or v_query is not null and length(v_query) > 256
     or p_status is not null and p_status not in ('new','reviewing','planned','resolved','closed','deleting')
     or p_category is not null and p_category not in ('bug','idea','experience','other')
     or v_label is not null and length(v_label) > 32
     or v_user is not null and length(v_user) > 320
     or v_email is not null and length(v_email) > 320
     or p_from is not null and p_to is not null and p_from > p_to then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from public.platforms p where p.id = p_platform_id) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if p_cursor_feedback_id is not null then
    select coalesce(f.submitted_at, f.created_at) into v_cursor_at
    from public.platform_feedback f
    where f.platform_id = p_platform_id and f.id = p_cursor_feedback_id
      and f.status not in ('draft','deleted');
    if v_cursor_at is null then
      raise exception using errcode = 'P0002', message = 'resource_not_found';
    end if;
  end if;

  return query
  select f.id, f.platform_account_id, f.user_id,
    coalesce(f.author_display_name_snapshot, 'Unknown user'::text),
    f.contact_allowed, f.category, f.title,
    case when f.body is null then null else left(regexp_replace(f.body, E'[\\n\\r\\t]+', ' ', 'g'), 240) end,
    f.status, f.flagged,
    coalesce((select array_agg(l.label order by l.label)
      from public.platform_feedback_labels l where l.feedback_id = f.id), '{}'::text[]),
    (select count(*)::integer from public.platform_feedback_attachments a
      where a.feedback_id = f.id and a.status not in ('deleted','expired','failed')),
    f.row_version, f.submitted_at, f.resolved_at, f.created_at, f.updated_at
  from public.platform_feedback f
  where f.platform_id = p_platform_id
    and f.status not in ('draft','deleted')
    and (p_status is null or f.status = p_status)
    and (p_category is null or f.category = p_category)
    and (v_label is null or exists (
      select 1 from public.platform_feedback_labels l
      where l.feedback_id = f.id and lower(l.label) = v_label
    ))
    and (v_user is null
      or f.user_id::text ilike '%' || v_user || '%'
      or f.platform_account_id::text ilike '%' || v_user || '%'
      or coalesce(f.author_display_name_snapshot, '') ilike '%' || v_user || '%')
    and (v_email is null or lower(coalesce(f.contact_email_snapshot, '')) ilike '%' || v_email || '%')
    and (p_has_attachments is null or p_has_attachments = exists (
      select 1 from public.platform_feedback_attachments a
      where a.feedback_id = f.id and a.status not in ('deleted','expired','failed')
    ))
    and (p_from is null or coalesce(f.submitted_at, f.created_at) >= p_from)
    and (p_to is null or coalesce(f.submitted_at, f.created_at) <= p_to)
    and (v_query is null
      or coalesce(f.title, '') ilike '%' || v_query || '%'
      or coalesce(f.body, '') ilike '%' || v_query || '%'
      or coalesce(f.author_display_name_snapshot, '') ilike '%' || v_query || '%'
      or coalesce(f.contact_email_snapshot, '') ilike '%' || v_query || '%')
    and (p_cursor_feedback_id is null
      or (coalesce(f.submitted_at, f.created_at), f.id) < (v_cursor_at, p_cursor_feedback_id))
  order by coalesce(f.submitted_at, f.created_at) desc, f.id desc
  limit p_limit;
end;
$$;


ALTER FUNCTION "private"."admin_feedback_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_cursor_feedback_id" "uuid", "p_limit" integer, "p_query" "text", "p_status" "text", "p_category" "text", "p_label" "text", "p_user" "text", "p_email" "text", "p_has_attachments" boolean, "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_feedback_note_add"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_id" "uuid", "p_note" "text") RETURNS TABLE("event_id" "uuid", "feedback_id" "uuid", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_feedback public.platform_feedback;
  v_event public.platform_feedback_events;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_feedback_id is null
     or p_note is null or length(btrim(p_note)) not between 1 and 5000 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_feedback from public.platform_feedback f
  where f.platform_id = p_platform_id and f.id = p_feedback_id;
  if not found or v_feedback.status in ('draft','deleting','deleted') then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  insert into public.platform_feedback_events(
    platform_id, feedback_id, event_type, actor_user_id, note_body, metadata
  ) values (
    p_platform_id, p_feedback_id, 'note_added', (p_ctx).admin_user_id, btrim(p_note), '{}'::jsonb
  ) returning * into v_event;
  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, p_platform_id, v_feedback.platform_account_id,
    'feedback.note_added', 'platform_feedback', p_feedback_id, null, null, '{}'::jsonb
  );
  return query select v_event.id, p_feedback_id, v_event.created_at;
end;
$$;


ALTER FUNCTION "private"."admin_feedback_note_add"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_id" "uuid", "p_note" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_feedback_read"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_id" "uuid") RETURNS TABLE("feedback_id" "uuid", "platform_id" "uuid", "platform_account_id" "uuid", "user_id" "uuid", "author_display_name" "text", "contact_allowed" boolean, "contact_email" "text", "category" "text", "title" "text", "body" "text", "status" "text", "flagged" boolean, "client_context" "jsonb", "labels" "text"[], "attachments" "jsonb", "timeline" "jsonb", "row_version" bigint, "submitted_at" timestamp with time zone, "resolved_at" timestamp with time zone, "delete_requested_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_feedback_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  return query
  select f.id, f.platform_id, f.platform_account_id, f.user_id,
    coalesce(f.author_display_name_snapshot, 'Unknown user'::text),
    f.contact_allowed, f.contact_email_snapshot, f.category, f.title, f.body,
    f.status, f.flagged, f.client_context,
    coalesce((select array_agg(l.label order by l.label)
      from public.platform_feedback_labels l where l.feedback_id = f.id), '{}'::text[]),
    coalesce((select jsonb_agg(jsonb_build_object(
        'attachment_id', a.id,
        'original_name', a.original_name,
        'mime_type', a.mime_type,
        'actual_size_bytes', a.actual_size_bytes,
        'status', a.status,
        'write_outcome', a.write_outcome,
        'created_at', a.created_at,
        'content_path', case when a.status = 'active' and a.write_outcome = 'confirmed'
          then '/admin/api/v1/platforms/' || f.platform_id::text || '/feedback/' || f.id::text
            || '/attachments/' || a.id::text || '/content'
          else null end
      ) order by a.created_at, a.id)
      from public.platform_feedback_attachments a
      where a.feedback_id = f.id and a.status <> 'deleted'), '[]'::jsonb),
    coalesce((select jsonb_agg(jsonb_build_object(
        'event_id', e.id,
        'event_type', e.event_type,
        'actor_user_id', e.actor_user_id,
        'note_body', e.note_body,
        'metadata', e.metadata,
        'created_at', e.created_at
      ) order by e.created_at, e.id)
      from public.platform_feedback_events e where e.feedback_id = f.id), '[]'::jsonb),
    f.row_version, f.submitted_at, f.resolved_at, f.delete_requested_at,
    f.created_at, f.updated_at
  from public.platform_feedback f
  where f.platform_id = p_platform_id and f.id = p_feedback_id
    and f.status not in ('draft','deleted');
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
end;
$$;


ALTER FUNCTION "private"."admin_feedback_read"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_feedback_status_update"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_id" "uuid", "p_expected_row_version" bigint, "p_status" "text", "p_reason" "text") RETURNS TABLE("feedback_id" "uuid", "status" "text", "row_version" bigint, "resolved_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_feedback public.platform_feedback;
  v_previous text;
  v_now timestamptz := clock_timestamp();
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_feedback_id is null or p_expected_row_version is null
     or p_expected_row_version < 1 or p_status not in ('new','reviewing','planned','resolved','closed')
     or p_reason is null or length(btrim(p_reason)) not between 1 and 2000 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_feedback from public.platform_feedback f
  where f.platform_id = p_platform_id and f.id = p_feedback_id for update;
  if not found or v_feedback.status in ('draft','deleting','deleted') then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if v_feedback.row_version <> p_expected_row_version then
    raise exception using errcode = '40001', message = 'precondition_failed';
  end if;
  v_previous := v_feedback.status;
  if v_previous = p_status then
    raise exception using errcode = 'P0001', message = 'feedback_status_unchanged';
  end if;
  if not (
    (v_previous = 'new' and p_status in ('reviewing','planned','resolved','closed'))
    or (v_previous = 'reviewing' and p_status in ('new','planned','resolved','closed'))
    or (v_previous = 'planned' and p_status in ('reviewing','resolved','closed'))
    or (v_previous = 'resolved' and p_status in ('reviewing','closed'))
    or (v_previous = 'closed' and p_status = 'reviewing')
  ) then
    raise exception using errcode = 'P0001', message = 'invalid_feedback_transition';
  end if;
  update public.platform_feedback f set
    status = p_status,
    resolved_at = case
      when p_status = 'resolved' then coalesce(f.resolved_at, v_now)
      when p_status = 'closed' then f.resolved_at
      else null
    end,
    row_version = f.row_version + 1
  where f.id = v_feedback.id returning * into v_feedback;
  insert into public.platform_feedback_events(
    platform_id, feedback_id, event_type, actor_user_id, metadata
  ) values (
    p_platform_id, p_feedback_id, 'status_changed', (p_ctx).admin_user_id,
    jsonb_build_object('from', v_previous, 'to', p_status, 'reason', btrim(p_reason))
  );
  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, p_platform_id, v_feedback.platform_account_id,
    'feedback.status_changed', 'platform_feedback', p_feedback_id, null, null,
    jsonb_build_object('from', v_previous, 'to', p_status)
  );
  return query select v_feedback.id, v_feedback.status, v_feedback.row_version,
    v_feedback.resolved_at, v_feedback.updated_at;
end;
$$;


ALTER FUNCTION "private"."admin_feedback_status_update"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_feedback_id" "uuid", "p_expected_row_version" bigint, "p_status" "text", "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_identity_accounts"("p_ctx" "private"."admin_context", "p_user_ids" "uuid"[], "p_platform_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("user_id" "uuid", "identity_state" "text", "account_count" bigint, "accounts" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if (p_ctx).admin_user_id is null
     or (p_ctx).session_id is null
     or p_user_ids is null
     or cardinality(p_user_ids) > 1000
     or not exists (
       select 1 from private.system_admin sa
       where sa.user_id = (p_ctx).admin_user_id
     )
     or not exists (
       select 1
       from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id)
       where active
     ) then
    raise exception using
      errcode = case
        when p_user_ids is null or cardinality(p_user_ids) > 1000
          then '22023'
        else '42501'
      end,
      message = case
        when p_user_ids is null or cardinality(p_user_ids) > 1000
          then 'invalid_input'
        else 'admin_required'
      end;
  end if;

  return query
  with candidates as (
    select candidate.user_id, candidate.ordinality
    from unnest(p_user_ids) with ordinality as candidate(user_id, ordinality)
  )
  select
    candidate.user_id,
    coalesce(lifecycle.state, 'active')::text,
    (
      select count(*)
      from public.platform_accounts account_count_source
      where account_count_source.user_id = candidate.user_id
    )::bigint,
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'platform_id', account.platform_id,
            'platform_code', platform.code,
            'platform_name', platform.name,
            'platform_status', platform.status,
            'platform_account_id', account.id,
            'status', account.status,
            'activated_at', account.activated_at,
            'suspended_at', account.suspended_at,
            'closed_at', account.closed_at,
            'created_at', account.created_at,
            'updated_at', account.updated_at
          )
          order by account.created_at desc, account.id desc
        )
        from public.platform_accounts account
        join public.platforms platform on platform.id = account.platform_id
        where account.user_id = candidate.user_id
      ),
      '[]'::jsonb
    )
  from candidates candidate
  left join private.identity_lifecycle lifecycle on lifecycle.user_id = candidate.user_id
  where p_platform_id is null
     or exists (
       select 1
       from public.platform_accounts scoped_account
       where scoped_account.user_id = candidate.user_id
         and scoped_account.platform_id = p_platform_id
     )
  order by candidate.ordinality;
end;
$$;


ALTER FUNCTION "private"."admin_identity_accounts"("p_ctx" "private"."admin_context", "p_user_ids" "uuid"[], "p_platform_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_identity_lifecycle_read"("p_ctx" "private"."admin_context", "p_user_id" "uuid") RETURNS TABLE("user_id" "uuid", "identity_state" "text", "request_id" "uuid", "request_state" "text", "requested_at" timestamp with time zone, "approved_at" timestamp with time zone, "approved_by" "uuid", "cancelled_at" timestamp with time zone, "job_id" "uuid", "job_state" "text", "checkpoint" "text", "retry_count" integer, "next_attempt_at" timestamp with time zone, "last_error_code" "text", "job_created_at" timestamp with time zone, "completed_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if p_user_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  if (p_ctx).admin_user_id is null
     or (p_ctx).session_id is null
     or not exists (
       select 1 from private.system_admin sa
       where sa.user_id = (p_ctx).admin_user_id
     )
     or not exists (
       select 1
       from private.check_user_session(
         (p_ctx).admin_user_id,
         (p_ctx).session_id
       )
       where active
     ) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;

  return query
  select
    p_user_id,
    coalesce(lifecycle.state, 'active')::text,
    request.id,
    request.state,
    request.requested_at,
    request.approved_at,
    request.approved_by,
    request.cancelled_at,
    job.id,
    job.state,
    job.checkpoint,
    job.retry_count,
    job.next_attempt_at,
    job.last_error_code,
    job.created_at,
    job.completed_at
  from (select 1) anchor
  left join private.identity_lifecycle lifecycle
    on lifecycle.user_id = p_user_id
  left join lateral (
    select candidate.*
    from private.deletion_requests candidate
    where candidate.user_id = p_user_id
    order by
      (candidate.state in ('pending_admin', 'approved')) desc,
      candidate.requested_at desc,
      candidate.id desc
    limit 1
  ) request on true
  left join private.deletion_jobs job
    on job.request_id = request.id;
end;
$$;


ALTER FUNCTION "private"."admin_identity_lifecycle_read"("p_ctx" "private"."admin_context", "p_user_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_operation_claim"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_operation" "text", "p_operation_id" "uuid", "p_request_hash" "bytea") RETURNS TABLE("outcome" "text", "response_body" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public', 'extensions'
    AS $$
declare
  v_existing private.admin_idempotency%rowtype;
  v_new boolean := false;
  v_scope text;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_operation is null or length(p_operation) not between 1 and 128
     or p_operation_id is null or p_request_hash is null then
    raise exception using errcode='22023', message='invalid_input';
  end if;
  v_scope := 'platform:' || p_platform_id::text;
  insert into private.admin_idempotency(
    admin_user_id, platform_id, scope, operation, idempotency_key, request_hash
  ) values (
    (p_ctx).admin_user_id, p_platform_id, v_scope, p_operation,
    p_operation_id::text, p_request_hash
  ) on conflict (admin_user_id, scope, operation, idempotency_key)
    do nothing returning true into v_new;
  if coalesce(v_new, false) then
    return query select 'claimed'::text, null::jsonb;
    return;
  end if;
  select * into v_existing
  from private.admin_idempotency i
  where i.admin_user_id=(p_ctx).admin_user_id and i.scope=v_scope
    and i.operation=p_operation and i.idempotency_key=p_operation_id::text
  for update;
  if v_existing.request_hash <> p_request_hash then
    raise exception using errcode='23505', message='idempotency_conflict';
  end if;
  if v_existing.state='completed' then
    return query select 'replayed'::text, v_existing.response_body;
    return;
  end if;
  raise exception using errcode='P0001', message='operation_in_progress';
end;
$$;


ALTER FUNCTION "private"."admin_operation_claim"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_operation" "text", "p_operation_id" "uuid", "p_request_hash" "bytea") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_operation_finalize"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_operation" "text", "p_operation_id" "uuid", "p_response_body" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if p_response_body is null or jsonb_typeof(p_response_body) <> 'object' then
    raise exception using errcode='22023', message='invalid_input';
  end if;
  update private.admin_idempotency i
  set state='completed', response_status=200, response_body=p_response_body
  where i.admin_user_id=(p_ctx).admin_user_id
    and i.scope='platform:'||p_platform_id::text
    and i.operation=p_operation and i.idempotency_key=p_operation_id::text
    and i.state='pending';
  if not found then
    raise exception using errcode='P0001', message='operation_not_claimed';
  end if;
end;
$$;


ALTER FUNCTION "private"."admin_operation_finalize"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_operation" "text", "p_operation_id" "uuid", "p_response_body" "jsonb") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_origin_create"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_environment" "text", "p_origin" "text", "p_oauth_callback_url" "text", "p_password_reset_url" "text", "p_email_confirmation_url" "text") RETURNS TABLE("origin_id" "uuid", "platform_id" "uuid", "environment" "text", "origin" "text", "oauth_callback_url" "text", "password_reset_url" "text", "email_confirmation_url" "text", "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_origin public.platform_auth_origins;
begin
  if not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active)
     or not exists (select 1 from public.platforms where id = p_platform_id)
     or p_environment not in ('local', 'preview', 'staging', 'production')
     or p_origin is null or length(btrim(p_origin)) not between 1 and 512
     or p_origin ~ '[[:space:]]'
     or p_oauth_callback_url is null or length(btrim(p_oauth_callback_url)) not between 1 and 1024
     or p_password_reset_url is null or length(btrim(p_password_reset_url)) not between 1 and 1024
     or p_email_confirmation_url is null or length(btrim(p_email_confirmation_url)) not between 1 and 1024
  then raise exception using errcode = '22023', message = 'invalid_input'; end if;
  insert into public.platform_auth_origins (
    platform_id, environment, origin, oauth_callback_url,
    password_reset_url, email_confirmation_url
  ) values (
    p_platform_id, p_environment, btrim(p_origin), btrim(p_oauth_callback_url),
    btrim(p_password_reset_url), btrim(p_email_confirmation_url)
  ) returning * into v_origin;
  perform private.audit_append((p_ctx).request_id, 'admin', (p_ctx).admin_user_id,
    p_platform_id, null, 'platform.origin_created', 'platform_auth_origin', v_origin.id, null, null, '{}'::jsonb);
  return query select v_origin.id, v_origin.platform_id, v_origin.environment, v_origin.origin,
    v_origin.oauth_callback_url, v_origin.password_reset_url, v_origin.email_confirmation_url,
    v_origin.status, v_origin.created_at, v_origin.updated_at;
end;
$$;


ALTER FUNCTION "private"."admin_origin_create"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_environment" "text", "p_origin" "text", "p_oauth_callback_url" "text", "p_password_reset_url" "text", "p_email_confirmation_url" "text") OWNER TO "domain_owner";







CREATE OR REPLACE FUNCTION "private"."admin_origin_list_v2"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_query" "text" DEFAULT NULL::"text") RETURNS TABLE("origin_id" "uuid", "platform_id" "uuid", "environment" "text", "origin" "text", "oauth_callback_url" "text", "password_reset_url" "text", "email_confirmation_url" "text", "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_query text;
begin
  if p_platform_id is null or (p_query is not null and length(btrim(p_query)) > 128)
     or not exists (select 1 from private.system_admin sa where sa.user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active)
  then raise exception using errcode = case when p_platform_id is null or (p_query is not null and length(btrim(p_query)) > 128) then '22023' else '42501' end,
    message = case when p_platform_id is null or (p_query is not null and length(btrim(p_query)) > 128) then 'invalid_input' else 'admin_required' end; end if;
  v_query := nullif(btrim(p_query), '');
  return query
    select o.id, o.platform_id, o.environment, o.origin, o.oauth_callback_url,
      o.password_reset_url, o.email_confirmation_url, o.status, o.created_at, o.updated_at
    from public.platform_auth_origins o
    where o.platform_id = p_platform_id
      and (v_query is null or o.id::text ilike '%' || v_query || '%'
        or o.environment ilike '%' || v_query || '%'
        or o.origin ilike '%' || v_query || '%'
        or o.status ilike '%' || v_query || '%')
    order by o.environment, o.origin;
end;
$$;


ALTER FUNCTION "private"."admin_origin_list_v2"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_query" "text") OWNER TO "domain_owner";


