ALTER FUNCTION "private"."admin_platform_get"("p_ctx" "private"."admin_context", "p_platform_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_platform_key_confirm_deployment"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_key_id" "uuid") RETURNS TABLE("key_id" "uuid", "status" "text", "deployment_confirmed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active)
  then raise exception using errcode = '42501', message = 'admin_required'; end if;
  update private.platform_api_keys as k
  set deployment_confirmed_at = coalesce(k.deployment_confirmed_at, now()),
      deployment_confirmed_by = coalesce(k.deployment_confirmed_by, (p_ctx).admin_user_id)
  where k.id = p_key_id and k.platform_id = p_platform_id and k.status = 'active'
  returning k.id, k.status, k.deployment_confirmed_at
    into key_id, status, deployment_confirmed_at;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  perform private.audit_append((p_ctx).request_id, 'admin', (p_ctx).admin_user_id,
    p_platform_id, null, 'platform.key_deployment_confirmed', 'platform_api_key',
    p_key_id, null, null, '{}'::jsonb);
  return next;
end;
$$;


ALTER FUNCTION "private"."admin_platform_key_confirm_deployment"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_key_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_platform_key_create"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_key_id" "uuid", "p_name" "text", "p_key_hmac" "text", "p_hmac_key_version" integer, "p_key_prefix" "text", "p_key_suffix" "text", "p_creation_operation_id" "uuid", "p_expires_at" timestamp with time zone) RETURNS TABLE("key_id" "uuid", "platform_id" "uuid", "name" "text", "hmac_key_version" integer, "key_prefix" "text", "key_suffix" "text", "status" "text", "expires_at" timestamp with time zone, "creation_operation_id" "uuid", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $_$
declare
  v_key private.platform_api_keys;
begin
  if not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active)
     or not exists (select 1 from public.platforms where id = p_platform_id)
     or p_key_id is null or p_name is null or length(btrim(p_name)) not between 1 and 128
     or p_key_hmac is null or p_key_hmac !~ '^[0-9a-f]{64}$'
     or p_hmac_key_version is null or p_hmac_key_version < 1
     or p_key_prefix is null or p_key_suffix is null
     or p_creation_operation_id is null
  then raise exception using errcode = '22023', message = 'invalid_input'; end if;
  insert into private.platform_api_keys (
    id, platform_id, name, key_hmac, hmac_key_version, key_prefix, key_suffix,
    created_by, creation_operation_id, expires_at
  ) values (
    p_key_id, p_platform_id, btrim(p_name), lower(p_key_hmac), p_hmac_key_version,
    p_key_prefix, p_key_suffix, (p_ctx).admin_user_id, p_creation_operation_id, p_expires_at
  ) returning * into v_key;
  perform private.audit_append((p_ctx).request_id, 'admin', (p_ctx).admin_user_id,
    p_platform_id, null, 'platform.key_created', 'platform_api_key', v_key.id, null, null, '{}'::jsonb);
  return query select v_key.id, v_key.platform_id, v_key.name, v_key.hmac_key_version,
    v_key.key_prefix, v_key.key_suffix, v_key.status, v_key.expires_at,
    v_key.creation_operation_id, v_key.created_at;
end;
$_$;


ALTER FUNCTION "private"."admin_platform_key_create"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_key_id" "uuid", "p_name" "text", "p_key_hmac" "text", "p_hmac_key_version" integer, "p_key_prefix" "text", "p_key_suffix" "text", "p_creation_operation_id" "uuid", "p_expires_at" timestamp with time zone) OWNER TO "domain_owner";







CREATE OR REPLACE FUNCTION "private"."admin_platform_key_list_v3"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_query" "text" DEFAULT NULL::"text") RETURNS TABLE("key_id" "uuid", "platform_id" "uuid", "name" "text", "hmac_key_version" integer, "key_prefix" "text", "key_suffix" "text", "status" "text", "expires_at" timestamp with time zone, "revoked_at" timestamp with time zone, "created_by" "uuid", "revoked_by" "uuid", "creation_operation_id" "uuid", "created_at" timestamp with time zone, "deployment_confirmed_at" timestamp with time zone, "deployment_confirmed_by" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_query text;
begin
  if p_platform_id is null or (p_query is not null and length(btrim(p_query)) > 128)
     or not exists (select 1 from private.system_admin sa where sa.user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active)
  then raise exception using errcode = case when p_platform_id is null or (p_query is not null and length(btrim(p_query)) > 128) then '22023' else '42501' end,
    message = case when p_platform_id is null or (p_query is not null and length(btrim(p_query)) > 128) then 'invalid_input' else 'admin_required' end; end if;
  v_query := nullif(btrim(p_query), '');
  return query
    select k.id, k.platform_id, k.name, k.hmac_key_version, k.key_prefix, k.key_suffix,
      k.status, k.expires_at, k.revoked_at, k.created_by, k.revoked_by,
      k.creation_operation_id, k.created_at, k.deployment_confirmed_at,
      k.deployment_confirmed_by
    from private.platform_api_keys k
    where k.platform_id = p_platform_id
      and (v_query is null or k.id::text ilike '%' || v_query || '%'
        or k.name ilike '%' || v_query || '%'
        or k.status ilike '%' || v_query || '%'
        or k.key_prefix ilike '%' || v_query || '%'
        or k.key_suffix ilike '%' || v_query || '%')
    order by k.created_at desc, k.id desc;
end;
$$;


ALTER FUNCTION "private"."admin_platform_key_list_v3"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_query" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_platform_key_revoke"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_key_id" "uuid") RETURNS TABLE("key_id" "uuid", "status" "text", "revoked_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (
       select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id)
       where active
     ) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;
  update private.platform_api_keys as k
  set status = 'revoked', revoked_at = coalesce(k.revoked_at, now()), revoked_by = (p_ctx).admin_user_id
  where k.id = p_key_id and k.platform_id = p_platform_id and k.status = 'active'
  returning k.id, k.status, k.revoked_at into key_id, status, revoked_at;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  perform private.audit_append((p_ctx).request_id, 'admin', (p_ctx).admin_user_id,
    p_platform_id, null, 'platform.key_revoked', 'platform_api_key', p_key_id, null, null, '{}'::jsonb);
  return next;
end;
$$;


ALTER FUNCTION "private"."admin_platform_key_revoke"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_key_id" "uuid") OWNER TO "domain_owner";







CREATE OR REPLACE FUNCTION "private"."admin_platform_list_v3"("p_ctx" "private"."admin_context", "p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_cursor_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("platform_id" "uuid", "code" "text", "name" "text", "status" "text", "allow_activation" boolean, "default_locale" "text", "default_plan_id" "uuid", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_query text;
  v_cursor_created_at timestamptz;
begin
  if p_limit is null or p_limit not between 1 and 100
     or (p_query is not null and length(btrim(p_query)) > 128)
     or ((p_cursor_created_at is null) <> (p_cursor_id is null))
  then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  if not exists (
       select 1 from private.system_admin sa
       where sa.user_id = (p_ctx).admin_user_id
     )
     or not exists (
       select 1
       from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id)
       where active
     )
  then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;

  if p_cursor_id is not null then
    select p.created_at
      into v_cursor_created_at
    from public.platforms p
    where p.id = p_cursor_id;

    if v_cursor_created_at is null then
      raise exception using errcode = 'P0002', message = 'resource_not_found';
    end if;
  end if;

  v_query := nullif(btrim(p_query), '');
  return query
    select p.id, p.code, p.name, p.status, p.allow_activation,
      p.default_locale, p.default_plan_id, p.created_at, p.updated_at
    from public.platforms p
    where (
      v_query is null
      or p.id::text ilike '%' || v_query || '%'
      or p.code ilike '%' || v_query || '%'
      or p.name ilike '%' || v_query || '%'
      or p.status ilike '%' || v_query || '%'
    )
      and (
        p_cursor_id is null
        or (p.created_at, p.id) < (v_cursor_created_at, p_cursor_id)
      )
    order by p.created_at desc, p.id desc
    limit p_limit;
end;
$$;


ALTER FUNCTION "private"."admin_platform_list_v3"("p_ctx" "private"."admin_context", "p_query" "text", "p_limit" integer, "p_cursor_created_at" timestamp with time zone, "p_cursor_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_platform_overview"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_days" integer DEFAULT 30) RETURNS TABLE("platform_id" "uuid", "period_days" integer, "period_start" timestamp with time zone, "period_end" timestamp with time zone, "previous_start" timestamp with time zone, "total_accounts" bigint, "active_accounts" bigint, "suspended_accounts" bigint, "closed_accounts" bigint, "new_accounts" bigint, "previous_new_accounts" bigint, "period_closed_accounts" bigint, "previous_closed_accounts" bigint, "net_accounts" bigint, "previous_net_accounts" bigint, "active_paid_accounts" bigint, "orders" bigint, "previous_orders" bigint, "granted_orders" bigint, "previous_granted_orders" bigint, "attention_orders" bigint, "previous_attention_orders" bigint, "pending_config_reviews" bigint, "pending_feedback" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_period interval;
  v_period_start timestamptz;
  v_previous_start timestamptz;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_days is null or p_days not in (7, 30, 90) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from public.platforms p where p.id = p_platform_id) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  v_period := make_interval(days => p_days);
  v_period_start := v_now - v_period;
  v_previous_start := v_period_start - v_period;
  return query
  with account_metrics as (
    select count(*)::bigint as total_accounts,
      count(*) filter (where a.status = 'active')::bigint as active_accounts,
      count(*) filter (where a.status = 'suspended')::bigint as suspended_accounts,
      count(*) filter (where a.status = 'closed')::bigint as closed_accounts,
      count(*) filter (where a.created_at >= v_period_start and a.created_at < v_now)::bigint as new_accounts,
      count(*) filter (where a.created_at >= v_previous_start and a.created_at < v_period_start)::bigint as previous_new_accounts,
      count(*) filter (where a.closed_at >= v_period_start and a.closed_at < v_now)::bigint as period_closed_accounts,
      count(*) filter (where a.closed_at >= v_previous_start and a.closed_at < v_period_start)::bigint as previous_closed_accounts
    from public.platform_accounts a where a.platform_id = p_platform_id
  ), paid_metrics as (
    select count(*)::bigint as active_paid_accounts
    from private.commerce_active_paid_entitlements(p_platform_id, v_now)
  ), order_metrics as (
    select
      count(*) filter (where o.created_at >= v_period_start and o.created_at < v_now)::bigint as orders,
      count(*) filter (where o.created_at >= v_previous_start and o.created_at < v_period_start)::bigint as previous_orders,
      count(*) filter (where o.created_at >= v_period_start and o.created_at < v_now and o.entitlement_status = 'granted')::bigint as granted_orders,
      count(*) filter (where o.created_at >= v_previous_start and o.created_at < v_period_start and o.entitlement_status = 'granted')::bigint as previous_granted_orders,
      count(*) filter (where o.created_at >= v_period_start and o.created_at < v_now and (
        o.linkage_status = 'ambiguous' or o.entitlement_status = 'blocked'
        or (o.provider_paid_at is not null and o.verification_status <> 'verified' and o.resolution_status = 'open')
        or exists (select 1 from public.billing_processing_jobs j where j.billing_order_id = o.id and j.state in ('retryable','manual_review'))
      ))::bigint as attention_orders,
      count(*) filter (where o.created_at >= v_previous_start and o.created_at < v_period_start and (
        o.linkage_status = 'ambiguous' or o.entitlement_status = 'blocked'
        or (o.provider_paid_at is not null and o.verification_status <> 'verified' and o.resolution_status = 'open')
        or exists (select 1 from public.billing_processing_jobs j where j.billing_order_id = o.id and j.state in ('retryable','manual_review'))
      ))::bigint as previous_attention_orders
    from public.billing_orders o
    where o.platform_id = p_platform_id
      and o.created_at >= v_previous_start and o.created_at < v_now
  ), review_metrics as (
    select count(*)::bigint as pending_config_reviews
    from public.platform_config_gallery_submissions s
    where s.platform_id = p_platform_id and s.status = 'pending'
  ), feedback_metrics as (
    select count(*)::bigint as pending_feedback
    from public.platform_feedback f
    where f.platform_id = p_platform_id and f.status in ('new','reviewing')
  )
  select p_platform_id, p_days, v_period_start, v_now, v_previous_start,
    a.total_accounts, a.active_accounts, a.suspended_accounts, a.closed_accounts,
    a.new_accounts, a.previous_new_accounts,
    a.period_closed_accounts, a.previous_closed_accounts,
    a.new_accounts - a.period_closed_accounts,
    a.previous_new_accounts - a.previous_closed_accounts,
    paid.active_paid_accounts,
    o.orders, o.previous_orders, o.granted_orders, o.previous_granted_orders,
    o.attention_orders, o.previous_attention_orders,
    r.pending_config_reviews, f.pending_feedback
  from account_metrics a
  cross join paid_metrics paid
  cross join order_metrics o
  cross join review_metrics r
  cross join feedback_metrics f;
end;
$$;


ALTER FUNCTION "private"."admin_platform_overview"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_days" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_platform_update"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_status" "text", "p_allow_activation" boolean) RETURNS TABLE("platform_id" "uuid", "status" "text", "allow_activation" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_platform public.platforms;
begin
  if (p_ctx).admin_user_id is null or (p_ctx).session_id is null
     or p_platform_id is null or p_status not in ('active', 'disabled') then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (
       select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id)
       where active
     ) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;

  select * into v_platform from public.platforms where id = p_platform_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  update public.platforms
  set status = p_status, allow_activation = p_allow_activation
  where id = p_platform_id
  returning public.platforms.id, public.platforms.status, public.platforms.allow_activation
    into platform_id, status, allow_activation;
  perform private.audit_append((p_ctx).request_id, 'admin', (p_ctx).admin_user_id,
    p_platform_id, null, 'platform.updated', 'platform', p_platform_id, null, null,
    jsonb_build_object('status', p_status, 'allow_activation', p_allow_activation));
  return next;
end;
$$;


ALTER FUNCTION "private"."admin_platform_update"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_status" "text", "p_allow_activation" boolean) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_redemption_campaign_codes"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_batch_id" "uuid", "p_cursor_code_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("redemption_code_id" "uuid", "masked_code" "text", "status" "text", "redeemed_by_platform_account_id" "uuid", "redeemed_by_display_name" "text", "redeemed_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_cursor_created_at timestamptz;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_batch_id is null or p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (
    select 1 from public.redemption_code_batches b
    where b.platform_id = p_platform_id and b.id = p_batch_id
  ) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if p_cursor_code_id is not null then
    select c.created_at into v_cursor_created_at
    from public.redemption_codes c
    where c.platform_id = p_platform_id and c.batch_id = p_batch_id and c.id = p_cursor_code_id;
    if v_cursor_created_at is null then
      raise exception using errcode = 'P0002', message = 'resource_not_found';
    end if;
  end if;

  return query
  select
    c.id,
    case
      when c.code_prefix is null and c.code_suffix is null then '••••'::text
      when c.code_prefix is null then '••••' || c.code_suffix
      when c.code_suffix is null then c.code_prefix || '••••'
      else c.code_prefix || '••••' || c.code_suffix
    end,
    c.status,
    c.redeemed_by_platform_account_id,
    pr.display_name,
    c.redeemed_at,
    c.created_at
  from public.redemption_codes c
  left join public.platform_profiles pr on pr.platform_account_id = c.redeemed_by_platform_account_id
  where c.platform_id = p_platform_id
    and c.batch_id = p_batch_id
    and (p_cursor_code_id is null or (c.created_at, c.id) < (v_cursor_created_at, p_cursor_code_id))
  order by c.created_at desc, c.id desc
  limit p_limit;
end;
$$;


ALTER FUNCTION "private"."admin_redemption_campaign_codes"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_batch_id" "uuid", "p_cursor_code_id" "uuid", "p_limit" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_redemption_campaign_create"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_offer_id" "uuid", "p_plan_id" "uuid", "p_name" "text", "p_quantity" integer, "p_duration_value" integer, "p_duration_unit" "text", "p_expires_at" timestamp with time zone, "p_delivery_deadline" timestamp with time zone, "p_creation_operation_id" "uuid", "p_delivery_receipt_hmac" "text", "p_codes" "jsonb") RETURNS TABLE("batch_id" "uuid", "status" "text", "quantity" integer, "creation_state" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public', 'extensions'
    AS $_$
declare
  v_batch public.redemption_code_batches;
  v_offer public.platform_commercial_offers;
  v_plan public.plans;
  v_code jsonb;
  v_resolved_plan_id uuid;
  v_resolved_duration_value integer;
  v_resolved_duration_unit text;
  v_hash bytea;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or ((p_offer_id is null)=(p_plan_id is null))
    or p_name is null or length(p_name) not between 1 and 256
    or p_quantity not between 1 and 1000 or p_expires_at is null or p_delivery_deadline is null
    or p_creation_operation_id is null or p_delivery_receipt_hmac is null
    or coalesce(jsonb_typeof(p_codes),'')<>'array' or jsonb_array_length(p_codes)<>p_quantity then
    raise exception using errcode='22023', message='invalid_input';
  end if;
  perform 1 from public.platforms p where p.id=p_platform_id for update;
  if not found then raise exception using errcode='P0002', message='resource_not_found'; end if;
  if p_offer_id is not null then
    select * into v_offer from public.platform_commercial_offers o
    where o.platform_id=p_platform_id and o.id=p_offer_id and o.status='active';
    if not found then raise exception using errcode='P0001', message='offer_unavailable'; end if;
    v_resolved_plan_id:=v_offer.plan_id;
    v_resolved_duration_value:=v_offer.duration_value;
    v_resolved_duration_unit:=v_offer.duration_unit;
  else
    if p_duration_value is null or p_duration_value<=0 or p_duration_unit not in ('day','month','year') then
      raise exception using errcode='22023', message='invalid_input';
    end if;
    v_resolved_plan_id:=p_plan_id;
    v_resolved_duration_value:=p_duration_value;
    v_resolved_duration_unit:=p_duration_unit;
  end if;
  select * into v_plan from public.plans p
  where p.platform_id=p_platform_id and p.id=v_resolved_plan_id and p.kind='paid' and p.status='active';
  if not found then raise exception using errcode='P0001', message='plan_unavailable'; end if;
  if p_expires_at<=clock_timestamp() or p_delivery_deadline<=clock_timestamp() then
    raise exception using errcode='22023', message='invalid_input';
  end if;
  v_hash:=extensions.digest(convert_to(jsonb_build_array(p_platform_id,v_resolved_plan_id,p_offer_id,p_name,
    p_quantity,v_resolved_duration_value,v_resolved_duration_unit,p_expires_at,p_delivery_deadline,
    lower(p_delivery_receipt_hmac),p_codes)::text,'utf8'),'sha256');
  select * into v_batch from public.redemption_code_batches b
  where b.platform_id=p_platform_id and b.creation_operation_id=p_creation_operation_id for update;
  if found then
    if v_batch.creation_request_hash<>v_hash then
      raise exception using errcode='23505', message='idempotency_conflict';
    end if;
    return query select v_batch.id,v_batch.status,v_batch.quantity,'replayed_existing'::text;
    return;
  end if;
  insert into public.redemption_code_batches(
    platform_id,plan_id,name,quantity,duration_value,duration_unit,expires_at,delivery_deadline,
    delivery_session_id,delivery_receipt_hmac,created_by,creation_operation_id,creation_request_hash,
    commercial_offer_id
  ) values (
    p_platform_id,v_resolved_plan_id,p_name,p_quantity,v_resolved_duration_value,v_resolved_duration_unit,
    p_expires_at,p_delivery_deadline,(p_ctx).session_id,lower(p_delivery_receipt_hmac),(p_ctx).admin_user_id,
    p_creation_operation_id,v_hash,p_offer_id
  ) returning * into v_batch;
  for v_code in select value from jsonb_array_elements(p_codes) loop
    if jsonb_typeof(v_code)<>'object' or length(coalesce(v_code->>'code_hmac',''))<>64
      or coalesce(v_code->>'code_hmac','')!~'^[0-9a-fA-F]{64}$'
      or nullif(v_code->>'hmac_key_version','') is null then
      raise exception using errcode='22023', message='invalid_input';
    end if;
    insert into public.redemption_codes(platform_id,batch_id,plan_id,code_hmac,hmac_key_version,code_prefix,code_suffix)
    values(p_platform_id,v_batch.id,v_resolved_plan_id,lower(v_code->>'code_hmac'),
      (v_code->>'hmac_key_version')::smallint,v_code->>'code_prefix',v_code->>'code_suffix');
  end loop;
  perform private.audit_append((p_ctx).request_id,'admin',(p_ctx).admin_user_id,p_platform_id,null,
    'redemption.campaign_created','redemption_code_batch',v_batch.id,null,null,
    jsonb_build_object('quantity',p_quantity,'plan_id',v_resolved_plan_id,'offer_id',p_offer_id,
      'duration_value',v_resolved_duration_value,'duration_unit',v_resolved_duration_unit));
  return query select v_batch.id,v_batch.status,v_batch.quantity,'created'::text;
end;
$_$;


ALTER FUNCTION "private"."admin_redemption_campaign_create"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_offer_id" "uuid", "p_plan_id" "uuid", "p_name" "text", "p_quantity" integer, "p_duration_value" integer, "p_duration_unit" "text", "p_expires_at" timestamp with time zone, "p_delivery_deadline" timestamp with time zone, "p_creation_operation_id" "uuid", "p_delivery_receipt_hmac" "text", "p_codes" "jsonb") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_redemption_campaign_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_cursor_batch_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20, "p_query" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_plan_id" "uuid" DEFAULT NULL::"uuid", "p_offer_id" "uuid" DEFAULT NULL::"uuid", "p_created_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_created_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("batch_id" "uuid", "plan_id" "uuid", "plan_code" "text", "plan_name" "text", "commercial_offer_id" "uuid", "offer_code" "text", "offer_name" "text", "name" "text", "status" "text", "quantity" integer, "redeemed_count" bigint, "unused_count" bigint, "disabled_count" bigint, "redemption_rate" numeric, "expires_at" timestamp with time zone, "delivery_deadline" timestamp with time zone, "delivered_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_query text := nullif(btrim(p_query), '');
  v_cursor_created_at timestamptz;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_limit is null or p_limit not between 1 and 100
     or (v_query is not null and length(v_query) > 128)
     or (p_status is not null and p_status not in ('pending_delivery', 'active', 'disabled'))
     or (p_created_from is not null and p_created_to is not null and p_created_from > p_created_to) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from public.platforms p where p.id = p_platform_id) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if p_cursor_batch_id is not null then
    select b.created_at into v_cursor_created_at
    from public.redemption_code_batches b
    where b.platform_id = p_platform_id and b.id = p_cursor_batch_id;
    if v_cursor_created_at is null then
      raise exception using errcode = 'P0002', message = 'resource_not_found';
    end if;
  end if;

  return query
  select
    b.id,
    b.plan_id,
    plan.code,
    plan.name,
    b.commercial_offer_id,
    offer.code,
    offer.name,
    b.name,
    b.status,
    b.quantity,
    stats.redeemed_count,
    stats.unused_count,
    stats.disabled_count,
    case when b.quantity = 0 then 0::numeric
      else round(stats.redeemed_count::numeric / b.quantity::numeric, 6) end,
    b.expires_at,
    b.delivery_deadline,
    b.delivered_at,
    b.created_at
  from public.redemption_code_batches b
  join public.plans plan on plan.platform_id = b.platform_id and plan.id = b.plan_id
  left join public.platform_commercial_offers offer
    on offer.platform_id = b.platform_id and offer.id = b.commercial_offer_id
  cross join lateral (
    select
      count(*) filter (where c.status = 'redeemed')::bigint as redeemed_count,
      count(*) filter (where c.status = 'unused')::bigint as unused_count,
      count(*) filter (where c.status = 'disabled')::bigint as disabled_count
    from public.redemption_codes c
    where c.platform_id = b.platform_id and c.batch_id = b.id
  ) stats
  where b.platform_id = p_platform_id
    and (v_query is null
      or b.name ilike '%' || v_query || '%'
      or plan.code ilike '%' || v_query || '%'
      or plan.name ilike '%' || v_query || '%'
      or coalesce(offer.code, '') ilike '%' || v_query || '%'
      or coalesce(offer.name, '') ilike '%' || v_query || '%')
    and (p_status is null or b.status = p_status)
    and (p_plan_id is null or b.plan_id = p_plan_id)
    and (p_offer_id is null or b.commercial_offer_id = p_offer_id)
    and (p_created_from is null or b.created_at >= p_created_from)
    and (p_created_to is null or b.created_at <= p_created_to)
    and (p_cursor_batch_id is null or (b.created_at, b.id) < (v_cursor_created_at, p_cursor_batch_id))
  order by b.created_at desc, b.id desc
  limit p_limit;
end;
$$;


ALTER FUNCTION "private"."admin_redemption_campaign_list"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_cursor_batch_id" "uuid", "p_limit" integer, "p_query" "text", "p_status" "text", "p_plan_id" "uuid", "p_offer_id" "uuid", "p_created_from" timestamp with time zone, "p_created_to" timestamp with time zone) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_security_status"("p_ctx" "private"."admin_context", "p_current_aal" "text") RETURNS TABLE("current_aal" "text", "recent_mfa_expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
begin
  if p_current_aal is null or p_current_aal not in ('aal1', 'aal2') then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  if not exists (
    select 1
    from private.system_admin admin
    where admin.user_id = (p_ctx).admin_user_id
  ) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;

  if not exists (
    select 1
    from private.check_user_session(
      (p_ctx).admin_user_id,
      (p_ctx).session_id
    )
    where active
  ) then
    raise exception using errcode = '42501', message = 'session_not_active';
  end if;

  return query
    select p_current_aal, max(proof.expires_at)
    from private.admin_step_up proof
    where proof.user_id = (p_ctx).admin_user_id
      and proof.session_id = (p_ctx).session_id
      and proof.verified_at <= now()
      and proof.expires_at > now();
end;
$$;


ALTER FUNCTION "private"."admin_security_status"("p_ctx" "private"."admin_context", "p_current_aal" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_step_up_issue"("p_ctx" "private"."admin_context", "p_factor_id" "uuid", "p_verified_at" timestamp with time zone, "p_attestation_nonce" "uuid") RETURNS TABLE("proof_id" "uuid", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
begin
  if (p_ctx).admin_user_id is null
     or (p_ctx).session_id is null
     or p_factor_id is null
     or p_verified_at is null
     or p_attestation_nonce is null
     or p_verified_at <= v_now - interval '90 seconds'
     or p_verified_at > v_now + interval '5 seconds'
     or not exists (
       select 1 from private.system_admin
       where user_id = (p_ctx).admin_user_id
     )
     or not exists (
       select 1 from private.check_user_session(
         (p_ctx).admin_user_id,
         (p_ctx).session_id
       ) where active
     ) then
    raise exception using errcode = '42501', message = 'recent_mfa_required';
  end if;

  return query
  insert into private.admin_step_up (
    user_id, session_id, factor_id, verified_at, expires_at, attestation_nonce
  ) values (
    (p_ctx).admin_user_id,
    (p_ctx).session_id,
    p_factor_id,
    p_verified_at,
    p_verified_at + interval '30 minutes',
    p_attestation_nonce
  )
  on conflict (user_id, session_id, attestation_nonce)
    where attestation_nonce is not null
    do nothing
  returning id, private.admin_step_up.expires_at;

  if not found then
    raise exception using errcode = '42501', message = 'recent_mfa_required';
  end if;
end;
$$;


ALTER FUNCTION "private"."admin_step_up_issue"("p_ctx" "private"."admin_context", "p_factor_id" "uuid", "p_verified_at" timestamp with time zone, "p_attestation_nonce" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_step_up_valid"("p_user_id" "uuid", "p_session_id" "uuid", "p_proof_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
  select exists (
    select 1
    from private.admin_step_up proof
    where proof.id = p_proof_id
      and proof.user_id = p_user_id
      and proof.session_id = p_session_id
      and proof.expires_at > now()
      and proof.verified_at <= now()
      and proof.expires_at <= proof.verified_at + interval '30 minutes'
  )
$$;


ALTER FUNCTION "private"."admin_step_up_valid"("p_user_id" "uuid", "p_session_id" "uuid", "p_proof_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_storage_policy_read"("p_ctx" "private"."admin_context", "p_platform_id" "uuid") RETURNS TABLE("platform_id" "uuid", "enabled" boolean, "max_file_bytes" bigint, "max_platform_total_bytes" bigint, "platform_reserved_bytes" bigint, "platform_actual_bytes" bigint, "platform_available_bytes" bigint, "platform_over_capacity" boolean, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_policy public.platform_file_policies;
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from public.platforms p where p.id = p_platform_id) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  select * into v_policy from public.platform_file_policies p
  where p.platform_id = p_platform_id;
  return query
    with usage as (
      select coalesce(sum(f.reserved_bytes), 0)::bigint as reserved_bytes,
        coalesce(sum(coalesce(f.actual_size_bytes, 0)), 0)::bigint as actual_bytes
      from public.platform_config_files f
      where f.platform_id = p_platform_id and f.status <> 'deleted'
    ), facts as (
      select coalesce(v_policy.max_platform_total_bytes, 1073741824::bigint) as capacity,
        usage.reserved_bytes, usage.actual_bytes
      from usage
    )
    select p_platform_id,
      coalesce(v_policy.enabled, true),
      coalesce(v_policy.max_file_bytes, 1048576::bigint),
      facts.capacity, facts.reserved_bytes, facts.actual_bytes,
      greatest(facts.capacity - facts.reserved_bytes, 0::bigint),
      facts.reserved_bytes > facts.capacity,
      v_policy.updated_at
    from facts;
end;
$$;


ALTER FUNCTION "private"."admin_storage_policy_read"("p_ctx" "private"."admin_context", "p_platform_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_storage_policy_update"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_enabled" boolean, "p_max_file_bytes" bigint, "p_max_platform_total_bytes" bigint) RETURNS TABLE("platform_id" "uuid", "enabled" boolean, "max_file_bytes" bigint, "max_platform_total_bytes" bigint, "platform_reserved_bytes" bigint, "platform_actual_bytes" bigint, "platform_available_bytes" bigint, "platform_over_capacity" boolean, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.billing_admin_assert(p_ctx);
  if p_platform_id is null or p_enabled is null
     or p_max_file_bytes not between 1 and 1048576
     or p_max_platform_total_bytes not between 1048576 and 1099511627776
     or p_max_file_bytes > p_max_platform_total_bytes then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from public.platforms p where p.id = p_platform_id) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  insert into public.platform_file_policies(
    platform_id, enabled, max_file_bytes, max_platform_total_bytes
  ) values (
    p_platform_id, p_enabled, p_max_file_bytes, p_max_platform_total_bytes
  ) on conflict on constraint platform_file_policies_pkey do update set
    enabled = excluded.enabled,
    max_file_bytes = excluded.max_file_bytes,
    max_platform_total_bytes = excluded.max_platform_total_bytes;
  perform private.audit_append(
    (p_ctx).request_id, 'admin', (p_ctx).admin_user_id, p_platform_id, null,
    'storage.policy_updated', 'platform_file_policy', p_platform_id, null, null,
    jsonb_build_object(
      'enabled', p_enabled,
      'max_file_bytes', p_max_file_bytes,
      'max_platform_total_bytes', p_max_platform_total_bytes
    )
  );
  return query select * from private.admin_storage_policy_read(p_ctx, p_platform_id);
end;
$$;


ALTER FUNCTION "private"."admin_storage_policy_update"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_enabled" boolean, "p_max_file_bytes" bigint, "p_max_platform_total_bytes" bigint) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."admin_subscription_read"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid") RETURNS TABLE("platform_account_id" "uuid", "subscription_id" "uuid", "status" "text", "plan_id" "uuid", "plan_code" "text", "plan_name" "text", "features" "jsonb", "started_at" timestamp with time zone, "current_period_end" timestamp with time zone, "next_transition_at" timestamp with time zone, "last_event_sequence" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if (p_ctx).admin_user_id is null or (p_ctx).session_id is null
     or not exists (select 1 from private.system_admin where user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) where active) then
    raise exception using errcode = '42501', message = 'admin_required';
  end if;
  return query
    select s.platform_account_id, s.id, s.status, s.plan_id, p.code, p.name, p.features,
      s.started_at, s.current_period_end, s.next_transition_at, s.last_event_sequence
    from public.subscriptions s
    left join public.plans p on p.platform_id = s.platform_id and p.id = s.plan_id
    where s.platform_id = p_platform_id and s.platform_account_id = p_platform_account_id;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
end;
$$;


ALTER FUNCTION "private"."admin_subscription_read"("p_ctx" "private"."admin_context", "p_platform_id" "uuid", "p_platform_account_id" "uuid") OWNER TO "domain_owner";


