    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if (p_ctx).admin_user_id is null or (p_ctx).session_id is null
     or (p_ctx).request_id is null
     or not exists (select 1 from private.system_admin a where a.user_id = (p_ctx).admin_user_id)
     or not exists (select 1 from private.check_user_session((p_ctx).admin_user_id, (p_ctx).session_id) s where s.active)
  then raise exception using errcode = '42501', message = 'admin_required'; end if;
end;
$$;


ALTER FUNCTION "private"."billing_admin_assert"("p_ctx" "private"."admin_context") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_alert_delivery_update"("p_ctx" "private"."job_context", "p_alert_id" "uuid", "p_delivery_status" "text", "p_error_code" "text" DEFAULT NULL::"text") RETURNS TABLE("alert_id" "uuid", "alert_key" "text", "status" "text", "delivery_status" "text", "delivery_attempts" integer, "last_delivery_error" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_alert private.billing_operational_alerts;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null or p_alert_id is null
     or p_delivery_status not in ('delivered', 'failed')
     or (p_error_code is not null and (length(p_error_code) < 1 or length(p_error_code) > 128)) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  update private.billing_operational_alerts as a
  set delivery_status = p_delivery_status,
      delivery_attempts = a.delivery_attempts + 1,
      last_delivery_at = clock_timestamp(),
      last_delivery_error = case when p_delivery_status = 'failed' then p_error_code else null end,
      updated_at = clock_timestamp()
  where a.id = p_alert_id
  returning * into v_alert;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  return query select v_alert.id, v_alert.alert_key, v_alert.status,
    v_alert.delivery_status, v_alert.delivery_attempts, v_alert.last_delivery_error;
end;
$$;


ALTER FUNCTION "private"."billing_alert_delivery_update"("p_ctx" "private"."job_context", "p_alert_id" "uuid", "p_delivery_status" "text", "p_error_code" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_alert_threshold_defaults"() RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'pending_age_seconds', 900,
    'processing_age_seconds', 120,
    'discovery_stale_seconds', 900,
    'processing_stale_seconds', 900,
    'expired_lease_count', 1,
    'manual_review_count', 1,
    'duplicate_payment_count', 1,
    'retry_budget_exhausted_count', 1,
    'refund_mismatch_count', 1,
    'scheduler_failure_count', 1
  );
$$;


ALTER FUNCTION "private"."billing_alert_threshold_defaults"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_alerts_evaluate"("p_ctx" "private"."job_context", "p_thresholds" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("alert_id" "uuid", "alert_key" "text", "severity" "text", "status" "text", "fingerprint" "text", "occurrence_count" bigint, "first_seen_at" timestamp with time zone, "last_seen_at" timestamp with time zone, "recovered_at" timestamp with time zone, "delivery_status" "text", "delivery_attempts" integer, "details" "jsonb", "needs_delivery" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_thresholds jsonb;
  v_key text;
  v_value jsonb;
  v_metrics record;
  v_item jsonb;
  v_alert record;
  v_fingerprint text;
  v_now timestamptz := clock_timestamp();
  v_expected jsonb := '[]'::jsonb;
  v_threshold numeric;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or length((p_ctx).lease_owner) not between 1 and 128
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null
     or p_thresholds is null or jsonb_typeof(p_thresholds) <> 'object' then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  for v_key, v_value in
    select key, value from jsonb_each(p_thresholds)
  loop
    if v_key not in (
      'pending_age_seconds', 'processing_age_seconds',
      'discovery_stale_seconds', 'processing_stale_seconds',
      'expired_lease_count', 'manual_review_count',
      'duplicate_payment_count', 'retry_budget_exhausted_count',
      'refund_mismatch_count', 'scheduler_failure_count'
    ) or jsonb_typeof(v_value) <> 'number' or (v_value #>> '{}')::numeric <= 0 then
      raise exception using errcode = '22023', message = 'invalid_thresholds';
    end if;
  end loop;

  v_thresholds := private.billing_alert_threshold_defaults() || p_thresholds;
  select * into v_metrics from private.billing_observability_snapshot();

  if coalesce(v_metrics.oldest_pending_age_seconds, 0) >= (v_thresholds->>'pending_age_seconds')::numeric then
    v_expected := v_expected || jsonb_build_array(jsonb_build_object(
      'alert_key', 'billing.jobs.pending_age', 'severity', 'high',
      'details', jsonb_build_object('metric', 'oldest_pending_age_seconds', 'value', v_metrics.oldest_pending_age_seconds, 'threshold', (v_thresholds->>'pending_age_seconds')::numeric, 'observed_at', v_metrics.observed_at)
    ));
  end if;
  if coalesce(v_metrics.oldest_processing_age_seconds, 0) >= (v_thresholds->>'processing_age_seconds')::numeric then
    v_expected := v_expected || jsonb_build_array(jsonb_build_object(
      'alert_key', 'billing.jobs.processing_age', 'severity', 'high',
      'details', jsonb_build_object('metric', 'oldest_processing_age_seconds', 'value', v_metrics.oldest_processing_age_seconds, 'threshold', (v_thresholds->>'processing_age_seconds')::numeric, 'observed_at', v_metrics.observed_at)
    ));
  end if;
  if v_metrics.expired_lease_count >= (v_thresholds->>'expired_lease_count')::numeric then
    v_expected := v_expected || jsonb_build_array(jsonb_build_object(
      'alert_key', 'billing.jobs.expired_lease', 'severity', 'critical',
      'details', jsonb_build_object('metric', 'expired_lease_count', 'value', v_metrics.expired_lease_count, 'threshold', (v_thresholds->>'expired_lease_count')::numeric, 'observed_at', v_metrics.observed_at)
    ));
  end if;
  if v_metrics.manual_review_count >= (v_thresholds->>'manual_review_count')::numeric then
    v_expected := v_expected || jsonb_build_array(jsonb_build_object(
      'alert_key', 'billing.jobs.manual_review', 'severity', 'high',
      'details', jsonb_build_object('metric', 'manual_review_count', 'value', v_metrics.manual_review_count, 'threshold', (v_thresholds->>'manual_review_count')::numeric, 'observed_at', v_metrics.observed_at)
    ));
  end if;
  if v_metrics.retry_budget_exhausted_count >= (v_thresholds->>'retry_budget_exhausted_count')::numeric then
    v_expected := v_expected || jsonb_build_array(jsonb_build_object(
      'alert_key', 'billing.jobs.retry_budget_exhausted', 'severity', 'critical',
      'details', jsonb_build_object('metric', 'retry_budget_exhausted_count', 'value', v_metrics.retry_budget_exhausted_count, 'threshold', (v_thresholds->>'retry_budget_exhausted_count')::numeric, 'observed_at', v_metrics.observed_at)
    ));
  end if;
  if v_metrics.duplicate_payment_count >= (v_thresholds->>'duplicate_payment_count')::numeric then
    v_expected := v_expected || jsonb_build_array(jsonb_build_object(
      'alert_key', 'billing.payments.duplicate', 'severity', 'high',
      'details', jsonb_build_object('metric', 'duplicate_payment_count', 'value', v_metrics.duplicate_payment_count, 'threshold', (v_thresholds->>'duplicate_payment_count')::numeric, 'observed_at', v_metrics.observed_at)
    ));
  end if;
  if v_metrics.refund_mismatch_count >= (v_thresholds->>'refund_mismatch_count')::numeric then
    v_expected := v_expected || jsonb_build_array(jsonb_build_object(
      'alert_key', 'billing.refunds.compensation_pending', 'severity', 'critical',
      'details', jsonb_build_object('metric', 'refund_mismatch_count', 'value', v_metrics.refund_mismatch_count, 'threshold', (v_thresholds->>'refund_mismatch_count')::numeric, 'observed_at', v_metrics.observed_at)
    ));
  end if;
  if v_metrics.discovery_last_success_at is null
     or coalesce(v_metrics.discovery_lag_seconds, 0) >= (v_thresholds->>'discovery_stale_seconds')::numeric then
    v_expected := v_expected || jsonb_build_array(jsonb_build_object(
      'alert_key', 'billing.reconciliation.discovery_stale', 'severity', 'critical',
      'details', jsonb_build_object('metric', 'discovery_lag_seconds', 'value', v_metrics.discovery_lag_seconds, 'threshold', (v_thresholds->>'discovery_stale_seconds')::numeric, 'last_success_at', v_metrics.discovery_last_success_at, 'observed_at', v_metrics.observed_at)
    ));
  end if;
  if v_metrics.processing_last_success_at is null
     or coalesce(v_metrics.processing_lag_seconds, 0) >= (v_thresholds->>'processing_stale_seconds')::numeric then
    v_expected := v_expected || jsonb_build_array(jsonb_build_object(
      'alert_key', 'billing.reconciliation.processing_stale', 'severity', 'critical',
      'details', jsonb_build_object('metric', 'processing_lag_seconds', 'value', v_metrics.processing_lag_seconds, 'threshold', (v_thresholds->>'processing_stale_seconds')::numeric, 'last_success_at', v_metrics.processing_last_success_at, 'observed_at', v_metrics.observed_at)
    ));
  end if;
  if v_metrics.scheduler_failure_count >= (v_thresholds->>'scheduler_failure_count')::numeric then
    v_expected := v_expected || jsonb_build_array(jsonb_build_object(
      'alert_key', 'billing.scheduler.delivery_failed', 'severity', 'high',
      'details', jsonb_build_object('metric', 'scheduler_failure_count', 'value', v_metrics.scheduler_failure_count, 'threshold', (v_thresholds->>'scheduler_failure_count')::numeric, 'observed_at', v_metrics.observed_at)
    ));
  end if;

  for v_item in select value from jsonb_array_elements(v_expected)
  loop
    v_key := v_item->>'alert_key';
    v_fingerprint := md5((v_item->'details')::text);
    select a.* into v_alert
    from private.billing_operational_alerts as a
    where a.alert_key = v_key
    for update;
    if not found then
      insert into private.billing_operational_alerts (
        alert_key, severity, status, fingerprint, occurrence_count,
        first_seen_at, last_seen_at, delivery_status, details
      ) values (
        v_key, v_item->>'severity', 'active', v_fingerprint, 1,
        v_now, v_now, 'pending', v_item->'details'
      ) returning * into v_alert;
    else
      update private.billing_operational_alerts as a
      set severity = v_item->>'severity', status = 'active',
          fingerprint = v_fingerprint,
          occurrence_count = case when a.status = 'active' then a.occurrence_count + 1 else 1 end,
          first_seen_at = case when a.status = 'active' then a.first_seen_at else v_now end,
          last_seen_at = v_now, recovered_at = null,
          delivery_status = case
            when a.status = 'recovered' or a.fingerprint <> v_fingerprint or a.delivery_status = 'failed' then 'pending'
            else a.delivery_status
          end,
          last_delivery_error = case
            when a.status = 'recovered' or a.fingerprint <> v_fingerprint then null
            else a.last_delivery_error
          end,
          details = v_item->'details', updated_at = v_now
      where a.id = v_alert.id
      returning * into v_alert;
    end if;
    alert_id := v_alert.id;
    alert_key := v_alert.alert_key;
    severity := v_alert.severity;
    status := v_alert.status;
    fingerprint := v_alert.fingerprint;
    occurrence_count := v_alert.occurrence_count;
    first_seen_at := v_alert.first_seen_at;
    last_seen_at := v_alert.last_seen_at;
    recovered_at := v_alert.recovered_at;
    delivery_status := v_alert.delivery_status;
    delivery_attempts := v_alert.delivery_attempts;
    details := v_alert.details;
    needs_delivery := v_alert.delivery_status = 'pending';
    return next;
  end loop;

  for v_alert in
    select a.*
    from private.billing_operational_alerts a
    where a.status = 'active'
      and not exists (
        select 1 from jsonb_array_elements(v_expected) item
        where item->>'alert_key' = a.alert_key
      )
    for update
  loop
    update private.billing_operational_alerts as a
    set status = 'recovered', recovered_at = v_now, last_seen_at = v_now,
        delivery_status = 'pending',
        details = a.details || jsonb_build_object('recovered_at', v_now),
        updated_at = v_now
    where a.id = v_alert.id
    returning * into v_alert;
    alert_id := v_alert.id;
    alert_key := v_alert.alert_key;
    severity := v_alert.severity;
    status := v_alert.status;
    fingerprint := v_alert.fingerprint;
    occurrence_count := v_alert.occurrence_count;
    first_seen_at := v_alert.first_seen_at;
    last_seen_at := v_alert.last_seen_at;
    recovered_at := v_alert.recovered_at;
    delivery_status := v_alert.delivery_status;
    delivery_attempts := v_alert.delivery_attempts;
    details := v_alert.details;
    needs_delivery := true;
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "private"."billing_alerts_evaluate"("p_ctx" "private"."job_context", "p_thresholds" "jsonb") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_checkout_custom_order_id"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
begin
  if new.custom_order_id is null then new.custom_order_id := new.id::text; end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."billing_checkout_custom_order_id"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_checkout_lifecycle_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_platform_status text;
  v_purchases_paused boolean;
  v_plan_status text;
begin
  select p.status into v_platform_status from public.platforms p
  where p.id=new.platform_id for share;
  if v_platform_status is null or v_platform_status<>'active' then
    raise exception using errcode='42501', message='platform_disabled';
  end if;
  select c.purchases_paused into v_purchases_paused
  from public.platform_commerce_policy c where c.platform_id=new.platform_id for share;
  if coalesce(v_purchases_paused,false) then
    raise exception using errcode='P0001', message='purchases_paused';
  end if;
  select p.status into v_plan_status from public.plans p
  where p.platform_id=new.platform_id and p.id=new.entitlement_plan_id for share;
  if v_plan_status is null or v_plan_status<>'active' then
    raise exception using errcode='P0001', message='plan_unavailable';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."billing_checkout_lifecycle_guard"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_checkout_snapshot_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_mapping public.billing_provider_products;
  v_offer public.platform_commercial_offers;
  v_price public.platform_commercial_prices;
begin
  if tg_op='UPDATE' then
    if new.platform_id is distinct from old.platform_id
      or new.platform_account_id is distinct from old.platform_account_id
      or new.entitlement_plan_id is distinct from old.entitlement_plan_id
      or new.provider_account_id is distinct from old.provider_account_id
      or new.provider_product_id is distinct from old.provider_product_id
      or new.commercial_offer_id is distinct from old.commercial_offer_id
      or new.commercial_price_id is distinct from old.commercial_price_id
      or new.offer_code_snapshot is distinct from old.offer_code_snapshot
      or new.term_kind_snapshot is distinct from old.term_kind_snapshot
      or new.duration_value_snapshot is distinct from old.duration_value_snapshot
      or new.duration_unit_snapshot is distinct from old.duration_unit_snapshot
      or new.price_amount is distinct from old.price_amount
      or new.currency is distinct from old.currency
      or new.price_version is distinct from old.price_version
      or new.mapping_version is distinct from old.mapping_version
      or new.custom_order_id is distinct from old.custom_order_id
      or new.provider_external_plan_id_snapshot is distinct from old.provider_external_plan_id_snapshot
      or new.provider_product_type_snapshot is distinct from old.provider_product_type_snapshot
      or new.provider_external_sku_ids_snapshot is distinct from old.provider_external_sku_ids_snapshot
      or new.provider_sku_count_snapshot is distinct from old.provider_sku_count_snapshot
      or new.provider_purchase_months_snapshot is distinct from old.provider_purchase_months_snapshot
      or new.provider_expected_show_amount_snapshot is distinct from old.provider_expected_show_amount_snapshot
      or new.provider_expected_total_amount_snapshot is distinct from old.provider_expected_total_amount_snapshot
      or new.provider_price_version_snapshot is distinct from old.provider_price_version_snapshot then
      raise exception using errcode='P0001', message='checkout_snapshot_immutable';
    end if;
    return new;
  end if;
  select * into v_mapping from public.billing_provider_products m
  where m.provider_account_id=new.provider_account_id and m.id=new.provider_product_id;
  if not found or not v_mapping.published or not v_mapping.enabled
    or v_mapping.validation_status<>'verified' then
    raise exception using errcode='P0001', message='provider_mapping_unavailable';
  end if;
  select * into v_offer from public.platform_commercial_offers o
  where o.platform_id=new.platform_id and o.id=new.commercial_offer_id;
  select * into v_price from public.platform_commercial_prices p
  where p.platform_id=new.platform_id and p.id=new.commercial_price_id
    and p.offer_id=new.commercial_offer_id;
  if v_offer.id is null or v_price.id is null
    or v_mapping.platform_id<>new.platform_id
    or v_mapping.commercial_price_id<>v_price.id
    or new.entitlement_plan_id<>v_offer.plan_id
    or new.offer_code_snapshot<>v_offer.code
    or new.term_kind_snapshot<>v_offer.term_kind
    or new.duration_value_snapshot<>v_offer.duration_value
    or new.duration_unit_snapshot<>v_offer.duration_unit
    or new.price_amount<>v_price.amount or new.currency<>v_price.currency
    or new.price_version<>v_price.version
    or new.mapping_version<>v_mapping.mapping_version then
    raise exception using errcode='P0001', message='checkout_snapshot_mismatch';
  end if;
  -- The caller selects only the canonical Mapping. Freeze the provider contract
  -- from that verified Mapping inside the same transaction instead of trusting
  -- caller-supplied snapshot fields.
  new.provider_external_plan_id_snapshot := v_mapping.external_plan_id;
  new.provider_product_type_snapshot := v_mapping.product_type;
  new.provider_external_sku_ids_snapshot := v_mapping.external_sku_ids;
  new.provider_sku_count_snapshot := v_mapping.sku_count;
  new.provider_purchase_months_snapshot := v_mapping.purchase_months;
  new.provider_expected_show_amount_snapshot := v_mapping.expected_show_amount;
  new.provider_expected_total_amount_snapshot := v_mapping.expected_total_amount;
  new.provider_price_version_snapshot := v_mapping.price_version;
  return new;
end;
$$;


ALTER FUNCTION "private"."billing_checkout_snapshot_guard"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_cron_observability"() RETURNS TABLE("scheduler_last_accepted_at" timestamp with time zone, "scheduler_last_completed_at" timestamp with time zone, "scheduler_failure_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
  select
    max(i.request_accepted_at) filter (where i.scheduler_state = 'queued'),
    max(i.http_completed_at) filter (where i.scheduler_state = 'queued' and i.business_state in ('completed', 'completed_with_failures')),
    count(*) filter (where i.scheduled_at >= clock_timestamp() - interval '24 hours' and (i.scheduler_state = 'queue_failed' or i.business_state = 'failed'))::bigint
  from private.billing_cron_invocations i;
$$;


ALTER FUNCTION "private"."billing_cron_observability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."billing_maintenance_cron"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  function_url text;
  worker_token text;
  endpoint text;
  request_id bigint;
begin
  perform private.billing_maintenance_cron_observe();

  if not pg_try_advisory_xact_lock(7092026090702::bigint) then
    insert into private.billing_cron_invocations (
      requested_limit, scheduler_state, business_state, error_code
    ) values (5, 'skipped', 'not_applicable', 'OVERLAPPING_INVOCATION');
    return;
  end if;

  select decrypted_secret
  into function_url
  from vault.decrypted_secrets
  where name = 'billing_maintenance_function_url'
  limit 1;

  select decrypted_secret
  into worker_token
  from vault.decrypted_secrets
  where name = 'billing_maintenance_job_token'
  limit 1;

  if nullif(btrim(function_url), '') is null
     or nullif(btrim(worker_token), '') is null then
    insert into private.billing_cron_invocations (
      requested_limit, scheduler_state, business_state, error_code
    ) values (5, 'skipped', 'not_applicable', 'MISSING_RUNTIME_CONFIG');
    return;
  end if;

  endpoint := private.billing_maintenance_endpoint(function_url);
  if endpoint is null then
    insert into private.billing_cron_invocations (
      requested_limit, scheduler_state, business_state, error_code
    ) values (5, 'skipped', 'not_applicable', 'INVALID_FUNCTION_URL');
    return;
  end if;

  begin
    request_id := net.http_post(
      url := endpoint,
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || worker_token
      ),
      body := jsonb_build_object('limit', 5),
      timeout_milliseconds := 5000
    );

    insert into private.billing_cron_invocations (
      request_id, requested_limit, scheduler_state, business_state,
      request_accepted_at
    ) values (
      request_id, 5, 'queued', 'pending', clock_timestamp()
    );
  exception when others then
    insert into private.billing_cron_invocations (
      requested_limit, scheduler_state, business_state, error_code
    ) values (5, 'queue_failed', 'not_applicable', 'PG_NET_ENQUEUE_FAILED');
  end;
end;
$$;


ALTER FUNCTION "private"."billing_maintenance_cron"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."billing_maintenance_cron_observe"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $_$
declare
  v_response record;
  v_body jsonb;
  v_processed integer;
  v_failed integer;
  v_summary jsonb;
  v_business_state text;
  v_error_code text;
begin
  for v_response in
    select i.id, r.status_code, r.timed_out, r.error_msg, r.content, r.created
    from private.billing_cron_invocations i
    join net._http_response r on r.id = i.request_id
    where i.scheduler_state = 'queued'
      and i.http_completed_at is null
    order by i.scheduled_at, i.id
    limit 20
  loop
    v_body := '{}'::jsonb;
    if v_response.content is not null then
      begin
        v_body := v_response.content::jsonb;
      exception when others then
        v_body := '{}'::jsonb;
      end;
    end if;

    v_processed := null;
    if jsonb_typeof(v_body->'processed') = 'number'
       and (v_body->>'processed') ~ '^[0-9]+$' then
      v_processed := (v_body->>'processed')::integer;
    end if;

    v_failed := 0;
    if jsonb_typeof(v_body->'results') = 'array' then
      select count(*)::integer
      into v_failed
      from jsonb_array_elements(v_body->'results') as result(item)
      where (result.item->>'status') in ('failed', 'invalid_claim')
         or (result.item->>'status') ~ '^[4-9][0-9][0-9]$';
    end if;

    v_error_code := case
      when coalesce(v_response.timed_out, false) then 'HTTP_TIMEOUT'
      when v_response.error_msg is not null then 'HTTP_REQUEST_FAILED'
      when v_response.status_code is null then 'HTTP_STATUS_MISSING'
      when v_response.status_code < 200 or v_response.status_code >= 300
        then 'HTTP_' || v_response.status_code::text
      when v_processed is null then 'WORKER_RESPONSE_INVALID'
      else null
    end;

    v_business_state := case
      when v_error_code is not null then 'failed'
      when v_failed > 0 then 'completed_with_failures'
      else 'completed'
    end;

    v_summary := jsonb_build_object(
      'processed', v_processed,
      'failed', v_failed,
      'result_count', case
        when jsonb_typeof(v_body->'results') = 'array'
          then jsonb_array_length(v_body->'results')
        else 0
      end
    );

    update private.billing_cron_invocations
    set business_state = v_business_state,
        error_code = v_error_code,
        http_status_code = v_response.status_code,
        http_timed_out = v_response.timed_out,
        processed_count = v_processed,
        failed_count = v_failed,
        response_summary = v_summary,
        http_completed_at = v_response.created,
        updated_at = clock_timestamp()
    where id = v_response.id;
  end loop;

  -- Keep the operational history bounded while retaining enough data for
  -- incident review. pg_net itself retains response rows for only six hours.
  delete from private.billing_cron_invocations
  where scheduled_at < clock_timestamp() - interval '30 days';
end;
$_$;


ALTER FUNCTION "private"."billing_maintenance_cron_observe"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."billing_maintenance_endpoint"("p_function_url" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_base text := rtrim(nullif(btrim(p_function_url), ''), '/');
begin
  if v_base is null
     or v_base !~* '^https?://'
     or v_base ~ '[?#]' then
    return null;
  end if;

  if v_base ~* '/maintenance/v1/billing/jobs/run$' then
    return v_base;
  end if;

  if v_base ~* '/maintenance$' then
    return v_base || '/v1/billing/jobs/run';
  end if;

  return null;
end;
$_$;


ALTER FUNCTION "private"."billing_maintenance_endpoint"("p_function_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."billing_observability_snapshot"() RETURNS TABLE("observed_at" timestamp with time zone, "pending_count" bigint, "processing_count" bigint, "retryable_count" bigint, "completed_count" bigint, "manual_review_count" bigint, "oldest_pending_age_seconds" numeric, "oldest_processing_age_seconds" numeric, "expired_lease_count" bigint, "retry_attempts_total" bigint, "retry_budget_exhausted_count" bigint, "duplicate_payment_count" bigint, "refund_mismatch_count" bigint, "discovery_last_success_at" timestamp with time zone, "processing_last_success_at" timestamp with time zone, "discovery_lag_seconds" numeric, "processing_lag_seconds" numeric, "scheduler_last_accepted_at" timestamp with time zone, "scheduler_last_completed_at" timestamp with time zone, "scheduler_failure_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
  with now_value as (
    select clock_timestamp() as observed_at
  ),
  jobs as (
    select
      count(*) filter (where j.state = 'pending')::bigint as pending_count,
      count(*) filter (where j.state = 'processing')::bigint as processing_count,
      count(*) filter (where j.state = 'retryable')::bigint as retryable_count,
      count(*) filter (where j.state = 'completed')::bigint as completed_count,
      count(*) filter (where j.state = 'manual_review')::bigint as manual_review_count,
      min(j.created_at) filter (where j.state in ('pending', 'retryable')) as oldest_pending_created_at,
      min(j.created_at) filter (where j.state = 'processing') as oldest_processing_created_at,
      count(*) filter (where j.state = 'processing' and j.lease_until <= n.observed_at)::bigint as expired_lease_count,
      coalesce(sum(j.retry_attempts) filter (where j.state in ('pending', 'processing', 'retryable', 'manual_review')), 0)::bigint as retry_attempts_total,
      count(*) filter (where j.retry_attempts >= j.max_attempts)::bigint as retry_budget_exhausted_count
    from public.billing_processing_jobs j
    cross join now_value n
  ),
  cursors as (
    select
      max(c.last_success_at) filter (where c.stream = 'discovery') as discovery_last_success_at,
      max(c.last_success_at) filter (where c.stream = 'processing') as processing_last_success_at
    from public.billing_reconciliation_cursors c
  ),
  scheduler as (
    select * from private.billing_cron_observability()
  )
  select
    n.observed_at,
    j.pending_count,
    j.processing_count,
    j.retryable_count,
    j.completed_count,
    j.manual_review_count,
    greatest(extract(epoch from (n.observed_at - j.oldest_pending_created_at)), 0),
    greatest(extract(epoch from (n.observed_at - j.oldest_processing_created_at)), 0),
    j.expired_lease_count,
    j.retry_attempts_total,
    j.retry_budget_exhausted_count,
    (select count(*)::bigint from public.billing_settlements s where s.decision_code = 'duplicate_payment'),
    (select count(*)::bigint from private.billing_refund_observations r where r.status = 'compensation_pending'),
    c.discovery_last_success_at,
    c.processing_last_success_at,
    case when c.discovery_last_success_at is null then null else extract(epoch from (n.observed_at - c.discovery_last_success_at)) end,
    case when c.processing_last_success_at is null then null else extract(epoch from (n.observed_at - c.processing_last_success_at)) end,
    s.scheduler_last_accepted_at,
    s.scheduler_last_completed_at,
    s.scheduler_failure_count
  from now_value n
  cross join jobs j
  cross join cursors c
  cross join scheduler s;
$$;


ALTER FUNCTION "private"."billing_observability_snapshot"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_order_link_checkout"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_order_id" "uuid", "p_fence" bigint, "p_custom_order_id" "text") RETURNS TABLE("order_id" "uuid", "linked" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_job public.billing_processing_jobs;
  v_order public.billing_orders;
  v_checkout public.billing_checkout_intents;
  v_checkout_count integer:=0;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null or (p_ctx).fencing_token is null
    or (p_ctx).request_id is null or p_job_id is null or p_order_id is null or p_fence is null
    or p_fence<>(p_ctx).fencing_token then
    raise exception using errcode='22023', message='invalid_input';
  end if;
  select * into v_job from public.billing_processing_jobs j where j.id=p_job_id
    and j.state='processing' and j.lease_owner=(p_ctx).lease_owner and j.fence=p_fence
    and j.lease_until>clock_timestamp() for update;
  if not found then raise exception using errcode='40001', message='fence_conflict'; end if;
  if v_job.billing_order_id is not null and v_job.billing_order_id<>p_order_id then
    raise exception using errcode='40001', message='job_order_conflict';
  end if;
  select * into v_order from public.billing_orders o where o.id=p_order_id for update;
  if not found then raise exception using errcode='P0002', message='resource_not_found'; end if;
  if v_order.checkout_intent_id is null and v_order.linkage_status='unlinked'
    and v_order.resolution_status='open'
    and not exists(select 1 from public.billing_settlements s where s.billing_order_id=v_order.id)
    and p_custom_order_id is not null and length(p_custom_order_id) between 1 and 256 then
    for v_checkout in select * from public.billing_checkout_intents c
      where c.provider_account_id=v_order.provider_account_id and c.custom_order_id=p_custom_order_id
      order by c.created_at desc,c.id desc for update
    loop
      v_checkout_count:=v_checkout_count+1;
      if v_checkout_count>1 then exit; end if;
    end loop;
    if v_checkout_count=1 then
      update public.billing_orders set checkout_intent_id=v_checkout.id,
        platform_id=v_checkout.platform_id,platform_account_id=v_checkout.platform_account_id,
        linkage_status='linked'
      where id=v_order.id and checkout_intent_id is null;
    end if;
  end if;
  update public.billing_processing_jobs set updated_at=clock_timestamp()
  where id=p_job_id and state='processing' and lease_owner=(p_ctx).lease_owner
    and fence=p_fence and lease_until>clock_timestamp();
  if not found then raise exception using errcode='40001', message='fence_conflict'; end if;
  select * into v_order from public.billing_orders o where o.id=p_order_id;
  return query select v_order.id,v_order.checkout_intent_id is not null;
end;
$$;


ALTER FUNCTION "private"."billing_order_link_checkout"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_order_id" "uuid", "p_fence" bigint, "p_custom_order_id" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_order_query_target"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_order_id" "uuid", "p_fence" bigint) RETURNS TABLE("provider_account_id" "uuid", "provider_order_no" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_job public.billing_processing_jobs;
  v_order public.billing_orders;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).request_id is null
     or p_job_id is null or p_order_id is null or p_fence is null
     or p_fence <> (p_ctx).fencing_token then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_job from public.billing_processing_jobs j
  where j.id = p_job_id and j.state = 'processing'
    and j.lease_owner = (p_ctx).lease_owner and j.fence = p_fence
    and j.lease_until > clock_timestamp();
  if not found then raise exception using errcode = '40001', message = 'fence_conflict'; end if;
  if v_job.billing_order_id is not null and v_job.billing_order_id <> p_order_id then
    raise exception using errcode = '40001', message = 'job_order_conflict';
  end if;
  select * into v_order from public.billing_orders o where o.id = p_order_id;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  return query select v_order.provider_account_id, v_order.provider_order_no;
end;
$$;


ALTER FUNCTION "private"."billing_order_query_target"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_order_id" "uuid", "p_fence" bigint) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_order_verify_and_settle"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_order_id" "uuid", "p_fence" bigint, "p_facts" "jsonb") RETURNS TABLE("order_id" "uuid", "verification_status" "text", "entitlement_status" "text", "settlement_id" "uuid", "settlement_state" "text", "grant_id" "uuid", "decision_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $_$
declare
  v_job public.billing_processing_jobs;
  v_order public.billing_orders;
  v_checkout public.billing_checkout_intents;
  v_settlement public.billing_settlements;
  v_existing_auto public.billing_settlements;
  v_grant record;
  v_status text;
  v_provider_user_id text;
  v_external_plan_id text;
  v_product_type text;
  v_custom_order_id text;
  v_currency text;
  v_purchase_months integer;
  v_total_amount numeric(12, 2);
  v_show_amount numeric(12, 2);
  v_sku_ids text[] := '{}'::text[];
  v_quantity integer := 0;
  v_sku_items_valid boolean := true;
  v_valid boolean := false;
  v_decision text;
  v_settlement_state text;
  v_verification_status text;
  v_entitlement_status text;
  v_grant_id uuid;
  v_settlement_id uuid;
  v_error text;
  v_contract_version integer;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).request_id is null
     or p_job_id is null or p_order_id is null or p_fence is null
     or p_fence <> (p_ctx).fencing_token or jsonb_typeof(p_facts) <> 'object' then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  select * into v_job
  from public.billing_processing_jobs j
  where j.id = p_job_id and j.state = 'processing'
    and j.lease_owner = (p_ctx).lease_owner and j.fence = p_fence
    and j.lease_until > clock_timestamp()
  for update;
  if not found then raise exception using errcode = '40001', message = 'fence_conflict'; end if;

  select * into v_order from public.billing_orders o where o.id = p_order_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_job.billing_order_id is not null and v_job.billing_order_id <> p_order_id then
    raise exception using errcode = '40001', message = 'job_order_conflict';
  end if;
  select * into v_settlement from public.billing_settlements s
  where s.billing_order_id = p_order_id for update;

  update public.billing_processing_jobs set billing_order_id = p_order_id
  where id = p_job_id and (billing_order_id is null or billing_order_id = p_order_id)
    and lease_owner = (p_ctx).lease_owner and fence = p_fence
    and lease_until > clock_timestamp();
  if not found then raise exception using errcode = '40001', message = 'fence_conflict'; end if;

  v_status := lower(nullif(p_facts->>'status', ''));
  if v_status is null then v_status := 'unknown'; end if;
  v_provider_user_id := nullif(p_facts->>'provider_user_id', '');
  v_external_plan_id := nullif(p_facts->>'external_plan_id', '');
  v_product_type := nullif(p_facts->>'product_type', '');
  v_custom_order_id := nullif(p_facts->>'custom_order_id', '');
  v_currency := nullif(p_facts->>'currency', '');
  if nullif(p_facts->>'purchase_months', '') ~ '^[0-9]+$' then
    v_purchase_months := (p_facts->>'purchase_months')::integer;
  end if;
  if nullif(p_facts->>'total_amount', '') ~ '^[0-9]+(\.[0-9]+)?$' then
    v_total_amount := (p_facts->>'total_amount')::numeric;
  end if;
  if nullif(p_facts->>'show_amount', '') ~ '^[0-9]+(\.[0-9]+)?$' then
    v_show_amount := (p_facts->>'show_amount')::numeric;
  end if;

  if jsonb_typeof(p_facts->'sku_items') = 'array' then
    select coalesce(array_agg(nullif(item->>'external_sku_id', '') order by item->>'external_sku_id'), '{}'::text[]),
      coalesce(sum(case when item->>'quantity' ~ '^[1-9][0-9]*$' then (item->>'quantity')::integer else 0 end), 0),
      coalesce(bool_and(
        jsonb_typeof(item) = 'object'
        and nullif(item->>'external_sku_id', '') is not null
        and item->>'quantity' ~ '^[1-9][0-9]*$'
        and case when item->>'quantity' ~ '^[1-9][0-9]*$'
          then (item->>'quantity')::integer between 1 and 1000
          else false end
      ), true)
    into v_sku_ids, v_quantity, v_sku_items_valid
    from jsonb_array_elements(p_facts->'sku_items') as sku(item);
  elsif jsonb_typeof(p_facts->'sku_ids') = 'array' then
    select coalesce(array_agg(value order by value), '{}'::text[]), coalesce(cardinality(array_agg(value)), 0)
    into v_sku_ids, v_quantity
    from jsonb_array_elements_text(p_facts->'sku_ids') as sku(value)
    where nullif(value, '') is not null;
  end if;
  if nullif(p_facts->>'quantity', '') ~ '^[1-9][0-9]*$' then
    v_quantity := (p_facts->>'quantity')::integer;
  end if;
  if v_product_type = '0' and cardinality(v_sku_ids) = 0 and v_quantity = 0 then
    v_quantity := 1;
  end if;
  if nullif(p_facts->>'contract_version', '') ~ '^[1-9][0-9]*$' then
    v_contract_version := (p_facts->>'contract_version')::integer;
  else
    v_contract_version := 1;
  end if;

  update public.billing_orders set
    provider_status = v_status,
    provider_user_id = v_provider_user_id,
    external_plan_id = v_external_plan_id,
    product_type = v_product_type,
    external_sku_ids = v_sku_ids,
    quantity = nullif(v_quantity, 0),
    purchase_months = v_purchase_months,
    total_amount = v_total_amount,
    show_amount = v_show_amount,
    currency = v_currency,
    custom_order_id = v_custom_order_id,
    discount_metadata = case when jsonb_typeof(p_facts->'discount_metadata') = 'object'
      then p_facts->'discount_metadata' else '{}'::jsonb end,
    provider_facts = p_facts,
    provider_paid_at = case when v_status = 'paid' then coalesce(v_order.provider_paid_at, clock_timestamp()) else v_order.provider_paid_at end,
    last_observed_at = clock_timestamp()
  where id = p_order_id
  returning * into v_order;

  insert into public.billing_order_observations (
    billing_order_id, processing_job_id, provider_status,
    provider_contract_version, source, provider_facts, observed_at
  ) values (
    v_order.id, p_job_id, v_status, v_contract_version, v_job.job_kind,
    p_facts, clock_timestamp()
  ) on conflict (billing_order_id, processing_job_id) do update set
    provider_status = excluded.provider_status,
    provider_contract_version = excluded.provider_contract_version,
    source = excluded.source,
    provider_facts = excluded.provider_facts,
    observed_at = excluded.observed_at;

  if v_settlement.state = 'finalized' then
    update public.billing_processing_jobs set
      state = 'completed', lease_owner = null, lease_until = null,
      error_class = null, error_code = null
    where id = p_job_id and lease_owner = (p_ctx).lease_owner and fence = p_fence
      and lease_until > clock_timestamp();
    if not found then raise exception using errcode = '40001', message = 'fence_conflict'; end if;
    return query select v_order.id, v_order.verification_status, v_order.entitlement_status,
      v_settlement.id, v_settlement.state, v_settlement.grant_id, v_settlement.decision_code;
    return;
  end if;

  if v_status = 'pending' or v_status = 'unknown' then
    update public.billing_processing_jobs set state = 'retryable', lease_owner = null,
      lease_until = null, error_class = 'provider_observation', error_code = 'PROVIDER_STATUS_UNKNOWN',
      next_attempt_at = clock_timestamp() + interval '1 minute'
    where id = p_job_id and lease_owner = (p_ctx).lease_owner and fence = p_fence
      and lease_until > clock_timestamp();
    if not found then raise exception using errcode = '40001', message = 'fence_conflict'; end if;
    return query select v_order.id, v_order.verification_status, v_order.entitlement_status,
      null::uuid, null::text, null::uuid, 'retryable'::text;
    return;
  end if;

  if v_order.checkout_intent_id is not null then
    select * into v_checkout from public.billing_checkout_intents c
    where c.platform_id = v_order.platform_id and c.platform_account_id = v_order.platform_account_id
      and c.id = v_order.checkout_intent_id for update;
    if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
    v_valid := (
      v_status = 'paid'
      and v_sku_items_valid
      and v_order.provider_account_id = v_checkout.provider_account_id
      and v_provider_user_id is not null
      and v_external_plan_id is not null
      and v_product_type is not null
      and v_custom_order_id is not null
      and v_currency is not null
      and v_total_amount is not null
      and v_show_amount is not null
      and v_checkout.provider_external_plan_id_snapshot is not null
      and v_checkout.provider_product_type_snapshot is not null
      and v_checkout.provider_external_sku_ids_snapshot is not null
      and v_checkout.provider_sku_count_snapshot is not null
      and v_checkout.provider_expected_show_amount_snapshot is not null
      and v_checkout.provider_expected_total_amount_snapshot is not null
      and v_checkout.provider_price_version_snapshot is not null
      and v_custom_order_id = v_checkout.custom_order_id
      and v_external_plan_id = v_checkout.provider_external_plan_id_snapshot
      and v_product_type = v_checkout.provider_product_type_snapshot
      and v_sku_ids = v_checkout.provider_external_sku_ids_snapshot
      and case when v_checkout.provider_product_type_snapshot = '0'
        then v_quantity = 1 else v_quantity = v_checkout.provider_sku_count_snapshot end
      and (
        (v_checkout.provider_product_type_snapshot = '1' and v_checkout.provider_purchase_months_snapshot is null)
        or v_purchase_months is not distinct from v_checkout.provider_purchase_months_snapshot
      )
      and v_total_amount is not distinct from v_checkout.provider_expected_total_amount_snapshot
      and v_show_amount is not distinct from v_checkout.provider_expected_show_amount_snapshot
      and v_currency = v_checkout.currency
      and v_checkout.provider_price_version_snapshot = v_checkout.price_version
    ) is true;
  end if;

  if v_status = 'failed' then
    v_verification_status := 'verified';
    v_entitlement_status := 'rejected';
    v_decision := 'provider_not_paid';
    v_settlement_state := 'finalized';
  elsif v_checkout.id is null then
    v_verification_status := case when v_status = 'paid' then 'verified' else 'rejected' end;
    v_entitlement_status := 'blocked';
    v_decision := 'unlinked_order';
    v_settlement_state := 'review_required';
  elsif v_valid is not true then
    v_verification_status := 'rejected';
    v_entitlement_status := 'blocked';
    v_decision := 'contract_conflict';
    v_settlement_state := 'review_required';
  else
    select * into v_existing_auto from public.billing_settlements s
    where s.checkout_intent_id = v_checkout.id and s.settlement_kind = 'automatic'
    for update;
    if found and v_existing_auto.billing_order_id <> v_order.id then
      v_verification_status := 'verified';
      v_entitlement_status := 'blocked';
      v_decision := 'duplicate_payment';
      v_settlement_state := 'review_required';
    else
      begin
        select * into v_grant from private.entitlement_apply(
          v_order.platform_id, v_order.platform_account_id, v_checkout.entitlement_plan_id,
          'billing_order', v_order.id, v_checkout.duration_value_snapshot,
          v_checkout.duration_unit_snapshot, null, 'billing_order_settlement', null
        );
        v_grant_id := v_grant.grant_id;
        v_verification_status := 'verified';
        v_entitlement_status := 'granted';
        v_decision := 'granted';
        v_settlement_state := 'finalized';
      exception when others then
        if sqlerrm like '%plan_conflict%' then v_error := 'plan_conflict';
        elsif sqlerrm like '%entitlement_perpetual%' then v_error := 'already_perpetual';
        elsif sqlerrm like '%account_not_active%' then v_error := 'account_not_active';
        elsif sqlerrm like '%plan_unavailable%' then v_error := 'plan_unavailable';
        else raise;
        end if;
        v_verification_status := 'verified';
        v_entitlement_status := 'blocked';
        v_decision := v_error;
        v_settlement_state := 'review_required';
      end;
    end if;
  end if;

  if v_decision = 'granted' then
    if v_settlement is null then
      insert into public.billing_settlements (
        billing_order_id, checkout_intent_id, platform_id, platform_account_id,
        settlement_kind, state, operation_id, grant_id, decision_reason, decision_code
      ) values (
        v_order.id, v_checkout.id, v_order.platform_id, v_order.platform_account_id,
        'automatic', 'finalized', v_order.id, v_grant_id, 'billing_order_settlement', v_decision
      ) returning id into v_settlement_id;
    else
      update public.billing_settlements set
        state = 'finalized', grant_id = v_grant_id,
        decision_reason = 'billing_order_settlement', decision_code = v_decision,
        updated_at = clock_timestamp()
      where id = v_settlement.id
      returning id into v_settlement_id;
    end if;
    update public.billing_checkout_intents set status = 'granted', paid_at = coalesce(paid_at, clock_timestamp()),
      granted_at = clock_timestamp() where id = v_checkout.id;
  elsif v_decision in ('provider_not_paid', 'duplicate_payment', 'contract_conflict', 'unlinked_order', 'plan_conflict', 'already_perpetual', 'account_not_active', 'plan_unavailable') then
    if v_settlement is null then
      insert into public.billing_settlements (
        billing_order_id, checkout_intent_id, platform_id, platform_account_id,
        settlement_kind, state, operation_id, decision_reason, decision_code
      ) values (
        v_order.id, v_checkout.id, v_order.platform_id, v_order.platform_account_id,
        'manual', v_settlement_state, v_order.id, v_decision, v_decision
      ) returning id into v_settlement_id;
    else
      update public.billing_settlements set
        state = v_settlement_state, grant_id = null,
        decision_reason = v_decision, decision_code = v_decision,
        updated_at = clock_timestamp()
      where id = v_settlement.id
      returning id into v_settlement_id;
    end if;
  end if;

  update public.billing_orders set
    verification_status = v_verification_status,
    verification_reason = v_decision,
    verified_at = clock_timestamp(),
    entitlement_status = v_entitlement_status,
    linkage_status = case when v_checkout.id is null then 'unlinked' else 'linked' end
  where id = v_order.id returning * into v_order;
  update public.billing_processing_jobs set
    state = case when v_decision in ('duplicate_payment', 'contract_conflict', 'unlinked_order', 'plan_conflict', 'already_perpetual', 'account_not_active', 'plan_unavailable') then 'manual_review' else 'completed' end,
    lease_owner = null, lease_until = null, error_class = case when v_decision = 'granted' then null else 'billing_verification' end,
    error_code = case when v_decision = 'granted' then null else v_decision end
  where id = p_job_id and lease_owner = (p_ctx).lease_owner and fence = p_fence
    and lease_until > clock_timestamp();
  if not found then raise exception using errcode = '40001', message = 'fence_conflict'; end if;
  return query select v_order.id, v_order.verification_status, v_order.entitlement_status,
    v_settlement_id, v_settlement_state, v_grant_id, v_decision;
end;
$_$;


ALTER FUNCTION "private"."billing_order_verify_and_settle"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_order_id" "uuid", "p_fence" bigint, "p_facts" "jsonb") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_orders_admin_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  new.admin_version := old.admin_version + 1;
  return new;
end;
$$;


ALTER FUNCTION "private"."billing_orders_admin_version"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_processing_job_claim"("p_ctx" "private"."job_context", "p_limit" integer DEFAULT 20) RETURNS TABLE("job_id" "uuid", "job_kind" "text", "webhook_event_id" "uuid", "billing_order_id" "uuid", "attempt" integer, "fence" bigint, "lease_until" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or length((p_ctx).lease_owner) not between 1 and 128
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null
     or p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  -- A crashed worker may leave a processing row at the retry ceiling.  Move
  -- it to the same searchable manual queue as an in-flight retry that reaches
  -- the ceiling; never reclaim it into an unbounded loop.
  with exhausted as (
    update public.billing_processing_jobs j
    set state = 'manual_review', lease_owner = null, lease_until = null,
        error_class = 'dead_letter', error_code = 'RETRY_BUDGET_EXHAUSTED',
        dead_lettered_at = coalesce(j.dead_lettered_at, clock_timestamp()),
        updated_at = clock_timestamp()
    where j.retry_attempts >= j.max_attempts
      and (
        j.state in ('pending', 'retryable')
        or (j.state = 'processing' and j.lease_until <= clock_timestamp())
      )
    returning j.webhook_event_id
  )
  update public.billing_webhook_events e
  set processing_status = 'manual_review', processed_at = clock_timestamp(),
      error_code = 'RETRY_BUDGET_EXHAUSTED'
  where e.id in (
    select exhausted.webhook_event_id
    from exhausted
    where exhausted.webhook_event_id is not null
  );

  return query
    with candidates as (
      select j.id
      from public.billing_processing_jobs j
      where (
        j.state in ('pending', 'retryable')
        and j.next_attempt_at <= clock_timestamp()
        and j.retry_attempts < j.max_attempts
      )
      or (
        j.state = 'processing'
        and j.lease_until <= clock_timestamp()
        and j.retry_attempts < j.max_attempts
      )
      order by j.next_attempt_at, j.created_at, j.id
      for update skip locked
      limit p_limit
    ), claimed as (
      update public.billing_processing_jobs j
      set state = 'processing', attempts = j.attempts + 1,
          retry_attempts = j.retry_attempts + 1,
          lease_owner = (p_ctx).lease_owner,
          lease_until = clock_timestamp() + interval '60 seconds',
          fence = j.fence + 1,
          error_class = case when j.state = 'processing' then 'lease' else null end,
          error_code = case when j.state = 'processing' then 'LEASE_EXPIRED' else null end,
          updated_at = clock_timestamp()
      from candidates
      where j.id = candidates.id
      returning j.id, j.job_kind, j.webhook_event_id, j.billing_order_id,
        j.attempts, j.fence, j.lease_until
    ) select * from claimed;
end;
$$;


ALTER FUNCTION "private"."billing_processing_job_claim"("p_ctx" "private"."job_context", "p_limit" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_processing_job_finish"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_fence" bigint, "p_state" "text", "p_error_class" "text" DEFAULT NULL::"text", "p_error_code" "text" DEFAULT NULL::"text") RETURNS TABLE("job_id" "uuid", "state" "text", "fence" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_job public.billing_processing_jobs;
  v_event_id uuid;
  v_state text := p_state;
  v_error_class text := p_error_class;
  v_error_code text := p_error_code;
  v_delay integer;
  v_result_job_id uuid;
  v_result_state text;
  v_result_fence bigint;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).request_id is null
     or p_job_id is null or p_fence is null or p_fence <> (p_ctx).fencing_token
     or p_state not in ('retryable', 'completed', 'manual_review')
     or (p_state = 'retryable' and (p_error_class is null or p_error_code is null)) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  select * into v_job
  from public.billing_processing_jobs j
  where j.id = p_job_id and j.state = 'processing'
    and j.lease_owner = (p_ctx).lease_owner and j.fence = p_fence
    and j.lease_until > clock_timestamp()
  for update;
  if not found then
    raise exception using errcode = '40001', message = 'fence_conflict';
  end if;
  v_event_id := v_job.webhook_event_id;

  if p_state = 'retryable' and v_job.retry_attempts >= v_job.max_attempts then
    v_state := 'manual_review';
    v_error_class := 'dead_letter';
    v_error_code := 'RETRY_BUDGET_EXHAUSTED';
  end if;
  if v_state = 'manual_review' then
    v_delay := null;
  else
    v_delay := private.billing_processing_job_retry_delay_seconds(
      v_error_class, v_error_code, v_job.retry_attempts
    ) + floor(random() * 30)::integer;
  end if;

  update public.billing_processing_jobs j
  set state = v_state, lease_owner = null, lease_until = null,
      error_class = v_error_class, error_code = v_error_code,
      last_error_class = p_error_class, last_error_code = p_error_code,
      dead_lettered_at = case when v_state = 'manual_review'
        then coalesce(j.dead_lettered_at, clock_timestamp()) else j.dead_lettered_at end,
      next_attempt_at = case when v_state = 'retryable'
        then clock_timestamp() + make_interval(secs => v_delay) else j.next_attempt_at end,
      updated_at = clock_timestamp()
  where j.id = p_job_id and j.state = 'processing'
    and j.lease_owner = (p_ctx).lease_owner and j.fence = p_fence
    and j.lease_until > clock_timestamp()
  returning j.id, j.state, j.fence
  into v_result_job_id, v_result_state, v_result_fence;
  if not found then
    raise exception using errcode = '40001', message = 'fence_conflict';
  end if;

  if v_event_id is not null then
    update public.billing_webhook_events
    set processing_status = case v_state
          when 'retryable' then 'retryable'
          when 'manual_review' then 'manual_review'
          else 'processed'
        end,
        processed_at = case when v_state in ('completed', 'manual_review')
          then clock_timestamp() else null end,
        error_code = case when v_state = 'completed' then null else v_error_code end
    where id = v_event_id;
  end if;
  return query select v_result_job_id, v_result_state, v_result_fence;
end;
$$;


ALTER FUNCTION "private"."billing_processing_job_finish"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_fence" bigint, "p_state" "text", "p_error_class" "text", "p_error_code" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_processing_job_requeue"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_operation_id" "uuid", "p_reason" "text") RETURNS TABLE("job_id" "uuid", "state" "text", "fence" bigint, "attempts" integer, "requeue_count" integer, "replayed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_job public.billing_processing_jobs;
  v_order public.billing_orders;
  v_settlement public.billing_settlements;
  v_platform_id uuid;
  v_platform_account_id uuid;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null or p_job_id is null
     or p_operation_id is null or p_reason is null
     or length(p_reason) not between 1 and 1024 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  select * into v_job from public.billing_processing_jobs j
  where j.id = p_job_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if v_job.last_requeue_operation_id = p_operation_id then
    return query select v_job.id, v_job.state, v_job.fence, v_job.attempts,
      v_job.requeue_count, true;
    return;
  end if;
  if v_job.state <> 'manual_review'
     or coalesce(v_job.last_error_class, v_job.error_class) not in
       ('provider', 'provider_contract', 'worker', 'dead_letter')
     or coalesce(v_job.last_error_code, v_job.error_code) not in (
       'PROVIDER_UNAVAILABLE', 'PROVIDER_ORDER_NOT_FOUND', 'PROVIDER_TIMEOUT',
       'PROVIDER_RATE_LIMITED', 'PROVIDER_RESPONSE_INVALID',
       'RETRY_BUDGET_EXHAUSTED', 'RATE_LIMITED'
     ) then
    raise exception using errcode = 'P0001', message = 'job_requeue_not_allowed';
  end if;

  if v_job.billing_order_id is not null then
    select * into v_order from public.billing_orders o
    where o.id = v_job.billing_order_id
    for update;
    if found then
      v_platform_id := v_order.platform_id;
      v_platform_account_id := v_order.platform_account_id;
      select * into v_settlement from public.billing_settlements s
      where s.billing_order_id = v_order.id
      order by s.created_at desc, s.id desc
      limit 1
      for update;
      if v_order.linkage_status = 'unlinked'
         or v_order.resolution_status = 'resolved'
         or (found and v_settlement.state = 'finalized') then
        raise exception using errcode = 'P0001', message = 'job_requeue_not_allowed';
      end if;
    end if;
  end if;

  update public.billing_processing_jobs j
  set state = 'pending', lease_owner = null, lease_until = null,
      error_class = null, error_code = null,
      next_attempt_at = clock_timestamp(), retry_attempts = 0,
      requeue_count = j.requeue_count + 1,
      last_requeue_operation_id = p_operation_id,
      last_requeue_at = clock_timestamp(), last_requeue_reason = p_reason,
      fence = j.fence + 1, updated_at = clock_timestamp()
  where j.id = p_job_id and j.state = 'manual_review'
  returning j.id, j.state, j.fence, j.attempts, j.requeue_count
  into v_job.id, v_job.state, v_job.fence, v_job.attempts, v_job.requeue_count;
  if not found then
    raise exception using errcode = '40001', message = 'job_requeue_conflict';
  end if;

  if v_job.webhook_event_id is not null then
    update public.billing_webhook_events e
    set processing_status = 'queued', processed_at = null, error_code = null
    where e.id = v_job.webhook_event_id;
  end if;
  perform private.audit_append(
    p_operation_id, 'job', null, v_platform_id, v_platform_account_id,
    'billing.job.requeued', 'billing_processing_job', p_job_id, null, null,
    jsonb_build_object('reason', p_reason, 'requeue_count', v_job.requeue_count)
  );
  return query select v_job.id, v_job.state, v_job.fence, v_job.attempts,
    v_job.requeue_count, false;
end;
$$;


ALTER FUNCTION "private"."billing_processing_job_requeue"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_operation_id" "uuid", "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_processing_job_requeue_contract"("p_ctx" "private"."job_context", "p_job_id" "uuid") RETURNS TABLE("job_id" "uuid", "state" "text", "fence" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_job public.billing_processing_jobs;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null or p_job_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  select * into v_job
  from public.billing_processing_jobs j
  where j.id = p_job_id
    and j.state = 'manual_review'
    and j.job_kind = 'webhook_order_discovery'
    and j.error_code = 'PROVIDER_RESPONSE_INVALID'
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'job_requeue_not_allowed';
  end if;

  update public.billing_processing_jobs j
  set state = 'pending', lease_owner = null, lease_until = null,
      error_class = null, error_code = null,
      next_attempt_at = clock_timestamp()
  where j.id = p_job_id and j.state = 'manual_review';

  if v_job.webhook_event_id is not null then
    update public.billing_webhook_events e
    set processing_status = 'queued', processed_at = null, error_code = null
    where e.id = v_job.webhook_event_id;
  end if;

  return query
    select j.id, j.state, j.fence
    from public.billing_processing_jobs j
    where j.id = p_job_id;
end;
$$;


ALTER FUNCTION "private"."billing_processing_job_requeue_contract"("p_ctx" "private"."job_context", "p_job_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_processing_job_retry_delay_seconds"("p_error_class" "text", "p_error_code" "text", "p_retry_attempt" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_base integer;
  v_exponent integer;
begin
  if p_retry_attempt is null or p_retry_attempt < 1 then
    return 60;
  end if;
  v_base := case
    when p_error_code in ('PROVIDER_RATE_LIMITED', 'RATE_LIMITED') then 300
    when p_error_class = 'provider' then 60
    when p_error_class = 'worker' then 30
    else 60
  end;
  v_exponent := least(p_retry_attempt - 1, 5);
  return least(3600, v_base * power(2::numeric, v_exponent)::integer);
end;
$$;


ALTER FUNCTION "private"."billing_processing_job_retry_delay_seconds"("p_error_class" "text", "p_error_code" "text", "p_retry_attempt" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_processing_job_sync_webhook_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if new.webhook_event_id is null
     or old.state is not distinct from new.state
     or new.state not in ('completed', 'retryable', 'manual_review') then
    return new;
  end if;

  update public.billing_webhook_events
  set processing_status = case new.state
        when 'retryable' then 'retryable'
        when 'manual_review' then 'manual_review'
        else 'processed'
      end,
      processed_at = case when new.state in ('completed', 'manual_review')
        then clock_timestamp() else null end,
      error_code = case when new.state = 'completed' then null else new.error_code end
  where id = new.webhook_event_id;
  return new;
end;
$$;


ALTER FUNCTION "private"."billing_processing_job_sync_webhook_event"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_provider_product_contract_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_checkout_exists boolean;
begin
  if tg_op='DELETE' then
    select exists(
      select 1 from public.billing_checkout_intents c
      where c.provider_account_id=old.provider_account_id and c.provider_product_id=old.id
    ) or old.published into v_checkout_exists;
    if v_checkout_exists then
      raise exception using errcode='P0001', message='mapping_immutable';
    end if;
    return old;
  end if;
  select old.published or exists(
    select 1 from public.billing_checkout_intents c
    where c.provider_account_id=old.provider_account_id and c.provider_product_id=old.id
  ) into v_checkout_exists;
  if v_checkout_exists and (
    new.provider_account_id is distinct from old.provider_account_id
    or new.platform_id is distinct from old.platform_id
    or new.commercial_price_id is distinct from old.commercial_price_id
    or new.external_plan_id is distinct from old.external_plan_id
    or new.product_type is distinct from old.product_type
    or new.external_sku_ids is distinct from old.external_sku_ids
    or new.sku_count is distinct from old.sku_count
    or new.purchase_months is distinct from old.purchase_months
    or new.expected_show_amount is distinct from old.expected_show_amount
    or new.expected_total_amount is distinct from old.expected_total_amount
    or new.currency is distinct from old.currency
    or new.price_version is distinct from old.price_version
    or new.mapping_version is distinct from old.mapping_version
  ) then
    raise exception using errcode='P0001', message='mapping_immutable';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."billing_provider_product_contract_guard"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_reconciliation_cursor_update"("p_ctx" "private"."job_context", "p_provider_account_id" "uuid", "p_stream" "text", "p_expected_version" bigint, "p_high_water_created_at" timestamp with time zone, "p_high_water_order_no" "text", "p_page_cursor" "text", "p_success" boolean, "p_error_code" "text" DEFAULT NULL::"text") RETURNS TABLE("provider_account_id" "uuid", "stream" "text", "version" bigint, "high_water_created_at" timestamp with time zone, "high_water_order_no" "text", "page_cursor" "text", "last_success_at" timestamp with time zone, "last_error_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_cursor public.billing_reconciliation_cursors;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null or p_provider_account_id is null
     or p_stream not in ('discovery', 'processing')
     or p_expected_version is null or p_expected_version < 0 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (
    select 1 from public.billing_processing_jobs j
    where j.id = (p_ctx).job_id and j.state = 'processing'
      and j.lease_owner = (p_ctx).lease_owner
      and j.fence = (p_ctx).fencing_token
      and j.lease_until > clock_timestamp()
  ) then
    raise exception using errcode = '40001', message = 'fence_conflict';
  end if;
  select * into v_cursor from public.billing_reconciliation_cursors c
  where c.provider_account_id = p_provider_account_id and c.stream = p_stream for update;
  if not found then
    if p_expected_version <> 0 then raise exception using errcode = '40001', message = 'cursor_conflict'; end if;
    insert into public.billing_reconciliation_cursors (
      provider_account_id, stream, version, high_water_created_at, high_water_order_no,
      page_cursor, head_scan_at, last_success_at, last_error_code
    ) values (
      p_provider_account_id, p_stream, 1, p_high_water_created_at, p_high_water_order_no,
      p_page_cursor, clock_timestamp(), case when p_success then clock_timestamp() else null end,
      case when p_success then null else p_error_code end
    ) returning * into v_cursor;
  else
    if v_cursor.version <> p_expected_version then
      raise exception using errcode = '40001', message = 'cursor_conflict';
    end if;
    update public.billing_reconciliation_cursors as c set
      version = c.version + 1,
      high_water_created_at = case when p_high_water_created_at is not null and (c.high_water_created_at is null or (p_high_water_created_at, coalesce(p_high_water_order_no, '')) > (c.high_water_created_at, coalesce(c.high_water_order_no, ''))) then p_high_water_created_at else c.high_water_created_at end,
      high_water_order_no = case when p_high_water_created_at is not null and (c.high_water_created_at is null or (p_high_water_created_at, coalesce(p_high_water_order_no, '')) > (c.high_water_created_at, coalesce(c.high_water_order_no, ''))) then p_high_water_order_no else c.high_water_order_no end,
      page_cursor = p_page_cursor,
      head_scan_at = clock_timestamp(),
      last_success_at = case when p_success then clock_timestamp() else c.last_success_at end,
      last_error_code = case when p_success then null else p_error_code end
    where c.id = v_cursor.id returning c.* into v_cursor;
  end if;
  return query select v_cursor.provider_account_id, v_cursor.stream, v_cursor.version,
    v_cursor.high_water_created_at, v_cursor.high_water_order_no, v_cursor.page_cursor,
    v_cursor.last_success_at, v_cursor.last_error_code;
end;
$$;


ALTER FUNCTION "private"."billing_reconciliation_cursor_update"("p_ctx" "private"."job_context", "p_provider_account_id" "uuid", "p_stream" "text", "p_expected_version" bigint, "p_high_water_created_at" timestamp with time zone, "p_high_water_order_no" "text", "p_page_cursor" "text", "p_success" boolean, "p_error_code" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_reconciliation_page_failure"("p_ctx" "private"."job_context", "p_provider_account_id" "uuid", "p_page_number" integer, "p_expected_version" bigint, "p_error_code" "text") RETURNS TABLE("provider_account_id" "uuid", "page_number" integer, "cursor_version" bigint, "page_cursor" "text", "last_error_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $_$
declare
  v_cursor public.billing_reconciliation_cursors;
  v_page_cursor text := p_page_number::text;
  v_current_page integer;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or length((p_ctx).lease_owner) not between 1 and 128
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null or p_provider_account_id is null
     or p_page_number is null or p_page_number < 1 or p_page_number > 999999999
     or p_expected_version is null or p_expected_version < 0
     or p_error_code is null or length(p_error_code) not between 1 and 128 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (
    select 1 from public.billing_provider_accounts a
    where a.id = p_provider_account_id and a.status = 'active'
  ) then
    raise exception using errcode = 'P0001', message = 'provider_account_unavailable';
  end if;

  select * into v_cursor
  from public.billing_reconciliation_cursors c
  where c.provider_account_id = p_provider_account_id and c.stream = 'discovery'
  for update;
  if not found then
    if p_expected_version <> 0 then
      raise exception using errcode = '40001', message = 'cursor_conflict';
    end if;
    insert into public.billing_reconciliation_cursors (
      provider_account_id, stream, version, page_cursor, head_scan_at,
      last_error_code
    ) values (
      p_provider_account_id, 'discovery', 1, v_page_cursor, clock_timestamp(),
      p_error_code
    ) returning * into v_cursor;
  else
    if v_cursor.version <> p_expected_version then
      raise exception using errcode = '40001', message = 'cursor_conflict';
    end if;
    if v_cursor.page_cursor is null then
      v_current_page := 1;
    elsif v_cursor.page_cursor ~ '^[1-9][0-9]{0,8}$' then
      v_current_page := v_cursor.page_cursor::integer;
    else
      raise exception using errcode = 'P0001', message = 'reconciliation_cursor_invalid';
    end if;
    if v_current_page <> p_page_number then
      raise exception using errcode = '40001', message = 'cursor_conflict';
    end if;
    update public.billing_reconciliation_cursors c
    set version = c.version + 1,
        page_cursor = v_page_cursor,
        head_scan_at = clock_timestamp(),
        last_error_code = p_error_code
    where c.id = v_cursor.id
    returning c.* into v_cursor;
  end if;
  return query select p_provider_account_id, p_page_number, v_cursor.version,
    v_cursor.page_cursor, v_cursor.last_error_code;
end;
$_$;


ALTER FUNCTION "private"."billing_reconciliation_page_failure"("p_ctx" "private"."job_context", "p_provider_account_id" "uuid", "p_page_number" integer, "p_expected_version" bigint, "p_error_code" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_reconciliation_page_ingest"("p_ctx" "private"."job_context", "p_provider_account_id" "uuid", "p_page_number" integer, "p_expected_version" bigint, "p_next_page" integer, "p_orders" "jsonb") RETURNS TABLE("provider_account_id" "uuid", "page_number" integer, "next_page" integer, "cursor_version" bigint, "discovered_count" integer, "queued_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $_$
declare
  v_item jsonb;
  v_order_no text;
  v_order public.billing_orders;
  v_inserted boolean;
  v_discovered integer := 0;
  v_queued integer := 0;
  v_cursor record;
  v_current_page integer;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or length((p_ctx).lease_owner) not between 1 and 128
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null or p_provider_account_id is null
     or p_page_number is null or p_page_number < 1 or p_page_number > 999999999
     or p_expected_version is null or p_expected_version < 0
     or (p_next_page is not null and (p_next_page < 1 or p_next_page > 999999999))
     or coalesce(jsonb_typeof(p_orders), '') <> 'array'
     or jsonb_array_length(p_orders) > 50 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  if not exists (
    select 1 from public.billing_provider_accounts a
    where a.id = p_provider_account_id and a.status = 'active'
  ) then
    raise exception using errcode = 'P0001', message = 'provider_account_unavailable';
  end if;

  for v_item in select value from jsonb_array_elements(p_orders)
  loop
    if jsonb_typeof(v_item) <> 'object' then
      raise exception using errcode = 'P0001', message = 'provider_response_invalid';
    end if;
    v_order_no := nullif(btrim(v_item->>'out_trade_no'), '');
    if v_order_no is null or length(v_order_no) > 256 then
      raise exception using errcode = 'P0001', message = 'provider_response_invalid';
    end if;

    insert into public.billing_orders(provider_account_id, provider_order_no)
    values (p_provider_account_id, v_order_no)
    on conflict on constraint billing_orders_provider_account_id_provider_order_no_key do nothing
    returning * into v_order;
    v_inserted := found;
    if not v_inserted then
      select * into v_order
      from public.billing_orders o
      where o.provider_account_id = p_provider_account_id
        and o.provider_order_no = v_order_no;
    end if;
    if v_order.id is null then
      raise exception using errcode = 'P0001', message = 'order_target_unavailable';
    end if;
    v_discovered := v_discovered + 1;

    -- Repeated page scans are safe: only a newly discovered order or an order
    -- without an outstanding processing job receives a reconciliation job.
    if v_inserted or not exists (
      select 1 from public.billing_processing_jobs j
      where j.billing_order_id = v_order.id
        and j.state in ('pending', 'processing', 'retryable')
    ) and not exists (
      select 1 from public.billing_processing_jobs j
      where j.billing_order_id = v_order.id
        and j.job_kind = 'reconciliation'
        and j.state in ('completed', 'manual_review')
    ) then
      perform pg_advisory_xact_lock(
        hashtextextended('billing-reconciliation:' || v_order.id::text, 0)
      );
      if not exists (
        select 1 from public.billing_processing_jobs j
        where j.billing_order_id = v_order.id
          and j.state in ('pending', 'processing', 'retryable', 'completed', 'manual_review')
      ) then
        insert into public.billing_processing_jobs(job_kind, billing_order_id)
        values ('reconciliation', v_order.id);
        v_queued := v_queued + 1;
      end if;
    end if;
  end loop;

  -- This is a page-discovery operation, not an order-processing lease.  Keep
  -- it atomic with order/job insertion, but do not manufacture a processing
  -- job merely to satisfy the processing-stream cursor wrapper.
  select * into v_cursor
  from public.billing_reconciliation_cursors c
  where c.provider_account_id = p_provider_account_id and c.stream = 'discovery'
  for update;
  if not found then
    if p_expected_version <> 0 then
      raise exception using errcode = '40001', message = 'cursor_conflict';
    end if;
    insert into public.billing_reconciliation_cursors (
      provider_account_id, stream, version, page_cursor, head_scan_at,
      last_success_at, last_error_code
    ) values (
      p_provider_account_id, 'discovery', 1,
      case when p_next_page is null then null else p_next_page::text end,
      clock_timestamp(), clock_timestamp(), null
    ) returning * into v_cursor;
  else
    if v_cursor.version <> p_expected_version then
      raise exception using errcode = '40001', message = 'cursor_conflict';
    end if;
    if v_cursor.page_cursor is null then
      v_current_page := 1;
    elsif v_cursor.page_cursor ~ '^[1-9][0-9]{0,8}$' then
      v_current_page := v_cursor.page_cursor::integer;
    else
      raise exception using errcode = 'P0001', message = 'reconciliation_cursor_invalid';
    end if;
    if v_current_page <> p_page_number then
      raise exception using errcode = '40001', message = 'cursor_conflict';
    end if;
    update public.billing_reconciliation_cursors c
    set version = c.version + 1,
        page_cursor = case when p_next_page is null then null else p_next_page::text end,
        head_scan_at = clock_timestamp(),
        last_success_at = clock_timestamp(),
        last_error_code = null
    where c.id = v_cursor.id
    returning c.* into v_cursor;
  end if;

  return query select p_provider_account_id, p_page_number, p_next_page,
    v_cursor.version, v_discovered, v_queued;
end;
$_$;


ALTER FUNCTION "private"."billing_reconciliation_page_ingest"("p_ctx" "private"."job_context", "p_provider_account_id" "uuid", "p_page_number" integer, "p_expected_version" bigint, "p_next_page" integer, "p_orders" "jsonb") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_reconciliation_page_target"("p_ctx" "private"."job_context", "p_provider_account_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("provider_account_id" "uuid", "page_number" integer, "expected_version" bigint, "page_cursor" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $_$
declare
  v_cursor public.billing_reconciliation_cursors;
  v_provider public.billing_provider_accounts;
  v_page integer;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or length((p_ctx).lease_owner) not between 1 and 128
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  select * into v_provider
  from public.billing_provider_accounts a
  where a.status = 'active'
    and (p_provider_account_id is null or a.id = p_provider_account_id)
  order by a.id
  limit 1;
  if not found then return; end if;

  select * into v_cursor
  from public.billing_reconciliation_cursors c
  where c.provider_account_id = v_provider.id and c.stream = 'discovery';

  if not found then
    return query select v_provider.id, 1, 0::bigint, null::text;
    return;
  end if;

  if v_cursor.page_cursor is null then
    v_page := 1;
  elsif v_cursor.page_cursor ~ '^[1-9][0-9]{0,8}$' then
    v_page := v_cursor.page_cursor::integer;
  else
    raise exception using errcode = 'P0001', message = 'reconciliation_cursor_invalid';
  end if;

  return query select v_provider.id, v_page, v_cursor.version, v_cursor.page_cursor;
end;
$_$;


ALTER FUNCTION "private"."billing_reconciliation_page_target"("p_ctx" "private"."job_context", "p_provider_account_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_refund_observation_record"("p_ctx" "private"."job_context", "p_provider_account_id" "uuid", "p_provider_refund_id" "text", "p_provider_order_no" "text", "p_billing_order_id" "uuid", "p_status" "text", "p_refund_amount" numeric, "p_currency" "text", "p_details" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("observation_id" "uuid", "status" "text", "billing_order_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_observation private.billing_refund_observations;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null or p_provider_account_id is null
     or p_provider_refund_id is null or length(p_provider_refund_id) not between 1 and 256
     or p_provider_order_no is null or length(p_provider_order_no) not between 1 and 256
     or p_status not in ('observed', 'compensation_pending', 'compensated', 'rejected')
     or (p_refund_amount is not null and p_refund_amount < 0)
     or (p_currency is not null and p_currency <> 'CNY')
     or p_details is null or jsonb_typeof(p_details) <> 'object' then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  insert into private.billing_refund_observations (
    provider_account_id, provider_refund_id, provider_order_no,
    billing_order_id, status, refund_amount, currency, details
  ) values (
    p_provider_account_id, p_provider_refund_id, p_provider_order_no,
    p_billing_order_id, p_status, p_refund_amount, p_currency, p_details
  )
  on conflict (provider_account_id, provider_refund_id) do update
  set provider_order_no = excluded.provider_order_no,
      billing_order_id = excluded.billing_order_id,
      status = case when private.billing_refund_observations.status = 'compensated'
        and excluded.status <> 'compensated'
        then private.billing_refund_observations.status else excluded.status end,
      refund_amount = excluded.refund_amount,
      currency = excluded.currency,
      details = excluded.details,
      updated_at = clock_timestamp()
  returning * into v_observation;
  return query select v_observation.id, v_observation.status, v_observation.billing_order_id;
end;
$$;


ALTER FUNCTION "private"."billing_refund_observation_record"("p_ctx" "private"."job_context", "p_provider_account_id" "uuid", "p_provider_refund_id" "text", "p_provider_order_no" "text", "p_billing_order_id" "uuid", "p_status" "text", "p_refund_amount" numeric, "p_currency" "text", "p_details" "jsonb") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_webhook_discovery_target"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_fence" bigint) RETURNS TABLE("order_id" "uuid", "provider_account_id" "uuid", "provider_order_no" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_job public.billing_processing_jobs;
  v_event public.billing_webhook_events;
  v_order public.billing_orders;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).request_id is null
     or p_job_id is null or p_fence is null
     or p_fence <> (p_ctx).fencing_token then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  select * into v_job from public.billing_processing_jobs j
  where j.id = p_job_id and j.state = 'processing'
    and j.lease_owner = (p_ctx).lease_owner and j.fence = p_fence
    and j.lease_until > clock_timestamp()
  for update;
  if not found then raise exception using errcode = '40001', message = 'fence_conflict'; end if;
  if v_job.job_kind <> 'webhook_order_discovery' or v_job.webhook_event_id is null then
    raise exception using errcode = '22023', message = 'invalid_job_kind';
  end if;

  select * into v_event from public.billing_webhook_events e
  where e.id = v_job.webhook_event_id
  for update;
  if not found or v_event.provider_order_no is null then
    raise exception using errcode = 'P0001', message = 'missing_provider_order_no';
  end if;

  insert into public.billing_orders(provider_account_id, provider_order_no)
  values (v_event.provider_account_id, v_event.provider_order_no)
  on conflict (provider_account_id, provider_order_no) do nothing;

  select * into v_order from public.billing_orders o
  where o.provider_account_id = v_event.provider_account_id
    and o.provider_order_no = v_event.provider_order_no
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'order_target_unavailable';
  end if;
  if v_job.billing_order_id is not null and v_job.billing_order_id <> v_order.id then
    raise exception using errcode = '40001', message = 'job_order_conflict';
  end if;

  update public.billing_processing_jobs
  set billing_order_id = v_order.id
  where id = p_job_id and state = 'processing'
    and lease_owner = (p_ctx).lease_owner and fence = p_fence
    and lease_until > clock_timestamp();
  if not found then raise exception using errcode = '40001', message = 'fence_conflict'; end if;
  update public.billing_webhook_events
  set processing_status = 'processing', error_code = null
  where id = v_event.id;

  return query select v_order.id, v_order.provider_account_id, v_order.provider_order_no;
end;
$$;


ALTER FUNCTION "private"."billing_webhook_discovery_target"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_fence" bigint) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."billing_webhook_ingest"("p_provider_account_id" "uuid", "p_provider_event_key" "text", "p_payload_hash" "bytea", "p_signature_status" "text", "p_provider_order_no" "text") RETURNS TABLE("event_id" "uuid", "job_id" "uuid", "duplicate" boolean, "processing_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_event public.billing_webhook_events;
  v_job public.billing_processing_jobs;
begin
  if p_provider_account_id is null or p_provider_event_key is null
     or length(p_provider_event_key) not between 1 and 256
     or p_payload_hash is null or octet_length(p_payload_hash) <> 32
     or p_signature_status not in ('verified', 'unverified', 'invalid', 'missing')
     or p_provider_order_no is null or length(p_provider_order_no) not between 1 and 256 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (select 1 from public.billing_provider_accounts pa where pa.id = p_provider_account_id) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  insert into public.billing_webhook_events(
    provider_account_id, provider_event_key, payload_hash, signature_status,
    processing_status, provider_order_no
  ) values (
    p_provider_account_id, p_provider_event_key, p_payload_hash, p_signature_status,
    'queued', p_provider_order_no
  )
  on conflict (provider_account_id, provider_event_key) do nothing
  returning * into v_event;
  if not found then
    select e.* into v_event from public.billing_webhook_events e
    where e.provider_account_id = p_provider_account_id and e.provider_event_key = p_provider_event_key
    for update;
    if v_event.payload_hash <> p_payload_hash then
      insert into public.billing_webhook_event_conflicts (
        provider_account_id, webhook_event_id, provider_event_key,
        existing_payload_hash, conflicting_payload_hash
      ) values (
        p_provider_account_id, v_event.id, p_provider_event_key,
        v_event.payload_hash, p_payload_hash
      ) on conflict do nothing;
      update public.billing_webhook_events
      set processing_status = 'manual_review', error_code = 'WEBHOOK_PAYLOAD_CONFLICT'
      where id = v_event.id;
      select j.* into v_job from public.billing_processing_jobs j where j.webhook_event_id = v_event.id;
      return query select v_event.id, v_job.id, false, 'manual_review'::text;
      return;
    end if;
    select j.* into v_job from public.billing_processing_jobs j where j.webhook_event_id = v_event.id;
    return query select v_event.id, v_job.id, true, v_event.processing_status;
    return;
  end if;
  insert into public.billing_processing_jobs(job_kind, webhook_event_id)
  values ('webhook_order_discovery', v_event.id)
  returning * into v_job;
  return query select v_event.id, v_job.id, false, v_event.processing_status;
end;
$$;


ALTER FUNCTION "private"."billing_webhook_ingest"("p_provider_account_id" "uuid", "p_provider_event_key" "text", "p_payload_hash" "bytea", "p_signature_status" "text", "p_provider_order_no" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."check_user_session"("p_user_id" "uuid", "p_session_id" "uuid") RETURNS TABLE("active" boolean, "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
begin
  if p_user_id is null or p_session_id is null then
    return query select false, 'invalid_input'::text;
    return;
  end if;

  if not exists (select 1 from auth.users where id = p_user_id) then
    return query select false, 'user_not_found'::text;
    return;
  end if;

  if private.identity_is_blocked(p_user_id) then
    return query select false, 'identity_deleting'::text;
    return;
  end if;

  if not exists (
    select 1
    from auth.sessions
    where id = p_session_id
      and user_id = p_user_id
      and (not_after is null or not_after > now())
  ) then
    return query select false, 'session_not_found_or_expired'::text;
    return;
  end if;

  return query select true, 'active'::text;
end;
$$;


ALTER FUNCTION "private"."check_user_session"("p_user_id" "uuid", "p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."commerce_active_paid_entitlements"("p_platform_id" "uuid" DEFAULT NULL::"uuid", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS TABLE("platform_id" "uuid", "platform_account_id" "uuid", "grant_id" "uuid", "plan_id" "uuid", "ends_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
  with current_grants as (
    select distinct on (g.platform_id, g.platform_account_id)
      g.id, g.platform_id, g.platform_account_id, g.plan_id,
      g.ends_at, g.starts_at, g.created_at
    from public.subscription_grants g
    where (p_platform_id is null or g.platform_id = p_platform_id)
      and g.starts_at <= p_at
      and (g.ends_at is null or g.ends_at > p_at)
      and not exists (
        select 1
        from public.subscription_events revoked
        where revoked.platform_id = g.platform_id
          and revoked.platform_account_id = g.platform_account_id
          and revoked.grant_id = g.id
          and revoked.event_type = 'revoked'
      )
    order by g.platform_id, g.platform_account_id,
      g.starts_at desc, g.created_at desc, g.id desc
  )
  select cg.platform_id, cg.platform_account_id, cg.id, cg.plan_id, cg.ends_at
  from current_grants cg
  join public.plans p
    on p.platform_id = cg.platform_id and p.id = cg.plan_id
   and p.kind = 'paid' and p.status = 'active'
  join public.subscriptions s
    on s.platform_id = cg.platform_id
   and s.platform_account_id = cg.platform_account_id
   and s.status = 'active'
  join public.platform_accounts a
    on a.platform_id = cg.platform_id and a.id = cg.platform_account_id
   and a.status = 'active'
$$;


ALTER FUNCTION "private"."commerce_active_paid_entitlements"("p_platform_id" "uuid", "p_at" timestamp with time zone) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."commerce_offers_list"("p_platform_id" "uuid", "p_platform_key_id" "uuid") RETURNS TABLE("offer_id" "uuid", "offer_code" "text", "offer_name" "text", "offer_description" "text", "plan_id" "uuid", "plan_code" "text", "plan_name" "text", "duration_value" integer, "duration_unit" "text", "recommended" boolean, "price_id" "uuid", "price_amount" numeric, "currency" "text", "price_version" integer, "purchasable" boolean, "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_platform_status text;
  v_purchases_paused boolean := false;
begin
  select p.status into v_platform_status
  from public.platforms p
  join private.platform_api_keys k on k.platform_id=p.id
  where p.id=p_platform_id and k.id=p_platform_key_id
    and k.status='active' and (k.expires_at is null or k.expires_at>now());
  if not found then raise exception using errcode='28000', message='platform_key_invalid'; end if;
  select c.purchases_paused into v_purchases_paused
  from public.platform_commerce_policy c where c.platform_id=p_platform_id;
  return query
  select o.id,o.code,o.name,o.description,p.id,p.code,p.name,
    o.duration_value,o.duration_unit,o.recommended,
    price.id,price.amount,price.currency,price.version,
    (v_platform_status='active' and not coalesce(v_purchases_paused,false)
      and p.status='active' and price.id is not null
      and exists(
        select 1 from public.billing_provider_products m
        join public.billing_provider_accounts pa on pa.id=m.provider_account_id
        where m.platform_id=p_platform_id and m.commercial_price_id=price.id
          and pa.status='active' and m.published and m.enabled
          and m.validation_status='verified'
          and m.expected_show_amount=price.amount and m.currency=price.currency
          and m.price_version=price.version
      )),
    case
      when v_platform_status<>'active' then 'platform_disabled'
      when coalesce(v_purchases_paused,false) then 'purchases_paused'
      when p.status<>'active' then 'plan_unavailable'
      when price.id is null then 'price_unavailable'
      when not exists(
        select 1 from public.billing_provider_products m
        join public.billing_provider_accounts pa on pa.id=m.provider_account_id
        where m.platform_id=p_platform_id and m.commercial_price_id=price.id
          and pa.status='active' and m.published and m.enabled
          and m.validation_status='verified'
          and m.expected_show_amount=price.amount and m.currency=price.currency
          and m.price_version=price.version
      ) then 'provider_mapping_unavailable'
      else 'ready'
    end
  from public.platform_commercial_offers o
  join public.plans p on p.platform_id=o.platform_id and p.id=o.plan_id and p.kind='paid'
  left join public.platform_commercial_prices price
    on price.platform_id=o.platform_id and price.offer_id=o.id and price.status='active'
  where o.platform_id=p_platform_id and o.status='active'
  order by o.sort_order,o.id;
end;
$$;


ALTER FUNCTION "private"."commerce_offers_list"("p_platform_id" "uuid", "p_platform_key_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."commercial_offer_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if tg_op='UPDATE' then
    if new.platform_id is distinct from old.platform_id or new.code is distinct from old.code then
      raise exception using errcode='P0001', message='commercial_offer_identity_immutable';
    end if;
    if (new.plan_id is distinct from old.plan_id
        or new.term_kind is distinct from old.term_kind
        or new.duration_value is distinct from old.duration_value
        or new.duration_unit is distinct from old.duration_unit)
       and exists(select 1 from public.platform_commercial_prices p where p.offer_id=old.id) then
      raise exception using errcode='P0001', message='commercial_offer_terms_immutable';
    end if;
    if old.status='archived' and new.status<>'archived' then
      raise exception using errcode='P0001', message='commercial_offer_archived';
    end if;
    new.row_version := old.row_version + 1;
  end if;
  if new.status='active' and not exists(
    select 1 from public.plans p where p.platform_id=new.platform_id and p.id=new.plan_id
      and p.kind='paid' and p.status='active'
  ) then
    raise exception using errcode='P0001', message='plan_unavailable';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."commercial_offer_guard"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."commercial_price_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.platform_id is distinct from old.platform_id
      or new.offer_id is distinct from old.offer_id
      or new.version is distinct from old.version
      or new.amount is distinct from old.amount
      or new.currency is distinct from old.currency then
      raise exception using errcode = 'P0001', message = 'commercial_price_immutable';
    end if;
    if new.effective_from is distinct from old.effective_from
      and not (old.status = 'draft' and new.status = 'active'
        and old.effective_from is null and new.effective_from is not null) then
      raise exception using errcode = 'P0001', message = 'commercial_price_immutable';
    end if;
    if old.status = 'retired' and new.status <> 'retired' then
      raise exception using errcode = 'P0001', message = 'commercial_price_retired';
    end if;
    if old.status = 'active' and new.status not in ('active', 'retired') then
      raise exception using errcode = 'P0001', message = 'commercial_price_transition_invalid';
    end if;
    new.row_version := old.row_version + 1;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."commercial_price_guard"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_account_privacy_cleanup"("p_platform_account_id" "uuid", "p_now" timestamp with time zone, "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if p_platform_account_id is null or p_now is null or p_reason is null
     or length(p_reason) not between 1 and 128 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  update public.platform_config_gallery_entries e
  set status = 'removed', governance_reason = p_reason
  where e.status = 'approved'
    and exists (
      select 1 from public.platform_configs c
      where c.id = e.config_id
        and c.platform_account_id = p_platform_account_id
    );

  update public.platform_config_gallery_submissions s
  set status = 'cancelled',
      reviewed_at = coalesce(s.reviewed_at, p_now),
      review_reason = p_reason
  where s.status = 'pending'
    and exists (
      select 1 from public.platform_configs c
      where c.id = s.config_id
        and c.platform_account_id = p_platform_account_id
    );

  update public.platform_configs c
  set status = case when c.status = 'deleted' then 'deleted' else 'deleting' end,
      delete_requested_at = coalesce(c.delete_requested_at, p_now),
      title = '[deleted]',
      description = null,
      row_version = case
        when c.title <> '[deleted]' or c.description is not null or c.status = 'active'
          then c.row_version + 1
        else c.row_version
      end
  where c.platform_account_id = p_platform_account_id;

  update public.platform_config_versions v
  set schema_key = 'deleted', schema_version = '0', changelog = null
  where v.platform_account_id = p_platform_account_id
    and (v.schema_key <> 'deleted' or v.schema_version <> '0' or v.changelog is not null);

  delete from public.platform_config_likes l
  where l.platform_account_id = p_platform_account_id;

  update public.platform_config_usage_events u
  set actor_platform_account_id = null
  where u.actor_platform_account_id = p_platform_account_id;
end;
$$;


ALTER FUNCTION "private"."config_account_privacy_cleanup"("p_platform_account_id" "uuid", "p_now" timestamp with time zone, "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_create"("p_ctx" "private"."account_context", "p_title" "text", "p_description" "text" DEFAULT NULL::"text") RETURNS TABLE("config_id" "uuid", "title" "text", "description" "text", "status" "text", "current_version_id" "uuid", "row_version" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_principal record;
  v_account public.platform_accounts;
  v_limit integer;
  v_config public.platform_configs;
begin
  if (p_ctx).request_id is null or p_title is null or length(btrim(p_title)) not between 1 and 120
     or p_title ~ '[[:cntrl:]]' or p_description is not null and length(p_description) > 2000 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization <> 'allowed' then
    raise exception using errcode = '42501', message = v_principal.authorization;
  end if;
  select * into v_account from public.platform_accounts a
  where a.platform_id = (p_ctx).platform_id and a.id = v_principal.platform_account_id for update;
  perform private.config_rate_limit_require((p_ctx).platform_id, v_account.id, 'config_create', 3600, 60);
  v_limit := private.config_slot_limit(p_ctx);
  if (select count(*) from public.platform_configs c
      where c.platform_id = (p_ctx).platform_id and c.platform_account_id = v_account.id
        and c.status = 'active') >= v_limit then
    raise exception using errcode = 'P0001', message = 'config_slot_limit_exceeded';
  end if;
  insert into public.platform_configs(platform_id, platform_account_id, title, description)
  values ((p_ctx).platform_id, v_account.id, btrim(p_title), nullif(btrim(p_description), ''))
  returning * into v_config;
  perform private.audit_append((p_ctx).request_id, 'user', (p_ctx).user_id,
    v_config.platform_id, v_config.platform_account_id, 'config.created',
    'platform_config', v_config.id, null, null, '{}'::jsonb);
  return query select v_config.id, v_config.title, v_config.description, v_config.status,
    v_config.current_version_id, v_config.row_version, v_config.created_at, v_config.updated_at;
end;
$$;


ALTER FUNCTION "private"."config_create"("p_ctx" "private"."account_context", "p_title" "text", "p_description" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_delete_reconcile"("p_config_id" "uuid", "p_now" timestamp with time zone DEFAULT "clock_timestamp"()) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if p_config_id is null or p_now is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  update public.platform_configs c
  set status = 'deleted',
      deleted_at = coalesce(c.deleted_at, p_now),
      row_version = c.row_version + 1
  where c.id = p_config_id
    and c.status = 'deleting'
    and not exists (
      select 1
      from public.platform_config_versions v
      join public.platform_config_files f on f.id = v.file_id
      where v.config_id = c.id
        and f.status <> 'deleted'
    );
end;
$$;


ALTER FUNCTION "private"."config_delete_reconcile"("p_config_id" "uuid", "p_now" timestamp with time zone) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_delete_reconcile_on_config"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.config_delete_reconcile(new.id, clock_timestamp());
  return new;
end;
$$;


ALTER FUNCTION "private"."config_delete_reconcile_on_config"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_delete_reconcile_on_file"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_config_id uuid;
begin
  select v.config_id into v_config_id
  from public.platform_config_versions v
  where v.file_id = new.id;

  if v_config_id is not null then
    perform private.config_delete_reconcile(v_config_id, clock_timestamp());
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."config_delete_reconcile_on_file"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_delete_request"("p_ctx" "private"."account_context", "p_config_id" "uuid") RETURNS TABLE("config_id" "uuid", "status" "text", "row_version" bigint, "delete_requested_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_principal record;
  v_config public.platform_configs;
  v_now timestamptz := clock_timestamp();
begin
  if (p_ctx).request_id is null or p_config_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization <> 'allowed' then
    raise exception using errcode = '42501', message = v_principal.authorization;
  end if;
  select * into v_config from public.platform_configs c
  where c.platform_id = (p_ctx).platform_id
    and c.platform_account_id = v_principal.platform_account_id
    and c.id = p_config_id and c.status <> 'deleted' for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_config.status = 'active' then
    update public.platform_configs c
    set status = 'deleting', delete_requested_at = coalesce(c.delete_requested_at, v_now),
      row_version = c.row_version + 1
    where c.id = v_config.id returning * into v_config;
    update public.platform_config_gallery_entries e
    set status = 'removed', governance_reason = 'author_delete_requested'
    where e.platform_id = v_config.platform_id and e.config_id = v_config.id
      and e.status = 'approved';
    update public.platform_config_gallery_submissions s
    set status = 'cancelled', reviewed_at = coalesce(s.reviewed_at, v_now),
      review_reason = coalesce(s.review_reason, 'author_delete_requested')
    where s.platform_id = v_config.platform_id and s.config_id = v_config.id
      and s.status = 'pending';
    update public.platform_config_files f
    set status = 'deleting',
      cancel_requested_at = coalesce(f.cancel_requested_at, v_now),
      delete_requested_at = coalesce(f.delete_requested_at, v_now),
      next_attempt_at = v_now
    where f.id in (
      select v.file_id from public.platform_config_versions v
      where v.platform_id = v_config.platform_id and v.config_id = v_config.id
    ) and f.status <> 'deleted';
    perform private.audit_append(
      (p_ctx).request_id, 'user', (p_ctx).user_id, v_config.platform_id,
      v_config.platform_account_id, 'config.delete_requested', 'platform_config',
      v_config.id, null, null, '{}'::jsonb
    );
  end if;
  return query select v_config.id, v_config.status, v_config.row_version,
    v_config.delete_requested_at;
end;
$$;


ALTER FUNCTION "private"."config_delete_request"("p_ctx" "private"."account_context", "p_config_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_gallery_content_authorize"("p_ctx" "private"."account_context", "p_config_id" "uuid", "p_delivery_kind" "text") RETURNS TABLE("file_id" "uuid", "version_id" "uuid", "storage_bucket" "text", "storage_path" "text", "original_name" "text", "mime_type" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_principal record;
begin
  if (p_ctx).request_id is null or p_config_id is null
     or p_delivery_kind not in ('download', 'apply') then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization <> 'allowed' then
    raise exception using errcode = '42501', message = v_principal.authorization;
  end if;
  perform private.config_rate_limit_require(
    (p_ctx).platform_id, v_principal.platform_account_id,
    'config_gallery_delivery', 3600, 600
  );
  return query
    select f.id, e.published_version_id, f.storage_bucket, f.storage_path,
      f.original_name, coalesce(f.mime_type, 'application/octet-stream')
    from public.platform_config_gallery_entries e
    join public.platform_configs c
      on c.platform_id = e.platform_id and c.id = e.config_id
    join public.platform_accounts a
      on a.platform_id = c.platform_id and a.id = c.platform_account_id
    join public.platform_config_versions v
      on v.platform_id = e.platform_id and v.config_id = e.config_id
        and v.id = e.published_version_id
    join public.platform_config_files f on f.id = v.file_id
    where e.platform_id = (p_ctx).platform_id and e.config_id = p_config_id
      and e.status = 'approved' and c.status = 'active' and a.status = 'active'
      and f.resource_kind = 'config_version' and f.status = 'active'
      and f.write_outcome = 'confirmed';
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
end;
$$;


ALTER FUNCTION "private"."config_gallery_content_authorize"("p_ctx" "private"."account_context", "p_config_id" "uuid", "p_delivery_kind" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_gallery_like_set"("p_ctx" "private"."account_context", "p_config_id" "uuid", "p_liked" boolean) RETURNS TABLE("config_id" "uuid", "liked" boolean, "like_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_principal record;
  v_entry public.platform_config_gallery_entries;
begin
  if (p_ctx).request_id is null or p_config_id is null or p_liked is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization <> 'allowed' then
    raise exception using errcode = '42501', message = v_principal.authorization;
  end if;
  select e.* into v_entry
  from public.platform_config_gallery_entries e
  join public.platform_configs c
    on c.platform_id = e.platform_id and c.id = e.config_id
  join public.platform_accounts author
    on author.platform_id = c.platform_id and author.id = c.platform_account_id
  join public.platform_config_versions v
    on v.platform_id = e.platform_id and v.config_id = e.config_id
      and v.id = e.published_version_id
  join public.platform_config_files f on f.id = v.file_id
  where e.platform_id = (p_ctx).platform_id and e.config_id = p_config_id
    and e.status = 'approved' and c.status = 'active' and author.status = 'active'
    and f.resource_kind = 'config_version' and f.status = 'active'
    and f.write_outcome = 'confirmed';
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  perform private.config_rate_limit_require(
    (p_ctx).platform_id, v_principal.platform_account_id,
    'config_gallery_like', 3600, 240
  );
  if p_liked then
    insert into public.platform_config_likes(platform_id, config_id, platform_account_id)
    values ((p_ctx).platform_id, p_config_id, v_principal.platform_account_id)
    on conflict on constraint platform_config_likes_pkey do nothing;
  else
    delete from public.platform_config_likes l
    where l.platform_id = (p_ctx).platform_id and l.config_id = p_config_id
      and l.platform_account_id = v_principal.platform_account_id;
  end if;
  return query select p_config_id,
    exists (
      select 1 from public.platform_config_likes l
      where l.platform_id = (p_ctx).platform_id and l.config_id = p_config_id
        and l.platform_account_id = v_principal.platform_account_id
    ),
    (select count(*) from public.platform_config_likes l
      where l.platform_id = (p_ctx).platform_id and l.config_id = p_config_id);
end;
$$;


ALTER FUNCTION "private"."config_gallery_like_set"("p_ctx" "private"."account_context", "p_config_id" "uuid", "p_liked" boolean) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_gallery_list"("p_ctx" "private"."account_context", "p_cursor_config_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("config_id" "uuid", "title" "text", "description" "text", "author_display_name" "text", "published_version_id" "uuid", "version_number" integer, "schema_key" "text", "schema_version" "text", "changelog" "text", "like_count" bigint, "download_count" bigint, "apply_delivery_count" bigint, "liked" boolean, "approved_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_principal record;
  v_cursor_approved_at timestamptz;
begin
  if (p_ctx).request_id is null or p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization <> 'allowed' then
    raise exception using errcode = '42501', message = v_principal.authorization;
  end if;
  if p_cursor_config_id is not null then
    select e.approved_at into v_cursor_approved_at
    from public.platform_config_gallery_entries e
    join public.platform_configs c on c.platform_id = e.platform_id and c.id = e.config_id
    join public.platform_accounts a on a.platform_id = c.platform_id and a.id = c.platform_account_id
    join public.platform_config_versions v on v.platform_id = e.platform_id
      and v.config_id = e.config_id and v.id = e.published_version_id
    join public.platform_config_files f on f.id = v.file_id
    where e.platform_id = (p_ctx).platform_id and e.config_id = p_cursor_config_id
      and e.status = 'approved' and c.status = 'active' and a.status = 'active'
      and f.resource_kind = 'config_version' and f.status = 'active'
      and f.write_outcome = 'confirmed';
    if v_cursor_approved_at is null then
      raise exception using errcode = 'P0002', message = 'resource_not_found';
    end if;
  end if;
  return query
    select c.id, c.title, c.description, p.display_name,
      e.published_version_id, v.version_number, v.schema_key, v.schema_version,
      v.changelog,
      (select count(*) from public.platform_config_likes l
        where l.platform_id = e.platform_id and l.config_id = e.config_id),
      (select count(*) from public.platform_config_usage_events u
        where u.platform_id = e.platform_id and u.config_id = e.config_id
          and u.event_type = 'download_completed'),
      (select count(*) from public.platform_config_usage_events u
        where u.platform_id = e.platform_id and u.config_id = e.config_id
          and u.event_type = 'apply_delivery_completed'),
      exists (select 1 from public.platform_config_likes l
        where l.platform_id = e.platform_id and l.config_id = e.config_id
          and l.platform_account_id = v_principal.platform_account_id),
      e.approved_at, e.updated_at
    from public.platform_config_gallery_entries e
    join public.platform_configs c
      on c.platform_id = e.platform_id and c.id = e.config_id
    join public.platform_accounts a
      on a.platform_id = c.platform_id and a.id = c.platform_account_id
    left join public.platform_profiles p on p.platform_account_id = a.id
    join public.platform_config_versions v
      on v.platform_id = e.platform_id and v.config_id = e.config_id
        and v.id = e.published_version_id
    join public.platform_config_files f on f.id = v.file_id
    where e.platform_id = (p_ctx).platform_id and e.status = 'approved'
      and c.status = 'active' and a.status = 'active'
      and f.resource_kind = 'config_version' and f.status = 'active'
      and f.write_outcome = 'confirmed'
      and (p_cursor_config_id is null or (e.approved_at, e.config_id) <
        (v_cursor_approved_at, p_cursor_config_id))
    order by e.approved_at desc, e.config_id desc
    limit p_limit;
end;
$$;


ALTER FUNCTION "private"."config_gallery_list"("p_ctx" "private"."account_context", "p_cursor_config_id" "uuid", "p_limit" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_gallery_read"("p_ctx" "private"."account_context", "p_config_id" "uuid") RETURNS TABLE("config_id" "uuid", "title" "text", "description" "text", "author_display_name" "text", "published_version_id" "uuid", "version_number" integer, "schema_key" "text", "schema_version" "text", "changelog" "text", "like_count" bigint, "download_count" bigint, "apply_delivery_count" bigint, "liked" boolean, "approved_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_principal record;
begin
  if (p_ctx).request_id is null or p_config_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization <> 'allowed' then
    raise exception using errcode = '42501', message = v_principal.authorization;
  end if;
  return query
    select c.id, c.title, c.description, p.display_name,
      e.published_version_id, v.version_number, v.schema_key, v.schema_version,
      v.changelog,
      (select count(*) from public.platform_config_likes l
        where l.platform_id = e.platform_id and l.config_id = e.config_id),
      (select count(*) from public.platform_config_usage_events u
        where u.platform_id = e.platform_id and u.config_id = e.config_id
          and u.event_type = 'download_completed'),
      (select count(*) from public.platform_config_usage_events u
        where u.platform_id = e.platform_id and u.config_id = e.config_id
          and u.event_type = 'apply_delivery_completed'),
      exists (select 1 from public.platform_config_likes l
        where l.platform_id = e.platform_id and l.config_id = e.config_id
          and l.platform_account_id = v_principal.platform_account_id),
      e.approved_at, e.updated_at
    from public.platform_config_gallery_entries e
    join public.platform_configs c
      on c.platform_id = e.platform_id and c.id = e.config_id
    join public.platform_accounts a
      on a.platform_id = c.platform_id and a.id = c.platform_account_id
    left join public.platform_profiles p on p.platform_account_id = a.id
    join public.platform_config_versions v
      on v.platform_id = e.platform_id and v.config_id = e.config_id
        and v.id = e.published_version_id
    join public.platform_config_files f on f.id = v.file_id
    where e.platform_id = (p_ctx).platform_id and e.config_id = p_config_id
      and e.status = 'approved' and c.status = 'active' and a.status = 'active'
      and f.resource_kind = 'config_version' and f.status = 'active'
      and f.write_outcome = 'confirmed';
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
end;
$$;


ALTER FUNCTION "private"."config_gallery_read"("p_ctx" "private"."account_context", "p_config_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_gallery_submission_create"("p_ctx" "private"."account_context", "p_config_id" "uuid", "p_version_id" "uuid") RETURNS TABLE("submission_id" "uuid", "config_id" "uuid", "version_id" "uuid", "status" "text", "submitted_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_principal record;
  v_config public.platform_configs;
  v_submission public.platform_config_gallery_submissions;
begin
  if (p_ctx).request_id is null or p_config_id is null or p_version_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization <> 'allowed' then raise exception using errcode = '42501', message = v_principal.authorization; end if;
  select * into v_config from public.platform_configs c
  where c.platform_id = (p_ctx).platform_id and c.platform_account_id = v_principal.platform_account_id
    and c.id = p_config_id and c.status = 'active' for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_config.current_version_id is distinct from p_version_id
     or not exists (select 1 from public.platform_config_versions v
       join public.platform_config_files f on f.id = v.file_id
       where v.id = p_version_id and v.config_id = p_config_id
         and v.platform_id = (p_ctx).platform_id and v.platform_account_id = v_principal.platform_account_id
         and f.resource_kind = 'config_version' and f.status = 'active' and f.write_outcome = 'confirmed') then
    raise exception using errcode = 'P0001', message = 'version_not_ready';
  end if;
  perform private.config_rate_limit_require((p_ctx).platform_id, v_principal.platform_account_id,
    'config_gallery_submission', 86400, 20);
  if exists (select 1 from public.platform_config_gallery_submissions s
    where s.config_id = p_config_id and s.status = 'pending') then
    raise exception using errcode = 'P0001', message = 'submission_pending';
  end if;
  insert into public.platform_config_gallery_submissions(
    platform_id, config_id, version_id, submitted_by_account_id
  ) values ((p_ctx).platform_id, p_config_id, p_version_id, v_principal.platform_account_id)
  returning * into v_submission;
  perform private.audit_append((p_ctx).request_id, 'user', (p_ctx).user_id,
    (p_ctx).platform_id, v_principal.platform_account_id, 'config.gallery_submitted',
    'platform_config_gallery_submission', v_submission.id, null, null,
    jsonb_build_object('config_id', p_config_id, 'version_id', p_version_id));
  return query select v_submission.id, v_submission.config_id, v_submission.version_id,
    v_submission.status, v_submission.submitted_at;
end;
$$;


ALTER FUNCTION "private"."config_gallery_submission_create"("p_ctx" "private"."account_context", "p_config_id" "uuid", "p_version_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_gallery_usage_record"("p_ctx" "private"."account_context", "p_config_id" "uuid", "p_event_type" "text", "p_event_key" "text") RETURNS TABLE("usage_event_id" "uuid", "config_id" "uuid", "version_id" "uuid", "event_type" "text", "occurred_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_principal record;
  v_entry public.platform_config_gallery_entries;
  v_event public.platform_config_usage_events;
begin
  if (p_ctx).request_id is null or p_config_id is null
     or p_event_type not in ('download_completed', 'apply_delivery_completed')
     or p_event_key is null or length(p_event_key) not between 1 and 128
     or p_event_key ~ '[[:cntrl:]]' then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization <> 'allowed' then
    raise exception using errcode = '42501', message = v_principal.authorization;
  end if;
  select e.* into v_entry
  from public.platform_config_gallery_entries e
  join public.platform_configs c
    on c.platform_id = e.platform_id and c.id = e.config_id
  join public.platform_accounts author
    on author.platform_id = c.platform_id and author.id = c.platform_account_id
  join public.platform_config_versions v
    on v.platform_id = e.platform_id and v.config_id = e.config_id
      and v.id = e.published_version_id
  join public.platform_config_files f on f.id = v.file_id
  where e.platform_id = (p_ctx).platform_id and e.config_id = p_config_id
    and e.status = 'approved' and c.status = 'active' and author.status = 'active'
    and f.resource_kind = 'config_version' and f.status = 'active'
    and f.write_outcome = 'confirmed';
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  insert into public.platform_config_usage_events(
    platform_id, config_id, version_id, actor_platform_account_id,
    event_type, event_key
  ) values (
    (p_ctx).platform_id, p_config_id, v_entry.published_version_id,
    v_principal.platform_account_id, p_event_type, p_event_key
  )
  on conflict on constraint platform_config_usage_events_platform_id_event_type_event_k_key do nothing
  returning * into v_event;
  if not found then
    select * into v_event from public.platform_config_usage_events u
    where u.platform_id = (p_ctx).platform_id
      and u.event_type = p_event_type and u.event_key = p_event_key;
    if v_event.config_id <> p_config_id
       or v_event.version_id <> v_entry.published_version_id
       or v_event.actor_platform_account_id is distinct from v_principal.platform_account_id then
      raise exception using errcode = '23505', message = 'idempotency_conflict';
    end if;
  end if;
  return query select v_event.id, v_event.config_id, v_event.version_id,
    v_event.event_type, v_event.occurred_at;
end;
$$;


ALTER FUNCTION "private"."config_gallery_usage_record"("p_ctx" "private"."account_context", "p_config_id" "uuid", "p_event_type" "text", "p_event_key" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_list"("p_ctx" "private"."account_context", "p_cursor_config_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("config_id" "uuid", "title" "text", "description" "text", "status" "text", "current_version_id" "uuid", "row_version" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_principal record;
  v_cursor_updated_at timestamptz;
begin
  if (p_ctx).request_id is null or p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization not in ('allowed', 'suspended') then
    raise exception using errcode = '42501', message = v_principal.authorization;
  end if;
  if p_cursor_config_id is not null then
    select c.updated_at into v_cursor_updated_at from public.platform_configs c
    where c.platform_id = (p_ctx).platform_id
      and c.platform_account_id = v_principal.platform_account_id
      and c.id = p_cursor_config_id and c.status <> 'deleted';
    if v_cursor_updated_at is null then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  end if;
  return query select c.id, c.title, c.description, c.status, c.current_version_id,
    c.row_version, c.created_at, c.updated_at
  from public.platform_configs c
  where c.platform_id = (p_ctx).platform_id
    and c.platform_account_id = v_principal.platform_account_id
    and c.status <> 'deleted'
    and (p_cursor_config_id is null or (c.updated_at, c.id) < (v_cursor_updated_at, p_cursor_config_id))
  order by c.updated_at desc, c.id desc limit p_limit;
end;
$$;


ALTER FUNCTION "private"."config_list"("p_ctx" "private"."account_context", "p_cursor_config_id" "uuid", "p_limit" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_patch"("p_ctx" "private"."account_context", "p_config_id" "uuid", "p_expected_row_version" bigint, "p_title" "text", "p_description" "text") RETURNS TABLE("config_id" "uuid", "title" "text", "description" "text", "status" "text", "current_version_id" "uuid", "row_version" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_principal record;
  v_config public.platform_configs;
begin
  if (p_ctx).request_id is null or p_config_id is null or p_expected_row_version is null
     or p_expected_row_version < 1 or p_title is null or length(btrim(p_title)) not between 1 and 120
     or p_title ~ '[[:cntrl:]]' or p_description is not null and length(p_description) > 2000 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization <> 'allowed' then
    raise exception using errcode = '42501', message = v_principal.authorization;
  end if;
  update public.platform_configs c
  set title = btrim(p_title), description = nullif(btrim(p_description), ''),
      row_version = c.row_version + 1
  where c.platform_id = (p_ctx).platform_id
    and c.platform_account_id = v_principal.platform_account_id
    and c.id = p_config_id and c.status = 'active'
    and c.row_version = p_expected_row_version
  returning * into v_config;
  if not found then
    if exists (select 1 from public.platform_configs c where c.platform_id = (p_ctx).platform_id
      and c.platform_account_id = v_principal.platform_account_id and c.id = p_config_id and c.status = 'active') then
      raise exception using errcode = '40001', message = 'precondition_failed';
    end if;
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  perform private.audit_append((p_ctx).request_id, 'user', (p_ctx).user_id,
    v_config.platform_id, v_config.platform_account_id, 'config.updated',
    'platform_config', v_config.id, null, null,
    jsonb_build_object('row_version', v_config.row_version));
  return query select v_config.id, v_config.title, v_config.description, v_config.status,
    v_config.current_version_id, v_config.row_version, v_config.created_at, v_config.updated_at;
end;
$$;


ALTER FUNCTION "private"."config_patch"("p_ctx" "private"."account_context", "p_config_id" "uuid", "p_expected_row_version" bigint, "p_title" "text", "p_description" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_rate_limit_require"("p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_action" "text", "p_window_seconds" integer, "p_limit_count" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
  v_window timestamptz;
  v_key bytea;
  v_result record;
begin
  if p_platform_id is null or p_platform_account_id is null
     or p_action is null or length(p_action) not between 1 and 64
     or p_window_seconds not between 60 and 86400 or p_limit_count not between 1 and 10000 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  v_window := to_timestamp(floor(extract(epoch from v_now) / p_window_seconds) * p_window_seconds);
  v_key := extensions.digest(convert_to(
    p_platform_id::text || ':' || p_platform_account_id::text || ':' || p_action,
    'utf8'), 'sha256');
  select * into v_result from private.rate_limit_consume(
    v_key, v_window, p_window_seconds, p_limit_count);
  if not coalesce(v_result.allowed, false) then
    raise exception using errcode = 'P0001', message = 'rate_limited',
      detail = v_result.retry_at::text;
  end if;
end;
$$;


ALTER FUNCTION "private"."config_rate_limit_require"("p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_action" "text", "p_window_seconds" integer, "p_limit_count" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_read"("p_ctx" "private"."account_context", "p_config_id" "uuid") RETURNS TABLE("config_id" "uuid", "title" "text", "description" "text", "status" "text", "current_version_id" "uuid", "row_version" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_principal record;
begin
  if (p_ctx).request_id is null or p_config_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization not in ('allowed', 'suspended') then
    raise exception using errcode = '42501', message = v_principal.authorization;
  end if;
  return query select c.id, c.title, c.description, c.status, c.current_version_id,
    c.row_version, c.created_at, c.updated_at
  from public.platform_configs c
  where c.platform_id = (p_ctx).platform_id
    and c.platform_account_id = v_principal.platform_account_id
    and c.id = p_config_id and c.status <> 'deleted';
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
end;
$$;


ALTER FUNCTION "private"."config_read"("p_ctx" "private"."account_context", "p_config_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_slot_limit"("p_ctx" "private"."account_context") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $_$
declare
  v_entitlement record;
  v_text text;
  v_limit integer;
begin
  select * into v_entitlement from private.entitlement_current_read(p_ctx);
  if not found or v_entitlement.effective_status <> 'active'
     or v_entitlement.features is null
     or jsonb_typeof(v_entitlement.features->'config_slot_limit') <> 'number' then
    return 0;
  end if;
  v_text := v_entitlement.features->>'config_slot_limit';
  if v_text !~ '^[0-9]+$' or length(v_text) > 4 then return 0; end if;
  v_limit := v_text::integer;
  if v_limit not between 0 and 1000 then return 0; end if;
  return v_limit;
end;
$_$;


ALTER FUNCTION "private"."config_slot_limit"("p_ctx" "private"."account_context") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_storage_prepare_store"("p_ctx" "private"."account_context", "p_file_id" "uuid", "p_resource_kind" "text", "p_actual_size_bytes" bigint, "p_sha256" "text", "p_idempotency_key" "text", "p_operation" "text") RETURNS TABLE("file_id" "uuid", "status" "text", "write_outcome" "text", "reserved_bytes" bigint, "reserved_count" integer, "actual_size_bytes" bigint, "sha256" "text", "storage_path" "text", "write_attempt_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public', 'extensions'
    AS $_$
declare
  v_authorization text;
  v_account_id uuid;
  v_account public.platform_accounts;
  v_file public.platform_config_files;
  v_policy public.platform_file_policies;
  v_attempt private.file_write_attempts;
  v_claim private.idempotency_keys%rowtype;
  v_new_claim boolean := false;
  v_hash bytea;
  v_response jsonb;
begin
  if p_file_id is null or p_resource_kind <> 'config_version'
     or p_actual_size_bytes not between 1 and 1048576
     or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$'
     or p_idempotency_key is null or length(p_idempotency_key) not between 1 and 128
     or p_operation <> 'config_version_prepare_store' then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select principal.authorization, principal.platform_account_id
    into v_authorization, v_account_id
  from private.account_principal(p_ctx) principal;
  if v_authorization <> 'allowed' then
    raise exception using errcode = '42501', message = v_authorization;
  end if;
  select * into v_account from public.platform_accounts a
  where a.platform_id = (p_ctx).platform_id and a.id = v_account_id for update;
  select * into v_file from public.platform_config_files f
  where f.platform_id = (p_ctx).platform_id
    and f.platform_account_id = v_account_id and f.id = p_file_id
    and f.resource_kind = 'config_version' for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  v_hash := extensions.digest(convert_to(
    p_file_id::text || ':' || p_actual_size_bytes::text || ':' || p_sha256,
    'utf8'), 'sha256');
  insert into private.idempotency_keys (
    platform_id, platform_account_id, operation, actor_scope, idempotency_key, request_hash
  ) values (
    (p_ctx).platform_id, v_account_id, 'config_version_prepare_store',
    'user:' || (p_ctx).user_id::text, p_idempotency_key, v_hash
  ) on conflict (platform_id, platform_account_id, operation, actor_scope, idempotency_key)
    do nothing returning true into v_new_claim;
  if not coalesce(v_new_claim, false) then
    select * into v_claim from private.idempotency_keys i
    where i.platform_id = (p_ctx).platform_id and i.platform_account_id = v_account_id
      and i.operation = 'config_version_prepare_store'
      and i.actor_scope = 'user:' || (p_ctx).user_id::text
      and i.idempotency_key = p_idempotency_key for update;
    if v_claim.request_hash <> v_hash then
      raise exception using errcode = '23505', message = 'idempotency_conflict';
    end if;
    if v_claim.state = 'completed' then
      return query select (v_claim.response_body->>'file_id')::uuid,
        v_claim.response_body->>'status', v_claim.response_body->>'write_outcome',
        (v_claim.response_body->>'reserved_bytes')::bigint,
        (v_claim.response_body->>'reserved_count')::integer,
        (v_claim.response_body->>'actual_size_bytes')::bigint,
        v_claim.response_body->>'sha256', v_claim.response_body->>'storage_path',
        (v_claim.response_body->>'write_attempt_id')::uuid;
      return;
    end if;
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;
  if v_file.status <> 'receiving' or v_file.lease_until is null
     or v_file.lease_until <= clock_timestamp() then
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;
  if p_actual_size_bytes > v_file.requested_size_bytes then
    raise exception using errcode = '22023', message = 'size_mismatch';
  end if;
  select * into v_policy from public.platform_file_policies p
  where p.platform_id = (p_ctx).platform_id for update;
  if not found or not v_policy.enabled or p_actual_size_bytes > v_policy.max_file_bytes then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  insert into private.file_write_attempts (
    platform_id, platform_account_id, file_id, fencing_token,
    state, actual_size_bytes, sha256
  ) values (
    (p_ctx).platform_id, v_account_id, v_file.id, v_file.fencing_token,
    'in_flight', p_actual_size_bytes, p_sha256
  ) returning * into v_attempt;
  update public.platform_config_files f
  set status = 'storing', write_outcome = 'in_flight',
      actual_size_bytes = p_actual_size_bytes, sha256 = p_sha256,
      reserved_bytes = p_actual_size_bytes, lease_until = null, lease_owner = null
  where f.id = v_file.id;
  perform private.audit_append(
    (p_ctx).request_id, 'user', (p_ctx).user_id, (p_ctx).platform_id, v_account_id,
    'file.store_prepared', 'platform_config_file', v_file.id, null, null,
    jsonb_build_object('actual_size_bytes', p_actual_size_bytes,
      'write_attempt_id', v_attempt.id)
  );
  v_response := jsonb_build_object(
    'file_id', v_file.id, 'status', 'storing', 'write_outcome', 'in_flight',
    'reserved_bytes', p_actual_size_bytes, 'reserved_count', v_file.reserved_count,
    'actual_size_bytes', p_actual_size_bytes, 'sha256', p_sha256,
    'storage_path', v_file.storage_path, 'write_attempt_id', v_attempt.id
  );
  perform private.idempotency_finalize(
    (p_ctx).platform_id, v_account_id, 'config_version_prepare_store',
    'user:' || (p_ctx).user_id::text, p_idempotency_key, v_hash, 200, v_response
  );
  return query select v_file.id, 'storing'::text, 'in_flight'::text,
    p_actual_size_bytes, v_file.reserved_count, p_actual_size_bytes,
    p_sha256, v_file.storage_path, v_attempt.id;
end;
$_$;


ALTER FUNCTION "private"."config_storage_prepare_store"("p_ctx" "private"."account_context", "p_file_id" "uuid", "p_resource_kind" "text", "p_actual_size_bytes" bigint, "p_sha256" "text", "p_idempotency_key" "text", "p_operation" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_storage_receive_claim"("p_ctx" "private"."account_context", "p_file_id" "uuid", "p_resource_kind" "text", "p_lease_owner" "text", "p_lease_seconds" integer DEFAULT 15) RETURNS TABLE("file_id" "uuid", "platform_account_id" "uuid", "status" "text", "write_outcome" "text", "requested_size_bytes" bigint, "max_file_bytes" bigint, "reserved_bytes" bigint, "reserved_count" integer, "lease_until" timestamp with time zone, "fencing_token" bigint, "storage_path" "text", "mime_type" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_authorization text;
  v_account_id uuid;
  v_account public.platform_accounts;
  v_file public.platform_config_files;
  v_policy public.platform_file_policies;
  v_now timestamptz := clock_timestamp();
begin
  if (p_ctx).request_id is null or p_file_id is null
     or p_resource_kind <> 'config_version'
     or p_lease_owner is null or length(p_lease_owner) not between 1 and 128
     or p_lease_seconds not between 1 and 15 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select principal.authorization, principal.platform_account_id
    into v_authorization, v_account_id
  from private.account_principal(p_ctx) principal;
  if v_authorization <> 'allowed' then
    raise exception using errcode = '42501', message = v_authorization;
  end if;
  select * into v_account from public.platform_accounts a
  where a.platform_id = (p_ctx).platform_id and a.id = v_account_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  select * into v_policy from public.platform_file_policies p
  where p.platform_id = (p_ctx).platform_id for update;
  select * into v_file from public.platform_config_files f
  where f.platform_id = (p_ctx).platform_id
    and f.platform_account_id = v_account_id and f.id = p_file_id
    and f.resource_kind = 'config_version' for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_file.status <> 'pending' then
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;
  if v_file.intent_expires_at <= v_now then
    raise exception using errcode = 'P0001', message = 'intent_expired';
  end if;
  if v_file.lease_until is not null and v_file.lease_until > v_now then
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;
  update public.platform_config_files f
  set status = 'receiving', lease_owner = p_lease_owner,
      lease_until = v_now + make_interval(secs => p_lease_seconds),
      fencing_token = f.fencing_token + 1
  where f.id = v_file.id
  returning f.id, f.platform_account_id, f.status, f.write_outcome,
    f.requested_size_bytes, v_policy.max_file_bytes, f.reserved_bytes,
    f.reserved_count, f.lease_until, f.fencing_token, f.storage_path, f.mime_type
  into file_id, platform_account_id, status, write_outcome,
    requested_size_bytes, max_file_bytes, reserved_bytes, reserved_count,
    lease_until, fencing_token, storage_path, mime_type;
  perform private.audit_append(
    (p_ctx).request_id, 'user', (p_ctx).user_id, (p_ctx).platform_id, v_account_id,
    'file.receive_claimed', 'platform_config_file', p_file_id, null, null,
    jsonb_build_object('fencing_token', fencing_token)
  );
  return next;
end;
$$;


ALTER FUNCTION "private"."config_storage_receive_claim"("p_ctx" "private"."account_context", "p_file_id" "uuid", "p_resource_kind" "text", "p_lease_owner" "text", "p_lease_seconds" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."config_storage_upload_state"("p_ctx" "private"."account_context", "p_file_id" "uuid", "p_resource_kind" "text") RETURNS TABLE("file_id" "uuid", "platform_account_id" "uuid", "original_name" "text", "mime_type" "text", "requested_size_bytes" bigint, "actual_size_bytes" bigint, "sha256" "text", "status" "text", "write_outcome" "text", "storage_bucket" "text", "storage_path" "text", "intent_expires_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_principal record;
begin
  if (p_ctx).request_id is null or p_file_id is null
     or p_resource_kind <> 'config_version' then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization <> 'allowed' then
    raise exception using errcode = '42501', message = v_principal.authorization;
  end if;
  return query
    select f.id, f.platform_account_id, f.original_name, f.mime_type,
      f.requested_size_bytes, f.actual_size_bytes, f.sha256, f.status,
      f.write_outcome, f.storage_bucket, f.storage_path, f.intent_expires_at,
      f.created_at, f.updated_at
    from public.platform_config_files f
    where f.platform_id = (p_ctx).platform_id
      and f.platform_account_id = v_principal.platform_account_id
      and f.id = p_file_id and f.resource_kind = 'config_version';
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
end;
