CREATE OR REPLACE FUNCTION "private"."deletion_job_backup_barrier_guard"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_lease_fence" bigint) RETURNS TABLE("can_proceed" boolean, "error_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_job private.deletion_jobs;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null or p_job_id is null
     or p_lease_fence is null or p_lease_fence < 1 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (
    select 1 from private.job_leases l
    where l.job_kind = 'global_delete' and l.resource_id = p_job_id
      and l.lease_owner = (p_ctx).lease_owner and l.fencing_token = p_lease_fence
  ) then
    raise exception using errcode = '40001', message = 'stale_job_fence';
  end if;
  select * into v_job from private.deletion_jobs j where j.id = p_job_id;
  if not found or v_job.state <> 'running' or v_job.checkpoint <> 'accounts_closed'
     or v_job.fence <> (p_ctx).fencing_token then
    raise exception using errcode = '40001', message = 'stale_job_fence';
  end if;
  if exists (select 1 from private.file_backup_barriers b where b.state in ('active', 'running')) then
    return query select false, 'backup_barrier'::text;
    return;
  end if;
  return query select true, null::text;
end;
$$;


ALTER FUNCTION "private"."deletion_job_backup_barrier_guard"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_lease_fence" bigint) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."deletion_job_claim"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_lease_seconds" integer DEFAULT 60) RETURNS TABLE("job_id" "uuid", "user_id" "uuid", "checkpoint" "text", "fence" bigint, "lease_fence" bigint, "lease_until" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_job private.deletion_jobs;
  v_claim record;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).request_id is null
     or p_job_id is null or p_lease_seconds not between 1 and 3600 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_claim from private.job_lease_claim('global_delete', p_job_id, (p_ctx).lease_owner, p_lease_seconds);
  if not coalesce(v_claim.claimed, false) then return; end if;
  select * into v_job from private.deletion_jobs j where j.id = p_job_id for update;
  if not found then
    perform private.job_lease_release('global_delete', p_job_id, (p_ctx).lease_owner, v_claim.fencing_token);
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if v_job.state not in ('pending', 'retry') or v_job.next_attempt_at > clock_timestamp() then
    perform private.job_lease_release('global_delete', p_job_id, (p_ctx).lease_owner, v_claim.fencing_token);
    return query select v_job.id, v_job.user_id, v_job.checkpoint, v_job.fence,
      v_claim.fencing_token, v_claim.lease_until;
    return;
  end if;
  update private.deletion_jobs j set state = 'running', fence = j.fence + 1 where j.id = v_job.id returning * into v_job;
  return query select v_job.id, v_job.user_id, v_job.checkpoint, v_job.fence,
    v_claim.fencing_token, v_claim.lease_until;
end;
$$;


