    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_job private.deletion_jobs;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).request_id is null
     or p_job_id is null or p_lease_fence is null or p_lease_fence < 1 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if not exists (
    select 1 from private.job_leases l
    where l.job_kind = 'global_delete' and l.resource_id = p_job_id
      and l.lease_owner = (p_ctx).lease_owner and l.fencing_token = p_lease_fence
  ) then
    raise exception using errcode = '40001', message = 'stale_job_fence';
  end if;
  select * into v_job from private.deletion_jobs j where j.id = p_job_id;
  if not found or v_job.state <> 'running' or v_job.checkpoint <> 'files_blocked'
     or v_job.fence <> (p_ctx).fencing_token then
    raise exception using errcode = '40001', message = 'stale_job_fence';
  end if;
  return query
    select f.id, f.storage_bucket, f.storage_path, f.status, f.write_outcome
    from public.platform_config_files f
    join public.platform_accounts a on a.id = f.platform_account_id
    where a.user_id = v_job.user_id and f.status <> 'deleted'
    order by f.id;
end;
$$;


ALTER FUNCTION "private"."deletion_job_file_list"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_lease_fence" bigint) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."deletion_job_step"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_lease_fence" bigint, "p_step" "text", "p_outcome" "text", "p_error_code" "text" DEFAULT NULL::"text") RETURNS TABLE("job_id" "uuid", "state" "text", "checkpoint" "text", "retry_count" integer, "next_attempt_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_job private.deletion_jobs;
  v_lease private.job_leases;
  v_next text;
  v_now timestamptz := clock_timestamp();
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).request_id is null
     or p_job_id is null or p_lease_fence is null or p_lease_fence < 1
     or p_step not in ('sessions_revoked', 'accounts_closed', 'files_blocked', 'personal_data_cleared', 'history_anonymized', 'auth_deleted')
     or p_outcome not in ('completed', 'retry', 'blocked')
     or p_outcome in ('retry', 'blocked') and (p_error_code is null or length(p_error_code) not between 1 and 128) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_lease from private.job_leases l
  where l.job_kind = 'global_delete' and l.resource_id = p_job_id
    and l.lease_owner = (p_ctx).lease_owner and l.fencing_token = p_lease_fence for update;
  if not found then raise exception using errcode = '40001', message = 'stale_job_fence'; end if;
  select * into v_job from private.deletion_jobs j where j.id = p_job_id for update;
  if not found or v_job.state <> 'running' or v_job.fence <> (p_ctx).fencing_token then
    raise exception using errcode = '40001', message = 'stale_job_fence';
  end if;
  v_next := case v_job.checkpoint
    when 'created' then 'sessions_revoked'
    when 'sessions_revoked' then 'accounts_closed'
    when 'accounts_closed' then 'files_blocked'
    when 'files_blocked' then 'personal_data_cleared'
    when 'personal_data_cleared' then 'history_anonymized'
    when 'history_anonymized' then 'auth_deleted'
    else null end;
  if p_step <> v_next then raise exception using errcode = 'P0001', message = 'invalid_delete_checkpoint'; end if;
  if p_outcome = 'completed' then
    if p_step = 'accounts_closed' then
      update public.platform_accounts set status = 'closed', closed_at = coalesce(closed_at, v_now)
      where user_id = v_job.user_id and status <> 'closed';
    elsif p_step = 'files_blocked' then
      perform private.config_account_privacy_cleanup(a.id, v_now, 'global_delete')
      from public.platform_accounts a where a.user_id = v_job.user_id;
      perform private.feedback_account_privacy_cleanup(a.id, v_now, 'global_delete')
      from public.platform_accounts a where a.user_id = v_job.user_id;
      perform private.account_admin_support_privacy_cleanup(a.id, v_now)
      from public.platform_accounts a where a.user_id = v_job.user_id;
      update public.platform_config_files f
      set status = case when f.status = 'deleted' then 'deleted' else 'deleting' end,
          cancel_requested_at = coalesce(f.cancel_requested_at, v_now),
          delete_requested_at = coalesce(f.delete_requested_at, v_now), next_attempt_at = v_now
      from public.platform_accounts a
      where a.id = f.platform_account_id and a.user_id = v_job.user_id and f.status <> 'deleted';
    elsif p_step = 'personal_data_cleared' then
      update public.platform_profiles profile set display_name = null, avatar_url = null,
        bio = null, locale = null, timezone = null, metadata = '{}'::jsonb
      from public.platform_accounts a
      where a.id = profile.platform_account_id and a.user_id = v_job.user_id;
      update public.platform_preferences prefs set preferences = '{}'::jsonb
      from public.platform_accounts a
      where a.id = prefs.platform_account_id and a.user_id = v_job.user_id;
    elsif p_step = 'history_anonymized' then
      update public.audit_logs set actor_user_id = null, ip = null, user_agent = null, metadata = '{}'::jsonb
      where actor_user_id = v_job.user_id;
    elsif p_step = 'auth_deleted' then
      update public.platform_accounts set user_id = null, anonymized_at = coalesce(anonymized_at, v_now),
        status = 'closed', closed_at = coalesce(closed_at, v_now)
      where user_id = v_job.user_id;
      delete from private.identity_lifecycle where user_id = v_job.user_id;
    end if;
    update private.deletion_jobs j set checkpoint = p_step,
      state = case when p_step = 'auth_deleted' then 'completed' else 'retry' end,
      next_attempt_at = case when p_step = 'auth_deleted' then j.next_attempt_at else v_now end,
      completed_at = case when p_step = 'auth_deleted' then v_now else null end,
      last_error_code = null where j.id = v_job.id returning * into v_job;
  else
    update private.deletion_jobs j set state = p_outcome, retry_count = j.retry_count + 1,
      next_attempt_at = v_now + make_interval(secs => least(3600, 60 * (2 ^ least(j.retry_count, 6)))),
      last_error_code = p_error_code where j.id = v_job.id returning * into v_job;
  end if;
  perform private.job_lease_release('global_delete', p_job_id, (p_ctx).lease_owner, p_lease_fence);
  return query select v_job.id, v_job.state, v_job.checkpoint, v_job.retry_count, v_job.next_attempt_at;
end;
$$;


ALTER FUNCTION "private"."deletion_job_step"("p_ctx" "private"."job_context", "p_job_id" "uuid", "p_lease_fence" bigint, "p_step" "text", "p_outcome" "text", "p_error_code" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."entitlement_apply"("p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_plan_id" "uuid", "p_source" "text", "p_operation_id" "uuid", "p_duration_value" integer, "p_duration_unit" "text", "p_actor_user_id" "uuid", "p_reason" "text", "p_redemption_code_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("grant_id" "uuid", "plan_id" "uuid", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone, "event_sequence" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_user_id uuid;
  v_lifecycle private.identity_lifecycle;
  v_platform public.platforms;
  v_account public.platform_accounts;
  v_plan public.plans;
  v_existing public.subscription_grants;
  v_now timestamptz := clock_timestamp();
  v_start timestamptz;
  v_end timestamptz;
  v_sequence bigint;
begin
  if p_source not in ('admin', 'redemption_code', 'billing_order')
     or p_operation_id is null or p_plan_id is null
     or p_reason is null or length(p_reason) not between 1 and 1024
     or (p_source = 'redemption_code' and (p_duration_value is null or p_duration_unit is null or p_redemption_code_id is null))
     or (p_source = 'billing_order' and p_redemption_code_id is not null)
     or (p_duration_value is not null and (p_duration_value <= 0 or p_duration_unit not in ('day', 'month', 'year'))) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_existing from public.subscription_grants g
  where g.platform_id = p_platform_id and g.source = p_source and g.operation_id = p_operation_id;
  if found then
    return query select v_existing.id, v_existing.plan_id, v_existing.starts_at, v_existing.ends_at,
      (select e.sequence from public.subscription_events e where e.grant_id = v_existing.id and e.event_type = 'granted');
    return;
  end if;

  -- Read the account owner before acquiring locks, then establish the
  -- identity barrier before platform and account locks.  Delete start uses an
  -- UPDATE/UPSERT on this same row, so the two operations are linearizable.
  select a.user_id into v_user_id from public.platform_accounts a
  where a.platform_id = p_platform_id and a.id = p_platform_account_id;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_user_id is not null then
    insert into private.identity_lifecycle (user_id, state)
    values (v_user_id, 'active')
    on conflict (user_id) do nothing;
    select * into v_lifecycle from private.identity_lifecycle l
    where l.user_id = v_user_id for share;
    if v_lifecycle.state = 'deleting' then
      raise exception using errcode = '42501', message = 'global_delete_pending';
    end if;
  end if;

  select * into v_platform from public.platforms p
  where p.id = p_platform_id for share;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_platform.status <> 'active' then raise exception using errcode = '42501', message = 'platform_disabled'; end if;

  select * into v_account from public.platform_accounts a
  where a.platform_id = p_platform_id and a.id = p_platform_account_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_account.status <> 'active' then raise exception using errcode = '42501', message = 'account_not_active'; end if;
  select * into v_plan from public.plans p where p.platform_id = p_platform_id and p.id = p_plan_id;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_plan.status <> 'active' or v_plan.kind <> 'paid' then raise exception using errcode = 'P0001', message = 'plan_unavailable'; end if;

  if exists (
    select 1 from public.subscription_grants g
    where g.platform_id = p_platform_id and g.platform_account_id = p_platform_account_id
      and g.plan_id <> p_plan_id and (g.ends_at is null or g.ends_at > v_now)
      and not exists (select 1 from public.subscription_events r where r.grant_id = g.id and r.event_type = 'revoked')
  ) then raise exception using errcode = 'P0001', message = 'plan_conflict'; end if;
  if exists (
    select 1 from public.subscription_grants g
    where g.platform_id = p_platform_id and g.platform_account_id = p_platform_account_id
      and g.plan_id = p_plan_id and g.ends_at is null
      and not exists (select 1 from public.subscription_events r where r.grant_id = g.id and r.event_type = 'revoked')
  ) then raise exception using errcode = 'P0001', message = 'entitlement_perpetual'; end if;
  if p_source = 'admin' and p_duration_value is null and exists (
    select 1 from public.subscription_grants g
    where g.platform_id = p_platform_id and g.platform_account_id = p_platform_account_id
      and (g.ends_at is null or g.ends_at > v_now)
      and not exists (select 1 from public.subscription_events r where r.grant_id = g.id and r.event_type = 'revoked')
  ) then raise exception using errcode = 'P0001', message = 'plan_conflict'; end if;

  select greatest(v_now, coalesce(max(g.ends_at), v_now)) into v_start
  from public.subscription_grants g
  where g.platform_id = p_platform_id and g.platform_account_id = p_platform_account_id
    and g.plan_id = p_plan_id and g.ends_at is not null and g.ends_at > v_now
    and not exists (select 1 from public.subscription_events r where r.grant_id = g.id and r.event_type = 'revoked');
  if p_duration_value is null then v_end := null;
  elsif p_duration_unit = 'day' then v_end := v_start + make_interval(days => p_duration_value);
  elsif p_duration_unit = 'month' then v_end := v_start + make_interval(months => p_duration_value);
  else v_end := v_start + make_interval(years => p_duration_value);
  end if;

  insert into public.subscription_grants (
    platform_id, platform_account_id, plan_id, source, operation_id,
    redemption_code_id, billing_order_id, starts_at, ends_at, created_by, reason
  ) values (
    p_platform_id, p_platform_account_id, p_plan_id, p_source, p_operation_id,
    p_redemption_code_id,
    case when p_source = 'billing_order' then p_operation_id else null end,
    v_start, v_end, p_actor_user_id, p_reason
  ) returning id into grant_id;

  select coalesce(max(e.sequence), 0) + 1 into v_sequence
  from public.subscription_events e
  where e.platform_id = p_platform_id and e.platform_account_id = p_platform_account_id;
  insert into public.subscription_events (
    platform_id, platform_account_id, sequence, event_type, grant_id,
    operation_id, actor_user_id, reason
  ) values (
    p_platform_id, p_platform_account_id, v_sequence, 'granted', grant_id,
    p_operation_id, p_actor_user_id, p_reason
  );
  perform private.entitlement_recompute(p_platform_id, p_platform_account_id);
  perform private.audit_append(p_operation_id, case when p_source = 'admin' then 'admin' else 'system' end,
    p_actor_user_id, p_platform_id, p_platform_account_id, 'entitlement.granted',
    'subscription_grant', grant_id, null, null,
    jsonb_build_object('plan_id', p_plan_id, 'source', p_source));
  return query select grant_id, p_plan_id, v_start, v_end, v_sequence;
end;
$$;


ALTER FUNCTION "private"."entitlement_apply"("p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_plan_id" "uuid", "p_source" "text", "p_operation_id" "uuid", "p_duration_value" integer, "p_duration_unit" "text", "p_actor_user_id" "uuid", "p_reason" "text", "p_redemption_code_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."entitlement_calendar_end"("p_start" timestamp with time zone, "p_duration_value" integer, "p_duration_unit" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_start_utc timestamp;
  v_target_month timestamp;
  v_day integer;
  v_last_day integer;
begin
  if p_duration_value <= 0 or p_duration_unit not in ('day', 'month', 'year') then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  if p_duration_unit = 'day' then
    return p_start + make_interval(days => p_duration_value);
  end if;

  v_start_utc := p_start at time zone 'UTC';
  v_target_month := date_trunc('month', v_start_utc) + case
    when p_duration_unit = 'month' then make_interval(months => p_duration_value)
    else make_interval(years => p_duration_value)
  end;
  v_day := extract(day from v_start_utc)::integer;
  v_last_day := extract(
    day from (v_target_month + interval '1 month - 1 day')
  )::integer;
  return (
    v_target_month
    + make_interval(days => least(v_day, v_last_day) - 1)
    + (v_start_utc - date_trunc('day', v_start_utc))
  ) at time zone 'UTC';
end;
$$;


ALTER FUNCTION "private"."entitlement_calendar_end"("p_start" timestamp with time zone, "p_duration_value" integer, "p_duration_unit" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."entitlement_current_read"("p_ctx" "private"."account_context") RETURNS TABLE("effective_status" "text", "entitlement_kind" "text", "plan_id" "uuid", "code" "text", "name" "text", "description" "text", "features" "jsonb", "offer_code" "text", "offer_name" "text", "started_at" timestamp with time zone, "current_period_end" timestamp with time zone, "next_transition_at" timestamp with time zone, "evaluated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_authorization text;
  v_account_id uuid;
  v_sub public.subscriptions;
  v_plan public.plans;
  v_default public.plans;
  v_offer_code text;
  v_offer_name text;
  v_now timestamptz := clock_timestamp();
begin
  select principal.authorization, principal.platform_account_id
    into v_authorization, v_account_id
  from private.account_principal(p_ctx) principal;
  if v_authorization <> 'allowed' then
    raise exception using errcode = '42501', message = v_authorization;
  end if;

  perform private.entitlement_recompute((p_ctx).platform_id, v_account_id);
  select * into v_sub
  from public.subscriptions s
  where s.platform_account_id = v_account_id;

  if v_sub.status = 'suspended' then
    return query select
      'suspended'::text, 'none'::text, null::uuid, null::text, null::text,
      null::text, '{}'::jsonb, null::text, null::text, null::timestamptz,
      null::timestamptz, v_sub.next_transition_at, v_now;
    return;
  end if;

  if v_sub.plan_id is not null then
    select * into v_plan
    from public.plans p
    where p.platform_id = (p_ctx).platform_id and p.id = v_sub.plan_id;

    select coalesce(ci.offer_code_snapshot, offer.code), offer.name
      into v_offer_code, v_offer_name
    from public.subscription_grants g
    left join public.billing_orders bo on bo.id = g.billing_order_id
    left join public.billing_checkout_intents ci on ci.id = bo.checkout_intent_id
    left join public.redemption_codes rc on rc.id = g.redemption_code_id
    left join public.redemption_code_batches batch
      on batch.platform_id = rc.platform_id and batch.id = rc.batch_id
    left join public.platform_commercial_offers offer
      on offer.platform_id = g.platform_id
     and offer.id = coalesce(ci.commercial_offer_id, batch.commercial_offer_id)
    where g.platform_id = (p_ctx).platform_id
      and g.platform_account_id = v_account_id
      and g.starts_at <= v_now
      and (g.ends_at is null or g.ends_at > v_now)
      and not exists (
        select 1 from public.subscription_events revoked
        where revoked.platform_id = g.platform_id
          and revoked.platform_account_id = g.platform_account_id
          and revoked.grant_id = g.id
          and revoked.event_type = 'revoked'
      )
    order by g.starts_at desc, g.created_at desc, g.id desc
    limit 1;

    return query select
      'active'::text,
      case when v_sub.current_period_end is null then 'perpetual' else 'term' end,
      v_plan.id, v_plan.code, v_plan.name, v_plan.description, v_plan.features,
      v_offer_code, v_offer_name, v_sub.started_at, v_sub.current_period_end,
      v_sub.next_transition_at, v_now;
    return;
  end if;

  select p.* into v_default
  from public.platforms platform
  join public.plans p
    on p.platform_id = platform.id and p.id = platform.default_plan_id
  where platform.id = (p_ctx).platform_id
    and p.status = 'active'
    and p.kind = 'free';
  if found then
    return query select
      'active'::text, 'free'::text, v_default.id, v_default.code,
      v_default.name, v_default.description, v_default.features,
      null::text, null::text, null::timestamptz, null::timestamptz,
      v_sub.next_transition_at, v_now;
  else
    return query select
      'none'::text, 'none'::text, null::uuid, null::text, null::text,
      null::text, '{}'::jsonb, null::text, null::text, null::timestamptz,
      null::timestamptz, v_sub.next_transition_at, v_now;
  end if;
end;
$$;


ALTER FUNCTION "private"."entitlement_current_read"("p_ctx" "private"."account_context") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."entitlement_recompute"("p_platform_id" "uuid", "p_platform_account_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
  v_status text := 'active';
  v_pause text;
  v_plan_id uuid;
  v_started_at timestamptz;
  v_period_end timestamptz;
  v_next_transition timestamptz;
  v_last_sequence bigint;
begin
  if not exists (
    select 1 from public.platform_accounts a
    where a.platform_id = p_platform_id and a.id = p_platform_account_id
  ) then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;

  select e.event_type into v_pause
  from public.subscription_events e
  where e.platform_id = p_platform_id and e.platform_account_id = p_platform_account_id
    and e.event_type in ('paused', 'resumed')
  order by e.sequence desc limit 1;
  if v_pause = 'paused' then v_status := 'suspended'; end if;

  select g.plan_id, g.starts_at, g.ends_at
    into v_plan_id, v_started_at, v_period_end
  from public.subscription_grants g
  where g.platform_id = p_platform_id and g.platform_account_id = p_platform_account_id
    and g.starts_at <= v_now
    and (g.ends_at is null or g.ends_at > v_now)
    and not exists (
      select 1 from public.subscription_events r
      where r.platform_id = g.platform_id and r.platform_account_id = g.platform_account_id
        and r.grant_id = g.id and r.event_type = 'revoked'
    )
  order by g.starts_at desc, g.created_at desc limit 1;

  if v_plan_id is not null and v_period_end is not null then
    select max(g.ends_at) into v_period_end
    from public.subscription_grants g
    where g.platform_id = p_platform_id and g.platform_account_id = p_platform_account_id
      and g.plan_id = v_plan_id and g.ends_at is not null and g.ends_at > v_now
      and not exists (
        select 1 from public.subscription_events r
        where r.platform_id = g.platform_id and r.platform_account_id = g.platform_account_id
          and r.grant_id = g.id and r.event_type = 'revoked'
      );
  end if;

  select min(g.starts_at) into v_next_transition
  from public.subscription_grants g
  where g.platform_id = p_platform_id and g.platform_account_id = p_platform_account_id
    and g.starts_at > v_now
    and not exists (
      select 1 from public.subscription_events r
      where r.platform_id = g.platform_id and r.platform_account_id = g.platform_account_id
        and r.grant_id = g.id and r.event_type = 'revoked'
    );
  if v_period_end is not null and (v_next_transition is null or v_period_end < v_next_transition) then
    v_next_transition := v_period_end;
  end if;

  select coalesce(max(e.sequence), 0) into v_last_sequence
  from public.subscription_events e
  where e.platform_id = p_platform_id and e.platform_account_id = p_platform_account_id;

  insert into public.subscriptions (
    platform_id, platform_account_id, plan_id, status, started_at,
    current_period_end, next_transition_at, last_event_sequence
  ) values (
    p_platform_id, p_platform_account_id, v_plan_id, v_status, v_started_at,
    v_period_end, v_next_transition, v_last_sequence
  ) on conflict (platform_account_id) do update set
    plan_id = excluded.plan_id,
    status = excluded.status,
    started_at = excluded.started_at,
    current_period_end = excluded.current_period_end,
    next_transition_at = excluded.next_transition_at,
    last_event_sequence = excluded.last_event_sequence;
end;
$$;


ALTER FUNCTION "private"."entitlement_recompute"("p_platform_id" "uuid", "p_platform_account_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_account_id"("p_ctx" "private"."account_context", "p_allow_suspended" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_principal record;
begin
  if (p_ctx).user_id is null or (p_ctx).session_id is null
     or (p_ctx).platform_id is null or (p_ctx).platform_key_id is null
     or (p_ctx).request_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_principal from private.account_principal(p_ctx);
  if v_principal.authorization <> 'allowed'
     and not (p_allow_suspended and v_principal.authorization = 'suspended') then
    raise exception using errcode = '42501', message = v_principal.authorization;
  end if;
  if v_principal.platform_account_id is null then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  return v_principal.platform_account_id;
end;
$$;


ALTER FUNCTION "private"."feedback_account_id"("p_ctx" "private"."account_context", "p_allow_suspended" boolean) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_account_privacy_cleanup"("p_platform_account_id" "uuid", "p_now" timestamp with time zone, "p_reason" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_feedback_id uuid;
  v_count integer := 0;
begin
  if p_platform_account_id is null or p_now is null or p_reason is null
     or length(p_reason) not between 1 and 128 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  for v_feedback_id in
    select f.id from public.platform_feedback f
    where f.platform_account_id = p_platform_account_id and f.status <> 'deleted'
    order by f.id for update
  loop
    perform private.feedback_privacy_delete(v_feedback_id, p_reason, p_now);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;


ALTER FUNCTION "private"."feedback_account_privacy_cleanup"("p_platform_account_id" "uuid", "p_now" timestamp with time zone, "p_reason" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_attachment_cancel"("p_ctx" "private"."account_context", "p_attachment_id" "uuid") RETURNS TABLE("attachment_id" "uuid", "status" "text", "write_outcome" "text", "deleted_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_account_id uuid;
  v_attachment public.platform_feedback_attachments;
  v_feedback public.platform_feedback;
  v_now timestamptz := clock_timestamp();
begin
  v_account_id := private.feedback_account_id(p_ctx, false);
  select * into v_attachment from public.platform_feedback_attachments a
  where a.id = p_attachment_id and a.platform_id = (p_ctx).platform_id
    and a.platform_account_id = v_account_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  select * into v_feedback from public.platform_feedback f where f.id = v_attachment.feedback_id for update;
  if v_feedback.status <> 'draft' then raise exception using errcode = 'P0001', message = 'feedback_not_editable'; end if;
  if v_attachment.status = 'deleted' then
    return query select v_attachment.id, v_attachment.status, v_attachment.write_outcome, v_attachment.deleted_at;
    return;
  end if;
  if v_attachment.status in ('pending', 'receiving') and v_attachment.write_outcome = 'not_started'
     and not exists (select 1 from private.feedback_attachment_write_attempts w where w.attachment_id = v_attachment.id)
     and (v_attachment.lease_until is null or v_attachment.lease_until <= v_now) then
    update public.platform_feedback_attachments set
      status = 'deleted', deleted_at = v_now, storage_path = null,
      original_name = '[deleted]', platform_account_id = null,
      cancel_requested_at = v_now, delete_requested_at = v_now
    where id = v_attachment.id returning * into v_attachment;
  elsif v_attachment.status not in ('deleting', 'deleted') then
    update public.platform_feedback_attachments set
      status = 'deleting', cancel_requested_at = coalesce(cancel_requested_at, v_now),
      delete_requested_at = coalesce(delete_requested_at, v_now),
      next_attempt_at = greatest(v_now, coalesce(lease_until, v_now))
    where id = v_attachment.id returning * into v_attachment;
  end if;
  return query select v_attachment.id, v_attachment.status, v_attachment.write_outcome, v_attachment.deleted_at;
end;
$$;


ALTER FUNCTION "private"."feedback_attachment_cancel"("p_ctx" "private"."account_context", "p_attachment_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_attachment_cleanup_candidates"("p_cursor_attachment_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("attachment_id" "uuid", "next_attempt_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if p_limit not between 1 and 100 then raise exception using errcode = '22023', message = 'invalid_input'; end if;
  return query select a.id, a.next_attempt_at
  from public.platform_feedback_attachments a
  where (p_cursor_attachment_id is null or a.id > p_cursor_attachment_id)
    and a.next_attempt_at <= clock_timestamp()
    and (
      a.status = 'deleting'
      or (a.status in ('pending', 'receiving') and a.write_outcome = 'not_started'
        and a.intent_expires_at <= clock_timestamp()
        and (a.lease_until is null or a.lease_until <= clock_timestamp()))
      or (a.status = 'storing' and a.write_outcome in ('in_flight', 'unknown'))
    )
  order by a.id limit p_limit;
end;
$$;


ALTER FUNCTION "private"."feedback_attachment_cleanup_candidates"("p_cursor_attachment_id" "uuid", "p_limit" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_attachment_cleanup_claim"("p_ctx" "private"."job_context", "p_attachment_id" "uuid", "p_lease_seconds" integer DEFAULT 60) RETURNS TABLE("attachment_id" "uuid", "action" "text", "status" "text", "write_outcome" "text", "storage_bucket" "text", "storage_path" "text", "fencing_token" bigint, "retry_count" integer, "next_attempt_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_claim record;
  v_attachment public.platform_feedback_attachments;
  v_action text;
  v_now timestamptz := clock_timestamp();
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or length((p_ctx).lease_owner) not between 1 and 128
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null or p_attachment_id is null
     or p_lease_seconds not between 1 and 3600 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_claim from private.job_lease_claim(
    'feedback_attachment_cleanup', p_attachment_id, (p_ctx).lease_owner, p_lease_seconds
  );
  if not coalesce(v_claim.claimed, false) then
    return query select p_attachment_id, 'busy'::text, null::text, null::text,
      null::text, null::text, v_claim.fencing_token, null::integer, v_claim.lease_until;
    return;
  end if;
  select * into v_attachment from public.platform_feedback_attachments a
  where a.id = p_attachment_id for update;
  if not found then
    perform private.job_lease_release('feedback_attachment_cleanup', p_attachment_id,
      (p_ctx).lease_owner, v_claim.fencing_token);
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  if exists (select 1 from private.file_backup_barriers b where b.state in ('active', 'running')) then
    v_action := 'backup_barrier';
  elsif v_attachment.status in ('pending', 'receiving')
    and v_attachment.write_outcome = 'not_started'
    and not exists (select 1 from private.feedback_attachment_write_attempts w where w.attachment_id = v_attachment.id)
    and v_attachment.intent_expires_at <= v_now
    and (v_attachment.lease_until is null or v_attachment.lease_until <= v_now) then
    update public.platform_feedback_attachments set
      status = 'expired', original_name = '[expired]', last_error_code = null
    where id = v_attachment.id returning * into v_attachment;
    v_action := 'no_storage';
  elsif v_attachment.status = 'deleting' and v_attachment.write_outcome = 'not_started'
    and not exists (select 1 from private.feedback_attachment_write_attempts w where w.attachment_id = v_attachment.id)
    and v_attachment.lease_until is not null and v_attachment.lease_until > v_now then
    v_action := 'receive_in_progress';
  elsif v_attachment.status = 'deleting' and v_attachment.write_outcome = 'not_started'
    and not exists (select 1 from private.feedback_attachment_write_attempts w where w.attachment_id = v_attachment.id) then
    update public.platform_feedback_attachments set
      status = 'deleted', deleted_at = v_now, storage_path = null,
      original_name = '[deleted]', platform_account_id = null, last_error_code = null
    where id = v_attachment.id returning * into v_attachment;
    v_action := 'no_storage';
  elsif v_attachment.status = 'deleting' and v_attachment.write_outcome = 'confirmed'
    and not exists (select 1 from private.feedback_attachment_write_attempts w
      where w.attachment_id = v_attachment.id and w.state in ('in_flight', 'unknown')) then
    v_action := 'remove';
  elsif v_attachment.status in ('storing', 'deleting')
    and v_attachment.write_outcome in ('in_flight', 'unknown') then
    v_action := 'settlement_required';
  else
    v_action := 'no_storage';
  end if;
  if v_action <> 'remove' then
    perform private.job_lease_release('feedback_attachment_cleanup', p_attachment_id,
      (p_ctx).lease_owner, v_claim.fencing_token);
  end if;
  return query select v_attachment.id, v_action, v_attachment.status,
    v_attachment.write_outcome, v_attachment.storage_bucket, v_attachment.storage_path,
    v_claim.fencing_token, v_attachment.retry_count, v_attachment.next_attempt_at;
end;
$$;


ALTER FUNCTION "private"."feedback_attachment_cleanup_claim"("p_ctx" "private"."job_context", "p_attachment_id" "uuid", "p_lease_seconds" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_attachment_cleanup_finish"("p_ctx" "private"."job_context", "p_attachment_id" "uuid", "p_fencing_token" bigint, "p_outcome" "text", "p_error_code" "text" DEFAULT NULL::"text") RETURNS TABLE("attachment_id" "uuid", "status" "text", "retry_count" integer, "next_attempt_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_attachment public.platform_feedback_attachments;
  v_lease private.job_leases;
  v_retry integer;
  v_next timestamptz;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null or (p_ctx).request_id is null
     or p_attachment_id is null or p_fencing_token is null or p_fencing_token < 1
     or p_outcome not in ('removed', 'not_found', 'failed', 'unknown')
     or p_outcome in ('failed', 'unknown') and (p_error_code is null or length(p_error_code) not between 1 and 128) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_lease from private.job_leases l
  where l.job_kind = 'feedback_attachment_cleanup' and l.resource_id = p_attachment_id
    and l.lease_owner = (p_ctx).lease_owner and l.fencing_token = p_fencing_token for update;
  if not found then raise exception using errcode = '40001', message = 'stale_job_fence'; end if;
  select * into v_attachment from public.platform_feedback_attachments a
  where a.id = p_attachment_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if p_outcome in ('removed', 'not_found') then
    if v_attachment.status <> 'deleting' or v_attachment.write_outcome <> 'confirmed'
       or exists (select 1 from private.feedback_attachment_write_attempts w
         where w.attachment_id = v_attachment.id and w.state in ('in_flight', 'unknown')) then
      raise exception using errcode = 'P0001', message = 'settlement_required';
    end if;
    update public.platform_feedback_attachments set
      status = 'deleted', deleted_at = clock_timestamp(), storage_path = null,
      original_name = '[deleted]', platform_account_id = null, last_error_code = null
    where id = v_attachment.id returning * into v_attachment;
  else
    v_retry := v_attachment.retry_count + 1;
    v_next := clock_timestamp() + make_interval(secs => least(3600, 60 * (2 ^ least(v_retry - 1, 6))));
    update public.platform_feedback_attachments set
      status = 'deleting', retry_count = v_retry, next_attempt_at = v_next,
      last_error_code = p_error_code
    where id = v_attachment.id returning * into v_attachment;
  end if;
  perform private.job_lease_release('feedback_attachment_cleanup', p_attachment_id,
    (p_ctx).lease_owner, p_fencing_token);
  return query select v_attachment.id, v_attachment.status, v_attachment.retry_count, v_attachment.next_attempt_at;
end;
$$;


ALTER FUNCTION "private"."feedback_attachment_cleanup_finish"("p_ctx" "private"."job_context", "p_attachment_id" "uuid", "p_fencing_token" bigint, "p_outcome" "text", "p_error_code" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_attachment_finalize"("p_ctx" "private"."account_context", "p_attachment_id" "uuid", "p_attempt_id" "uuid", "p_actual_size_bytes" bigint, "p_sha256" "text", "p_provider_request_id" "text" DEFAULT NULL::"text") RETURNS TABLE("attachment_id" "uuid", "status" "text", "write_outcome" "text", "uploaded_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $_$
declare
  v_account_id uuid;
  v_attachment public.platform_feedback_attachments;
  v_attempt private.feedback_attachment_write_attempts;
  v_now timestamptz := clock_timestamp();
begin
  if p_attachment_id is null or p_attempt_id is null
     or p_actual_size_bytes not between 1 and 4194304
     or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$'
     or p_provider_request_id is not null and length(p_provider_request_id) not between 1 and 256 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  v_account_id := private.feedback_account_id(p_ctx, true);
  select * into v_attachment from public.platform_feedback_attachments a
  where a.id = p_attachment_id and a.platform_id = (p_ctx).platform_id
    and a.platform_account_id = v_account_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  select * into v_attempt from private.feedback_attachment_write_attempts w
  where w.id = p_attempt_id and w.attachment_id = v_attachment.id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_attempt.state = 'confirmed' and v_attachment.status = 'active' then
    if v_attempt.actual_size_bytes <> p_actual_size_bytes or v_attempt.sha256 <> p_sha256 then
      raise exception using errcode = 'P0001', message = 'file_content_conflict';
    end if;
    return query select v_attachment.id, v_attachment.status, v_attachment.write_outcome, v_attachment.uploaded_at;
    return;
  end if;
  if v_attachment.status <> 'storing' or v_attachment.write_outcome not in ('in_flight', 'unknown')
     or v_attempt.state not in ('in_flight', 'unknown')
     or v_attempt.actual_size_bytes <> p_actual_size_bytes or v_attempt.sha256 <> p_sha256 then
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;
  update private.feedback_attachment_write_attempts set
    state = 'confirmed', settled_at = v_now, provider_request_id = p_provider_request_id,
    error_code = null
  where id = v_attempt.id;
  update public.platform_feedback_attachments set
    status = 'active', write_outcome = 'confirmed', uploaded_at = v_now,
    lease_owner = null, lease_until = null, last_error_code = null
  where id = v_attachment.id returning * into v_attachment;
  return query select v_attachment.id, v_attachment.status, v_attachment.write_outcome, v_attachment.uploaded_at;
end;
$_$;


ALTER FUNCTION "private"."feedback_attachment_finalize"("p_ctx" "private"."account_context", "p_attachment_id" "uuid", "p_attempt_id" "uuid", "p_actual_size_bytes" bigint, "p_sha256" "text", "p_provider_request_id" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_attachment_intent_create"("p_ctx" "private"."account_context", "p_feedback_id" "uuid", "p_original_name" "text", "p_requested_size_bytes" bigint, "p_mime_type" "text", "p_idempotency_key" "text") RETURNS TABLE("attachment_id" "uuid", "feedback_id" "uuid", "status" "text", "write_outcome" "text", "requested_size_bytes" bigint, "intent_expires_at" timestamp with time zone, "storage_path" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_account_id uuid;
  v_feedback public.platform_feedback;
  v_attachment public.platform_feedback_attachments;
  v_claim private.idempotency_keys%rowtype;
  v_new_claim boolean := false;
  v_hash bytea;
  v_response jsonb;
  v_live_count integer;
  v_live_bytes bigint;
  v_path text;
  v_now timestamptz := clock_timestamp();
begin
  if p_feedback_id is null or p_original_name is null
     or length(p_original_name) not between 1 and 255 or p_original_name ~ '[[:cntrl:]]'
     or p_requested_size_bytes is null or p_requested_size_bytes not between 1 and 4194304
     or p_mime_type not in ('image/jpeg', 'image/png', 'image/webp')
     or p_idempotency_key is null or length(p_idempotency_key) not between 1 and 128 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  v_account_id := private.feedback_account_id(p_ctx, false);
  perform 1 from public.platform_accounts a
    where a.platform_id = (p_ctx).platform_id and a.id = v_account_id for update;
  select * into v_feedback from public.platform_feedback f
  where f.id = p_feedback_id and f.platform_id = (p_ctx).platform_id
    and f.platform_account_id = v_account_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_feedback.status <> 'draft' then raise exception using errcode = 'P0001', message = 'feedback_not_editable'; end if;

  v_hash := extensions.digest(convert_to(
    p_feedback_id::text || ':' || p_original_name || ':' || p_requested_size_bytes::text || ':' || p_mime_type,
    'utf8'), 'sha256');
  insert into private.idempotency_keys (
    platform_id, platform_account_id, operation, actor_scope, idempotency_key, request_hash
  ) values (
    (p_ctx).platform_id, v_account_id, 'feedback_attachment_intent',
    'user:' || (p_ctx).user_id::text, p_idempotency_key, v_hash
  ) on conflict (platform_id, platform_account_id, operation, actor_scope, idempotency_key)
    do nothing returning true into v_new_claim;
  if not coalesce(v_new_claim, false) then
    select * into v_claim from private.idempotency_keys i
    where i.platform_id = (p_ctx).platform_id and i.platform_account_id = v_account_id
      and i.operation = 'feedback_attachment_intent'
      and i.actor_scope = 'user:' || (p_ctx).user_id::text
      and i.idempotency_key = p_idempotency_key for update;
    if v_claim.request_hash <> v_hash then raise exception using errcode = '23505', message = 'idempotency_conflict'; end if;
    if v_claim.state = 'completed' then
      return query select (v_claim.response_body->>'attachment_id')::uuid,
        (v_claim.response_body->>'feedback_id')::uuid, v_claim.response_body->>'status',
        v_claim.response_body->>'write_outcome',
        (v_claim.response_body->>'requested_size_bytes')::bigint,
        (v_claim.response_body->>'intent_expires_at')::timestamptz,
        v_claim.response_body->>'storage_path';
      return;
    end if;
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;

  select count(*)::integer, coalesce(sum(a.requested_size_bytes), 0)::bigint
    into v_live_count, v_live_bytes
  from public.platform_feedback_attachments a
  where a.feedback_id = v_feedback.id
    and a.status not in ('deleted', 'expired', 'failed');
  if v_live_count >= 5 then raise exception using errcode = 'P0001', message = 'feedback_attachment_limit_exceeded'; end if;
  if v_live_bytes + p_requested_size_bytes > 12582912 then
    raise exception using errcode = 'P0001', message = 'feedback_attachment_bytes_exceeded';
  end if;

  v_attachment.id := gen_random_uuid();
  v_path := (p_ctx).platform_id::text || '/' || v_account_id::text || '/'
    || v_feedback.id::text || '/' || v_attachment.id::text;
  insert into public.platform_feedback_attachments (
    id, feedback_id, platform_id, platform_account_id, original_name,
    storage_path, object_path_hash, mime_type, requested_size_bytes,
    intent_expires_at, next_attempt_at
  ) values (
    v_attachment.id, v_feedback.id, (p_ctx).platform_id, v_account_id,
    p_original_name, v_path,
    encode(extensions.digest(convert_to(v_path, 'utf8'), 'sha256'), 'hex'),
    p_mime_type, p_requested_size_bytes, v_now + interval '10 minutes', v_now
  ) returning * into v_attachment;
  perform private.audit_append(
    (p_ctx).request_id, 'user', (p_ctx).user_id, (p_ctx).platform_id, v_account_id,
    'feedback.attachment_intent_created', 'platform_feedback', v_feedback.id, null, null,
    jsonb_build_object('attachment_id', v_attachment.id,
      'requested_size_bytes', p_requested_size_bytes, 'mime_type', p_mime_type)
  );
  v_response := jsonb_build_object(
    'attachment_id', v_attachment.id, 'feedback_id', v_feedback.id,
    'status', v_attachment.status, 'write_outcome', v_attachment.write_outcome,
    'requested_size_bytes', v_attachment.requested_size_bytes,
    'intent_expires_at', v_attachment.intent_expires_at, 'storage_path', v_attachment.storage_path
  );
  perform private.idempotency_finalize(
    (p_ctx).platform_id, v_account_id, 'feedback_attachment_intent',
    'user:' || (p_ctx).user_id::text, p_idempotency_key, v_hash, 201, v_response
  );
  return query select v_attachment.id, v_feedback.id, v_attachment.status,
    v_attachment.write_outcome, v_attachment.requested_size_bytes,
    v_attachment.intent_expires_at, v_attachment.storage_path;
end;
$$;


ALTER FUNCTION "private"."feedback_attachment_intent_create"("p_ctx" "private"."account_context", "p_feedback_id" "uuid", "p_original_name" "text", "p_requested_size_bytes" bigint, "p_mime_type" "text", "p_idempotency_key" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_attachment_list"("p_ctx" "private"."account_context", "p_feedback_id" "uuid") RETURNS TABLE("attachment_id" "uuid", "status" "text", "write_outcome" "text", "original_name" "text", "mime_type" "text", "requested_size_bytes" bigint, "actual_size_bytes" bigint, "sha256" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_account_id uuid;
begin
  v_account_id := private.feedback_account_id(p_ctx, false);
  if not exists (select 1 from public.platform_feedback f
    where f.id = p_feedback_id and f.platform_id = (p_ctx).platform_id
      and f.platform_account_id = v_account_id and f.status not in ('deleting', 'deleted')) then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  return query select a.id, a.status, a.write_outcome, a.original_name,
    a.mime_type, a.requested_size_bytes, a.actual_size_bytes, a.sha256,
    a.created_at, a.updated_at
  from public.platform_feedback_attachments a
  where a.feedback_id = p_feedback_id and a.platform_id = (p_ctx).platform_id
    and a.platform_account_id = v_account_id and a.status <> 'deleted'
  order by a.created_at, a.id;
end;
$$;


ALTER FUNCTION "private"."feedback_attachment_list"("p_ctx" "private"."account_context", "p_feedback_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_attachment_mark_unknown"("p_ctx" "private"."account_context", "p_attachment_id" "uuid", "p_attempt_id" "uuid", "p_error_code" "text") RETURNS TABLE("attachment_id" "uuid", "status" "text", "write_outcome" "text", "write_attempt_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_account_id uuid;
  v_attachment public.platform_feedback_attachments;
  v_attempt private.feedback_attachment_write_attempts;
begin
  if p_attachment_id is null or p_attempt_id is null or p_error_code is null
     or length(p_error_code) not between 1 and 128 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  v_account_id := private.feedback_account_id(p_ctx, true);
  select * into v_attachment from public.platform_feedback_attachments a
  where a.id = p_attachment_id and a.platform_id = (p_ctx).platform_id
    and a.platform_account_id = v_account_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  select * into v_attempt from private.feedback_attachment_write_attempts w
  where w.id = p_attempt_id and w.attachment_id = v_attachment.id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_attempt.state = 'unknown' then
    return query select v_attachment.id, v_attachment.status, v_attachment.write_outcome, v_attempt.id;
    return;
  end if;
  if v_attachment.status <> 'storing' or v_attachment.write_outcome <> 'in_flight'
     or v_attempt.state <> 'in_flight' then
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;
  update private.feedback_attachment_write_attempts set state = 'unknown', error_code = p_error_code
  where id = v_attempt.id returning * into v_attempt;
  update public.platform_feedback_attachments set write_outcome = 'unknown', last_error_code = p_error_code
  where id = v_attachment.id returning * into v_attachment;
  return query select v_attachment.id, v_attachment.status, v_attachment.write_outcome, v_attempt.id;
end;
$$;


ALTER FUNCTION "private"."feedback_attachment_mark_unknown"("p_ctx" "private"."account_context", "p_attachment_id" "uuid", "p_attempt_id" "uuid", "p_error_code" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_attachment_prepare_store"("p_ctx" "private"."account_context", "p_attachment_id" "uuid", "p_actual_size_bytes" bigint, "p_sha256" "text", "p_idempotency_key" "text") RETURNS TABLE("attachment_id" "uuid", "status" "text", "write_outcome" "text", "actual_size_bytes" bigint, "sha256" "text", "storage_path" "text", "write_attempt_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $_$
declare
  v_account_id uuid;
  v_attachment public.platform_feedback_attachments;
  v_attempt private.feedback_attachment_write_attempts;
  v_claim private.idempotency_keys%rowtype;
  v_hash bytea;
  v_new_claim boolean := false;
  v_response jsonb;
begin
  if p_attachment_id is null or p_actual_size_bytes is null or p_actual_size_bytes not between 1 and 4194304
     or p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$'
     or p_idempotency_key is null or length(p_idempotency_key) not between 1 and 128 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  v_account_id := private.feedback_account_id(p_ctx, false);
  select * into v_attachment from public.platform_feedback_attachments a
  where a.id = p_attachment_id and a.platform_id = (p_ctx).platform_id
    and a.platform_account_id = v_account_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if not exists (select 1 from public.platform_feedback f where f.id = v_attachment.feedback_id and f.status = 'draft') then
    raise exception using errcode = 'P0001', message = 'feedback_not_editable';
  end if;
  if v_attachment.status <> 'receiving' or v_attachment.lease_until is null
     or v_attachment.lease_until <= clock_timestamp() then
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;
  if p_actual_size_bytes > v_attachment.requested_size_bytes then
    raise exception using errcode = '22023', message = 'upload_size_mismatch';
  end if;

  v_hash := extensions.digest(convert_to(
    p_attachment_id::text || ':' || p_actual_size_bytes::text || ':' || p_sha256,
    'utf8'), 'sha256');
  insert into private.idempotency_keys (
    platform_id, platform_account_id, operation, actor_scope, idempotency_key, request_hash
  ) values (
    (p_ctx).platform_id, v_account_id, 'feedback_attachment_prepare_store',
    'user:' || (p_ctx).user_id::text, p_idempotency_key, v_hash
  ) on conflict (platform_id, platform_account_id, operation, actor_scope, idempotency_key)
    do nothing returning true into v_new_claim;
  if not coalesce(v_new_claim, false) then
    select * into v_claim from private.idempotency_keys i
    where i.platform_id = (p_ctx).platform_id and i.platform_account_id = v_account_id
      and i.operation = 'feedback_attachment_prepare_store'
      and i.actor_scope = 'user:' || (p_ctx).user_id::text
      and i.idempotency_key = p_idempotency_key for update;
    if v_claim.request_hash <> v_hash then raise exception using errcode = '23505', message = 'idempotency_conflict'; end if;
    if v_claim.state = 'completed' then
      return query select (v_claim.response_body->>'attachment_id')::uuid,
        v_claim.response_body->>'status', v_claim.response_body->>'write_outcome',
        (v_claim.response_body->>'actual_size_bytes')::bigint,
        v_claim.response_body->>'sha256', v_claim.response_body->>'storage_path',
        (v_claim.response_body->>'write_attempt_id')::uuid;
      return;
    end if;
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;

  insert into private.feedback_attachment_write_attempts (
    platform_id, attachment_id, fencing_token, actual_size_bytes, sha256
  ) values (
    (p_ctx).platform_id, v_attachment.id, v_attachment.fencing_token,
    p_actual_size_bytes, p_sha256
  ) returning * into v_attempt;
  update public.platform_feedback_attachments a set
    status = 'storing', write_outcome = 'in_flight',
    actual_size_bytes = p_actual_size_bytes, sha256 = p_sha256
  where a.id = v_attachment.id returning * into v_attachment;
  v_response := jsonb_build_object(
    'attachment_id', v_attachment.id, 'status', v_attachment.status,
    'write_outcome', v_attachment.write_outcome, 'actual_size_bytes', p_actual_size_bytes,
    'sha256', p_sha256, 'storage_path', v_attachment.storage_path,
    'write_attempt_id', v_attempt.id
  );
  perform private.idempotency_finalize(
    (p_ctx).platform_id, v_account_id, 'feedback_attachment_prepare_store',
    'user:' || (p_ctx).user_id::text, p_idempotency_key, v_hash, 200, v_response
  );
  return query select v_attachment.id, v_attachment.status, v_attachment.write_outcome,
    v_attachment.actual_size_bytes, v_attachment.sha256, v_attachment.storage_path, v_attempt.id;
end;
$_$;


ALTER FUNCTION "private"."feedback_attachment_prepare_store"("p_ctx" "private"."account_context", "p_attachment_id" "uuid", "p_actual_size_bytes" bigint, "p_sha256" "text", "p_idempotency_key" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_attachment_receive_claim"("p_ctx" "private"."account_context", "p_attachment_id" "uuid", "p_lease_owner" "text", "p_lease_seconds" integer DEFAULT 15) RETURNS TABLE("attachment_id" "uuid", "feedback_id" "uuid", "status" "text", "write_outcome" "text", "requested_size_bytes" bigint, "lease_until" timestamp with time zone, "fencing_token" bigint, "storage_path" "text", "mime_type" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_account_id uuid;
  v_attachment public.platform_feedback_attachments;
  v_feedback public.platform_feedback;
  v_now timestamptz := clock_timestamp();
begin
  if p_attachment_id is null or p_lease_owner is null or length(p_lease_owner) not between 1 and 128
     or p_lease_seconds not between 1 and 15 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  v_account_id := private.feedback_account_id(p_ctx, false);
  select * into v_attachment from public.platform_feedback_attachments a
  where a.id = p_attachment_id and a.platform_id = (p_ctx).platform_id
    and a.platform_account_id = v_account_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  select * into v_feedback from public.platform_feedback f where f.id = v_attachment.feedback_id for update;
  if v_feedback.status <> 'draft' then raise exception using errcode = 'P0001', message = 'feedback_not_editable'; end if;
  if v_attachment.status <> 'pending' then raise exception using errcode = 'P0001', message = 'operation_in_progress'; end if;
  if v_attachment.intent_expires_at <= v_now then raise exception using errcode = 'P0001', message = 'intent_expired'; end if;
  if v_attachment.lease_until is not null and v_attachment.lease_until > v_now then
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;
  update public.platform_feedback_attachments a set
    status = 'receiving', lease_owner = p_lease_owner,
    lease_until = v_now + make_interval(secs => p_lease_seconds),
    fencing_token = a.fencing_token + 1
  where a.id = v_attachment.id returning * into v_attachment;
  return query select v_attachment.id, v_attachment.feedback_id, v_attachment.status,
    v_attachment.write_outcome, v_attachment.requested_size_bytes,
    v_attachment.lease_until, v_attachment.fencing_token,
    v_attachment.storage_path, v_attachment.mime_type;
end;
$$;


ALTER FUNCTION "private"."feedback_attachment_receive_claim"("p_ctx" "private"."account_context", "p_attachment_id" "uuid", "p_lease_owner" "text", "p_lease_seconds" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_attachment_upload_state"("p_ctx" "private"."account_context", "p_feedback_id" "uuid", "p_attachment_id" "uuid") RETURNS TABLE("attachment_id" "uuid", "feedback_id" "uuid", "platform_account_id" "uuid", "status" "text", "write_outcome" "text", "requested_size_bytes" bigint, "actual_size_bytes" bigint, "sha256" "text", "storage_path" "text", "mime_type" "text", "uploaded_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_account_id uuid;
begin
  if p_feedback_id is null or p_attachment_id is null then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  v_account_id := private.feedback_account_id(p_ctx, false);
  return query
  select a.id, a.feedback_id, a.platform_account_id, a.status, a.write_outcome,
    a.requested_size_bytes, a.actual_size_bytes, a.sha256, a.storage_path, a.mime_type, a.uploaded_at
  from public.platform_feedback_attachments a
  join public.platform_feedback f on f.id = a.feedback_id
  where a.id = p_attachment_id and a.feedback_id = p_feedback_id
    and a.platform_id = (p_ctx).platform_id and a.platform_account_id = v_account_id
    and f.platform_id = (p_ctx).platform_id and f.platform_account_id = v_account_id
    and f.status = 'draft' and a.status not in ('deleting', 'deleted', 'expired', 'failed');
  if not found then
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
end;
$$;


ALTER FUNCTION "private"."feedback_attachment_upload_state"("p_ctx" "private"."account_context", "p_feedback_id" "uuid", "p_attachment_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_client_context_valid"("p_value" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select p_value is not null
    and jsonb_typeof(p_value) = 'object'
    and not exists (
      select 1 from jsonb_object_keys(p_value) as k(key)
      where k.key not in ('app_version', 'route', 'locale', 'timezone', 'os', 'browser')
    )
    and not exists (
      select 1 from jsonb_each(p_value) as e(key, value)
      where jsonb_typeof(e.value) <> 'string'
        or length(e.value #>> '{}') > case when e.key = 'route' then 512 else 256 end
    )
$$;


ALTER FUNCTION "private"."feedback_client_context_valid"("p_value" "jsonb") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_create"("p_ctx" "private"."account_context", "p_category" "text", "p_title" "text", "p_body" "text", "p_contact_allowed" boolean, "p_client_context" "jsonb", "p_idempotency_key" "text") RETURNS TABLE("feedback_id" "uuid", "status" "text", "category" "text", "title" "text", "row_version" bigint, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_account_id uuid;
  v_feedback public.platform_feedback;
  v_claim private.idempotency_keys%rowtype;
  v_new_claim boolean := false;
  v_hash bytea;
  v_response jsonb;
begin
  if p_category not in ('bug', 'idea', 'experience', 'other')
     or p_title is null or length(p_title) not between 1 and 160 or p_title ~ '[[:cntrl:]]'
     or p_body is null or length(p_body) not between 1 and 10000
     or p_contact_allowed is null
     or not private.feedback_client_context_valid(coalesce(p_client_context, '{}'::jsonb))
     or p_idempotency_key is null or length(p_idempotency_key) not between 1 and 128 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  v_account_id := private.feedback_account_id(p_ctx, false);
  perform 1 from public.platform_accounts a
    where a.platform_id = (p_ctx).platform_id and a.id = v_account_id for update;

  v_hash := extensions.digest(convert_to(
    p_category || ':' || p_title || ':' || p_body || ':' || p_contact_allowed::text
      || ':' || coalesce(p_client_context, '{}'::jsonb)::text,
    'utf8'), 'sha256');
  insert into private.idempotency_keys (
    platform_id, platform_account_id, operation, actor_scope, idempotency_key, request_hash
  ) values (
    (p_ctx).platform_id, v_account_id, 'feedback_create',
    'user:' || (p_ctx).user_id::text, p_idempotency_key, v_hash
  ) on conflict (platform_id, platform_account_id, operation, actor_scope, idempotency_key)
    do nothing returning true into v_new_claim;
  if not coalesce(v_new_claim, false) then
    select * into v_claim from private.idempotency_keys i
    where i.platform_id = (p_ctx).platform_id and i.platform_account_id = v_account_id
      and i.operation = 'feedback_create'
      and i.actor_scope = 'user:' || (p_ctx).user_id::text
      and i.idempotency_key = p_idempotency_key for update;
    if v_claim.request_hash <> v_hash then
      raise exception using errcode = '23505', message = 'idempotency_conflict';
    end if;
    if v_claim.state = 'completed' then
      return query select
        (v_claim.response_body->>'feedback_id')::uuid,
        v_claim.response_body->>'status',
        v_claim.response_body->>'category',
        p_title,
        (v_claim.response_body->>'row_version')::bigint,
        (v_claim.response_body->>'created_at')::timestamptz;
      return;
    end if;
    raise exception using errcode = 'P0001', message = 'operation_in_progress';
  end if;

  insert into public.platform_feedback (
    platform_id, platform_account_id, user_id, category, title, body,
    contact_allowed, client_context
  ) values (
    (p_ctx).platform_id, v_account_id, (p_ctx).user_id, p_category,
    p_title, p_body, p_contact_allowed, coalesce(p_client_context, '{}'::jsonb)
  ) returning * into v_feedback;
  perform private.audit_append(
    (p_ctx).request_id, 'user', (p_ctx).user_id, (p_ctx).platform_id, v_account_id,
    'feedback.draft_created', 'platform_feedback', v_feedback.id, null, null,
    jsonb_build_object('category', p_category, 'contact_allowed', p_contact_allowed)
  );
  v_response := jsonb_build_object(
    'feedback_id', v_feedback.id, 'status', v_feedback.status,
    'category', v_feedback.category, 'row_version', v_feedback.row_version,
    'created_at', v_feedback.created_at
  );
  perform private.idempotency_finalize(
    (p_ctx).platform_id, v_account_id, 'feedback_create',
    'user:' || (p_ctx).user_id::text, p_idempotency_key, v_hash, 201, v_response
  );
  return query select v_feedback.id, v_feedback.status, v_feedback.category,
    v_feedback.title, v_feedback.row_version, v_feedback.created_at;
end;
$$;


ALTER FUNCTION "private"."feedback_create"("p_ctx" "private"."account_context", "p_category" "text", "p_title" "text", "p_body" "text", "p_contact_allowed" boolean, "p_client_context" "jsonb", "p_idempotency_key" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_delete_reconcile"("p_feedback_id" "uuid", "p_now" timestamp with time zone DEFAULT "clock_timestamp"()) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_feedback public.platform_feedback;
begin
  if p_feedback_id is null or p_now is null then raise exception using errcode = '22023', message = 'invalid_input'; end if;
  select * into v_feedback from public.platform_feedback f where f.id = p_feedback_id for update;
  if not found or v_feedback.status <> 'deleting' then return; end if;
  if exists (select 1 from public.platform_feedback_attachments a
    where a.feedback_id = v_feedback.id and a.status <> 'deleted') then return; end if;
  update public.platform_feedback set
    status = 'deleted', deleted_at = coalesce(deleted_at, p_now),
    platform_account_id = null, user_id = null,
    author_display_name_snapshot = null, contact_email_snapshot = null,
    contact_allowed = false, title = null, body = null, client_context = '{}'::jsonb,
    row_version = row_version + 1
  where id = v_feedback.id;
  insert into public.platform_feedback_events(platform_id, feedback_id, event_type, metadata)
  values (v_feedback.platform_id, v_feedback.id, 'deleted', '{}'::jsonb);
end;
$$;


ALTER FUNCTION "private"."feedback_delete_reconcile"("p_feedback_id" "uuid", "p_now" timestamp with time zone) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_delete_reconcile_on_attachment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.feedback_delete_reconcile(new.feedback_id, clock_timestamp());
  return new;
end;
$$;


ALTER FUNCTION "private"."feedback_delete_reconcile_on_attachment"() OWNER TO "domain_owner";


