    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  perform private.feedback_delete_reconcile(new.id, clock_timestamp());
  return new;
end;
$$;


ALTER FUNCTION "private"."feedback_delete_reconcile_on_feedback"() OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_list"("p_ctx" "private"."account_context", "p_cursor_feedback_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("feedback_id" "uuid", "category" "text", "title" "text", "status" "text", "flagged" boolean, "contact_allowed" boolean, "attachment_count" integer, "row_version" bigint, "submitted_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_account_id uuid;
  v_cursor_created_at timestamptz;
begin
  if p_limit is null or p_limit not between 1 and 100 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  v_account_id := private.feedback_account_id(p_ctx, false);
  if p_cursor_feedback_id is not null then
    select f.created_at into v_cursor_created_at
    from public.platform_feedback f
    where f.id = p_cursor_feedback_id and f.platform_id = (p_ctx).platform_id
      and f.platform_account_id = v_account_id and f.status not in ('deleting', 'deleted');
    if v_cursor_created_at is null then
      raise exception using errcode = 'P0002', message = 'resource_not_found';
    end if;
  end if;
  return query
    select f.id, f.category, f.title, f.status, f.flagged, f.contact_allowed,
      (select count(*)::integer from public.platform_feedback_attachments a
       where a.feedback_id = f.id and a.status not in ('deleted', 'expired', 'failed')),
      f.row_version, f.submitted_at, f.created_at, f.updated_at
    from public.platform_feedback f
    where f.platform_id = (p_ctx).platform_id and f.platform_account_id = v_account_id
      and f.status not in ('deleting', 'deleted')
      and (p_cursor_feedback_id is null
        or (f.created_at, f.id) < (v_cursor_created_at, p_cursor_feedback_id))
    order by f.created_at desc, f.id desc
    limit p_limit;
end;
$$;


ALTER FUNCTION "private"."feedback_list"("p_ctx" "private"."account_context", "p_cursor_feedback_id" "uuid", "p_limit" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_patch"("p_ctx" "private"."account_context", "p_feedback_id" "uuid", "p_expected_row_version" bigint, "p_category" "text", "p_title" "text", "p_body" "text", "p_contact_allowed" boolean, "p_client_context" "jsonb") RETURNS TABLE("feedback_id" "uuid", "status" "text", "row_version" bigint, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_account_id uuid;
  v_feedback public.platform_feedback;
begin
  if p_feedback_id is null or p_expected_row_version is null or p_expected_row_version < 1
     or p_category not in ('bug', 'idea', 'experience', 'other')
     or p_title is null or length(p_title) not between 1 and 160 or p_title ~ '[[:cntrl:]]'
     or p_body is null or length(p_body) not between 1 and 10000
     or p_contact_allowed is null
     or not private.feedback_client_context_valid(coalesce(p_client_context, '{}'::jsonb)) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  v_account_id := private.feedback_account_id(p_ctx, false);
  select * into v_feedback from public.platform_feedback f
  where f.id = p_feedback_id and f.platform_id = (p_ctx).platform_id
    and f.platform_account_id = v_account_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_feedback.status <> 'draft' then raise exception using errcode = 'P0001', message = 'feedback_not_editable'; end if;
  if v_feedback.row_version <> p_expected_row_version then raise exception using errcode = '40001', message = 'precondition_failed'; end if;
  update public.platform_feedback f set
    category = p_category, title = p_title, body = p_body,
    contact_allowed = p_contact_allowed, client_context = coalesce(p_client_context, '{}'::jsonb),
    row_version = f.row_version + 1
  where f.id = v_feedback.id returning * into v_feedback;
  return query select v_feedback.id, v_feedback.status, v_feedback.row_version, v_feedback.updated_at;
end;
$$;


ALTER FUNCTION "private"."feedback_patch"("p_ctx" "private"."account_context", "p_feedback_id" "uuid", "p_expected_row_version" bigint, "p_category" "text", "p_title" "text", "p_body" "text", "p_contact_allowed" boolean, "p_client_context" "jsonb") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_privacy_delete"("p_feedback_id" "uuid", "p_reason" "text", "p_now" timestamp with time zone DEFAULT "clock_timestamp"()) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_feedback public.platform_feedback;
begin
  if p_feedback_id is null or p_now is null or p_reason is null or length(p_reason) not between 1 and 128 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_feedback from public.platform_feedback f where f.id = p_feedback_id for update;
  if not found or v_feedback.status = 'deleted' then return; end if;
  update public.platform_feedback set
    status = 'deleting', delete_requested_at = coalesce(delete_requested_at, p_now),
    author_display_name_snapshot = null, contact_email_snapshot = null,
    contact_allowed = false, title = null, body = null, client_context = '{}'::jsonb,
    row_version = row_version + 1
  where id = v_feedback.id;
  delete from public.platform_feedback_labels where feedback_id = v_feedback.id;
  update public.platform_feedback_events set note_body = null, metadata = '{}'::jsonb
  where feedback_id = v_feedback.id;
  update public.platform_feedback_attachments set
    status = case when status = 'deleted' then 'deleted' else 'deleting' end,
    original_name = case when status = 'deleted' then original_name else '[deleting]' end,
    cancel_requested_at = coalesce(cancel_requested_at, p_now),
    delete_requested_at = coalesce(delete_requested_at, p_now),
    next_attempt_at = greatest(p_now, coalesce(lease_until, p_now))
  where feedback_id = v_feedback.id and status <> 'deleted';
  insert into public.platform_feedback_events(platform_id, feedback_id, event_type, metadata)
  values (v_feedback.platform_id, v_feedback.id, 'delete_requested',
    jsonb_build_object('reason_code', p_reason));
  perform private.feedback_delete_reconcile(v_feedback.id, p_now);
end;
$$;


ALTER FUNCTION "private"."feedback_privacy_delete"("p_feedback_id" "uuid", "p_reason" "text", "p_now" timestamp with time zone) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_read"("p_ctx" "private"."account_context", "p_feedback_id" "uuid") RETURNS TABLE("feedback_id" "uuid", "category" "text", "title" "text", "body" "text", "status" "text", "contact_allowed" boolean, "client_context" "jsonb", "flagged" boolean, "row_version" bigint, "submitted_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare v_account_id uuid;
begin
  if p_feedback_id is null then raise exception using errcode = '22023', message = 'invalid_input'; end if;
  v_account_id := private.feedback_account_id(p_ctx, false);
  return query select f.id, f.category, f.title, f.body, f.status,
    f.contact_allowed, f.client_context, f.flagged, f.row_version,
    f.submitted_at, f.created_at, f.updated_at
  from public.platform_feedback f
  where f.id = p_feedback_id and f.platform_id = (p_ctx).platform_id
    and f.platform_account_id = v_account_id and f.status not in ('deleting', 'deleted');
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
end;
$$;


ALTER FUNCTION "private"."feedback_read"("p_ctx" "private"."account_context", "p_feedback_id" "uuid") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."feedback_submit"("p_ctx" "private"."account_context", "p_feedback_id" "uuid", "p_contact_email_snapshot" "text") RETURNS TABLE("feedback_id" "uuid", "status" "text", "row_version" bigint, "submitted_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_account_id uuid;
  v_feedback public.platform_feedback;
  v_display_name text;
  v_attachment_count integer;
  v_now timestamptz := clock_timestamp();
begin
  if p_feedback_id is null or p_contact_email_snapshot is not null
     and length(p_contact_email_snapshot) not between 3 and 320 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  v_account_id := private.feedback_account_id(p_ctx, false);
  select * into v_feedback from public.platform_feedback f
  where f.id = p_feedback_id and f.platform_id = (p_ctx).platform_id
    and f.platform_account_id = v_account_id for update;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  if v_feedback.status = 'new' then
    return query select v_feedback.id, v_feedback.status, v_feedback.row_version, v_feedback.submitted_at;
    return;
  end if;
  if v_feedback.status <> 'draft' then raise exception using errcode = 'P0001', message = 'feedback_not_editable'; end if;
  if v_feedback.contact_allowed and p_contact_email_snapshot is null then
    raise exception using errcode = '22023', message = 'contact_email_required';
  end if;
  if exists (
    select 1 from public.platform_feedback_attachments a
    where a.feedback_id = v_feedback.id and a.status not in ('active', 'deleted', 'expired', 'failed')
  ) then raise exception using errcode = 'P0001', message = 'feedback_attachment_not_ready'; end if;
  select count(*)::integer into v_attachment_count
  from public.platform_feedback_attachments a
  where a.feedback_id = v_feedback.id and a.status = 'active';
  select nullif(btrim(p.display_name), '') into v_display_name
  from public.platform_profiles p where p.platform_account_id = v_account_id;
  update public.platform_feedback f set
    status = 'new', submitted_at = v_now,
    author_display_name_snapshot = v_display_name,
    contact_email_snapshot = p_contact_email_snapshot,
    row_version = f.row_version + 1
  where f.id = v_feedback.id returning * into v_feedback;
  insert into public.platform_feedback_events (
    platform_id, feedback_id, event_type, actor_user_id, metadata
  ) values (
    v_feedback.platform_id, v_feedback.id, 'submitted', (p_ctx).user_id,
    jsonb_build_object('category', v_feedback.category, 'attachment_count', v_attachment_count)
  );
  perform private.audit_append(
    (p_ctx).request_id, 'user', (p_ctx).user_id, (p_ctx).platform_id, v_account_id,
    'feedback.submitted', 'platform_feedback', v_feedback.id, null, null,
    jsonb_build_object('category', v_feedback.category,
      'attachment_count', v_attachment_count, 'contact_allowed', v_feedback.contact_allowed)
  );
  return query select v_feedback.id, v_feedback.status, v_feedback.row_version, v_feedback.submitted_at;
end;
$$;


ALTER FUNCTION "private"."feedback_submit"("p_ctx" "private"."account_context", "p_feedback_id" "uuid", "p_contact_email_snapshot" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."file_backup_barrier_begin"("p_ctx" "private"."job_context", "p_scope" "text", "p_recovery_set_id" "text", "p_deadline_at" timestamp with time zone, "p_manifest_version" "text" DEFAULT NULL::"text") RETURNS TABLE("barrier_id" "uuid", "scope" "text", "recovery_set_id" "text", "state" "text", "fencing_token" bigint, "started_at" timestamp with time zone, "deadline_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
  v_lease private.job_leases;
  v_barrier private.file_backup_barriers;
begin
  if (p_ctx).job_id is null
     or (p_ctx).lease_owner is null
     or length((p_ctx).lease_owner) not between 1 and 128
     or (p_ctx).fencing_token is null
     or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null
     or p_scope not in ('platform', 'global', 'file')
     or p_recovery_set_id is null
     or length(p_recovery_set_id) not between 1 and 256
     or p_deadline_at is null
     or p_deadline_at <= v_now
     or p_deadline_at > v_now + interval '2 hours'
     or (p_manifest_version is not null and length(p_manifest_version) not between 1 and 128) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  select * into v_lease
  from private.job_leases l
  where l.job_kind = 'backup_manifest'
    and l.resource_id = (p_ctx).job_id
    and l.lease_owner = (p_ctx).lease_owner
    and l.fencing_token = (p_ctx).fencing_token
    and l.lease_until > v_now
  for update;
  if not found then
    raise exception using errcode = '40001', message = 'stale_job_fence';
  end if;

  select * into v_barrier
  from private.file_backup_barriers b
  where b.scope = p_scope and b.recovery_set_id = p_recovery_set_id
  for update;
  if found then
    raise exception using errcode = '23505', message =
      case when v_barrier.state in ('active', 'running')
        then 'backup_in_progress' else 'recovery_set_already_recorded' end;
  end if;

  insert into private.file_backup_barriers (
    scope, recovery_set_id, state, lease_owner, fencing_token,
    started_at, deadline_at, manifest_version
  ) values (
    p_scope, p_recovery_set_id, 'running', (p_ctx).lease_owner,
    (p_ctx).fencing_token, v_now, p_deadline_at, p_manifest_version
  )
  returning * into v_barrier;

  return query
    select v_barrier.id, v_barrier.scope, v_barrier.recovery_set_id,
      v_barrier.state, v_barrier.fencing_token, v_barrier.started_at,
      v_barrier.deadline_at;
end;
$$;


ALTER FUNCTION "private"."file_backup_barrier_begin"("p_ctx" "private"."job_context", "p_scope" "text", "p_recovery_set_id" "text", "p_deadline_at" timestamp with time zone, "p_manifest_version" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."file_backup_barrier_finish"("p_ctx" "private"."job_context", "p_barrier_id" "uuid", "p_fencing_token" bigint, "p_result" "text", "p_manifest_version" "text" DEFAULT NULL::"text", "p_error_code" "text" DEFAULT NULL::"text") RETURNS TABLE("barrier_id" "uuid", "scope" "text", "recovery_set_id" "text", "state" "text", "fencing_token" bigint, "finished_at" timestamp with time zone, "manifest_version" "text", "last_error_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
  v_lease private.job_leases;
  v_barrier private.file_backup_barriers;
  v_state text := p_result;
  v_error text := p_error_code;
begin
  if (p_ctx).job_id is null
     or (p_ctx).lease_owner is null
     or length((p_ctx).lease_owner) not between 1 and 128
     or (p_ctx).fencing_token is null
     or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null
     or p_barrier_id is null
     or p_fencing_token is null
     or p_fencing_token < 1
     or p_fencing_token <> (p_ctx).fencing_token
     or p_result not in ('complete', 'failed') then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  if p_result = 'complete' then
    if p_manifest_version is null or length(p_manifest_version) not between 1 and 128 then
      raise exception using errcode = '22023', message = 'manifest_required';
    end if;
    if p_error_code is not null then
      raise exception using errcode = '22023', message = 'invalid_input';
    end if;
  elsif p_error_code is null or length(p_error_code) not between 1 and 128 then
    raise exception using errcode = '22023', message = 'error_code_required';
  end if;

  select * into v_lease
  from private.job_leases l
  where l.job_kind = 'backup_manifest'
    and l.resource_id = (p_ctx).job_id
    and l.lease_owner = (p_ctx).lease_owner
    and l.fencing_token = (p_ctx).fencing_token
    and l.lease_until > v_now
  for update;
  if not found then
    raise exception using errcode = '40001', message = 'stale_job_fence';
  end if;

  select * into v_barrier
  from private.file_backup_barriers b
  where b.id = p_barrier_id
    and b.state = 'running'
    and b.lease_owner = (p_ctx).lease_owner
    and b.fencing_token = p_fencing_token
  for update;
  if not found then
    raise exception using errcode = '40001', message = 'stale_job_fence';
  end if;

  if v_now > v_barrier.deadline_at then
    v_state := 'failed';
    v_error := 'deadline_exceeded';
    p_manifest_version := null;
  end if;

  update private.file_backup_barriers b
  set state = v_state,
      finished_at = v_now,
      manifest_version = case when v_state = 'complete' then p_manifest_version else null end,
      last_error_code = case when v_state = 'failed' then v_error else null end
  where b.id = v_barrier.id
  returning * into v_barrier;

  perform private.job_lease_release(
    'backup_manifest', (p_ctx).job_id, (p_ctx).lease_owner, p_fencing_token
  );

  return query
    select v_barrier.id, v_barrier.scope, v_barrier.recovery_set_id,
      v_barrier.state, v_barrier.fencing_token, v_barrier.finished_at,
      v_barrier.manifest_version, v_barrier.last_error_code;
end;
$$;


ALTER FUNCTION "private"."file_backup_barrier_finish"("p_ctx" "private"."job_context", "p_barrier_id" "uuid", "p_fencing_token" bigint, "p_result" "text", "p_manifest_version" "text", "p_error_code" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."file_cleanup_candidates"("p_cursor_file_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("file_id" "uuid", "next_attempt_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
begin
  if p_limit not between 1 and 100 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  return query
    select f.id, f.next_attempt_at
    from public.platform_config_files f
    where (p_cursor_file_id is null or f.id > p_cursor_file_id)
      and f.next_attempt_at <= clock_timestamp()
      and (
        (f.status in ('pending', 'receiving') and f.write_outcome = 'not_started'
          and (f.lease_until is null or f.lease_until <= clock_timestamp())
          and (f.status = 'receiving' or f.intent_expires_at <= clock_timestamp()))
        or (f.status in ('storing', 'deleting') and f.write_outcome in ('in_flight', 'unknown'))
        or (f.status = 'deleting' and f.write_outcome = 'confirmed')
      )
    order by f.id
    limit p_limit;
end;
$$;


ALTER FUNCTION "private"."file_cleanup_candidates"("p_cursor_file_id" "uuid", "p_limit" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."file_cleanup_claim"("p_ctx" "private"."job_context", "p_file_id" "uuid", "p_lease_seconds" integer DEFAULT 60) RETURNS TABLE("file_id" "uuid", "action" "text", "status" "text", "write_outcome" "text", "platform_id" "uuid", "platform_account_id" "uuid", "storage_bucket" "text", "storage_path" "text", "write_attempt_id" "uuid", "fencing_token" bigint, "retry_count" integer, "next_attempt_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_claim record;
  v_file public.platform_config_files;
  v_now timestamptz := clock_timestamp();
  v_action text;
  v_attempt_id uuid;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or length((p_ctx).lease_owner) not between 1 and 128
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null or p_file_id is null
     or p_lease_seconds not between 1 and 3600 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_claim from private.job_lease_claim(
    'file_cleanup', p_file_id, (p_ctx).lease_owner, p_lease_seconds
  );
  if not coalesce(v_claim.claimed, false) then
    return query select p_file_id, 'busy'::text, null::text, null::text,
      null::uuid, null::uuid, null::text, null::text, null::uuid,
      v_claim.fencing_token, null::integer, v_claim.lease_until;
    return;
  end if;
  select * into v_file from public.platform_config_files f
  where f.id = p_file_id for update;
  if not found then
    perform private.job_lease_release('file_cleanup', p_file_id, (p_ctx).lease_owner, v_claim.fencing_token);
    raise exception using errcode = 'P0002', message = 'resource_not_found';
  end if;
  perform 1 from public.platform_accounts a
  where a.platform_id = v_file.platform_id and a.id = v_file.platform_account_id for update;
  if exists (select 1 from private.file_backup_barriers b where b.state in ('active', 'running')) then
    v_action := 'backup_barrier';
  elsif v_file.status in ('pending', 'receiving')
    and v_file.write_outcome = 'not_started'
    and not exists (select 1 from private.file_write_attempts a where a.file_id = v_file.id)
    and (v_file.lease_until is null or v_file.lease_until <= v_now)
    and (v_file.status = 'receiving' or v_file.intent_expires_at <= v_now) then
    update public.platform_config_files f
    set status = 'expired', reserved_bytes = 0, reserved_count = 0,
        next_attempt_at = v_now
    where f.id = v_file.id
    returning * into v_file;
    perform private.audit_append(
      (p_ctx).request_id, 'job', null, v_file.platform_id, v_file.platform_account_id,
      'file.intent_expired', 'platform_config_file', v_file.id, null, null,
      jsonb_build_object('reason', 'no_storage_write_started')
    );
    v_action := 'no_storage';
  elsif v_file.status in ('active', 'deleting') and v_file.write_outcome = 'confirmed' then
    select a.id into v_attempt_id from private.file_write_attempts a
    where a.file_id = v_file.id and a.state in ('in_flight', 'unknown') limit 1;
    if v_attempt_id is null then v_action := 'remove';
    else v_action := 'settlement_required';
    end if;
  elsif v_file.status in ('storing', 'deleting')
    and v_file.write_outcome in ('in_flight', 'unknown') then
    v_action := 'settlement_required';
  else
    v_action := 'no_storage';
  end if;
  if v_action = 'settlement_required' and v_file.updated_at <= v_now - interval '5 minutes' then
    perform private.audit_append(
      (p_ctx).request_id, 'job', null, v_file.platform_id, v_file.platform_account_id,
      'file.unknown_write_alert', 'platform_config_file', v_file.id, null, null,
      jsonb_build_object('write_outcome', v_file.write_outcome)
    );
  end if;
  if v_action <> 'remove' then
    perform private.job_lease_release('file_cleanup', p_file_id, (p_ctx).lease_owner, v_claim.fencing_token);
  end if;
  return query select v_file.id, v_action, v_file.status, v_file.write_outcome,
    v_file.platform_id, v_file.platform_account_id, v_file.storage_bucket,
    v_file.storage_path, v_attempt_id, v_claim.fencing_token,
    v_file.retry_count, v_file.next_attempt_at;
end;
$$;


ALTER FUNCTION "private"."file_cleanup_claim"("p_ctx" "private"."job_context", "p_file_id" "uuid", "p_lease_seconds" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."file_cleanup_finish"("p_ctx" "private"."job_context", "p_file_id" "uuid", "p_fencing_token" bigint, "p_outcome" "text", "p_error_code" "text" DEFAULT NULL::"text") RETURNS TABLE("file_id" "uuid", "status" "text", "write_outcome" "text", "reserved_bytes" bigint, "retry_count" integer, "next_attempt_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_file public.platform_config_files;
  v_lease private.job_leases;
  v_account public.platform_accounts;
  v_retry integer;
  v_next timestamptz;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).request_id is null or p_file_id is null
     or p_fencing_token is null or p_fencing_token < 1
     or p_outcome not in ('removed', 'not_found', 'failed', 'unknown')
     or p_outcome in ('failed', 'unknown') and (p_error_code is null or length(p_error_code) not between 1 and 128) then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  select * into v_lease from private.job_leases l
  where l.job_kind = 'file_cleanup' and l.resource_id = p_file_id
    and l.lease_owner = (p_ctx).lease_owner and l.fencing_token = p_fencing_token for update;
  if not found then raise exception using errcode = '40001', message = 'stale_job_fence'; end if;
  select * into v_file from public.platform_config_files f where f.id = p_file_id;
  if not found then raise exception using errcode = 'P0002', message = 'resource_not_found'; end if;
  select * into v_account from public.platform_accounts a
  where a.platform_id = v_file.platform_id and a.id = v_file.platform_account_id for update;
  select * into v_file from public.platform_config_files f where f.id = p_file_id for update;
  if p_outcome in ('removed', 'not_found') then
    if v_file.status not in ('active', 'deleting') or v_file.write_outcome <> 'confirmed' then
      raise exception using errcode = 'P0001', message = 'settlement_required';
    end if;
    update public.platform_config_files f
    set status = 'deleted', reserved_bytes = 0, reserved_count = 0,
        deleted_at = clock_timestamp(), next_attempt_at = clock_timestamp()
    where f.id = v_file.id
    returning * into v_file;
    perform private.audit_append(
      (p_ctx).request_id, 'job', null, v_file.platform_id, v_file.platform_account_id,
      'file.deleted_confirmed', 'platform_config_file', v_file.id, null, null,
      jsonb_build_object('outcome', p_outcome)
    );
  else
    v_retry := v_file.retry_count + 1;
    v_next := clock_timestamp() + make_interval(secs => least(3600, 60 * (2 ^ least(v_retry - 1, 6))));
    update public.platform_config_files f
    set status = case when f.status = 'active' then 'deleting' else f.status end,
        retry_count = v_retry, next_attempt_at = v_next, last_error_code = p_error_code
    where f.id = v_file.id
    returning * into v_file;
    perform private.audit_append(
      (p_ctx).request_id, 'job', null, v_file.platform_id, v_file.platform_account_id,
      case when v_retry >= 10 then 'file.cleanup_manual_required' else 'file.cleanup_retry' end,
      'platform_config_file', v_file.id, null, null,
      jsonb_build_object('retry_count', v_retry, 'error_code', p_error_code)
    );
  end if;
  perform private.job_lease_release('file_cleanup', p_file_id, (p_ctx).lease_owner, p_fencing_token);
  return query select v_file.id, v_file.status, v_file.write_outcome,
    v_file.reserved_bytes, v_file.retry_count, v_file.next_attempt_at;
end;
$$;


ALTER FUNCTION "private"."file_cleanup_finish"("p_ctx" "private"."job_context", "p_file_id" "uuid", "p_fencing_token" bigint, "p_outcome" "text", "p_error_code" "text") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."file_reconcile_step"("p_ctx" "private"."job_context", "p_cursor_file_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 20) RETURNS TABLE("file_id" "uuid", "issue_code" "text", "status" "text", "write_outcome" "text", "reserved_bytes" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_file public.platform_config_files;
  v_issue text;
begin
  if (p_ctx).job_id is null or (p_ctx).lease_owner is null
     or (p_ctx).fencing_token is null or (p_ctx).fencing_token < 1
    or (p_ctx).request_id is null or p_limit not between 1 and 100 then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;
  for v_file in
    select f.* from public.platform_config_files f
    where (p_cursor_file_id is null or f.id > p_cursor_file_id)
      and ((f.write_outcome in ('in_flight', 'unknown') and f.updated_at <= clock_timestamp() - interval '5 minutes')
       or (f.status = 'deleting' and f.updated_at <= clock_timestamp() - interval '15 minutes')
       or (f.reserved_bytes = 0 and f.status in ('pending', 'receiving', 'storing', 'active', 'deleting')))
    order by f.id
    limit p_limit
  loop
    v_issue := case
      when v_file.write_outcome in ('in_flight', 'unknown') then 'unknown_write'
      when v_file.status = 'deleting' then 'delete_backlog'
      else 'budget_invariant' end;
    perform private.audit_append(
      (p_ctx).request_id, 'job', null, v_file.platform_id, v_file.platform_account_id,
      'file.reconcile_alert', 'platform_config_file', v_file.id, null, null,
      jsonb_build_object('issue_code', v_issue, 'reserved_bytes', v_file.reserved_bytes)
    );
    file_id := v_file.id; issue_code := v_issue; status := v_file.status;
    write_outcome := v_file.write_outcome; reserved_bytes := v_file.reserved_bytes;
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "private"."file_reconcile_step"("p_ctx" "private"."job_context", "p_cursor_file_id" "uuid", "p_limit" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."idempotency_claim"("p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_operation" "text", "p_actor_scope" "text", "p_idempotency_key" "text", "p_request_hash" "bytea") RETURNS TABLE("outcome" "text", "response_status" integer, "response_body" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
declare
  existing private.idempotency_keys%rowtype;
begin
  insert into private.idempotency_keys (
    platform_id, platform_account_id, operation, actor_scope,
    idempotency_key, request_hash
  ) values (
    p_platform_id, p_platform_account_id, p_operation, p_actor_scope,
    p_idempotency_key, p_request_hash
  ) on conflict (platform_id, platform_account_id, operation, actor_scope, idempotency_key)
  do nothing;

  select * into existing
  from private.idempotency_keys
  where platform_id = p_platform_id
    and platform_account_id = p_platform_account_id
    and operation = p_operation
    and actor_scope = p_actor_scope
    and idempotency_key = p_idempotency_key
  for update;

  if existing.request_hash <> p_request_hash then
    return query select 'conflict'::text, null::integer, null::jsonb;
  elsif existing.state = 'completed' then
    return query select 'completed'::text, existing.response_status, existing.response_body;
  else
    return query select 'pending'::text, null::integer, null::jsonb;
  end if;
end;
$$;


ALTER FUNCTION "private"."idempotency_claim"("p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_operation" "text", "p_actor_scope" "text", "p_idempotency_key" "text", "p_request_hash" "bytea") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."idempotency_cleanup"("p_ctx" "private"."job_context", "p_before" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 100) RETURNS TABLE("user_deleted" integer, "admin_deleted" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
declare
  v_before timestamptz := coalesce(p_before, clock_timestamp());
  v_user_deleted integer := 0;
  v_admin_deleted integer := 0;
begin
  if (p_ctx).job_id is null
     or (p_ctx).lease_owner is null
     or length((p_ctx).lease_owner) not between 1 and 128
     or (p_ctx).fencing_token is null
     or (p_ctx).fencing_token < 1
     or (p_ctx).request_id is null
     or p_limit is null
     or p_limit not between 1 and 1000
     or v_before > clock_timestamp() then
    raise exception using errcode = '22023', message = 'invalid_input';
  end if;

  with candidates as (
    select ctid
    from private.idempotency_keys
    where expires_at <= v_before
    order by expires_at, created_at
    limit p_limit
  )
  delete from private.idempotency_keys i
  using candidates
  where i.ctid = candidates.ctid;
  get diagnostics v_user_deleted = row_count;

  with candidates as (
    select ctid
    from private.admin_idempotency
    where expires_at <= v_before
    order by expires_at, created_at
    limit p_limit
  )
  delete from private.admin_idempotency i
  using candidates
  where i.ctid = candidates.ctid;
  get diagnostics v_admin_deleted = row_count;

  return query select v_user_deleted, v_admin_deleted;
end;
$$;


ALTER FUNCTION "private"."idempotency_cleanup"("p_ctx" "private"."job_context", "p_before" timestamp with time zone, "p_limit" integer) OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."idempotency_finalize"("p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_operation" "text", "p_actor_scope" "text", "p_idempotency_key" "text", "p_request_hash" "bytea", "p_response_status" integer, "p_response_body" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private'
    AS $$
begin
  update private.idempotency_keys
  set state = 'completed',
      response_status = p_response_status,
      response_body = p_response_body
  where platform_id = p_platform_id
    and platform_account_id = p_platform_account_id
    and operation = p_operation
    and actor_scope = p_actor_scope
    and idempotency_key = p_idempotency_key
    and request_hash = p_request_hash
    and state = 'pending';
  return found;
end;
$$;


ALTER FUNCTION "private"."idempotency_finalize"("p_platform_id" "uuid", "p_platform_account_id" "uuid", "p_operation" "text", "p_actor_scope" "text", "p_idempotency_key" "text", "p_request_hash" "bytea", "p_response_status" integer, "p_response_body" "jsonb") OWNER TO "domain_owner";


CREATE OR REPLACE FUNCTION "private"."identity_delete_request"("p_ctx" "private"."account_context", "p_recent_proof_id" "uuid") RETURNS TABLE("request_id" "uuid", "state" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'private', 'public'
    AS $$
declare
  v_existing private.deletion_requests;
  v_session record;
begin
  select * into v_session from private.check_user_session((p_ctx).user_id, (p_ctx).session_id);
  if not coalesce(v_session.active, false) then raise exception using errcode = '42501', message = 'unauthorized'; end if;
  if p_recent_proof_id is null or not exists (
    select 1 from private.user_recent_auth_proofs proof
    where proof.id = p_recent_proof_id and proof.user_id = (p_ctx).user_id
      and proof.session_id = (p_ctx).session_id and proof.expires_at > now()
      and proof.verified_at <= now() and proof.expires_at <= proof.verified_at + interval '5 minutes'
  ) then raise exception using errcode = '42501', message = 'recent_mfa_required'; end if;
  select * into v_existing from private.deletion_requests as dr where dr.user_id = (p_ctx).user_id and dr.state = 'pending_admin' for update;
  if found then return query select v_existing.id, v_existing.state; return; end if;
  insert into private.deletion_requests (user_id, request_session_id) values ((p_ctx).user_id, (p_ctx).session_id)
  returning private.deletion_requests.id, private.deletion_requests.state into request_id, state;
  perform private.audit_append((p_ctx).request_id, 'user', (p_ctx).user_id, null, null,
    'identity.delete_requested', 'deletion_request', request_id, null, null, '{}'::jsonb);
  return next;
end;
$$;


ALTER FUNCTION "private"."identity_delete_request"("p_ctx" "private"."account_context", "p_recent_proof_id" "uuid") OWNER TO "domain_owner";


