CREATE TABLE IF NOT EXISTS "public"."platform_config_files" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "platform_id" "uuid" NOT NULL,
    "platform_account_id" "uuid" NOT NULL,
    "original_name" "text" NOT NULL,
    "storage_bucket" "text" DEFAULT 'platform-config-files'::"text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "mime_type" "text",
    "purpose" "text",
    "requested_size_bytes" bigint NOT NULL,
    "actual_size_bytes" bigint,
    "sha256" "text",
    "reserved_bytes" bigint DEFAULT 0 NOT NULL,
    "reserved_count" integer DEFAULT 1 NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "intent_expires_at" timestamp with time zone NOT NULL,
    "lease_until" timestamp with time zone,
    "fencing_token" bigint DEFAULT 0 NOT NULL,
    "write_outcome" "text" DEFAULT 'not_started'::"text" NOT NULL,
    "uploaded_at" timestamp with time zone,
    "delete_requested_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "lease_owner" "text",
    "cancel_requested_at" timestamp with time zone,
    "retry_count" integer DEFAULT 0 NOT NULL,
    "next_attempt_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_error_code" "text",
    "resource_kind" "text" DEFAULT 'config_version'::"text" NOT NULL,
    CONSTRAINT "platform_config_files_actual_size_bytes_check" CHECK ((("actual_size_bytes" IS NULL) OR (("actual_size_bytes" >= 1) AND ("actual_size_bytes" <= 1048576)))),
    CONSTRAINT "platform_config_files_check" CHECK ((("actual_size_bytes" IS NULL) OR ("actual_size_bytes" <= "requested_size_bytes"))),
    CONSTRAINT "platform_config_files_check1" CHECK ((("status" <> 'active'::"text") OR (("actual_size_bytes" IS NOT NULL) AND ("sha256" IS NOT NULL)))),
    CONSTRAINT "platform_config_files_check3" CHECK ((("status" <> 'deleted'::"text") OR ("deleted_at" IS NOT NULL))),
    CONSTRAINT "platform_config_files_check4" CHECK ((("write_outcome" <> 'confirmed'::"text") OR ("actual_size_bytes" IS NOT NULL))),
    CONSTRAINT "platform_config_files_fencing_token_check" CHECK (("fencing_token" >= 0)),
    CONSTRAINT "platform_config_files_last_error_code_check" CHECK ((("last_error_code" IS NULL) OR (("length"("last_error_code") >= 1) AND ("length"("last_error_code") <= 128)))),
    CONSTRAINT "platform_config_files_lease_owner_check" CHECK ((("lease_owner" IS NULL) OR (("length"("lease_owner") >= 1) AND ("length"("lease_owner") <= 128)))),
    CONSTRAINT "platform_config_files_mime_type_check" CHECK ((("mime_type" IS NULL) OR (("length"("mime_type") >= 1) AND ("length"("mime_type") <= 255)))),
    CONSTRAINT "platform_config_files_original_name_check" CHECK ((("length"("original_name") >= 1) AND ("length"("original_name") <= 255))),
    CONSTRAINT "platform_config_files_purpose_check" CHECK ((("purpose" IS NULL) OR (("length"("purpose") >= 1) AND ("length"("purpose") <= 128)))),
    CONSTRAINT "platform_config_files_requested_size_bytes_check" CHECK ((("requested_size_bytes" >= 1) AND ("requested_size_bytes" <= 1048576))),
    CONSTRAINT "platform_config_files_reserved_bytes_check" CHECK (("reserved_bytes" >= 0)),
    CONSTRAINT "platform_config_files_reserved_count_check" CHECK (("reserved_count" = ANY (ARRAY[0, 1]))),
    CONSTRAINT "platform_config_files_resource_kind_check" CHECK (("resource_kind" = 'config_version'::"text")),
    CONSTRAINT "platform_config_files_retry_count_check" CHECK (("retry_count" >= 0)),
    CONSTRAINT "platform_config_files_sha256_check" CHECK ((("sha256" IS NULL) OR ("sha256" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "platform_config_files_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'receiving'::"text", 'storing'::"text", 'active'::"text", 'deleting'::"text", 'deleted'::"text", 'failed'::"text", 'expired'::"text"]))),
    CONSTRAINT "platform_config_files_storage_bucket_check" CHECK (("storage_bucket" = 'platform-config-files'::"text")),
    CONSTRAINT "platform_config_files_storage_path_check" CHECK ((("length"("storage_path") >= 1) AND ("length"("storage_path") <= 512))),
    CONSTRAINT "platform_config_files_write_outcome_check" CHECK (("write_outcome" = ANY (ARRAY['not_started'::"text", 'in_flight'::"text", 'confirmed'::"text", 'unknown'::"text", 'settled_absent'::"text"])))
);

