    "title" "text",
    "body" "text",
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "flagged" boolean DEFAULT false NOT NULL,
    "client_context" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "row_version" bigint DEFAULT 1 NOT NULL,
    "submitted_at" timestamp with time zone,
    "resolved_at" timestamp with time zone,
    "delete_requested_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "platform_feedback_author_display_name_snapshot_check" CHECK ((("author_display_name_snapshot" IS NULL) OR ("length"("author_display_name_snapshot") <= 120))),
    CONSTRAINT "platform_feedback_body_check" CHECK ((("body" IS NULL) OR (("length"("body") >= 1) AND ("length"("body") <= 10000)))),
    CONSTRAINT "platform_feedback_category_check" CHECK (("category" = ANY (ARRAY['bug'::"text", 'idea'::"text", 'experience'::"text", 'other'::"text"]))),
    CONSTRAINT "platform_feedback_check" CHECK ((("status" = 'deleted'::"text") OR (("platform_account_id" IS NOT NULL) AND ("user_id" IS NOT NULL)))),
    CONSTRAINT "platform_feedback_check1" CHECK ((("status" <> 'draft'::"text") OR ("submitted_at" IS NULL))),
    CONSTRAINT "platform_feedback_check2" CHECK ((("status" = ANY (ARRAY['draft'::"text", 'deleting'::"text", 'deleted'::"text"])) OR ("submitted_at" IS NOT NULL))),
    CONSTRAINT "platform_feedback_check3" CHECK ((("status" <> ALL (ARRAY['deleting'::"text", 'deleted'::"text"])) OR ("delete_requested_at" IS NOT NULL))),
    CONSTRAINT "platform_feedback_check4" CHECK ((("status" <> 'deleted'::"text") OR ("deleted_at" IS NOT NULL))),
    CONSTRAINT "platform_feedback_check5" CHECK ((("status" <> ALL (ARRAY['draft'::"text", 'new'::"text", 'reviewing'::"text", 'planned'::"text", 'resolved'::"text", 'closed'::"text"])) OR (("title" IS NOT NULL) AND ("body" IS NOT NULL)))),
    CONSTRAINT "platform_feedback_client_context_check" CHECK (("jsonb_typeof"("client_context") = 'object'::"text")),
    CONSTRAINT "platform_feedback_contact_email_snapshot_check" CHECK ((("contact_email_snapshot" IS NULL) OR (("length"("contact_email_snapshot") >= 3) AND ("length"("contact_email_snapshot") <= 320)))),
    CONSTRAINT "platform_feedback_row_version_check" CHECK (("row_version" > 0)),
    CONSTRAINT "platform_feedback_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'new'::"text", 'reviewing'::"text", 'planned'::"text", 'resolved'::"text", 'closed'::"text", 'deleting'::"text", 'deleted'::"text"]))),
    CONSTRAINT "platform_feedback_title_check" CHECK ((("title" IS NULL) OR ((("length"("title") >= 1) AND ("length"("title") <= 160)) AND ("title" !~ '[[:cntrl:]]'::"text"))))
);

