CREATE TABLE IF NOT EXISTS "public"."platform_feedback_attachments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "feedback_id" "uuid" NOT NULL,
    "platform_id" "uuid" NOT NULL,
    "platform_account_id" "uuid",
    "original_name" "text" NOT NULL,
    "storage_bucket" "text" DEFAULT 'platform-feedback-attachments'::"text" NOT NULL,
    "storage_path" "text",
    "object_path_hash" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "requested_size_bytes" bigint NOT NULL,
    "actual_size_bytes" bigint,
    "sha256" "text",
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "write_outcome" "text" DEFAULT 'not_started'::"text" NOT NULL,
    "intent_expires_at" timestamp with time zone NOT NULL,
    "lease_owner" "text",
    "lease_until" timestamp with time zone,
    "fencing_token" bigint DEFAULT 0 NOT NULL,
    "retry_count" integer DEFAULT 0 NOT NULL,
    "next_attempt_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_error_code" "text",
    "uploaded_at" timestamp with time zone,
    "cancel_requested_at" timestamp with time zone,
    "delete_requested_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "platform_feedback_attachments_actual_size_bytes_check" CHECK ((("actual_size_bytes" IS NULL) OR (("actual_size_bytes" >= 1) AND ("actual_size_bytes" <= 4194304)))),
    CONSTRAINT "platform_feedback_attachments_check" CHECK ((("actual_size_bytes" IS NULL) OR ("actual_size_bytes" <= "requested_size_bytes"))),
    CONSTRAINT "platform_feedback_attachments_check1" CHECK ((("status" <> 'active'::"text") OR (("actual_size_bytes" IS NOT NULL) AND ("sha256" IS NOT NULL) AND ("write_outcome" = 'confirmed'::"text")))),
    CONSTRAINT "platform_feedback_attachments_check2" CHECK ((("status" <> 'deleted'::"text") OR (("deleted_at" IS NOT NULL) AND ("storage_path" IS NULL)))),
    CONSTRAINT "platform_feedback_attachments_check3" CHECK ((("status" = 'deleted'::"text") OR (("platform_account_id" IS NOT NULL) AND ("storage_path" IS NOT NULL)))),
    CONSTRAINT "platform_feedback_attachments_fencing_token_check" CHECK (("fencing_token" >= 0)),
    CONSTRAINT "platform_feedback_attachments_last_error_code_check" CHECK ((("last_error_code" IS NULL) OR (("length"("last_error_code") >= 1) AND ("length"("last_error_code") <= 128)))),
    CONSTRAINT "platform_feedback_attachments_lease_owner_check" CHECK ((("lease_owner" IS NULL) OR (("length"("lease_owner") >= 1) AND ("length"("lease_owner") <= 128)))),
    CONSTRAINT "platform_feedback_attachments_mime_type_check" CHECK (("mime_type" = ANY (ARRAY['image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text"]))),
    CONSTRAINT "platform_feedback_attachments_object_path_hash_check" CHECK (("object_path_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "platform_feedback_attachments_original_name_check" CHECK (((("length"("original_name") >= 1) AND ("length"("original_name") <= 255)) AND ("original_name" !~ '[[:cntrl:]]'::"text"))),
    CONSTRAINT "platform_feedback_attachments_requested_size_bytes_check" CHECK ((("requested_size_bytes" >= 1) AND ("requested_size_bytes" <= 4194304))),
    CONSTRAINT "platform_feedback_attachments_retry_count_check" CHECK (("retry_count" >= 0)),
    CONSTRAINT "platform_feedback_attachments_sha256_check" CHECK ((("sha256" IS NULL) OR ("sha256" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "platform_feedback_attachments_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'receiving'::"text", 'storing'::"text", 'active'::"text", 'deleting'::"text", 'deleted'::"text", 'failed'::"text", 'expired'::"text"]))),
    CONSTRAINT "platform_feedback_attachments_storage_bucket_check" CHECK (("storage_bucket" = 'platform-feedback-attachments'::"text")),
    CONSTRAINT "platform_feedback_attachments_storage_path_check" CHECK ((("storage_path" IS NULL) OR (("length"("storage_path") >= 1) AND ("length"("storage_path") <= 512)))),
    CONSTRAINT "platform_feedback_attachments_write_outcome_check" CHECK (("write_outcome" = ANY (ARRAY['not_started'::"text", 'in_flight'::"text", 'confirmed'::"text", 'unknown'::"text", 'settled_absent'::"text"])))
);

