    CONSTRAINT "redemption_code_batches_check" CHECK (("expires_at" > "created_at")),
    CONSTRAINT "redemption_code_batches_check1" CHECK (("delivery_deadline" > "created_at")),
    CONSTRAINT "redemption_code_batches_check2" CHECK (((("status" = 'active'::"text") AND ("delivered_at" IS NOT NULL) AND ("delivery_receipt_hmac" IS NOT NULL)) OR ("status" <> 'active'::"text"))),
    CONSTRAINT "redemption_code_batches_duration_unit_check" CHECK (("duration_unit" = ANY (ARRAY['day'::"text", 'month'::"text", 'year'::"text"]))),
