RESET SESSION AUTHORIZATION;



SET SESSION AUTHORIZATION "postgres";
GRANT SELECT("status") ON TABLE "auth"."mfa_factors" TO "domain_owner";
RESET SESSION AUTHORIZATION;

-- Schema dumps omit essential non-secret installation metadata.
-- The hosted public-schema defaults include non-RLS privileges; business tables
-- are reachable only through the canonical private API, including future tables.
revoke all on all tables in schema public from public, anon, authenticated;
revoke all on all sequences in schema public from public, anon, authenticated;
alter default privileges for role postgres in schema public
  revoke all on tables from public, anon, authenticated;
alter default privileges for role postgres in schema public
  revoke all on sequences from public, anon, authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values
  ('platform-config-files','platform-config-files',false,1048576,null),
  ('platform-feedback-attachments','platform-feedback-attachments',false,4194304,array['image/jpeg','image/png','image/webp']::text[])
on conflict (id) do update set name=excluded.name, public=false,
  file_size_limit=excluded.file_size_limit, allowed_mime_types=excluded.allowed_mime_types;
select cron.schedule('billing-worker-every-minute','* * * * *','select private.billing_maintenance_cron();');

-- Installer settings must not leak into domain writes in the same connection.
reset row_security;
reset check_function_bodies;
reset search_path;
